	if p.char == 'u' && !p.eof {
		p.next()
		p.expectChar("l")
		p.expectChar("l")
		end := p.pos
		if p.eof {
			end = len(p.data)
		}
		if !p.isDelim() {
			p.fail("Unexpected character " + q(p.char))
		}
		return &Node{Kind: Null, Raw: string(p.data[start:end])}
	}
	if p.char == 'a' && !p.eof {
		p.next()
		p.expectChar("nN")
		return p.finishSpecial(start)
	}
	p.fail("Unexpected character " + q(p.char))
	return nil
}

func (p *Parser) parseNaN(start int) *Node {
	p.next() // N or n
	p.expectChar("aA")
	p.expectChar("nN")
	return p.finishSpecial(start)
}

func (p *Parser) parseInfinity(start int) *Node {
	p.next() // I or i
	p.expectChar("nN")
	p.expectChar("fF")
	if p.char == 'i' && !p.eof {
		p.next()
		p.expectChar("n")
		p.expectChar("i")
		p.expectChar("t")
		p.expectChar("y")
	}
	return p.finishSpecial(start)
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func (p *Parser) parseNumber() *Node {
	start := p.pos
	if p.char == '-' {
		p.next()
		if !p.eof {
			switch p.char {
			case 'I', 'i':
				return p.parseInfinity(start)
			case 'N':
				return p.parseNaN(start)
			case 'n':
				p.next()
				p.expectChar("a")
				p.expectChar("nN")
				return p.finishSpecial(start)
			}
		}
	}
	if p.eof {
		p.fail("Invalid character " + q(p.char) + " in number")
	}
	if p.char == '0' {
		p.next()
	} else if p.char >= '1' && p.char <= '9' {
		for !p.eof && isDigit(p.char) {
			p.next()
		}
	} else {
		p.fail("Invalid character " + q(p.char) + " in number")
	}
	if !p.eof && p.char == '.' {
		p.next()
		if p.eof || !isDigit(p.char) {
			p.fail("Invalid character " + q(p.char) + " in number")
		}
		for !p.eof && isDigit(p.char) {
			p.next()
		}
	}
	if !p.eof && (p.char == 'e' || p.char == 'E') {
		p.next()
		if !p.eof && (p.char == '+' || p.char == '-') {
			p.next()
		}
		if p.eof || !isDigit(p.char) {
			p.fail("Invalid character " + q(p.char) + " in number")
		}
		for !p.eof && isDigit(p.char) {
			p.next()
		}
	}
	end := p.pos
	if p.eof {
		end = len(p.data)
	}
	return &Node{Kind: Number, Raw: string(p.data[start:end])}
}

func (p *Parser) parseString() string {
	start := p.pos
	p.next() // opening quote
	for {
		if p.eof {
			p.fail("Unexpected end of input in string")
		}
		if p.char == '\\' {
			p.next()
			if p.eof {
				p.fail("Unexpected end of input in string")
			}
			p.next()
			continue
		}
		if p.char == '"' {
			p.next()
			end := p.pos
			if p.eof {
				end = len(p.data)
			}
			return string(p.data[start:end])
		}
		p.next()
	}
}

func (p *Parser) parseObject() *Node {
	n := &Node{Kind: Object}
	p.next() // {
	p.skipWhitespace()
	if p.char == '}' && !p.eof {
		p.next()
		return n
	}
	for {
		if p.eof || p.char != '"' {
			p.fail("Expected object key to be a string, got " + q(p.char))
		}
		key := p.parseString()
		p.skipWhitespace()
		if p.eof || p.char != ':' {
			p.fail("Expected colon after object key, got " + q(p.char))
		}
		p.next()
		v := p.parseValue()
		v.Key = key
		v.HasKey = true
		v.Parent = n
		n.Children = append(n.Children, v)
		p.skipWhitespace()
		if p.char == ',' && !p.eof {
			cpos, cline, cls := p.pos, p.line, p.lineStart
			p.next()
			p.skipWhitespace()
			if p.char == '}' && !p.eof {
				if p.Strict {
					p.failAt("Trailing comma is not allowed in strict mode", cpos, cline, cls)
				}
				p.next()
				return n
			}
			continue
		}
		if p.char == '}' && !p.eof {
			p.next()
			return n
		}
		p.fail("Unexpected character " + q(p.char) + " in object")
	}
}

func (p *Parser) parseArray() *Node {
	n := &Node{Kind: Array}
	p.next() // [
	p.skipWhitespace()
	if p.char == ']' && !p.eof {
		p.next()
		return n
	}
	for {
		v := p.parseValue()
		v.Parent = n
		n.Children = append(n.Children, v)
		p.skipWhitespace()
		if p.char == ',' && !p.eof {
			cpos, cline, cls := p.pos, p.line, p.lineStart
			p.next()
			p.skipWhitespace()
			if p.char == ']' && !p.eof {
				if p.Strict {
					p.failAt("Trailing comma is not allowed in strict mode", cpos, cline, cls)
				}
				p.next()
				return n
			}
			continue
		}
		if p.char == ']' && !p.eof {
			p.next()
			return n
		}
		p.fail("Invalid character " + q(p.char) + " in array")
	}
}
