package jsonx

import (
	"bufio"
	"strconv"
	"strings"
)

// Theme holds color codes. Empty strings mean no color.
type Theme struct {
	Key     string
	String  string
	Number  string
	Bool    string
	Null    string
	Syntax  string
	Preview string
	// KeyFn etc. allow custom rendering
}

const reset = "\x1b[0m"

func colorize(code, s string) string {
	if code == "" {
		return s
	}
	return code + s + reset
}

type Printer struct {
	W     *bufio.Writer
	Theme *Theme
	NoInline bool
}

func (p *Printer) syntax(s string) {
	if p.Theme != nil && p.Theme.Syntax != "" {
		p.W.WriteString(colorize(p.Theme.Syntax, s))
	} else {
		p.W.WriteString(s)
	}
}

func (p *Printer) value(n *Node) {
	if p.Theme == nil {
		p.W.WriteString(n.Raw)
		return
	}
	switch n.Kind {
	case String:
		p.W.WriteString(colorize(p.Theme.String, n.Raw))
	case Number:
		p.W.WriteString(colorize(p.Theme.Number, n.Raw))
	case Bool:
		p.W.WriteString(colorize(p.Theme.Bool, n.Raw))
	case Null:
		p.W.WriteString(colorize(p.Theme.Null, n.Raw))
	default:
		p.W.WriteString(n.Raw)
	}
}

func (p *Printer) key(k string) {
	if p.Theme == nil {
		p.W.WriteString(k)
	} else {
		p.W.WriteString(colorize(p.Theme.Key, k))
	}
	p.syntax(":")
	p.W.WriteString(" ")
}

// PrintTop prints a top level node followed by a newline.
// Returns an error if a top-level string cannot be unquoted.
func (p *Printer) PrintTop(n *Node) error {
	if n.Kind == String {
		s, err := strconv.Unquote(n.Raw)
		if err != nil {
			return err
		}
		p.W.WriteString(s)
		p.W.WriteString("\n")
		return nil
	}
	p.print(n, 0)
	p.W.WriteString("\n")
	return nil
}

func (p *Printer) print(n *Node, level int) {
	switch n.Kind {
	case Object, Array:
		open, close := "{", "}"
		if n.Kind == Array {
			open, close = "[", "]"
		}
		if len(n.Children) == 0 {
			p.syntax(open)
			if n.Synthetic {
				p.W.WriteString("\n")
				p.W.WriteString(strings.Repeat("  ", level))
			}
			p.syntax(close)
			return
		}
		if n.Inline && !p.NoInline {
			p.syntax(open)
			p.W.WriteString(" ")
			for i, c := range n.Children {
				if i > 0 {
					p.syntax(",")
					p.W.WriteString(" ")
				}
				if n.Kind == Object {
					p.key(c.Key)
				}
				p.print(c, level+1)
			}
			p.W.WriteString(" ")
			p.syntax(close)
			return
		}
		p.syntax(open)
		p.W.WriteString("\n")
		ind := strings.Repeat("  ", level+1)
		for i, c := range n.Children {
			p.W.WriteString(ind)
			if n.Kind == Object {
				p.key(c.Key)
			}
			p.print(c, level+1)
			if i < len(n.Children)-1 {
				p.syntax(",")
			}
			p.W.WriteString("\n")
		}
		p.W.WriteString(strings.Repeat("  ", level))
		p.syntax(close)
	default:
		p.value(n)
	}
}
