package js

import (
	"strings"
	"unicode"
	"unicode/utf8"
)

type lexer struct {
	src    []rune
	off    int // offset of current char
	chr    rune
	errors *[]perror

	insertSemicolon   bool
	implicitSemicolon bool
	newlineBefore     bool

	// for strict checks
	lastOctal bool
}

func newLexer(src string, errs *[]perror) *lexer {
	l := &lexer{src: []rune(src), errors: errs}
	l.off = -1
	l.read()
	return l
}

func (l *lexer) read() {
	l.off++
	if l.off < len(l.src) {
		l.chr = l.src[l.off]
	} else {
		l.off = len(l.src)
		l.chr = -1
	}
}

func (l *lexer) peek() rune {
	if l.off+1 < len(l.src) {
		return l.src[l.off+1]
	}
	return -1
}

func (l *lexer) err(idx int, msg string) {
	*l.errors = append(*l.errors, perror{idx: idx, msg: msg})
}

func isLineTerminator(c rune) bool {
	return c == '\n' || c == '\r' || c == '\u2028' || c == '\u2029'
}

func isIdentStart(c rune) bool {
	return c == '$' || c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '\\' ||
		(c >= utf8.RuneSelf && (unicode.IsLetter(c) || unicode.Is(unicode.Nl, c) || unicode.Is(unicode.Other_ID_Start, c)))
}

func isIdentPart(c rune) bool {
	return c == '$' || c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '\\' ||
		c == '\u200c' || c == '\u200d' ||
		(c >= utf8.RuneSelf && (unicode.IsLetter(c) || unicode.IsDigit(c) || unicode.Is(unicode.Mn, c) || unicode.Is(unicode.Mc, c) || unicode.Is(unicode.Nd, c) || unicode.Is(unicode.Pc, c) || unicode.Is(unicode.Nl, c) || unicode.Is(unicode.Other_ID_Start, c) || unicode.Is(unicode.Other_ID_Continue, c)))
}

func digitVal(c rune) int {
	switch {
	case c >= '0' && c <= '9':
		return int(c - '0')
	case c >= 'a' && c <= 'f':
		return int(c - 'a' + 10)
	case c >= 'A' && c <= 'F':
		return int(c - 'A' + 10)
	}
	return 16
}

func (l *lexer) skipWhiteSpace() {
	for {
		switch l.chr {
		case ' ', '\t', '\f', '\v', '\u00a0', '\ufeff':
			l.read()
			continue
		case '\r', '\u2028', '\u2029', '\n':
			if l.insertSemicolon {
				return
			}
			l.newlineBefore = true
			l.read()
			continue
		}
		if l.chr >= utf8.RuneSelf && l.chr != -1 && unicode.IsSpace(l.chr) {
			l.read()
			continue
		}
		break
	}
}

type token struct {
	tok     Tok
	literal string
	value   string // parsed string value / identifier name
	idx     int
	octal   bool // legacy octal number literal
	escaped bool // identifier contains escapes
}

func (l *lexer) scan() (t token) {
	l.implicitSemicolon = false
	l.newlineBefore = false
	for {
		l.skipWhiteSpace()
		t.idx = l.off
		insertSemicolon := false
		chr := l.chr
		switch {
		case chr != -1 && isIdentStart(chr):
			name, escaped, ok := l.scanIdentifier()
			if !ok {
				t.tok = tILLEGAL
				t.literal = name
				l.insertSemicolon = false
				return
			}
			t.literal = name
			t.value = name
			t.escaped = escaped
			if kw, isKw := keywords[name]; isKw && !escaped {
				t.tok = kw
				switch kw {
				case tTHIS, tBREAK, tTHROW, tRETURN, tCONTINUE, tDEBUGGER, tNULL, tBOOLEAN, tSUPER:
					insertSemicolon = true
				}
			} else if isKw && escaped {
				t.tok = tIDENT
				insertSemicolon = true
			} else {
				t.tok = tIDENT
				insertSemicolon = true
			}
			l.insertSemicolon = insertSemicolon
			return
		case chr >= '0' && chr <= '9':
			insertSemicolon = true
			t.tok, t.literal, t.octal = l.scanNumber(false)
		default:
			l.read()
			switch chr {
			case -1:
				if l.insertSemicolon {
					l.insertSemicolon = false
					l.implicitSemicolon = true
				}
				t.tok = tEOF
			case '\r', '\n', '\u2028', '\u2029':
				l.insertSemicolon = false
				l.implicitSemicolon = true
				l.newlineBefore = true
				continue
			case ':':
				t.tok = tCOLON
			case '.':
				if l.chr >= '0' && l.chr <= '9' {
					insertSemicolon = true
					t.tok, t.literal, t.octal = l.scanNumber(true)
				} else {
					if l.chr == '.' {
						l.read()
						if l.chr == '.' {
							l.read()
							t.tok = tELLIPSIS
						} else {
							t.tok = tILLEGAL
						}
					} else {
						t.tok = tPERIOD
					}
				}
			case ',':
				t.tok = tCOMMA
			case ';':
				t.tok = tSEMICOLON
			case '(':
				t.tok = tLEFT_PAREN
			case ')':
				t.tok = tRIGHT_PAREN
				insertSemicolon = true
			case '[':
				t.tok = tLEFT_BRACKET
			case ']':
				t.tok = tRIGHT_BRACKET
				insertSemicolon = true
			case '{':
				t.tok = tLEFT_BRACE
			case '}':
				t.tok = tRIGHT_BRACE
				insertSemicolon = true
			case '+':
				if l.chr == '+' {
					l.read()
					t.tok = tINCREMENT
					insertSemicolon = true
				} else if l.chr == '=' {
					l.read()
					t.tok = tADD_ASSIGN
				} else {
					t.tok = tPLUS
				}
			case '-':
				if l.chr == '-' {
					l.read()
					t.tok = tDECREMENT
					insertSemicolon = true
				} else if l.chr == '=' {
					l.read()
					t.tok = tSUB_ASSIGN
				} else {
					t.tok = tMINUS
				}
			case '*':
				if l.chr == '*' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tEXP_ASSIGN
					} else {
						t.tok = tEXPONENT
					}
				} else if l.chr == '=' {
					l.read()
					t.tok = tMUL_ASSIGN
				} else {
					t.tok = tMULTIPLY
				}
			case '/':
				if l.chr == '/' {
					l.skipSingleLineComment()
					continue
				} else if l.chr == '*' {
					if l.skipMultiLineComment() {
						if l.insertSemicolon {
							l.implicitSemicolon = true
							l.insertSemicolon = false
						}
						l.newlineBefore = true
					}
					continue
				} else if l.chr == '=' {
					l.read()
					t.tok = tQUO_ASSIGN
				} else {
					t.tok = tSLASH
				}
			case '%':
				if l.chr == '=' {
					l.read()
					t.tok = tREM_ASSIGN
				} else {
					t.tok = tREMAINDER
				}
			case '^':
				if l.chr == '=' {
					l.read()
					t.tok = tXOR_ASSIGN
				} else {
					t.tok = tXOR
				}
			case '<':
				if l.chr == '<' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tSHL_ASSIGN
					} else {
						t.tok = tSHL
					}
				} else if l.chr == '=' {
					l.read()
					t.tok = tLESS_OR_EQUAL
				} else {
					t.tok = tLESS
				}
			case '>':
				if l.chr == '>' {
					l.read()
					if l.chr == '>' {
						l.read()
						if l.chr == '=' {
							l.read()
							t.tok = tUSHR_ASSIGN
						} else {
							t.tok = tUSHR
						}
					} else if l.chr == '=' {
						l.read()
						t.tok = tSHR_ASSIGN
					} else {
						t.tok = tSHR
					}
				} else if l.chr == '=' {
					l.read()
					t.tok = tGREATER_OR_EQUAL
				} else {
					t.tok = tGREATER
				}
			case '=':
				if l.chr == '>' {
					l.read()
					t.tok = tARROW
				} else if l.chr == '=' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tSTRICT_EQUAL
					} else {
						t.tok = tEQUAL
					}
				} else {
					t.tok = tASSIGN
				}
			case '!':
				if l.chr == '=' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tSTRICT_NOT_EQUAL
					} else {
						t.tok = tNOT_EQUAL
					}
				} else {
					t.tok = tNOT
				}
			case '~':
				t.tok = tBITWISE_NOT
			case '?':
				if l.chr == '.' && !(l.peek() >= '0' && l.peek() <= '9') {
					l.read()
					t.tok = tQUESTION_DOT
				} else if l.chr == '?' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tNULLISH_ASSIGN
					} else {
						t.tok = tNULLISH
					}
				} else {
					t.tok = tQUESTION
				}
			case '&':
				if l.chr == '&' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tLAND_ASSIGN
					} else {
						t.tok = tLAND
					}
				} else if l.chr == '=' {
					l.read()
					t.tok = tAND_ASSIGN
				} else {
					t.tok = tAND
				}
			case '|':
				if l.chr == '|' {
					l.read()
					if l.chr == '=' {
						l.read()
						t.tok = tLOR_ASSIGN
					} else {
						t.tok = tLOR
					}
				} else if l.chr == '=' {
					l.read()
					t.tok = tOR_ASSIGN
				} else {
					t.tok = tOR
				}
			case '"', '\'':
				insertSemicolon = true
				t.tok = tSTRING
				var ok bool
				t.literal, t.value, ok = l.scanString(chr, t.idx)
				if !ok {
					t.tok = tILLEGAL
				}
			case '`':
				t.tok = tBACKTICK
			case '#':
				if l.chr != -1 && isIdentStart(l.chr) {
					name, _, ok := l.scanIdentifier()
					if ok {
						t.tok = tPRIVATE_IDENT
						t.literal = "#" + name
						t.value = name
						insertSemicolon = true
					} else {
						t.tok = tILLEGAL
					}
				} else {
					t.tok = tILLEGAL
				}
			default:
				t.tok = tILLEGAL
			}
		}
		l.insertSemicolon = insertSemicolon
		if t.literal == "" {
			t.literal = string(l.src[t.idx:l.off])
		}
		return
	}
}

func (l *lexer) skipSingleLineComment() {
	for l.chr != -1 {
		if isLineTerminator(l.chr) {
			return
		}
		l.read()
	}
}

// returns true if a line terminator was seen
func (l *lexer) skipMultiLineComment() bool {
	l.read() // skip '*'
	nl := false
	for l.chr != -1 {
		chr := l.chr
		l.read()
		if chr == '*' && l.chr == '/' {
			l.read()
			return nl
		}
		if isLineTerminator(chr) {
			nl = true
		}
	}
	l.err(l.off, "Unexpected end of input")
	return nl
}

func (l *lexer) scanIdentifier() (string, bool, bool) {
	var sb strings.Builder
	escaped := false
	for l.chr != -1 && isIdentPart(l.chr) {
		if l.chr == '\\' {
			escaped = true
			l.read()
			if l.chr != 'u' {
				return sb.String(), escaped, false
			}
			l.read()
			var r rune
			if l.chr == '{' {
				l.read()
				n := 0
				for l.chr != '}' {
					d := digitVal(l.chr)
					if d >= 16 {
						return sb.String(), escaped, false
					}
					r = r*16 + rune(d)
					n++
					l.read()
				}
				l.read()
				if n == 0 {
					return sb.String(), escaped, false
				}
			} else {
				for i := 0; i < 4; i++ {
					d := digitVal(l.chr)
					if d >= 16 {
						return sb.String(), escaped, false
					}
					r = r*16 + rune(d)
					l.read()
				}
			}
			sb.WriteRune(r)
			continue
		}
		sb.WriteRune(l.chr)
		l.read()
	}
	return sb.String(), escaped, true
}

func isDigitBase(c rune, base int) bool {
	return digitVal(c) < base
}

func (l *lexer) scanMantissa(base int, allowSep bool) {
	for l.chr != -1 && (digitVal(l.chr) < base || (allowSep && l.chr == '_')) {
		after := l.chr == '_'
		l.read()
		if after && !isDigitBase(l.chr, base) {
			l.err(l.off, "Only one underscore is allowed as numeric separator")
		}
	}
}

func (l *lexer) scanNumber(decimalPoint bool) (Tok, string, bool) {
	start := l.off
	tkn := tNUMBER
	octal := false
	if decimalPoint {
		start--
		l.scanMantissa(10, true)
	} else {
		if l.chr == '0' {
			l.read()
			base := 0
			switch l.chr {
			case 'x', 'X':
				base = 16
			case 'o', 'O':
				base = 8
			case 'b', 'B':
				base = 2
			case '.', 'e', 'E':
			default:
				if l.chr >= '0' && l.chr <= '9' {
					// legacy octal
					l.scanMantissa(8, false)
					octal = true
					goto end
				}
			}
			if base > 0 {
				l.read()
				if !isDigitBase(l.chr, base) {
					return tILLEGAL, string(l.src[start:l.off]), false
				}
				l.scanMantissa(base, true)
				goto end
			}
		} else {
			l.scanMantissa(10, true)
		}
		if l.chr == '.' {
			l.read()
			l.scanMantissa(10, true)
		}
	}
	if l.chr == 'e' || l.chr == 'E' {
		l.read()
		if l.chr == '-' || l.chr == '+' {
			l.read()
		}
		if l.chr >= '0' && l.chr <= '9' {
			l.read()
			l.scanMantissa(10, true)
		} else {
			return tILLEGAL, string(l.src[start:l.off]), false
		}
	}
end:
	if l.chr == 'n' {
		l.read()
		tkn = tBIGINT
	}
	if l.chr != -1 && (isIdentStart(l.chr) || (l.chr >= '0' && l.chr <= '9')) {
		return tILLEGAL, string(l.src[start:l.off]), false
	}
	return tkn, string(l.src[start:l.off]), octal
}

// scanString scans a string literal; opening quote already consumed.
func (l *lexer) scanString(quote rune, start int) (string, string, bool) {
	var sb []uint16
	ok := true
	for l.chr != quote {
		chr := l.chr
		if chr == -1 || isLineTerminator(chr) && chr != '\u2028' && chr != '\u2029' {
			return string(l.src[start:l.off]), "", false
		}
		l.read()
		if chr == '\\' {
			if isLineTerminator(l.chr) {
				if l.chr == '\r' {
					l.read()
					if l.chr == '\n' {
						l.read()
					}
				} else {
					l.read()
				}
				continue
			}
			c, good := l.scanEscape(quote)
			if !good {
				ok = false
			}
			sb = append(sb, c...)
			continue
		}
		sb = appendRuneUTF16(sb, chr)
	}
	l.read()
	if !ok {
		return string(l.src[start:l.off]), "", false
	}
	return string(l.src[start:l.off]), utf16ToString(sb), true
}

func appendRuneUTF16(b []uint16, r rune) []uint16 {
	if r >= 0x10000 {
		r -= 0x10000
		return append(b, uint16(0xD800+(r>>10)), uint16(0xDC00+(r&0x3FF)))
	}
	return append(b, uint16(r))
}

func (l *lexer) scanEscape(quote rune) ([]uint16, bool) {
	chr := l.chr
	switch chr {
	case 'n':
		l.read()
		return []uint16{'\n'}, true
	case 't':
		l.read()
		return []uint16{'\t'}, true
	case 'r':
		l.read()
		return []uint16{'\r'}, true
	case 'b':
		l.read()
		return []uint16{'\b'}, true
	case 'f':
		l.read()
		return []uint16{'\f'}, true
	case 'v':
		l.read()
		return []uint16{'\v'}, true
	case 'x':
		l.read()
		v := 0
		for i := 0; i < 2; i++ {
			d := digitVal(l.chr)
			if d >= 16 {
				return nil, false
			}
			v = v*16 + d
			l.read()
		}
		return []uint16{uint16(v)}, true
	case 'u':
		l.read()
		if l.chr == '{' {
			l.read()
			v := 0
			n := 0
			for l.chr != '}' {
				d := digitVal(l.chr)
				if d >= 16 {
					return nil, false
				}
				v = v*16 + d
				if v > 0x10FFFF {
					return nil, false
				}
				n++
				l.read()
			}
			l.read()
			if n == 0 {
				return nil, false
			}
			return appendRuneUTF16(nil, rune(v)), true
		}
		v := 0
		for i := 0; i < 4; i++ {
			d := digitVal(l.chr)
			if d >= 16 {
				return nil, false
			}
			v = v*16 + d
			l.read()
		}
		return []uint16{uint16(v)}, true
	case '0', '1', '2', '3', '4', '5', '6', '7':
		// legacy octal
		v := int(chr - '0')
		l.read()
		if chr == '0' && !(l.chr >= '0' && l.chr <= '7') {
			return []uint16{0}, true
		}
		if l.chr >= '0' && l.chr <= '7' {
			v = v*8 + int(l.chr-'0')
			l.read()
			if chr <= '3' && l.chr >= '0' && l.chr <= '7' {
				v = v*8 + int(l.chr-'0')
				l.read()
			}
		}
		return []uint16{uint16(v)}, true
	case -1:
		return nil, false
	}
	l.read()
	return appendRuneUTF16(nil, chr), true
}

// scanTemplatePart scans template characters after '`' or '}' until '`' or '${'.
// Returns cooked (may be invalid), raw, finished (true if ended with backtick), ok.
func (l *lexer) scanTemplatePart() (cooked string, cookedOK bool, raw string, finished bool, ok bool) {
	var sb []uint16
	var rb []rune
	cookedOK = true
	for {
		chr := l.chr
		if chr == -1 {
			return "", false, string(rb), false, false
		}
		if chr == '`' {
			l.read()
			break
		}
		if chr == '$' && l.peek() == '{' {
			l.read()
			l.read()
			return utf16ToString(sb), cookedOK, string(rb), false, true
		}
		l.read()
		if chr == '\\' {
			startEsc := l.off
			if isLineTerminator(l.chr) {
				if l.chr == '\r' {
					l.read()
					if l.chr == '\n' {
						l.read()
					}
					rb = append(rb, '\\', '\n')
				} else {
					rb = append(rb, '\\', l.chr)
					l.read()
				}
				continue
			}
			c, good := l.scanEscape('`')
			if !good {
				cookedOK = false
			}
			sb = append(sb, c...)
			rb = append(rb, '\\')
			rb = append(rb, l.src[startEsc:l.off]...)
			continue
		}
		if chr == '\r' {
			if l.chr == '\n' {
				l.read()
			}
			chr = '\n'
		}
		sb = appendRuneUTF16(sb, chr)
		rb = append(rb, chr)
	}
	return utf16ToString(sb), cookedOK, string(rb), true, true
}

// scanRegExp scans a regular expression literal starting at '/' at index start.
func (l *lexer) scanRegExp(start int) (pattern, flags string, ok bool, errmsg string) {
	l.off = start
	l.chr = l.src[start]
	l.read() // skip '/'
	inClass := false
	var sb strings.Builder
	for {
		chr := l.chr
		if chr == -1 || isLineTerminator(chr) {
			return "", "", false, "Invalid regular expression: missing /"
		}
		l.read()
		if chr == '\\' {
			if l.chr == -1 || isLineTerminator(l.chr) {
				return "", "", false, "Invalid regular expression: missing /"
			}
			sb.WriteRune(chr)
			sb.WriteRune(l.chr)
			l.read()
			continue
		}
		if chr == '[' {
			inClass = true
		} else if chr == ']' {
			inClass = false
		} else if chr == '/' && !inClass {
			break
		}
		sb.WriteRune(chr)
	}
	fstart := l.off
	for l.chr != -1 && isIdentPart(l.chr) {
		l.read()
	}
	l.insertSemicolon = true
	return sb.String(), string(l.src[fstart:l.off]), true, ""
}
