{"command":"cd /workspace/internal/js && cat > parser.go <<'EOF'
package js

import (
	"math"
	"math/big"
	"strconv"
	"strings"
)

type perror struct {
	idx int
	msg string
}

type lexState struct {
	off               int
	chr               rune
	insertSemicolon   bool
	implicitSemicolon bool
	newlineBefore     bool
	tok               token
	nerr              int
}

type funcCtx struct {
	isArrow     bool
	isAsync     bool
	isGenerator bool
	inFunction  bool
	inClass     bool
	allowSuper  bool
}

type parser struct {
	l      *lexer
	tok    token
	errors []perror
	src    []rune

	allowIn bool
	fn      *funcCtx

	recoverIdx   int
	recoverCount int
}

func newParser(src string) *parser {
	p := &parser{}
	p.l = newLexer(src, &p.errors)
	p.src = p.l.src
	p.allowIn = true
	p.fn = &funcCtx{}
	p.next()
	return p
}

func (p *parser) next() {
	p.tok = p.l.scan()
}

func (p *parser) mark() lexState {
	return lexState{off: p.l.off, chr: p.l.chr, insertSemicolon: p.l.insertSemicolon,
		implicitSemicolon: p.l.implicitSemicolon, newlineBefore: p.l.newlineBefore, tok: p.tok, nerr: len(p.errors)}
}

func (p *parser) restore(s lexState) {
	p.l.off = s.off
	p.l.chr = s.chr
	p.l.insertSemicolon = s.insertSemicolon
	p.l.implicitSemicolon = s.implicitSemicolon
	p.l.newlineBefore = s.newlineBefore
	p.tok = s.tok
	p.errors = p.errors[:s.nerr]
}

// peek returns the next token type without consuming.
func (p *parser) peek() token {
	s := p.mark()
	p.next()
	t := p.tok
	p.restore(s)
	return t
}

func (p *parser) error(idx int, msg string) {
	p.errors = append(p.errors, perror{idx: idx, msg: msg})
}

func (p *parser) errorUnexpectedToken(t token) {
	switch t.tok {
	case tEOF:
		p.error(t.idx, "Unexpected end of input")
		return
	case tBOOLEAN, tNULL:
		p.error(t.idx, "Unexpected token "+t.literal)
		return
	case tIDENT:
		p.error(t.idx, "Unexpected identifier")
		return
	case tKEYWORD:
		p.error(t.idx, "Unexpected reserved word")
		return
	case tNUMBER, tBIGINT:
		p.error(t.idx, "Unexpected number")
		return
	case tSTRING:
		p.error(t.idx, "Unexpected string")
		return
	case tPRIVATE_IDENT:
		p.error(t.idx, "Unexpected identifier")
		return
	}
	p.error(t.idx, "Unexpected token "+t.tok.String())
}

func (p *parser) expect(tk Tok) int {
	idx := p.tok.idx
	if p.tok.tok != tk {
		p.errorUnexpectedToken(p.tok)
	}
	p.next()
	return idx
}

func (p *parser) optionalSemicolon() {
	if p.tok.tok == tSEMICOLON {
		p.next()
		return
	}
	if p.l.implicitSemicolon {
		p.l.implicitSemicolon = false
		return
	}
	if p.tok.tok != tEOF && p.tok.tok != tRIGHT_BRACE {
		p.expect(tSEMICOLON)
	}
}

func (p *parser) semicolon() {
	if p.tok.tok != tRIGHT_PAREN && p.tok.tok != tRIGHT_BRACE {
		if p.l.implicitSemicolon {
			p.l.implicitSemicolon = false
			return
		}
		p.expect(tSEMICOLON)
	}
}

func (p *parser) nextStatement() {
	for {
		switch p.tok.tok {
		case tBREAK, tCONTINUE, tFOR, tIF, tRETURN, tSWITCH, tVAR, tDO, tTRY, tWITH, tWHILE, tTHROW, tCATCH, tFINALLY:
			if p.tok.idx == p.recoverIdx && p.recoverCount < 10 {
				p.recoverCount++
				return
			}
			if p.tok.idx > p.recoverIdx {
				p.recoverIdx = p.tok.idx
				p.recoverCount = 0
				return
			}
		case tEOF:
			return
		}
		p.next()
	}
}

func isIdTok(t token) bool {
	return t.tok == tIDENT || isKeywordTok(t.tok)
}

func (p *parser) isBindingId(t token) bool {
	if t.tok != tIDENT {
		return false
	}
	return true
}

// ---------------- program ----------------

func (p *parser) parseProgram() []Stmt {
	var list []Stmt
	for p.tok.tok != tEOF {
		list = append(list, p.parseStatement())
	}
	return list
}

func (p *parser) parseStatementList() []Stmt {
	var list []Stmt
	for p.tok.tok != tRIGHT_BRACE && p.tok.tok != tEOF {
		list = append(list, p.parseStatement())
	}
	return list
}

func (p *parser) parseStatement() Stmt {
	if p.tok.tok == tEOF {
		p.errorUnexpectedToken(p.tok)
		return &BadStmt{base{p.tok.idx}}
	}
	switch p.tok.tok {
	case tSEMICOLON:
		idx := p.tok.idx
		p.next()
		return &EmptyStmt{base{idx}}
	case tLEFT_BRACE:
		return p.parseBlockStatement()
	case tIF:
		return p.parseIfStatement()
	case tDO:
		return p.parseDoWhileStatement()
	case tWHILE:
		return p.parseWhileStatement()
	case tFOR:
		return p.parseForStatement()
	case tBREAK:
		return p.parseBreakContinue(true)
	case tCONTINUE:
		return p.parseBreakContinue(false)
	case tDEBUGGER:
		idx := p.tok.idx
		p.next()
		p.semicolon()
		return &DebuggerStmt{base{idx}}
	case tWITH:
		return p.parseWithStatement()
	case tVAR:
		return p.parseVarStatement()
	case tCONST:
		return p.parseLexicalDeclaration(tCONST)
	case tFUNCTION:
		idx := p.tok.idx
		f := p.parseFunction(true, false, idx)
		return &FuncDecl{base{idx}, f}
	case tCLASS:
		idx := p.tok.idx
		c := p.parseClass(true)
		return &ClassDecl{base{idx}, c}
	case tSWITCH:
		return p.parseSwitchStatement()
	case tRETURN:
		return p.parseReturnStatement()
	case tTHROW:
		return p.parseThrowStatement()
	case tTRY:
		return p.parseTryStatement()
	case tIDENT:
		if p.tok.value == "let" && !p.tok.escaped {
			nt := p.peek()
			if nt.tok == tLEFT_BRACKET || nt.tok == tIDENT || nt.tok == tLEFT_BRACE {
				return p.parseLexicalDeclaration(tIDENT)
			}
		}
		if p.tok.value == "async" && !p.tok.escaped {
			s := p.mark()
			idx := p.tok.idx
			p.next()
			if p.tok.tok == tFUNCTION && !p.l.newlineBefore {
				f := p.parseFunction(true, true, idx)
				return &FuncDecl{base{idx}, f}
			}
			p.restore(s)
		}
	}
	idx := p.tok.idx
	expr := p.parseExpression()
	if id, ok := expr.(*Identifier); ok && p.tok.tok == tCOLON {
		p.next()
		body := p.parseStatement()
		return &LabeledStmt{base{idx}, id.Name, body}
	}
	p.optionalSemicolon()
	return &ExprStmt{base{idx}, expr}
}

func (p *parser) parseBlockStatement() *BlockStmt {
	b := &BlockStmt{base: base{p.tok.idx}}
	p.expect(tLEFT_BRACE)
	b.List = p.parseStatementList()
	p.expect(tRIGHT_BRACE)
	return b
}

func (p *parser) parseIfStatement() Stmt {
	idx := p.expect(tIF)
	p.expect(tLEFT_PAREN)
	test := p.parseExpression()
	p.expect(tRIGHT_PAREN)
	s := &IfStmt{base: base{idx}, Test: test}
	s.Cons = p.parseStatement()
	if p.tok.tok == tELSE {
		p.next()
		s.Alt = p.parseStatement()
	}
	return s
}

func (p *parser) parseDoWhileStatement() Stmt {
	idx := p.expect(tDO)
	s := &DoWhileStmt{base: base{idx}}
	if p.tok.tok == tLEFT_BRACE {
		s.Body = p.parseBlockStatement()
	} else {
		s.Body = p.parseStatement()
	}
	p.expect(tWHILE)
	p.expect(tLEFT_PAREN)
	s.Test = p.parseExpression()
	p.expect(tRIGHT_PAREN)
	if p.tok.tok == tSEMICOLON {
		p.next()
	}
	return s
}

func (p *parser) parseWhileStatement() Stmt {
	idx := p.expect(tWHILE)
	p.expect(tLEFT_PAREN)
	s := &WhileStmt{base: base{idx}}
	s.Test = p.parseExpression()
	p.expect(tRIGHT_PAREN)
	s.Body = p.parseStatement()
	return s
}

func (p *parser) parseWithStatement() Stmt {
	idx := p.expect(tWITH)
	p.expect(tLEFT_PAREN)
	s := &WithStmt{base: base{idx}}
	s.Obj = p.parseExpression()
	p.expect(tRIGHT_PAREN)
	s.Body = p.parseStatement()
	return s
}

func (p *parser) parseBreakContinue(isBreak bool) Stmt {
	idx := p.tok.idx
	p.next()
	label := ""
	if !p.l.implicitSemicolon && p.tok.tok == tIDENT {
		label = p.tok.value
		p.next()
	}
	p.semicolon()
	if isBreak {
		return &BreakStmt{base{idx}, label}
	}
	return &ContinueStmt{base{idx}, label}
}

func (p *parser) parseReturnStatement() Stmt {
	idx := p.expect(tRETURN)
	if !p.fn.inFunction {
		p.error(idx, "Illegal return statement")
		p.nextStatement()
		return &BadStmt{base{idx}}
	}
	s := &ReturnStmt{base: base{idx}}
	if !p.l.implicitSemicolon && p.tok.tok != tSEMICOLON && p.tok.tok != tRIGHT_BRACE && p.tok.tok != tEOF {
		s.Arg = p.parseExpression()
	}
	p.semicolon()
	return s
}

func (p *parser) parseThrowStatement() Stmt {
	idx := p.expect(tTHROW)
	if p.l.implicitSemicolon {
		if p.tok.tok == tEOF {
			p.errorUnexpectedToken(p.tok)
		} else {
			p.error(p.tok.idx, "Illegal newline after throw")
		}
		p.nextStatement()
		return &BadStmt{base{idx}}
	}
	s := &ThrowStmt{base: base{idx}, Arg: p.parseExpression()}
	p.semicolon()
	return s
}

func (p *parser) parseTryStatement() Stmt {
	idx := p.expect(tTRY)
	s := &TryStmt{base: base{idx}}
	s.Block = p.parseBlockStatement()
	if p.tok.tok == tCATCH {
		p.next()
		if p.tok.tok == tLEFT_PAREN {
			p.next()
			s.Param = p.parseBindingTarget()
			p.expect(tRIGHT_PAREN)
		}
		s.Handler = p.parseBlockStatement()
	}
	if p.tok.tok == tFINALLY {
		p.next()
		s.Finalizer = p.parseBlockStatement()
	}
	if s.Handler == nil && s.Finalizer == nil {
		p.error(p.tok.idx, "Missing catch or finally after try")
		return &BadStmt{base{idx}}
	}
	return s
}

func (p *parser) parseSwitchStatement() Stmt {
	idx := p.expect(tSWITCH)
	p.expect(tLEFT_PAREN)
	s := &SwitchStmt{base: base{idx}}
	s.Disc = p.parseExpression()
	p.expect(tRIGHT_PAREN)
	p.expect(tLEFT_BRACE)
	hasDefault := false
	for p.tok.tok != tEOF {
		if p.tok.tok == tRIGHT_BRACE {
			p.next()
			break
		}
		c := &SwitchCase{}
		if p.tok.tok == tDEFAULT {
			if hasDefault {
				p.error(p.tok.idx, "Already saw a default in switch")
			}
			hasDefault = true
			p.next()
		} else {
			p.expect(tCASE)
			c.Test = p.parseExpression()
		}
		p.expect(tCOLON)
		for p.tok.tok != tEOF && p.tok.tok != tRIGHT_BRACE && p.tok.tok != tCASE && p.tok.tok != tDEFAULT {
			c.Body = append(c.Body, p.parseStatement())
		}
		s.Cases = append(s.Cases, c)
	}
	return s
}

func (p *parser) parseVarStatement() Stmt {
	idx := p.expect(tVAR)
	d := &VarDecl{base: base{idx}, Kind: tVAR}
	d.Decls = p.parseDeclarators(tVAR)
	p.semicolon()
	return d
}

func (p *parser) parseLexicalDeclaration(kind Tok) Stmt {
	idx := p.tok.idx
	p.next()
	d := &VarDecl{base: base{idx}, Kind: kind}
	d.Decls = p.parseDeclarators(kind)
	p.semicolon()
	return d
}

func (p *parser) parseDeclarators(kind Tok) []*Declarator {
	var list []*Declarator
	for {
		dc := &Declarator{idx: p.tok.idx}
		dc.Target = p.parseBindingTarget()
		if p.tok.tok == tASSIGN {
			p.next()
			dc.Init = p.parseAssignmentExpression()
		}
		list = append(list, dc)
		if p.tok.tok != tCOMMA {
			break
		}
		p.next()
	}
	return list
}

func (p *parser) parseBindingTarget() Pattern {
	switch p.tok.tok {
	case tIDENT:
		id := &Identifier{base{p.tok.idx}, p.tok.value}
		p.next()
		return id
	case tLEFT_BRACKET:
		return p.parseArrayBindingPattern()
	case tLEFT_BRACE:
		return p.parseObjectBindingPattern()
	}
	idx := p.tok.idx
	p.errorUnexpectedToken(p.tok)
	p.nextStatement()
	return &BadExpr{base{idx}}
}

func (p *parser) parseArrayBindingPattern() Pattern {
	pat := &ArrayPattern{base: base{p.tok.idx}}
	p.expect(tLEFT_BRACKET)
	for p.tok.tok != tRIGHT_BRACKET && p.tok.tok != tEOF {
		if p.tok.tok == tCOMMA {
			p.next()
			pat.Elems = append(pat.Elems, &PatElem{})
			continue
		}
		if p.tok.tok == tELLIPSIS {
			p.next()
			pat.Rest = p.parseBindingTarget()
			break
		}
		el := &PatElem{Target: p.parseBindingTarget()}
		if p.tok.tok == tASSIGN {
			p.next()
			el.Default = p.parseAssignmentExpression()
		}
		pat.Elems = append(pat.Elems, el)
		if p.tok.tok != tRIGHT_BRACKET {
			p.expect(tCOMMA)
		}
	}
	p.expect(tRIGHT_BRACKET)
	return pat
}

func (p *parser) parsePropertyKey() (key Expr, name string, computed bool) {
	t := p.tok
	switch t.tok {
	case tIDENT, tSTRING:
		p.next()
		return &StringLit{base{t.idx}, t.value, t.literal}, t.value, false
	case tNUMBER, tBIGINT:
		p.next()
		v := p.numberValue(t)
		var s string
		switch n := v.(type) {
		case *NumberLit:
			s = numberToString(n.Value)
		case *BigIntLit:
			s = n.Value.String()
		}
		return &StringLit{base{t.idx}, s, t.literal}, s, false
	case tLEFT_BRACKET:
		p.next()
		e := p.parseAssignmentExpression()
		p.expect(tRIGHT_BRACKET)
		return e, "", true
	case tPRIVATE_IDENT:
		p.next()
		return &StringLit{base{t.idx}, "#" + t.value, t.literal}, "#" + t.value, false
	}
	if isKeywordTok(t.tok) {
		p.next()
		return &StringLit{base{t.idx}, t.literal, t.literal}, t.literal, false
	}
	p.errorUnexpectedToken(t)
	p.nextStatement()
	return &BadExpr{base{t.idx}}, "", false
}

func (p *parser) parseObjectBindingPattern() Pattern {
	pat := &ObjectPattern{base: base{p.tok.idx}}
	p.expect(tLEFT_BRACE)
	for p.tok.tok != tRIGHT_BRACE && p.tok.tok != tEOF {
		if p.tok.tok == tELLIPSIS {
			p.next()
			pat.Rest = p.parseBindingTarget()
			break
		}
		t := p.tok
		key, name, computed := p.parsePropertyKey()
		pp := &PatProp{Key: key, Name: name, Computed: computed}
		if p.tok.tok == tCOLON {
			p.next()
			pp.Target = p.parseBindingTarget()
		} else {
			if t.tok != tIDENT {
				p.errorUnexpectedToken(p.tok)
			}
			pp.Target = &Identifier{base{t.idx}, name}
		}
		if p.tok.tok == tASSIGN {
			p.next()
			pp.Default = p.parseAssignmentExpression()
		}
		pat.Props = append(pat.Props, pp)
		if p.tok.tok != tRIGHT_BRACE {
			p.expect(tCOMMA)
		}
	}
	p.expect(tRIGHT_BRACE)
	return pat
}

func (p *parser) parseForStatement() Stmt {
	idx := p.expect(tFOR)
	if p.tok.tok == tIDENT && p.tok.value == "await" {
		p.next()
	}
	p.expect(tLEFT_PAREN)
	var init Node
	if p.tok.tok != tSEMICOLON {
		allowIn := p.allowIn
		p.allowIn = false
		isLet := p.tok.tok == tIDENT && p.tok.value == "let" && !p.tok.escaped
		if isLet {
			nt := p.peek()
			isLet = nt.tok == tIDENT || nt.tok == tLEFT_BRACKET || nt.tok == tLEFT_BRACE
		}
		if p.tok.tok == tVAR || p.tok.tok == tCONST || isLet {
			kind := p.tok.tok
			didx := p.tok.idx
			p.next()
			d := &VarDecl{base: base{didx}, Kind: kind}
			var list []*Declarator
			for {
				dc := &Declarator{idx: p.tok.idx}
				dc.Target = p.parseBindingTarget()
				if p.tok.tok == tASSIGN {
					p.next()
					dc.Init = p.parseAssignmentExpression()
				}
				list = append(list, dc)
				if p.tok.tok != tCOMMA {
					break
				}
				p.next()
			}
			d.Decls = list
			init = d
			p.allowIn = allowIn
			if p.tok.tok == tIN || (p.tok.tok == tIDENT && p.tok.value == "of") {
				of := p.tok.tok == tIDENT
				p.next()
				var right Expr
				if of {
					right = p.parseAssignmentExpression()
				} else {
					right = p.parseExpression()
				}
				p.expect(tRIGHT_PAREN)
				body := p.parseStatement()
				return &ForInStmt{base{idx}, d, right, body, of}
			}
		} else {
			expr := p.parseExpression()
			p.allowIn = allowIn
			if p.tok.tok == tIN || (p.tok.tok == tIDENT && p.tok.value == "of") {
				of := p.tok.tok == tIDENT
				target := p.toAssignTarget(expr, true)
				p.next()
				var right Expr
				if of {
					right = p.parseAssignmentExpression()
				} else {
					right = p.parseExpression()
				}
				p.expect(tRIGHT_PAREN)
				body := p.parseStatement()
				return &ForInStmt{base{idx}, target, right, body, of}
			}
			init = expr
		}
		p.allowIn = allowIn
	}
	s := &ForStmt{base: base{idx}, Init: init}
	p.expect(tSEMICOLON)
	if p.tok.tok != tSEMICOLON {
		s.Test = p.parseExpression()
	}
	p.expect(tSEMICOLON)
	if p.tok.tok != tRIGHT_PAREN {
		s.Update = p.parseExpression()
	}
	p.expect(tRIGHT_PAREN)
	s.Body = p.parseStatement()
	return s
}

// ---------------- expressions ----------------

func (p *parser) parseExpression() Expr {
	idx := p.tok.idx
	left := p.parseAssignmentExpression()
	if p.tok.tok == tCOMMA {
		seq := []Expr{left}
		for p.tok.tok == tCOMMA {
			p.next()
			seq = append(seq, p.parseAssignmentExpression())
		}
		return &SeqExpr{base{idx}, seq}
	}
	return left
}

func assignOp(t Tok) (Tok, bool) {
	switch t {
	case tASSIGN:
		return tASSIGN, true
	case tADD_ASSIGN:
		return tPLUS, true
	case tSUB_ASSIGN:
		return tMINUS, true
	case tMUL_ASSIGN:
		return tMULTIPLY, true
	case tEXP_ASSIGN:
		return tEXPONENT, true
	case tQUO_ASSIGN:
		return tSLASH, true
	case tREM_ASSIGN:
		return tREMAINDER, true
	case tAND_ASSIGN:
		return tAND, true
	case tOR_ASSIGN:
		return tOR, true
	case tXOR_ASSIGN:
		return tXOR, true
	case tSHL_ASSIGN:
		return tSHL, true
	case tSHR_ASSIGN:
		return tSHR, true
	case tUSHR_ASSIGN:
		return tUSHR, true
	case tLAND_ASSIGN:
		return tLAND, true
	case tLOR_ASSIGN:
		return tLOR, true
	case tNULLISH_ASSIGN:
		return tNULLISH, true
	}
	return 0, false
}

func (p *parser) parseAssignmentExpression() Expr {
	start := p.tok.idx
	parenthesis := false
	async := false
	var state lexState
	switch p.tok.tok {
	case tLEFT_PAREN:
		state = p.mark()
		parenthesis = true
	case tIDENT:
		if p.tok.value == "async" && !p.tok.escaped {
			nt := p.peek()
			if !p.l.newlineBefore || true {
				if nt.tok == tIDENT || nt.tok == tLEFT_PAREN {
					s := p.mark()
					p.next()
					if !p.l.newlineBefore {
						if p.tok.tok == tIDENT {
							// async x => ...
							id := &Identifier{base{p.tok.idx}, p.tok.value}
							p.next()
							if p.tok.tok == tARROW && !p.l.newlineBefore {
								return p.parseArrowFunction(start, []Pattern{id}, nil, nil, true)
							}
						} else if p.tok.tok == tLEFT_PAREN {
							state = p.mark()
							async = true
						}
					}
					if !async {
						p.restore(s)
					}
				}
			}
		}
		if p.tok.value == "yield" && p.fn.isGenerator {
			return p.parseYield()
		}
	}
	if async {
		// try parse params then expect arrow
		ps, defs, rest, ok := p.tryParseParams()
		if ok && p.tok.tok == tARROW && !p.l.newlineBefore {
			return p.parseArrowFunction(start, ps, defs, rest, true)
		}
		// not an arrow: restore to 'async' identifier and parse normally
		p.restore(state)
		// state is at '(' ; we need to go back to 'async' ident: re-create call expression
		callee := &Identifier{base{start}, "async"}
		var left Expr = p.parseCallExpression(callee)
		left = p.continueLeftHandSide(left)
		left = p.continueFromPostfix(left)
		return p.finishAssignment(start, left, false)
	}
	left := p.parseConditionalExpression()
	if p.tok.tok == tARROW {
		if p.l.newlineBefore {
			p.errorUnexpectedToken(p.tok)
			p.nextStatement()
			return &BadExpr{base{start}}
		}
		if id, ok := left.(*Identifier); ok {
			return p.parseArrowFunction(start, []Pattern{id}, nil, nil, false)
		}
		if parenthesis {
			p.restore(state)
			ps, defs, rest, ok := p.tryParseParams()
			if ok && p.tok.tok == tARROW {
				return p.parseArrowFunction(start, ps, defs, rest, false)
			}
		}
		p.error(left.Pos(), "Malformed arrow function parameter list")
		return &BadExpr{base{start}}
	}
	return p.finishAssignment(start, left, parenthesis)
}

func (p *parser) finishAssignment(start int, left Expr, parenthesis bool) Expr {
	op, isAssign := assignOp(p.tok.tok)
	if !isAssign {
		return left
	}
	idx := p.tok.idx
	p.next()
	ok := false
	switch l := left.(type) {
	case *Identifier, *MemberExpr:
		ok = true
	case *ArrayLit:
		if !parenthesis && op == tASSIGN {
			left = p.toAssignTarget(l, false)
			ok = true
		}
	case *ObjectLit:
		if !parenthesis && op == tASSIGN {
			left = p.toAssignTarget(l, false)
			ok = true
		}
	}
	if ok {
		return &AssignExpr{base{idx}, op, left, p.parseAssignmentExpression()}
	}
	p.error(left.Pos(), "Invalid left-hand side in assignment")
	p.nextStatement()
	return &BadExpr{base{idx}}
}

// toAssignTarget converts an expression to an assignment pattern.
func (p *parser) toAssignTarget(e Expr, forIn bool) Node {
	switch v := e.(type) {
	case *Identifier, *MemberExpr:
		return e
	case *ParenExpr:
		return p.toAssignTarget(v.Expr, forIn)
	case *ArrayLit:
		pat := &ArrayPattern{base: base{v.idx}}
		for i, el := range v.Elems {
			if el == nil {
				pat.Elems = append(pat.Elems, &PatElem{})
				continue
			}
			if sp, ok := el.(*SpreadElem); ok && i == len(v.Elems)-1 {
				pat.Rest = p.toAssignTarget(sp.Arg, forIn)
				continue
			}
			pat.Elems = append(pat.Elems, p.toPatElem(el))
		}
		return pat
	case *ObjectLit:
		pat := &ObjectPattern{base: base{v.idx}}
		for _, pr := range v.Props {
			if pr.Kind == propSpread {
				pat.Rest = p.toAssignTarget(pr.Value, forIn)
				continue
			}
			pp := &PatProp{Key: pr.Key, Name: pr.Name, Computed: pr.Computed}
			if pr.Shorthand {
				if a, ok := pr.Value.(*AssignExpr); ok && a.Op == tASSIGN {
					pp.Target = a.Target
					pp.Default = a.Value
				} else {
					pp.Target = pr.Value
				}
			} else {
				el := p.toPatElem(pr.Value)
				pp.Target = el.Target
				pp.Default = el.Default
			}
			pat.Props = append(pat.Props, pp)
		}
		return pat
	case *AssignExpr:
		return e
	case *ArrayPattern, *ObjectPattern:
		return e
	}
	p.error(e.Pos(), "Invalid left-hand side in assignment")
	return &BadExpr{base{e.Pos()}}
}

func (p *parser) toPatElem(e Expr) *PatElem {
	if a, ok := e.(*AssignExpr); ok && a.Op == tASSIGN {
		var t Node = a.Target
		if ex, ok := a.Target.(Expr); ok {
			t = p.toAssignTarget(ex, false)
		}
		return &PatElem{Target: t, Default: a.Value}
	}
	return &PatElem{Target: p.toAssignTarget(e, false)}
}

// tryParseParams parses a formal parameter list starting at '('.
func (p *parser) tryParseParams() (params []Pattern, defaults []Expr, rest Pattern, ok bool) {
	nerr := len(p.errors)
	p.expect(tLEFT_PAREN)
	for p.tok.tok != tRIGHT_PAREN && p.tok.tok != tEOF {
		if p.tok.tok == tELLIPSIS {
			p.next()
			rest = p.parseBindingTarget()
			break
		}
		t := p.parseBindingTarget()
		var def Expr
		if p.tok.tok == tASSIGN {
			p.next()
			def = p.parseAssignmentExpression()
		}
		params = append(params, t)
		defaults = append(defaults, def)
		if p.tok.tok != tRIGHT_PAREN {
			p.expect(tCOMMA)
		}
	}
	p.expect(tRIGHT_PAREN)
	return params, defaults, rest, len(p.errors) == nerr
}

func (p *parser) parseArrowFunction(start int, params []Pattern, defaults []Expr, rest Pattern, async bool) Expr {
	p.expect(tARROW)
	f := &FuncLit{base: base{start}, IsArrow: true, IsAsync: async, Params: params, Defaults: defaults, Rest: rest}
	if defaults == nil {
		f.Defaults = make([]Expr, len(params))
	}
	saved := p.fn
	p.fn = &funcCtx{isArrow: true, isAsync: async, inFunction: true, inClass: saved.inClass, allowSuper: saved.allowSuper}
	if p.tok.tok == tLEFT_BRACE {
		p.expect(tLEFT_BRACE)
		f.Body = p.parseStatementList()
		end := p.tok.idx
		p.expect(tRIGHT_BRACE)
		f.Source = p.slice(start, end+1)
	} else {
		allowIn := p.allowIn
		e := p.parseAssignmentExpression()
		p.allowIn = allowIn
		f.ExprBody = e
		f.Source = p.slice(start, p.lastEnd())
	}
	p.fn = saved
	return f
}

func (p *parser) lastEnd() int {
	// end of previous token: approximate by current token idx, trimming whitespace
	end := p.tok.idx
	if end > len(p.src) {
		end = len(p.src)
	}
	for end > 0 {
		c := p.src[end-1]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
			end--
			continue
		}
		break
	}
	return end
}

func (p *parser) slice(a, b int) string {
	if a < 0 {
		a = 0
	}
	if b > len(p.src) {
		b = len(p.src)
	}
	if a > b {
		return ""
	}
	return string(p.src[a:b])
}

func (p *parser) parseYield() Expr {
	idx := p.tok.idx
	p.next()
	y := &YieldExpr{base: base{idx}}
	if !p.l.implicitSemicolon {
		if p.tok.tok == tMULTIPLY {
			y.Delegate = true
			p.next()
			y.Arg = p.parseAssignmentExpression()
			return y
		}
		switch p.tok.tok {
		case tRIGHT_PAREN, tRIGHT_BRACKET, tRIGHT_BRACE, tCOMMA, tCOLON, tSEMICOLON, tEOF:
		default:
			if !(p.tok.tok == tIN) {
				y.Arg = p.parseAssignmentExpression()
			}
		}
	}
	return y
}

func (p *parser) parseConditionalExpression() Expr {
	idx := p.tok.idx
	left := p.parseBinary(0)
	if p.tok.tok == tQUESTION {
		p.next()
		allowIn := p.allowIn
		p.allowIn = true
		cons := p.parseAssignmentExpression()
		p.allowIn = allowIn
		p.expect(tCOLON)
		alt := p.parseAssignmentExpression()
		return &CondExpr{base{idx}, left, cons, alt}
	}
	return left
}

func (p *parser) binPrec(t Tok) int {
	switch t {
	case tNULLISH:
		return 1
	case tLOR:
		return 2
	case tLAND:
		return 3
	case tOR:
		return 4
	case tXOR:
		return 5
	case tAND:
		return 6
	case tEQUAL, tNOT_EQUAL, tSTRICT_EQUAL, tSTRICT_NOT_EQUAL:
		return 7
	case tLESS, tGREATER, tLESS_OR_EQUAL, tGREATER_OR_EQUAL, tINSTANCEOF:
		return 8
	case tIN:
		if p.allowIn {
			return 8
		}
		return 0
	case tSHL, tSHR, tUSHR:
		return 9
	case tPLUS, tMINUS:
		return 10
	case tMULTIPLY, tSLASH, tREMAINDER:
		return 11
	case tEXPONENT:
		return 12
	}
	return 0
}

func (p *parser) parseBinary(minPrec int) Expr {
	idx := p.tok.idx
	var left Expr
	left = p.parseUnaryExpression()
	for {
		prec := p.binPrec(p.tok.tok)
		if prec == 0 || prec <= minPrec {
			if !(prec == 12 && minPrec == 12) {
				break
			}
		}
		op := p.tok.tok
		if op == tEXPONENT {
			if u, ok := left.(*UnaryExpr); ok {
				_ = u
				p.error(p.tok.idx, "Unary operator used immediately before exponentiation expression. Parenthesis must be used to disambiguate operator precedence")
			}
		}
		p.next()
		var right Expr
		if op == tEXPONENT {
			right = p.parseBinary(prec - 1) // right assoc
		} else {
			right = p.parseBinary(prec)
		}
		switch op {
		case tLAND, tLOR, tNULLISH:
			left = &LogicalExpr{base{idx}, op, left, right}
		default:
			left = &BinaryExpr{base{idx}, op, left, right}
		}
	}
	return left
}

func (p *parser) parseUnaryExpression() Expr {
	switch p.tok.tok {
	case tPLUS, tMINUS, tNOT, tBITWISE_NOT, tDELETE, tVOID, tTYPEOF:
		op := p.tok.tok
		idx := p.tok.idx
		p.next()
		operand := p.parseUnaryExpression()
		return &UnaryExpr{base{idx}, op, operand}
	case tINCREMENT, tDECREMENT:
		op := p.tok.tok
		idx := p.tok.idx
		p.next()
		operand := p.parseUnaryExpression()
		switch operand.(type) {
		case *Identifier, *MemberExpr:
		default:
			p.error(idx, "Invalid left-hand side in assignment")
			p.nextStatement()
			return &BadExpr{base{idx}}
		}
		return &UpdateExpr{base{idx}, op, true, operand}
	case tIDENT:
		if p.tok.value == "await" && p.fn.isAsync {
			idx := p.tok.idx
			p.next()
			return &AwaitExpr{base{idx}, p.parseUnaryExpression()}
		}
	}
	return p.parsePostfixExpression()
}

func (p *parser) parsePostfixExpression() Expr {
	operand := p.parseLeftHandSideExpressionAllowCall()
	return p.continueFromPostfix(operand)
}

func (p *parser) continueFromPostfix(operand Expr) Expr {
	switch p.tok.tok {
	case tINCREMENT, tDECREMENT:
		if p.l.implicitSemicolon {
			break
		}
		op := p.tok.tok
		idx := p.tok.idx
		p.next()
		switch operand.(type) {
		case *Identifier, *MemberExpr:
		default:
			p.error(idx, "Invalid left-hand side in assignment")
			p.nextStatement()
			return &BadExpr{base{idx}}
		}
		return &UpdateExpr{base{operand.Pos()}, op, false, operand}
	}
	return operand
}

func (p *parser) parseLeftHandSideExpressionAllowCall() Expr {
	allowIn := p.allowIn
	p.allowIn = true
	defer func() { p.allowIn = allowIn }()
	var left Expr
	if p.tok.tok == tNEW {
		left = p.parseNewExpression()
	} else {
		left = p.parsePrimaryExpression()
	}
	return p.continueLeftHandSide(left)
}

func (p *parser) continueLeftHandSide(left Expr) Expr {
	start := left.Pos()
	optionalChain := false
	for {
		switch p.tok.tok {
		case tPERIOD:
			left = p.parseDotMember(left, false)
		case tLEFT_BRACKET:
			left = p.parseBracketMember(left, false)
		case tLEFT_PAREN:
			left = p.parseCallExpression(left)
		case tBACKTICK:
			if optionalChain {
				p.error(p.tok.idx, "Invalid template literal on optional chain")
				p.nextStatement()
				return &BadExpr{base{start}}
			}
			left = p.parseTemplateLiteral(left)
		case tQUESTION_DOT:
			optionalChain = true
			nt := p.peek()
			switch nt.tok {
			case tLEFT_BRACKET:
				p.next()
				left = p.parseBracketMember(left, true)
			case tLEFT_PAREN:
				p.next()
				c := p.parseCallExpression(left).(*CallExpr)
				c.Optional = true
				left = c
			case tBACKTICK:
				p.next()
				p.error(p.tok.idx, "Invalid template literal on optional chain")
				p.nextStatement()
				return &BadExpr{base{start}}
			default:
				left = p.parseDotMember(left, true)
			}
		default:
			if optionalChain {
				left = &OptionalChain{base{start}, left}
			}
			return left
		}
	}
}

func (p *parser) parseDotMember(left Expr, optional bool) Expr {
	period := p.tok.idx
	p.next()
	t := p.tok
	if t.tok == tPRIVATE_IDENT {
		p.next()
		return &MemberExpr{base: base{left.Pos()}, Object: left, Name: "#" + t.value, Optional: optional, Private: true}
	}
	if !isIdTok(t) {
		p.expect(tIDENT)
		p.nextStatement()
		return &BadExpr{base{period}}
	}
	p.next()
	name := t.value
	if t.tok != tIDENT {
		name = t.literal
	}
	return &MemberExpr{base: base{left.Pos()}, Object: left, Name: name, Optional: optional}
}

func (p *parser) parseBracketMember(left Expr, optional bool) Expr {
	p.expect(tLEFT_BRACKET)
	member := p.parseExpression()
	p.expect(tRIGHT_BRACKET)
	return &MemberExpr{base: base{left.Pos()}, Object: left, Prop: member, Computed: true, Optional: optional}
}

func (p *parser) parseArgumentList() []Expr {
	var args []Expr
	p.expect(tLEFT_PAREN)
	for p.tok.tok != tRIGHT_PAREN {
		var item Expr
		if p.tok.tok == tELLIPSIS {
			idx := p.tok.idx
			p.next()
			item = &SpreadElem{base{idx}, p.parseAssignmentExpression()}
		} else {
			item = p.parseAssignmentExpression()
		}
		args = append(args, item)
		if p.tok.tok != tCOMMA {
			break
		}
		p.next()
	}
	p.expect(tRIGHT_PAREN)
	return args
}

func (p *parser) parseCallExpression(left Expr) Expr {
	idx := left.Pos()
	args := p.parseArgumentList()
	return &CallExpr{base: base{idx}, Callee: left, Args: args}
}

func (p *parser) parseNewExpression() Expr {
	idx := p.expect(tNEW)
	if p.tok.tok == tPERIOD {
		p.next()
		if p.tok.tok == tIDENT && p.tok.value == "target" {
			p.next()
			return &MetaProp{base{idx}, "new", "target"}
		}
		p.errorUnexpectedToken(p.tok)
		p.nextStatement()
		return &BadExpr{base{idx}}
	}
	var callee Expr
	if p.tok.tok == tNEW {
		callee = p.parseNewExpression()
	} else {
		callee = p.parsePrimaryExpression()
	}
	// member accesses
	for {
		if p.tok.tok == tPERIOD {
			callee = p.parseDotMember(callee, false)
		} else if p.tok.tok == tLEFT_BRACKET {
			callee = p.parseBracketMember(callee, false)
		} else if p.tok.tok == tBACKTICK {
			callee = p.parseTemplateLiteral(callee)
		} else {
			break
		}
	}
	n := &NewExpr{base: base{idx}, Callee: callee}
	if p.tok.tok == tLEFT_PAREN {
		n.Args = p.parseArgumentList()
	}
	return n
}

func (p *parser) numberValue(t token) Expr {
	lit := strings.ReplaceAll(t.literal, "_", "")
	if t.tok == tBIGINT {
		s := lit[:len(lit)-1]
		b := new(big.Int)
		var ok bool
		if len(s) > 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X') {
			_, ok = b.SetString(s[2:], 16)
		} else if len(s) > 2 && s[0] == '0' && (s[1] == 'o' || s[1] == 'O') {
			_, ok = b.SetString(s[2:], 8)
		} else if len(s) > 2 && s[0] == '0' && (s[1] == 'b' || s[1] == 'B') {
			_, ok = b.SetString(s[2:], 2)
		} else {
			if strings.ContainsAny(s, ".eE") || (len(s) > 1 && s[0] == '0') {
				ok = false
			} else {
				_, ok = b.SetString(s, 10)
			}
		}
		if !ok {
			p.error(t.idx, "Illegal numeric literal")
			return &BigIntLit{base{t.idx}, big.NewInt(0)}
		}
		return &BigIntLit{base{t.idx}, b}
	}
	v, err := parseNumberLiteral(lit)
	if err {
		p.error(t.idx, "Illegal numeric literal")
	}
	return &NumberLit{base{t.idx}, v, t.literal, t.octal}
}

func parseNumberLiteral(lit string) (float64, bool) {
	if len(lit) > 1 && lit[0] == '0' {
		switch lit[1] {
		case 'x', 'X':
			return parseIntBase(lit[2:], 16)
		case 'o', 'O':
			return parseIntBase(lit[2:], 8)
		case 'b', 'B':
			return parseIntBase(lit[2:], 2)
		case '.', 'e', 'E':
		default:
			// legacy octal
			allOct := true
			for _, c := range lit[1:] {
				if c < '0' || c > '7' {
					allOct = false
				}
			}
			if allOct {
				return parseIntBase(lit[1:], 8)
			}
		}
	}
	v, err := strconv.ParseFloat(lit, 64)
	if err != nil {
		if ne, ok := err.(*strconv.NumError); ok && ne.Err == strconv.ErrRange {
			return v, false
		}
		return 0, true
	}
	return v, false
}

func parseIntBase(s string, base int) (float64, bool) {
	if s == "" {
		return 0, true
	}
	if u, err := strconv.ParseUint(s, base, 64); err == nil {
		return float64(u), false
	}
	b := new(big.Int)
	if _, ok := b.SetString(s, base); !ok {
		return 0, true
	}
	f, _ := new(big.Float).SetInt(b).Float64()
	if math.IsInf(f, 0) {
		return f, false
	}
	return f, false
}

func (p *parser) parsePrimaryExpression() Expr {
	t := p.tok
	idx := t.idx
	switch t.tok {
	case tIDENT:
		if t.value == "async" && !t.escaped {
			nt := p.peek()
			if nt.tok == tFUNCTION {
				s := p.mark()
				p.next()
				if !p.l.newlineBefore {
					return p.parseFunction(false, true, idx)
				}
				p.restore(s)
			}
		}
		p.next()
		return &Identifier{base{idx}, t.value}
	case tNULL:
		p.next()
		return &NullLit{base{idx}}
	case tBOOLEAN:
		p.next()
		return &BoolLit{base{idx}, t.literal == "true"}
	case tSTRING:
		p.next()
		return &StringLit{base{idx}, t.value, t.literal}
	case tNUMBER, tBIGINT:
		p.next()
		return p.numberValue(t)
	case tSLASH, tQUO_ASSIGN:
		return p.parseRegExpLiteral()
	case tLEFT_BRACE:
		return p.parseObjectLiteral()
	case tLEFT_BRACKET:
		return p.parseArrayLiteral()
	case tLEFT_PAREN:
		return p.parseParenthesisedExpression()
	case tBACKTICK:
		return p.parseTemplateLiteral(nil)
	case tTHIS:
		p.next()
		return &ThisExpr{base{idx}}
	case tSUPER:
		p.next()
		if p.tok.tok != tPERIOD && p.tok.tok != tLEFT_BRACKET && p.tok.tok != tLEFT_PAREN {
			p.errorUnexpectedToken(p.tok)
			p.nextStatement()
			return &BadExpr{base{idx}}
		}
		return &SuperExpr{base{idx}}
	case tFUNCTION:
		return p.parseFunction(false, false, idx)
	case tCLASS:
		return p.parseClass(false)
	case tPRIVATE_IDENT:
		p.next()
		if p.tok.tok == tIN {
			return &StringLit{base{idx}, "#" + t.value, t.literal}
		}
		return &Identifier{base{idx}, "#" + t.value}
	}
	p.errorUnexpectedToken(t)
	p.nextStatement()
	return &BadExpr{base{idx}}
}

func (p *parser) parseRegExpLiteral() Expr {
	idx := p.tok.idx
	pattern, flags, ok, msg := p.l.scanRegExp(idx)
	if !ok {
		p.error(idx, msg)
		// resync: continue scanning after the offending line
		p.l.insertSemicolon = false
		p.next()
		return &BadExpr{base{idx}}
	}
	p.next()
	return &RegExpLit{base{idx}, pattern, flags}
}

func (p *parser) parseParenthesisedExpression() Expr {
	opening := p.tok.idx
	p.expect(tLEFT_PAREN)
	var list []Expr
	if p.tok.tok != tRIGHT_PAREN {
		for {
			if p.tok.tok == tELLIPSIS {
				start := p.tok.idx
				p.errorUnexpectedToken(p.tok)
				p.next()
				p.parseAssignmentExpression()
				list = append(list, &BadExpr{base{start}})
			} else {
				list = append(list, p.parseAssignmentExpression())
			}
			if p.tok.tok != tCOMMA {
				break
			}
			p.next()
			if p.tok.tok == tRIGHT_PAREN {
				p.errorUnexpectedToken(p.tok)
				break
			}
		}
	}
	p.expect(tRIGHT_PAREN)
	if len(list) == 1 && len(p.errors) == 0 {
		return &ParenExpr{base{opening}, list[0]}
	}
	if len(list) == 0 {
		p.errorUnexpectedToken(token{tok: tRIGHT_PAREN, idx: p.tok.idx})
		return &BadExpr{base{opening}}
	}
	if len(list) == 1 {
		return &ParenExpr{base{opening}, list[0]}
	}
	return &ParenExpr{base{opening}, &SeqExpr{base{opening}, list}}
}

func (p *parser) parseArrayLiteral() Expr {
	idx := p.expect(tLEFT_BRACKET)
	a := &ArrayLit{base: base{idx}}
	for p.tok.tok != tRIGHT_BRACKET && p.tok.tok != tEOF {
		if p.tok.tok == tCOMMA {
			p.next()
			a.Elems = append(a.Elems, nil)
			continue
		}
		if p.tok.tok == tELLIPSIS {
			sidx := p.tok.idx
			p.next()
			a.Elems = append(a.Elems, &SpreadElem{base{sidx}, p.parseAssignmentExpression()})
		} else {
			a.Elems = append(a.Elems, p.parseAssignmentExpression())
		}
		if p.tok.tok != tRIGHT_BRACKET {
			p.expect(tCOMMA)
		}
	}
	p.expect(tRIGHT_BRACKET)
	return a
}

func (p *parser) parseObjectLiteral() Expr {
	idx := p.expect(tLEFT_BRACE)
	o := &ObjectLit{base: base{idx}}
	for p.tok.tok != tRIGHT_BRACE && p.tok.tok != tEOF {
		prop := p.parseObjectProperty()
		if prop != nil {
			o.Props = append(o.Props, prop)
		}
		if p.tok.tok != tRIGHT_BRACE {
			p.expect(tCOMMA)
		} else {
			break
		}
	}
	p.expect(tRIGHT_BRACE)
	return o
}

func (p *parser) parseObjectProperty() *Property {
	if p.tok.tok == tELLIPSIS {
		idx := p.tok.idx
		p.next()
		return &Property{Kind: propSpread, Value: p.parseAssignmentExpression(), idx: idx}
	}
	start := p.tok.idx
	t := p.tok
	async := false
	generator := false
	kind := propInit
	if t.tok == tIDENT && (t.value == "get" || t.value == "set" || t.value == "async") && !t.escaped {
		nt := p.peek()
		switch nt.tok {
		case tCOMMA, tRIGHT_BRACE, tCOLON, tLEFT_PAREN, tASSIGN:
		default:
			p.next()
			switch t.value {
			case "get":
				kind = propGet
			case "set":
				kind = propSet
			case "async":
				async = true
				kind = propMethod
			}
		}
	}
	if p.tok.tok == tMULTIPLY {
		p.next()
		generator = true
		kind = propMethod
	}
	keyTok := p.tok
	key, name, computed := p.parsePropertyKey()
	if kind == propGet || kind == propSet || async || generator || p.tok.tok == tLEFT_PAREN {
		if kind == propInit {
			kind = propMethod
		}
		f := p.parseMethod(start, async, generator, kind)
		if name != "" && !computed {
			f.Name = &Identifier{base{keyTok.idx}, name}
		}
		return &Property{Kind: kind, Key: key, Name: name, Computed: computed, Value: f, idx: start}
	}
	if p.tok.tok == tCOLON {
		p.next()
		v := p.parseAssignmentExpression()
		return &Property{Kind: propInit, Key: key, Name: name, Computed: computed, Value: v, idx: start}
	}
	// shorthand
	if keyTok.tok != tIDENT || computed {
		p.errorUnexpectedToken(p.tok)
		return nil
	}
	id := &Identifier{base{keyTok.idx}, name}
	if p.tok.tok == tASSIGN {
		// cover initialized name
		aidx := p.tok.idx
		p.next()
		v := p.parseAssignmentExpression()
		return &Property{Kind: propInit, Key: key, Name: name, Value: &AssignExpr{base{aidx}, tASSIGN, id, v}, Shorthand: true, idx: start}
	}
	return &Property{Kind: propInit, Key: key, Name: name, Value: id, Shorthand: true, idx: start}
}

func (p *parser) parseMethod(start int, async, generator bool, kind PropKind) *FuncLit {
	f := &FuncLit{base: base{start}, IsAsync: async, IsGenerator: generator, IsMethod: true}
	saved := p.fn
	p.fn = &funcCtx{isAsync: async, isGenerator: generator, inFunction: true, allowSuper: true, inClass: saved.inClass}
	ps, defs, rest, _ := p.tryParseParams()
	f.Params, f.Defaults, f.Rest = ps, defs, rest
	p.expect(tLEFT_BRACE)
	f.Body = p.parseStatementList()
	end := p.tok.idx
	p.expect(tRIGHT_BRACE)
	f.Source = p.slice(start, end+1)
	p.fn = saved
	return f
}

func (p *parser) parseFunction(declaration bool, async bool, start int) *FuncLit {
	if async {
		// current token is 'function' after async
	}
	p.expect(tFUNCTION)
	f := &FuncLit{base: base{start}, IsAsync: async}
	if p.tok.tok == tMULTIPLY {
		f.IsGenerator = true
		p.next()
	}
	if p.tok.tok == tIDENT {
		f.Name = &Identifier{base{p.tok.idx}, p.tok.value}
		p.next()
	} else if declaration {
		p.errorUnexpectedToken(p.tok)
	}
	saved := p.fn
	p.fn = &funcCtx{isAsync: async, isGenerator: f.IsGenerator, inFunction: true}
	ps, defs, rest, _ := p.tryParseParams()
	f.Params, f.Defaults, f.Rest = ps, defs, rest
	p.expect(tLEFT_BRACE)
	f.Body = p.parseStatementList()
	end := p.tok.idx
	p.expect(tRIGHT_BRACE)
	f.Source = p.slice(start, end+1)
	p.fn = saved
	return f
}

func (p *parser) parseClass(declaration bool) *ClassLit {
	start := p.tok.idx
	p.expect(tCLASS)
	c := &ClassLit{base: base{start}}
	if p.tok.tok == tIDENT && p.tok.value != "extends" {
		c.Name = &Identifier{base{p.tok.idx}, p.tok.value}
		p.next()
	} else if declaration {
		p.errorUnexpectedToken(p.tok)
	}
	if p.tok.tok == tEXTENDS {
		p.next()
		c.Super = p.parseLeftHandSideExpressionAllowCall()
	}
	p.expect(tLEFT_BRACE)
	saved := p.fn
	for p.tok.tok != tRIGHT_BRACE && p.tok.tok != tEOF {
		if p.tok.tok == tSEMICOLON {
			p.next()
			continue
		}
		mstart := p.tok.idx
		m := &ClassMember{idx: mstart}
		if p.tok.tok == tIDENT && p.tok.value == "static" {
			nt := p.peek()
			if nt.tok != tLEFT_PAREN && nt.tok != tASSIGN && nt.tok != tSEMICOLON && nt.tok != tRIGHT_BRACE {
				p.next()
				m.Static = true
				if p.tok.tok == tLEFT_BRACE {
					p.fn = &funcCtx{inFunction: true, allowSuper: true, inClass: true}
					p.next()
					m.IsBlock = true
					m.Block = p.parseStatementList()
					p.expect(tRIGHT_BRACE)
					p.fn = saved
					c.Members = append(c.Members, m)
					continue
				}
			}
		}
		async, generator := false, false
		kind := propMethod
		t := p.tok
		if t.tok == tIDENT && (t.value == "get" || t.value == "set" || t.value == "async") {
			nt := p.peek()
			switch nt.tok {
			case tLEFT_PAREN, tASSIGN, tSEMICOLON, tRIGHT_BRACE:
			default:
				p.next()
				switch t.value {
				case "get":
					kind = propGet
				case "set":
					kind = propSet
				case "async":
					async = true
				}
			}
		}
		if p.tok.tok == tMULTIPLY {
			p.next()
			generator = true
		}
		if p.tok.tok == tPRIVATE_IDENT {
			m.Private = true
		}
		keyTok := p.tok
		key, name, computed := p.parsePropertyKey()
		m.Key, m.Name, m.Computed = key, name, computed
		if p.tok.tok == tLEFT_PAREN {
			p.fn = &funcCtx{inClass: true}
			f := p.parseMethod(mstart, async, generator, kind)
			p.fn = saved
			if !computed {
				f.Name = &Identifier{base{keyTok.idx}, name}
			}
			m.Kind = kind
			m.Value = f
			if !m.Static && !computed && name == "constructor" && kind == propMethod && keyTok.tok != tPRIVATE_IDENT {
				f.IsCtor = true
				f.Name = nil
				c.Ctor = f
				continue
			}
		} else {
			m.Kind = propInit
			if p.tok.tok == tASSIGN {
				p.next()
				p.fn = &funcCtx{inFunction: true, allowSuper: true, inClass: true}
				m.Value = p.parseAssignmentExpression()
				p.fn = saved
			}
			p.semicolon()
		}
		c.Members = append(c.Members, m)
	}
	end := p.tok.idx
	p.expect(tRIGHT_BRACE)
	c.Source = p.slice(start, end+1)
	return c
}

func (p *parser) parseTemplateLiteral(tag Expr) Expr {
	idx := p.tok.idx
	if tag != nil {
		idx = tag.Pos()
	}
	tl := &TemplateLit{base: base{idx}, Tag: tag}
	// lexer is positioned right after the backtick
	for {
		cooked, cookOK, raw, finished, ok := p.l.scanTemplatePart()
		if !ok {
			p.error(p.l.off, "Unexpected end of input")
			p.l.insertSemicolon = false
			p.next()
			return &BadExpr{base{idx}}
		}
		tl.Cooked = append(tl.Cooked, cooked)
		tl.CookOK = append(tl.CookOK, cookOK)
		tl.Raws = append(tl.Raws, raw)
		if !cookOK && tag == nil {
			p.error(p.l.off, "Invalid escape sequence in template")
		}
		if finished {
			break
		}
		p.l.insertSemicolon = false
		p.next()
		e := p.parseExpression()
		tl.Exprs = append(tl.Exprs, e)
		if p.tok.tok != tRIGHT_BRACE {
			p.errorUnexpectedToken(p.tok)
			p.l.insertSemicolon = false
			p.next()
			return &BadExpr{base{idx}}
		}
		// lexer is right after '}'
	}
	p.l.insertSemicolon = true
	p.next()
	return tl
}
