type Property struct {
	Value        Value
	Getter       *Object
	Setter       *Object
	Accessor     bool
	Writable     bool
	Enumerable   bool
	Configurable bool
}

type NativeFunc func(this Value, args []Value) Value
type NativeCtor func(args []Value, newTarget *Object) Value

type Object struct {
	Class      string
	Proto      *Object
	props      map[Value]*Property
	keys       []Value
	Extensible bool

	IsArr bool
	Arr   []Value // nil entries are holes
	arrLenWritable bool

	Call      NativeFunc
	Construct NativeCtor
	Closure   *Closure

	Internal interface{}
	rt       *Runtime
}

func (o *Object) IsCallable() bool {
	return o.Call != nil || o.Closure != nil
}

func (o *Object) IsConstructor() bool {
	if o.Construct != nil {
		return true
	}
	if o.Closure != nil {
		l := o.Closure.Lit
		if l != nil {
			return !l.IsArrow && !l.IsMethod && !l.IsAsync && !l.IsGenerator || l.IsCtor || o.Closure.classCtor
		}
		return o.Closure.classCtor
	}
	return false
}

// arrayIndex parses s as array index.
func arrayIndex(s string) (int, bool) {
	n := len(s)
	if n == 0 || n > 10 {
		return 0, false
	}
	if s[0] == '0' {
		return 0, n == 1
	}
	v := 0
	for i := 0; i < n; i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0, false
		}
		v = v*10 + int(c-'0')
	}
	if v >= 4294967295 {
		return 0, false
	}
	return v, true
}

func (o *Object) getOwnProp(key Value) *Property {
	if o.IsArr {
		if s, ok := key.(string); ok {
			if idx, ok := arrayIndex(s); ok {
				if idx < len(o.Arr) && o.Arr[idx] != nil {
					return &Property{Value: o.Arr[idx], Writable: !o.isFrozenArr(), Enumerable: true, Configurable: !o.isFrozenArr()}
				}
				return nil
			}
			if s == "length" {
				return &Property{Value: float64(len(o.Arr)), Writable: o.arrLenWritable}
			}
		}
	}
	if o.Class == "String" {
		if s, ok := key.(string); ok {
			str := o.Internal.(string)
			if idx, ok := arrayIndex(s); ok {
				if idx < strLen(str) {
					return &Property{Value: strSub(str, idx, idx+1), Enumerable: true}
				}
			}
			if s == "length" {
				return &Property{Value: float64(strLen(str))}
			}
		}
	}
	if ta, ok := o.Internal.(*typedArray); ok {
		if s, ok := key.(string); ok {
			if idx, ok := arrayIndex(s); ok {
				if idx < ta.length {
					return &Property{Value: ta.get(idx), Writable: true, Enumerable: true, Configurable: true}
				}
				return nil
			}
		}
	}
	if o.props == nil {
		return nil
	}
	return o.props[key]
}

func (o *Object) isFrozenArr() bool {
	if o.Internal == frozenMarker {
		return true
	}
	return false
}

var frozenMarker = &struct{ x int }{1}

func (o *Object) setOwn(key Value, p *Property) {
	if o.props == nil {
		o.props = make(map[Value]*Property)
	}
	if _, exists := o.props[key]; !exists {
		o.keys = append(o.keys, key)
	}
	o.props[key] = p
}

// DefineData sets an own data property (enumerable, writable, configurable).
func (o *Object) Set(key string, v Value) {
