// DefineHidden sets a non-enumerable own property.
func (o *Object) DefineHidden(key Value, v Value) {
	o.setOwn(key, &Property{Value: v, Writable: true, Enumerable: false, Configurable: true})
}

func (o *Object) setIndex(idx int, v Value) {
	if idx < len(o.Arr) {
		o.Arr[idx] = v
		return
	}
	if idx > len(o.Arr)+50000000 {
		panic(o.rt.newRangeError("Invalid array length"))
	}
	for len(o.Arr) < idx {
		o.Arr = append(o.Arr, nil)
	}
	o.Arr = append(o.Arr, v)
}

func (o *Object) deleteOwn(key Value) bool {
	if o.IsArr {
		if s, ok := key.(string); ok {
			if idx, ok := arrayIndex(s); ok {
				if idx < len(o.Arr) {
					if o.isFrozenArr() {
