					}
					o.Arr[idx] = nil
				}
				return true
			}
			if s == "length" {
				return false
			}
		}
	}
	if o.props == nil {
		return true
	}
	p, ok := o.props[key]
	if !ok {
		return true
	}
	if !p.Configurable {
		return false
	}
	delete(o.props, key)
	for i, k := range o.keys {
		if k == key {
			copy(o.keys[i:], o.keys[i+1:])
			o.keys = o.keys[:len(o.keys)-1]
			break
		}
	}
	return true
}

// OwnKeys returns own property keys in spec order. If includeSymbols false, only strings.
func (o *Object) OwnKeys(includeSymbols bool) []Value {
	var res []Value
	if o.IsArr {
		for i, v := range o.Arr {
			if v != nil {
				res = append(res, strconv.Itoa(i))
			}
		}
	}
	if o.Class == "String" {
		n := strLen(o.Internal.(string))
		for i := 0; i < n; i++ {
			res = append(res, strconv.Itoa(i))
		}
	}
	if ta, ok := o.Internal.(*typedArray); ok {
		for i := 0; i < ta.length; i++ {
			res = append(res, strconv.Itoa(i))
		}
	}
	if len(o.keys) == 0 {
		if o.IsArr {
			res = append(res, "length")
		} else if o.Class == "String" {
			res = append(res, "length")
		}
		return res
	}
	var idxKeys []int
	var strKeys []Value
	var symKeys []Value
	for _, k := range o.keys {
		switch kk := k.(type) {
		case string:
			if idx, ok := arrayIndex(kk); ok && !o.IsArr {
				idxKeys = append(idxKeys, idx)
			} else {
				strKeys = append(strKeys, k)
			}
		case *Symbol:
			symKeys = append(symKeys, k)
		}
	}
	if len(idxKeys) > 0 {
		sort.Ints(idxKeys)
		for _, i := range idxKeys {
			res = append(res, strconv.Itoa(i))
		}
	}
	if o.IsArr || o.Class == "String" {
		res = append(res, "length")
	}
	res = append(res, strKeys...)
	if includeSymbols {
		res = append(res, symKeys...)
	}
	return res
}

