func (r *Runtime) getProp(o *Object, key Value, receiver Value) Value {
	for obj := o; obj != nil; obj = obj.Proto {
		if obj.Internal != nil {
			if px, ok := obj.Internal.(*proxyData); ok {
				return r.proxyGet(obj, px, key, receiver)
