			return p.Value
		}
	}
	return Undefined
}

func (r *Runtime) Get(o *Object, key Value) Value {
	return r.getProp(o, key, o)
}

func (r *Runtime) GetStr(o *Object, key string) Value {
	return r.getProp(o, key, o)
}

func (r *Runtime) findProp(o *Object, key Value) (*Property, *Object) {
	for obj := o; obj != nil; obj = obj.Proto {
		p := obj.getOwnProp(key)
		if p != nil {
			return p, obj
		}
	}
	return nil, nil
}

// setProp implements [[Set]] with strict semantics (throws on failure).
func (r *Runtime) setProp(o *Object, key Value, v Value, receiver Value) {
	if px, ok := o.Internal.(*proxyData); ok {
		r.proxySet(o, px, key, v, receiver)
		return
	}
	// fast path for arrays
	if o.IsArr && receiver == Value(o) {
		if s, ok := key.(string); ok {
			if idx, ok := arrayIndex(s); ok {
				if o.isFrozenArr() {
					panic(r.newTypeError("Cannot assign to read only property '" + s + "' of object '" + r.safeToString(o) + "'"))
				}
				if idx < len(o.Arr) && o.Arr[idx] != nil {
					o.Arr[idx] = v
