				panic(r.newTypeError("Cannot assign to read only property '" + keyToDisplay(key) + "' of object '[object String]'"))
			}
			panic(r.newTypeError("Cannot assign to read only property '" + keyToDisplay(key) + "' of object '" + r.safeToString(receiver) + "'"))
		}
