func (r *Runtime) setArrayLength(o *Object, v Value) {
	f := r.toNumber(v)
	n := toUint32(f)
	if float64(n) != f {
		panic(r.newRangeError("Invalid array length"))
	}
	if !o.arrLenWritable && o.Internal == frozenMarker {
		panic(r.newTypeError("Cannot assign to read only property 'length' of object '[object Array]'"))
	}
	ln := int(n)
	if ln < len(o.Arr) {
		for i := ln; i < len(o.Arr); i++ {
			o.Arr[i] = nil
		}
		o.Arr = o.Arr[:ln]
	} else {
		if ln > len(o.Arr)+50000000 {
