	for obj := o; obj != nil; obj = obj.Proto {
		if px, ok := obj.Internal.(*proxyData); ok {
			return r.proxyHas(obj, px, key)
		}
		if obj.getOwnProp(key) != nil {
			return true
		}
	}
	return false
}

func (r *Runtime) hasOwnProperty(o *Object, key Value) bool {
	return o.getOwnProp(key) != nil
}

func (r *Runtime) deleteProp(o *Object, key Value) bool {
	if px, ok := o.Internal.(*proxyData); ok {
		return r.proxyDelete(o, px, key)
	}
	if !o.deleteOwn(key) {
