	SymbolProto, BigIntProto, ErrorProto, DateProto, RegExpProto, MapProto, SetProto *Object
	WeakMapProto, WeakSetProto, PromiseProto, IteratorProto, ArrayIteratorProto, GeneratorProto *Object
	StringIteratorProto, MapIteratorProto, SetIteratorProto, RegExpStringIteratorProto *Object
