func (r *Runtime) newObject() *Object {
	return &Object{Class: "Object", Proto: r.ObjectProto, Extensible: true, rt: r}
}

func (r *Runtime) newObjectProto(proto *Object) *Object {
	return &Object{Class: "Object", Proto: proto, Extensible: true, rt: r}
}

func (r *Runtime) newArray(vals []Value) *Object {
	return &Object{Class: "Array", Proto: r.ArrayProto, Extensible: true, IsArr: true, Arr: vals, rt: r, arrLenWritable: true}
}

func (r *Runtime) NewArray(vals []Value) *Object { return r.newArray(vals) }
func (r *Runtime) NewObject() *Object           { return r.newObject() }

// ---------- errors ----------

func (r *Runtime) makeError(kind string, msg string) *Object {
	proto := r.errorProtos[kind]
	if proto == nil {
		proto = r.ErrorProto
	}
	o := &Object{Class: "Error", Proto: proto, Extensible: true, rt: r}
	o.DefineHidden("message", msg)
	o.DefineHidden("stack", kind+": "+msg)
	return o
}

func (r *Runtime) newTypeError(msg string) *Throw {
	return &Throw{r.makeError("TypeError", msg)}
}

func (r *Runtime) newRangeError(msg string) *Throw {
	return &Throw{r.makeError("RangeError", msg)}
}

func (r *Runtime) newReferenceError(msg string) *Throw {
	return &Throw{r.makeError("ReferenceError", msg)}
}

func (r *Runtime) newSyntaxError(msg string) *Throw {
	return &Throw{r.makeError("SyntaxError", msg)}
}

func (r *Runtime) newError(msg string) *Throw {
	return &Throw{r.makeError("Error", msg)}
}

func (r *Runtime) throwTypeError(msg string) {
	panic(r.newTypeError(msg))
}

// ---------- conversions ----------

func (r *Runtime) toPrimitive(v Value, hint string) Value {
	o, ok := v.(*Object)
	if !ok {
		return v
	}
	if ex := r.getProp(o, r.symToPrimitive, o); !isNullish(ex) {
		fn, ok := ex.(*Object)
		if !ok || !fn.IsCallable() {
			r.throwTypeError("Cannot convert object to primitive value")
		}
		h := hint
		if h == "" {
			h = "default"
		}
		res := r.call(fn, o, []Value{h})
		if _, isObj := res.(*Object); isObj {
			r.throwTypeError("Cannot convert object to primitive value")
		}
		return res
	}
	order := []string{"valueOf", "toString"}
	if hint == "string" {
		order = []string{"toString", "valueOf"}
	}
	for _, name := range order {
		m := r.getProp(o, name, o)
		if fn, ok := m.(*Object); ok && fn.IsCallable() {
			res := r.call(fn, o, nil)
			if _, isObj := res.(*Object); !isObj {
				return res
			}
		}
	}
	r.throwTypeError("Cannot convert object to primitive value")
	return nil
}

func (r *Runtime) toNumber(v Value) float64 {
	switch x := v.(type) {
	case float64:
		return x
	case undefinedType:
		return math.NaN()
	case nullType:
		return 0
	case bool:
		if x {
