					}
					key := r.memberKey(m, s)
					if o, ok := obj.(*Object); ok {
						res = r.deleteProp(o, key)
					}
				}
			}()
			return res
		case *Identifier:
			return false
		}
		r.eval(n.Operand, s)
		return true
	case tVOID:
		r.eval(n.Operand, s)
		return Undefined
	case tNOT:
		return !toBoolean(r.eval(n.Operand, s))
	}
	v := r.eval(n.Operand, s)
	switch n.Op {
	case tMINUS:
		nv := r.toNumeric(v)
		if b, ok := nv.(*big.Int); ok {
			return new(big.Int).Neg(b)
		}
		return -nv.(float64)
	case tPLUS:
		return r.toNumber(v)
	case tBITWISE_NOT:
		nv := r.toNumeric(v)
		if b, ok := nv.(*big.Int); ok {
			return new(big.Int).Not(b)
		}
		return float64(^toInt32(nv.(float64)))
	}
	panic(r.newSyntaxError("bad unary"))
}

func (r *Runtime) evalUpdate(n *UpdateExpr, s *Scope) Value {
	get, set := r.reference(n.Target, s)
	old := r.toNumeric(get())
	var nv Value
	switch x := old.(type) {
	case float64:
		if n.Op == tINCREMENT {
			nv = x + 1
		} else {
			nv = x - 1
		}
	case *big.Int:
		if n.Op == tINCREMENT {
			nv = new(big.Int).Add(x, big.NewInt(1))
		} else {
			nv = new(big.Int).Sub(x, big.NewInt(1))
		}
	}
	set(nv)
	if n.Prefix {
		return nv
	}
	return old
}

// reference returns getter and setter closures for an lvalue expression.
func (r *Runtime) reference(e Expr, s *Scope) (func() Value, func(Value)) {
	switch t := e.(type) {
	case *Identifier:
		return func() Value { return r.lookupIdent(t.Name, s) }, func(v Value) { r.assignIdent(t.Name, v, s) }
	case *ParenExpr:
		return r.reference(t.Expr, s)
	case *MemberExpr:
		if _, isSuper := t.Object.(*SuperExpr); isSuper {
			key := r.memberKey(t, s)
			this := r.thisValue(s)
			return func() Value {
					home := s.fr.home
					if home == nil || home.Proto == nil {
						return Undefined
					}
					return r.getProp(home.Proto, key, this)
				}, func(v Value) {
					r.putV(this, key, v)
				}
		}
		obj := r.eval(t.Object, s)
		if t.Private {
			return func() Value { return r.getPrivate(obj, t.Name, s) }, func(v Value) { r.setPrivate(obj, t.Name, v, s) }
		}
		key := r.memberKey(t, s)
		return func() Value {
				if isNullish(obj) {
					panic(r.newTypeError("Cannot read property '" + r.keyName(key) + "' of undefined"))
				}
				return r.getV(obj, key)
			}, func(v Value) {
				r.putV(obj, key, v)
			}
	}
	panic(r.newSyntaxError("Invalid left-hand side in assignment"))
}

func (r *Runtime) evalAssign(n *AssignExpr, s *Scope) Value {
	if n.Op == tASSIGN {
		switch t := n.Target.(type) {
		case *Identifier:
			v := r.eval(n.Value, s)
			if f, ok := n.Value.(*FuncLit); ok && f.Name == nil {
				r.setFunctionName(v, t.Name, "")
			} else if c, ok := n.Value.(*ClassLit); ok && c.Name == nil {
				r.setFunctionName(v, t.Name, "")
			}
			r.assignIdent(t.Name, v, s)
			return v
		case *MemberExpr:
			if _, isSuper := t.Object.(*SuperExpr); isSuper {
				_, set := r.reference(t, s)
				v := r.eval(n.Value, s)
				set(v)
				return v
			}
			obj := r.eval(t.Object, s)
			if t.Private {
				v := r.eval(n.Value, s)
				r.setPrivate(obj, t.Name, v, s)
				return v
			}
			key := r.memberKey(t, s)
			v := r.eval(n.Value, s)
			if o, ok := obj.(*Object); ok && o.IsArr {
				if ks, ok := key.(string); ok {
					if idx, ok := arrayIndex(ks); ok && idx < len(o.Arr) && o.Arr[idx] != nil && o.Proto == r.ArrayProto && o.Internal == nil {
						o.Arr[idx] = v
						return v
					}
				}
			}
			r.putV(obj, key, v)
			return v
		case *ObjectPattern, *ArrayPattern:
			v := r.eval(n.Value, s)
			r.bindPattern(t, v, s, bindAssign)
			return v
		case *ParenExpr:
			return r.evalAssign(&AssignExpr{n.base, n.Op, t.Expr, n.Value}, s)
		}
		panic(r.newSyntaxError("Invalid left-hand side in assignment"))
	}
	get, set := r.reference(n.Target, s)
	old := get()
	switch n.Op {
	case tLAND:
		if !toBoolean(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	case tLOR:
		if toBoolean(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	case tNULLISH:
		if !isNullish(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	}
	rv := r.eval(n.Value, s)
	v := r.binaryOp(n.Op, old, rv)
	set(v)
	return v
}

// ---------- statements ----------

func (r *Runtime) execStmts(list []Stmt, s *Scope) result {
	for _, st := range list {
		res := r.exec(st, s)
		if res.c != cNormal {
			return res
		}
	}
	return normalResult
}

func (r *Runtime) exec(st Stmt, s *Scope) result {
	switch n := st.(type) {
	case *ExprStmt:
		r.eval(n.X, s)
		return normalResult
	case *VarDecl:
		r.execVarDecl(n, s)
		return normalResult
	case *ReturnStmt:
		var v Value = Undefined
		if n.Arg != nil {
			v = r.eval(n.Arg, s)
		}
		return result{c: cReturn, v: v}
	case *IfStmt:
		if toBoolean(r.eval(n.Test, s)) {
			return r.exec(n.Cons, s)
		} else if n.Alt != nil {
			return r.exec(n.Alt, s)
		}
		return normalResult
	case *BlockStmt:
		bs := s
		if blockNeedsScope(n) {
			bs = newScope(s)
			r.hoistLexical(n.List, bs)
		}
		return r.execStmts(n.List, bs)
	case *ForStmt:
		return r.execFor(n, s, "")
	case *ForInStmt:
		return r.execForIn(n, s, "")
	case *WhileStmt:
		return r.execWhile(n, s, "")
	case *DoWhileStmt:
		return r.execDoWhile(n, s, "")
	case *EmptyStmt:
		return normalResult
	case *FuncDecl:
		return normalResult
	case *ClassDecl:
		v := r.evalClass(n.Class, s)
		sc, i := s.find(n.Class.Name.Name)
		if sc != nil {
			sc.vars[i].v = v
			sc.vars[i].init = true
		}
		return normalResult
	case *BreakStmt:
		return result{c: cBreak, label: n.Label}
	case *ContinueStmt:
		return result{c: cContinue, label: n.Label}
	case *ThrowStmt:
		v := r.eval(n.Arg, s)
		panic(&Throw{v})
	case *TryStmt:
		return r.execTry(n, s)
	case *SwitchStmt:
		return r.execSwitch(n, s)
	case *LabeledStmt:
		var res result
		switch body := n.Body.(type) {
		case *ForStmt:
			res = r.execFor(body, s, n.Label)
		case *ForInStmt:
			res = r.execForIn(body, s, n.Label)
		case *WhileStmt:
			res = r.execWhile(body, s, n.Label)
		case *DoWhileStmt:
			res = r.execDoWhile(body, s, n.Label)
		default:
			res = r.exec(n.Body, s)
		}
		if res.c == cBreak && res.label == n.Label {
			return normalResult
		}
		return res
	case *DebuggerStmt:
		return normalResult
	case *WithStmt:
		panic(r.newSyntaxError("Strict mode code may not include a with statement"))
	case *BadStmt:
		panic(r.newSyntaxError("Unexpected token"))
	}
	panic(r.newSyntaxError("Unsupported statement"))
}

func blockNeedsScope(b *BlockStmt) bool {
	for _, st := range b.List {
		switch d := st.(type) {
		case *VarDecl:
			if d.Kind != tVAR {
				return true
			}
		case *FuncDecl, *ClassDecl:
			return true
		}
	}
	return false
}

func (r *Runtime) execVarDecl(n *VarDecl, s *Scope) {
	kind := bindVar
	if n.Kind == tCONST {
		kind = bindConst
	} else if n.Kind != tVAR {
		kind = bindLet
	}
	for _, d := range n.Decls {
		if d.Init == nil {
			if kind == bindVar {
				continue
			}
			r.bindPattern(d.Target, Undefined, s, kind)
			continue
		}
		v := r.eval(d.Init, s)
		if id, ok := d.Target.(*Identifier); ok {
			if f, ok := d.Init.(*FuncLit); ok && f.Name == nil {
				r.setFunctionName(v, id.Name, "")
			} else if c, ok := d.Init.(*ClassLit); ok && c.Name == nil {
				r.setFunctionName(v, id.Name, "")
			}
		}
		r.bindPattern(d.Target, v, s, kind)
	}
}

func loopContinues(res result, label string) (stop bool, out result) {
	switch res.c {
	case cBreak:
		if res.label == "" || res.label == label {
			return true, normalResult
		}
		return true, res
	case cContinue:
		if res.label == "" || res.label == label {
			return false, normalResult
		}
		return true, res
	case cReturn:
		return true, res
	}
	return false, normalResult
}

func (r *Runtime) execFor(n *ForStmt, s *Scope, label string) result {
	ls := s
	var letNames []string
	if d, ok := n.Init.(*VarDecl); ok && d.Kind != tVAR {
		ls = newScope(s)
		for _, dc := range d.Decls {
			for _, name := range patternNames(dc.Target) {
				ls.declare(name, Undefined, d.Kind == tCONST, false)
				letNames = append(letNames, name)
			}
		}
		r.execVarDecl(d, ls)
	} else if d, ok := n.Init.(*VarDecl); ok {
		r.execVarDecl(d, s)
	} else if e, ok := n.Init.(Expr); ok && e != nil {
		r.eval(e, s)
	}
	iter := ls
	copyScope := func() *Scope {
		if len(letNames) == 0 {
			return ls
		}
		ns := newScope(s)
		for _, name := range letNames {
			_, i := iter.find(name)
			b := iter.vars[i]
			ns.declare(name, b.v, b.cnst, b.init)
		}
		return ns
	}
	iter = copyScope()
	for {
		if n.Test != nil {
			if !toBoolean(r.eval(n.Test, iter)) {
				break
			}
		}
		res := r.exec(n.Body, iter)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
		iter = copyScope()
		if n.Update != nil {
			r.eval(n.Update, iter)
		}
	}
	return normalResult
}

func (r *Runtime) execWhile(n *WhileStmt, s *Scope, label string) result {
	for toBoolean(r.eval(n.Test, s)) {
		res := r.exec(n.Body, s)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
	}
	return normalResult
}

func (r *Runtime) execDoWhile(n *DoWhileStmt, s *Scope, label string) result {
	for {
		res := r.exec(n.Body, s)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
		if !toBoolean(r.eval(n.Test, s)) {
			break
		}
	}
	return normalResult
}

func (r *Runtime) execForIn(n *ForInStmt, s *Scope, label string) result {
	var decl *VarDecl
	if d, ok := n.Left.(*VarDecl); ok {
		decl = d
	}
	bindOne := func(v Value) *Scope {
		if decl != nil {
			if decl.Kind == tVAR {
				r.bindPattern(decl.Decls[0].Target, v, s, bindVar)
				return s
			}
			ns := newScope(s)
			kind := bindLet
			if decl.Kind == tCONST {
				kind = bindConst
			}
			for _, name := range patternNames(decl.Decls[0].Target) {
				ns.declare(name, Undefined, decl.Kind == tCONST, false)
			}
			r.bindPattern(decl.Decls[0].Target, v, ns, kind)
			return ns
		}
		r.bindPattern(n.Left, v, s, bindAssign)
		return s
	}
	var out result
	if n.Of {
		var rhsScope = s
		if decl != nil && decl.Kind != tVAR {
			rhsScope = newScope(s)
			for _, name := range patternNames(decl.Decls[0].Target) {
				rhsScope.declare(name, Undefined, false, false)
			}
		}
		coll := r.eval(n.Right, rhsScope)
		r.iterate(coll, func(v Value) bool {
			bs := bindOne(v)
			res := r.exec(n.Body, bs)
			stop, o := loopContinues(res, label)
			if stop {
				out = o
				return false
			}
			return true
		})
		return out
	}
	coll := r.eval(n.Right, s)
	if isNullish(coll) {
		return normalResult
	}
	obj := r.toObject(coll)
	visited := map[string]bool{}
	for o := obj; o != nil; o = o.Proto {
		keys := r.ownKeys(o, false)
		for _, k := range keys {
			ks, ok := k.(string)
			if !ok {
				continue
			}
			if visited[ks] {
				continue
			}
			visited[ks] = true
			p := r.getOwnPropertyFull(o, ks)
			if p == nil || !p.Enumerable {
				continue
			}
			bs := bindOne(ks)
			res := r.exec(n.Body, bs)
			if stop, o := loopContinues(res, label); stop {
				return o
			}
		}
	}
	return normalResult
}

func (r *Runtime) execTry(n *TryStmt, s *Scope) (res result) {
	if n.Finalizer != nil {
		defer func() {
			rec := recover()
			fres := r.exec(n.Finalizer, s)
			if fres.c != cNormal {
				res = fres
				return
			}
			if rec != nil {
				panic(rec)
			}
		}()
	}
	if n.Handler == nil {
		return r.exec(n.Block, s)
	}
	thrown, caught, bres := r.tryBlock(n.Block, s)
	if !caught {
		return bres
	}
	cs := newScope(s)
	if n.Param != nil {
		for _, name := range patternNames(n.Param) {
			cs.declare(name, Undefined, false, false)
		}
		r.bindPattern(n.Param, thrown, cs, bindLet)
	}
	return r.exec(n.Handler, cs)
}

func (r *Runtime) tryBlock(b *BlockStmt, s *Scope) (thrown Value, caught bool, res result) {
	depth := r.callDepth
	defer func() {
		if rec := recover(); rec != nil {
			r.callDepth = depth
			if t, ok := rec.(*Throw); ok {
				thrown = t.Value
				caught = true
				return
			}
			panic(rec)
		}
	}()
	res = r.exec(b, s)
	return nil, false, res
}

func (r *Runtime) execSwitch(n *SwitchStmt, s *Scope) result {
	d := r.eval(n.Disc, s)
	bs := newScope(s)
	var all []Stmt
	for _, c := range n.Cases {
		all = append(all, c.Body...)
	}
	r.hoistLexical(all, bs)
	matched := -1
	for i, c := range n.Cases {
		if c.Test == nil {
			continue
		}
		if strictEquals(d, r.eval(c.Test, bs)) {
			matched = i
			break
		}
	}
	if matched < 0 {
		for i, c := range n.Cases {
			if c.Test == nil {
				matched = i
				break
			}
		}
	}
	if matched < 0 {
		return normalResult
	}
	for i := matched; i < len(n.Cases); i++ {
		res := r.execStmts(n.Cases[i].Body, bs)
		if res.c == cBreak && res.label == "" {
			return normalResult
		}
		if res.c != cNormal {
			return res
		}
	}
	return normalResult
}
