package js

import (
	"math"
	"math/big"
	"strconv"
)

type ctrl int

const (
	cNormal ctrl = iota
	cBreak
	cContinue
	cReturn
)

type result struct {
	c     ctrl
	label string
	v     Value
}

var normalResult = result{}

// ---------- identifiers ----------

func (r *Runtime) lookupIdent(name string, s *Scope) Value {
	sc, i := s.find(name)
	if sc != nil {
		b := &sc.vars[i]
		if !b.init {
			panic(r.newReferenceError("Cannot access a variable before initialization"))
		}
		return b.v
	}
	if name == "arguments" {
		if v, ok := r.argumentsObject(s); ok {
			return v
		}
	}
	if p, _ := r.findProp(r.Global, name); p != nil {
		if p.Accessor {
			if p.Getter == nil {
				return Undefined
			}
			return r.call(p.Getter, r.Global, nil)
		}
		return p.Value
	}
	panic(r.newReferenceError(name + " is not defined"))
}

func (r *Runtime) argumentsObject(s *Scope) (Value, bool) {
	for sc := s; sc != nil; sc = sc.parent {
		if sc.isFunc && sc.fr != nil && sc.fr.closure != nil && !sc.fr.closure.Lit.IsArrow {
			fr := sc.fr
			if fr.argsObj == nil {
				vals := make([]Value, len(fr.args))
				copy(vals, fr.args)
				a := &Object{Class: "Arguments", Proto: r.ObjectProto, Extensible: true, IsArr: true, Arr: vals, rt: r, arrLenWritable: true}
				a.DefineHidden(r.symIterator, r.GetStr(r.ArrayProto, "values"))
				fr.argsObj = a
			}
			return fr.argsObj, true
		}
	}
	return nil, false
}

func (r *Runtime) assignIdent(name string, v Value, s *Scope) {
	sc, i := s.find(name)
	if sc != nil {
		b := &sc.vars[i]
		if !b.init {
			panic(r.newReferenceError("Cannot access a variable before initialization"))
		}
		if b.cnst {
			panic(r.newTypeError("Assignment to constant variable."))
		}
		b.v = v
		return
	}
	if p, owner := r.findProp(r.Global, name); p != nil {
		_ = owner
		r.setProp(r.Global, name, v, r.Global)
		return
	}
	panic(r.newReferenceError(name + " is not defined"))
}

// ---------- property access ----------

func (r *Runtime) keyName(key Value) string {
	switch k := key.(type) {
	case string:
		return k
	case *Symbol:
		return k.String()
	}
	return r.toString(key)
}

func (r *Runtime) getV(v Value, key Value) Value {
	switch x := v.(type) {
	case *Object:
		if x.IsArr {
			if s, ok := key.(string); ok {
				if idx, ok := arrayIndex(s); ok {
					if idx < len(x.Arr) {
						if e := x.Arr[idx]; e != nil {
							return e
						}
					}
				} else if s == "length" {
					return float64(len(x.Arr))
				}
			}
		}
		return r.getProp(x, key, x)
	case string:
		if s, ok := key.(string); ok {
			if s == "length" {
				return float64(strLen(x))
			}
			if idx, ok := arrayIndex(s); ok {
				if idx < strLen(x) {
					return strSub(x, idx, idx+1)
				}
				return Undefined
			}
		}
		return r.getProp(r.StringProto, key, x)
	case undefinedType, nullType:
		panic(r.newTypeError("Cannot read property '" + r.keyName(key) + "' of undefined"))
	default:
		proto := r.protoOf(v)
		if proto == nil {
			return Undefined
		}
		return r.getProp(proto, key, v)
	}
}

// fast numeric index access
func (r *Runtime) getIndexed(v Value, f float64) (Value, bool) {
	if o, ok := v.(*Object); ok && o.IsArr {
		if f >= 0 && f < float64(len(o.Arr)) && f == math.Trunc(f) {
			if e := o.Arr[int(f)]; e != nil {
				return e, true
			}
		}
	}
	return nil, false
}

func (r *Runtime) putV(v Value, key Value, val Value) {
	switch x := v.(type) {
	case *Object:
		r.setProp(x, key, val, x)
	case undefinedType, nullType:
		panic(r.newTypeError("Cannot convert undefined or null to object"))
	default:
		proto := r.protoOf(v)
		p, _ := r.findProp(proto, key)
		if p != nil && p.Accessor && p.Setter != nil {
			r.call(p.Setter, v, []Value{val})
			return
		}
		if s, ok := v.(string); ok {
			if k, ok := key.(string); ok {
				if _, isIdx := arrayIndex(k); isIdx || k == "length" {
					panic(r.newTypeError("Cannot assign to read only property '" + k + "' of string '" + s + "'"))
				}
			}
		}
		panic(r.newTypeError("Cannot create property '" + r.keyName(key) + "' on " + typeOf(v) + " '" + r.safeToString(v) + "'"))
	}
}

// ---------- calls ----------

func (r *Runtime) call(fn *Object, this Value, args []Value) Value {
	if fn.Call != nil {
		return fn.Call(this, args)
	}
	if fn.Closure != nil {
		return r.callClosure(fn, fn.Closure, this, args, nil)
	}
	panic(r.newTypeError("Not a function: " + r.safeToString(fn)))
}

func (r *Runtime) Call(fn Value, this Value, args ...Value) Value {
	f, ok := fn.(*Object)
	if !ok || !f.IsCallable() {
		panic(r.newTypeError("Value is not an object: " + r.safeToString(fn)))
	}
	return r.call(f, this, args)
}

func (r *Runtime) callValue(fn Value, this Value, args []Value) Value {
	f, ok := fn.(*Object)
	if !ok {
		panic(r.newTypeError("Value is not an object: " + r.safeToString(fn)))
	}
	if !f.IsCallable() {
		panic(r.newTypeError("Not a function: " + r.safeToString(fn)))
	}
	return r.call(f, this, args)
}

func (r *Runtime) construct(fn *Object, args []Value, newTarget *Object) Value {
	if newTarget == nil {
		newTarget = fn
	}
	if fn.Construct != nil {
		return fn.Construct(args, newTarget)
	}
	if fn.Closure != nil && fn.IsConstructor() {
		return r.constructClosure(fn, args, newTarget)
	}
	panic(r.newTypeError("Value is not a constructor"))
}

func (r *Runtime) getPrototypeFromCtor(newTarget *Object, def *Object) *Object {
	if newTarget == nil {
		return def
	}
	p := r.GetStr(newTarget, "prototype")
	if po, ok := p.(*Object); ok {
		return po
	}
	return def
}

func (r *Runtime) evalArgs(args []Expr, s *Scope) []Value {
	if len(args) == 0 {
		return nil
	}
	res := make([]Value, 0, len(args))
	for _, a := range args {
		if sp, ok := a.(*SpreadElem); ok {
			v := r.eval(sp.Arg, s)
			r.iterate(v, func(x Value) bool {
				res = append(res, x)
				return true
			})
			continue
		}
		res = append(res, r.eval(a, s))
	}
	return res
}

type optShort struct{}

var optShortCircuit = &optShort{}

func (r *Runtime) evalCall(e *CallExpr, s *Scope) Value {
	var this Value = Undefined
	var fnv Value
	switch c := e.Callee.(type) {
	case *MemberExpr:
		if _, isSuper := c.Object.(*SuperExpr); isSuper {
			key := r.memberKey(c, s)
			home := s.fr.home
			var proto *Object
			if home != nil {
				proto = home.Proto
			}
			this = r.thisValue(s)
			if proto != nil {
				fnv = r.getProp(proto, key, this)
			} else {
				fnv = Undefined
			}
			break
		}
		obj := r.eval(c.Object, s)
		if c.Optional && isNullish(obj) {
			panic(optShortCircuit)
		}
		key := r.memberKey(c, s)
		if isNullish(obj) {
			panic(r.newTypeError("Cannot read property '" + r.keyName(key) + "' of undefined or null"))
		}
		this = obj
		if c.Private {
			fnv = r.getPrivate(obj, c.Name, s)
		} else {
			fnv = r.getV(obj, key)
		}
		if e.Optional && isNullish(fnv) {
			panic(optShortCircuit)
		}
		f, ok := fnv.(*Object)
		if !ok || !f.IsCallable() {
			if _, isU := fnv.(undefinedType); isU {
				panic(r.newTypeError("Object has no member '" + r.keyName(key) + "'"))
			}
			if ok {
				panic(r.newTypeError("Not a function: " + r.safeToString(fnv)))
			}
			panic(r.newTypeError("Value is not an object: " + r.safeToString(fnv)))
		}
		args := r.evalArgs(e.Args, s)
		return r.call(f, this, args)
	case *SuperExpr:
		return r.superCall(e, s)
	case *ParenExpr:
		if m, ok := c.Expr.(*MemberExpr); ok {
			return r.evalCall(&CallExpr{base: e.base, Callee: m, Args: e.Args, Optional: e.Optional}, s)
		}
		fnv = r.eval(c, s)
	default:
		fnv = r.eval(e.Callee, s)
	}
	if e.Optional && isNullish(fnv) {
		panic(optShortCircuit)
	}
	f, ok := fnv.(*Object)
	if !ok {
		panic(r.newTypeError("Value is not an object: " + r.safeToString(fnv)))
	}
	if !f.IsCallable() {
		panic(r.newTypeError("Not a function: " + r.safeToString(fnv)))
	}
	args := r.evalArgs(e.Args, s)
	return r.call(f, this, args)
}

func (r *Runtime) memberKey(m *MemberExpr, s *Scope) Value {
	if m.Computed {
		k := r.eval(m.Prop, s)
		switch kk := k.(type) {
		case string:
			return kk
		case float64:
			if kk >= 0 && kk < 1e9 && kk == math.Trunc(kk) {
				return strconv.Itoa(int(kk))
			}
		}
		return r.toPropertyKey(k)
	}
	return m.Name
}

func (r *Runtime) thisValue(s *Scope) Value {
	fr := s.fr
	if fr == nil {
		return Undefined
	}
	if fr.derived && !fr.thisInit {
		panic(r.newReferenceError("Must call super constructor in derived class before accessing 'this' or returning from derived constructor"))
	}
	return fr.this
}

// ---------- expression evaluation ----------

func (r *Runtime) eval(e Expr, s *Scope) Value {
	switch n := e.(type) {
	case *Identifier:
		if n.Name == "undefined" {
			if sc, _ := s.find("undefined"); sc == nil {
				return Undefined
			}
		}
		return r.lookupIdent(n.Name, s)
	case *NumberLit:
		return n.Value
	case *StringLit:
		return n.Value
	case *BoolLit:
		return n.Value
	case *NullLit:
		return Null
	case *BigIntLit:
		return n.Value
	case *ThisExpr:
		return r.thisValue(s)
	case *ParenExpr:
		return r.eval(n.Expr, s)
	case *TemplateLit:
		return r.evalTemplate(n, s)
	case *RegExpLit:
		return r.newRegExp(n.Pattern, n.Flags)
	case *ArrayLit:
		vals := make([]Value, 0, len(n.Elems))
		for _, el := range n.Elems {
			if el == nil {
				vals = append(vals, nil)
				continue
			}
			if sp, ok := el.(*SpreadElem); ok {
				v := r.eval(sp.Arg, s)
				r.iterate(v, func(x Value) bool {
					vals = append(vals, x)
					return true
				})
				continue
			}
			vals = append(vals, r.eval(el, s))
		}
		return r.newArray(vals)
	case *ObjectLit:
		return r.evalObjectLit(n, s)
	case *FuncLit:
		return r.makeClosure(n, s, nil)
	case *ClassLit:
		return r.evalClass(n, s)
	case *UnaryExpr:
		return r.evalUnary(n, s)
	case *UpdateExpr:
		return r.evalUpdate(n, s)
	case *BinaryExpr:
		l := r.eval(n.Left, s)
		rv := r.eval(n.Right, s)
		return r.binaryOp(n.Op, l, rv)
	case *LogicalExpr:
		l := r.eval(n.Left, s)
		switch n.Op {
		case tLAND:
			if !toBoolean(l) {
				return l
			}
		case tLOR:
			if toBoolean(l) {
				return l
			}
		case tNULLISH:
			if !isNullish(l) {
				return l
			}
		}
		return r.eval(n.Right, s)
	case *CondExpr:
		if toBoolean(r.eval(n.Test, s)) {
			return r.eval(n.Cons, s)
		}
		return r.eval(n.Alt, s)
	case *AssignExpr:
		return r.evalAssign(n, s)
	case *SeqExpr:
		var v Value = Undefined
		for _, x := range n.List {
			v = r.eval(x, s)
		}
		return v
	case *CallExpr:
		return r.evalCall(n, s)
	case *NewExpr:
		cv := r.eval(n.Callee, s)
		args := r.evalArgs(n.Args, s)
		f, ok := cv.(*Object)
		if !ok {
			panic(r.newTypeError("Value is not an object: " + r.safeToString(cv)))
		}
		if !f.IsConstructor() {
			panic(r.newTypeError("Value is not a constructor"))
		}
		return r.construct(f, args, f)
	case *MemberExpr:
		if _, isSuper := n.Object.(*SuperExpr); isSuper {
			key := r.memberKey(n, s)
			home := s.fr.home
			if home == nil || home.Proto == nil {
				return Undefined
			}
			return r.getProp(home.Proto, key, r.thisValue(s))
		}
		obj := r.eval(n.Object, s)
		if n.Optional && isNullish(obj) {
			panic(optShortCircuit)
		}
		if n.Private {
			return r.getPrivate(obj, n.Name, s)
		}
		if n.Computed {
			k := r.eval(n.Prop, s)
			if f, ok := k.(float64); ok {
				if v, ok := r.getIndexed(obj, f); ok {
					return v
				}
			}
			if isNullish(obj) {
				panic(r.newTypeError("Cannot read property '" + r.keyName(r.toPropertyKey(k)) + "' of undefined"))
			}
			return r.getV(obj, r.toPropertyKey(k))
		}
		return r.getV(obj, n.Name)
	case *OptionalChain:
		return r.evalOptional(n, s)
	case *SpreadElem:
		panic(r.newSyntaxError("Unexpected spread"))
	case *MetaProp:
		if s.fr != nil && s.fr.newTarget != nil {
			return s.fr.newTarget
		}
		return Undefined
	case *YieldExpr:
		return r.evalYield(n, s)
	case *AwaitExpr:
		return r.evalAwait(n, s)
	case *BadExpr:
		panic(r.newSyntaxError("Unexpected token"))
	}
	panic(r.newSyntaxError("Unsupported expression"))
}

func (r *Runtime) evalOptional(n *OptionalChain, s *Scope) (res Value) {
	defer func() {
		if rec := recover(); rec != nil {
			if rec == optShortCircuit {
				res = Undefined
				return
			}
			panic(rec)
		}
	}()
	return r.eval(n.Expr, s)
}

func (r *Runtime) evalTemplate(n *TemplateLit, s *Scope) Value {
	if n.Tag != nil {
		var this Value = Undefined
		var fnv Value
		if m, ok := n.Tag.(*MemberExpr); ok {
			obj := r.eval(m.Object, s)
			this = obj
			fnv = r.getV(obj, r.memberKey(m, s))
		} else {
			fnv = r.eval(n.Tag, s)
		}
		if n.cache == nil {
			cooked := make([]Value, len(n.Cooked))
			raws := make([]Value, len(n.Raws))
			for i := range n.Cooked {
				if n.CookOK[i] {
					cooked[i] = n.Cooked[i]
				} else {
					cooked[i] = Undefined
				}
				raws[i] = n.Raws[i]
			}
			arr := r.newArray(cooked)
			rawArr := r.newArray(raws)
			arr.DefineHidden("raw", rawArr)
			n.cache = arr
		}
		args := []Value{n.cache}
		for _, ex := range n.Exprs {
			args = append(args, r.eval(ex, s))
		}
		return r.callValue(fnv, this, args)
	}
	if len(n.Exprs) == 0 {
		return n.Cooked[0]
	}
	buf := make([]byte, 0, 32)
	buf = append(buf, n.Cooked[0]...)
	for i, ex := range n.Exprs {
		v := r.eval(ex, s)
		if sym, ok := v.(*Symbol); ok {
			_ = sym
			r.throwTypeError("Cannot convert a Symbol value to a string")
		}
		buf = append(buf, r.toString(v)...)
		buf = append(buf, n.Cooked[i+1]...)
	}
	return string(buf)
}

func (r *Runtime) evalObjectLit(n *ObjectLit, s *Scope) Value {
	o := r.newObject()
	for _, p := range n.Props {
		switch p.Kind {
		case propSpread:
			v := r.eval(p.Value, s)
			r.copyDataProperties(o, v, nil)
			continue
		}
		var key Value
		if p.Computed {
			key = r.toPropertyKey(r.eval(p.Key, s))
		} else {
			key = p.Name
		}
		switch p.Kind {
		case propInit:
			v := r.eval(p.Value, s)
			if f, ok := p.Value.(*FuncLit); ok && f.Name == nil {
				r.setFunctionName(v, key, "")
			} else if c, ok := p.Value.(*ClassLit); ok && c.Name == nil {
				r.setFunctionName(v, key, "")
			}
			if key == "__proto__" && !p.Computed && !p.Shorthand {
				if po, ok := v.(*Object); ok {
					o.Proto = po
				} else if _, ok := v.(nullType); ok {
					o.Proto = nil
				}
				continue
			}
			r.createDataProperty(o, key, v)
		case propMethod:
			fl := p.Value.(*FuncLit)
			fn := r.makeClosure(fl, s, o)
			r.setFunctionName(fn, key, "")
			r.createDataProperty(o, key, fn)
		case propGet, propSet:
			fl := p.Value.(*FuncLit)
			fn := r.makeClosure(fl, s, o)
			prefix := "get"
			if p.Kind == propSet {
				prefix = "set"
			}
			r.setFunctionName(fn, key, prefix)
			ex := o.getOwnProp(key)
			np := &Property{Accessor: true, Enumerable: true, Configurable: true}
			if ex != nil && ex.Accessor {
				np.Getter, np.Setter = ex.Getter, ex.Setter
			}
			if p.Kind == propGet {
				np.Getter = fn
			} else {
				np.Setter = fn
			}
			o.setOwn(key, np)
		}
	}
	return o
}

func (r *Runtime) createDataProperty(o *Object, key Value, v Value) {
	if o.IsArr {
		o.putOwn(key, v)
		return
	}
	if o.props != nil {
		if _, ok := o.props[key]; ok {
			o.props[key] = &Property{Value: v, Writable: true, Enumerable: true, Configurable: true}
			return
		}
	}
	o.setOwn(key, &Property{Value: v, Writable: true, Enumerable: true, Configurable: true})
}

func (r *Runtime) copyDataProperties(target *Object, src Value, exclude map[Value]bool) {
	switch x := src.(type) {
	case undefinedType, nullType:
		return
	case string:
		u := toUTF16(x)
		for i := range u {
			k := strconv.Itoa(i)
			if exclude != nil && exclude[k] {
				continue
			}
			r.createDataProperty(target, k, utf16ToString(u[i:i+1]))
		}
		return
	case *Object:
		for _, k := range r.ownKeys(x, true) {
			if exclude != nil && exclude[k] {
				continue
			}
			p := r.getOwnPropertyFull(x, k)
			if p == nil || !p.Enumerable {
				continue
			}
			r.createDataProperty(target, k, r.getProp(x, k, x))
		}
	}
}

func (r *Runtime) setFunctionName(v Value, key Value, prefix string) {
	f, ok := v.(*Object)
	if !ok || !f.IsCallable() {
		return
	}
	if p := f.getOwnProp("name"); p != nil {
		if s, ok := p.Value.(string); ok && s != "" {
			return
		}
		if f.Closure != nil && f.Closure.classCtor {
			// class with static name method etc
		}
	}
	name := ""
	switch k := key.(type) {
	case string:
		name = k
	case *Symbol:
		if k.Description != "" || k.HasDesc {
			name = "[" + k.Description + "]"
		}
	}
	if prefix != "" {
		name = prefix + " " + name
	}
	f.setOwn("name", &Property{Value: name, Configurable: true})
}

func (r *Runtime) evalUnary(n *UnaryExpr, s *Scope) Value {
	switch n.Op {
	case tTYPEOF:
		if id, ok := n.Operand.(*Identifier); ok {
			sc, i := s.find(id.Name)
			if sc == nil {
				if id.Name == "arguments" {
					if v, ok := r.argumentsObject(s); ok {
						return typeOf(v)
					}
				}
				if p, _ := r.findProp(r.Global, id.Name); p == nil {
					return "undefined"
				}
			} else if !sc.vars[i].init {
				panic(r.newReferenceError("Cannot access a variable before initialization"))
			}
		}
		return typeOf(r.eval(n.Operand, s))
	case tDELETE:
		switch t := n.Operand.(type) {
		case *MemberExpr:
			obj := r.eval(t.Object, s)
			key := r.memberKey(t, s)
			if isNullish(obj) {
				panic(r.newTypeError("Cannot convert undefined or null to object"))
			}
			o, ok := obj.(*Object)
			if !ok {
				return true
			}
			return r.deleteProp(o, key)
		case *OptionalChain:
			var res Value = true
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						if rec == optShortCircuit {
							res = true
							return
						}
						panic(rec)
					}
				}()
				if m, ok := t.Expr.(*MemberExpr); ok {
					obj := r.eval(m.Object, s)
					if m.Optional && isNullish(obj) {
						panic(optShortCircuit)
					}
					key := r.memberKey(m, s)
					if o, ok := obj.(*Object); ok {
						res = r.deleteProp(o, key)
					}
				}
			}()
			return res
		case *Identifier:
			return false
		}
		r.eval(n.Operand, s)
		return true
	case tVOID:
		r.eval(n.Operand, s)
		return Undefined
	case tNOT:
		return !toBoolean(r.eval(n.Operand, s))
	}
	v := r.eval(n.Operand, s)
	switch n.Op {
	case tMINUS:
		nv := r.toNumeric(v)
		if b, ok := nv.(*big.Int); ok {
			return new(big.Int).Neg(b)
		}
		return -nv.(float64)
	case tPLUS:
		return r.toNumber(v)
	case tBITWISE_NOT:
		nv := r.toNumeric(v)
		if b, ok := nv.(*big.Int); ok {
			return new(big.Int).Not(b)
		}
		return float64(^toInt32(nv.(float64)))
	}
	panic(r.newSyntaxError("bad unary"))
}

func (r *Runtime) evalUpdate(n *UpdateExpr, s *Scope) Value {
	get, set := r.reference(n.Target, s)
	old := r.toNumeric(get())
	var nv Value
	switch x := old.(type) {
	case float64:
		if n.Op == tINCREMENT {
			nv = x + 1
		} else {
			nv = x - 1
		}
	case *big.Int:
		if n.Op == tINCREMENT {
			nv = new(big.Int).Add(x, big.NewInt(1))
		} else {
			nv = new(big.Int).Sub(x, big.NewInt(1))
		}
	}
	set(nv)
	if n.Prefix {
		return nv
	}
	return old
}

// reference returns getter and setter closures for an lvalue expression.
func (r *Runtime) reference(e Expr, s *Scope) (func() Value, func(Value)) {
	switch t := e.(type) {
	case *Identifier:
		return func() Value { return r.lookupIdent(t.Name, s) }, func(v Value) { r.assignIdent(t.Name, v, s) }
	case *ParenExpr:
		return r.reference(t.Expr, s)
	case *MemberExpr:
		if _, isSuper := t.Object.(*SuperExpr); isSuper {
			key := r.memberKey(t, s)
			this := r.thisValue(s)
			return func() Value {
					home := s.fr.home
					if home == nil || home.Proto == nil {
						return Undefined
					}
					return r.getProp(home.Proto, key, this)
				}, func(v Value) {
					r.putV(this, key, v)
				}
		}
		obj := r.eval(t.Object, s)
		if t.Private {
			return func() Value { return r.getPrivate(obj, t.Name, s) }, func(v Value) { r.setPrivate(obj, t.Name, v, s) }
		}
		key := r.memberKey(t, s)
		return func() Value {
				if isNullish(obj) {
					panic(r.newTypeError("Cannot read property '" + r.keyName(key) + "' of undefined"))
				}
				return r.getV(obj, key)
			}, func(v Value) {
				r.putV(obj, key, v)
			}
	}
	panic(r.newSyntaxError("Invalid left-hand side in assignment"))
}

func (r *Runtime) evalAssign(n *AssignExpr, s *Scope) Value {
	if n.Op == tASSIGN {
		switch t := n.Target.(type) {
		case *Identifier:
			v := r.eval(n.Value, s)
			if f, ok := n.Value.(*FuncLit); ok && f.Name == nil {
				r.setFunctionName(v, t.Name, "")
			} else if c, ok := n.Value.(*ClassLit); ok && c.Name == nil {
				r.setFunctionName(v, t.Name, "")
			}
			r.assignIdent(t.Name, v, s)
			return v
		case *MemberExpr:
			if _, isSuper := t.Object.(*SuperExpr); isSuper {
				_, set := r.reference(t, s)
				v := r.eval(n.Value, s)
				set(v)
				return v
			}
			obj := r.eval(t.Object, s)
			if t.Private {
				v := r.eval(n.Value, s)
				r.setPrivate(obj, t.Name, v, s)
				return v
			}
			key := r.memberKey(t, s)
			v := r.eval(n.Value, s)
			if o, ok := obj.(*Object); ok && o.IsArr {
				if ks, ok := key.(string); ok {
					if idx, ok := arrayIndex(ks); ok && idx < len(o.Arr) && o.Arr[idx] != nil && o.Proto == r.ArrayProto && o.Internal == nil {
						o.Arr[idx] = v
						return v
					}
				}
			}
			r.putV(obj, key, v)
			return v
		case *ObjectPattern, *ArrayPattern:
			v := r.eval(n.Value, s)
			r.bindPattern(t, v, s, bindAssign)
			return v
		case *ParenExpr:
			return r.evalAssign(&AssignExpr{n.base, n.Op, t.Expr, n.Value}, s)
		}
		panic(r.newSyntaxError("Invalid left-hand side in assignment"))
	}
	get, set := r.reference(n.Target, s)
	old := get()
	switch n.Op {
	case tLAND:
		if !toBoolean(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	case tLOR:
		if toBoolean(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	case tNULLISH:
		if !isNullish(old) {
			return old
		}
		v := r.eval(n.Value, s)
		set(v)
		return v
	}
	rv := r.eval(n.Value, s)
	v := r.binaryOp(n.Op, old, rv)
	set(v)
	return v
}

// ---------- statements ----------

func (r *Runtime) execStmts(list []Stmt, s *Scope) result {
	for _, st := range list {
		res := r.exec(st, s)
		if res.c != cNormal {
			return res
		}
	}
	return normalResult
}

func (r *Runtime) exec(st Stmt, s *Scope) result {
	switch n := st.(type) {
	case *ExprStmt:
		r.eval(n.X, s)
		return normalResult
	case *VarDecl:
		r.execVarDecl(n, s)
		return normalResult
	case *ReturnStmt:
		var v Value = Undefined
		if n.Arg != nil {
			v = r.eval(n.Arg, s)
		}
		return result{c: cReturn, v: v}
	case *IfStmt:
		if toBoolean(r.eval(n.Test, s)) {
			return r.exec(n.Cons, s)
		} else if n.Alt != nil {
			return r.exec(n.Alt, s)
		}
		return normalResult
	case *BlockStmt:
		bs := s
		if blockNeedsScope(n) {
			bs = newScope(s)
			r.hoistLexical(n.List, bs)
		}
		return r.execStmts(n.List, bs)
	case *ForStmt:
		return r.execFor(n, s, "")
	case *ForInStmt:
		return r.execForIn(n, s, "")
	case *WhileStmt:
		return r.execWhile(n, s, "")
	case *DoWhileStmt:
		return r.execDoWhile(n, s, "")
	case *EmptyStmt:
		return normalResult
	case *FuncDecl:
		return normalResult
	case *ClassDecl:
		v := r.evalClass(n.Class, s)
		sc, i := s.find(n.Class.Name.Name)
		if sc != nil {
			sc.vars[i].v = v
			sc.vars[i].init = true
		}
		return normalResult
	case *BreakStmt:
		return result{c: cBreak, label: n.Label}
	case *ContinueStmt:
		return result{c: cContinue, label: n.Label}
	case *ThrowStmt:
		v := r.eval(n.Arg, s)
		panic(&Throw{v})
	case *TryStmt:
		return r.execTry(n, s)
	case *SwitchStmt:
		return r.execSwitch(n, s)
	case *LabeledStmt:
		var res result
		switch body := n.Body.(type) {
		case *ForStmt:
			res = r.execFor(body, s, n.Label)
		case *ForInStmt:
			res = r.execForIn(body, s, n.Label)
		case *WhileStmt:
			res = r.execWhile(body, s, n.Label)
		case *DoWhileStmt:
			res = r.execDoWhile(body, s, n.Label)
		default:
			res = r.exec(n.Body, s)
		}
		if res.c == cBreak && res.label == n.Label {
			return normalResult
		}
		return res
	case *DebuggerStmt:
		return normalResult
	case *WithStmt:
		panic(r.newSyntaxError("Strict mode code may not include a with statement"))
	case *BadStmt:
		panic(r.newSyntaxError("Unexpected token"))
	}
	panic(r.newSyntaxError("Unsupported statement"))
}

func blockNeedsScope(b *BlockStmt) bool {
	for _, st := range b.List {
		switch d := st.(type) {
		case *VarDecl:
			if d.Kind != tVAR {
				return true
			}
		case *FuncDecl, *ClassDecl:
			return true
		}
	}
	return false
}

func (r *Runtime) execVarDecl(n *VarDecl, s *Scope) {
	kind := bindVar
	if n.Kind == tCONST {
		kind = bindConst
	} else if n.Kind != tVAR {
		kind = bindLet
	}
	for _, d := range n.Decls {
		if d.Init == nil {
			if kind == bindVar {
				continue
			}
			r.bindPattern(d.Target, Undefined, s, kind)
			continue
		}
		v := r.eval(d.Init, s)
		if id, ok := d.Target.(*Identifier); ok {
			if f, ok := d.Init.(*FuncLit); ok && f.Name == nil {
				r.setFunctionName(v, id.Name, "")
			} else if c, ok := d.Init.(*ClassLit); ok && c.Name == nil {
				r.setFunctionName(v, id.Name, "")
			}
		}
		r.bindPattern(d.Target, v, s, kind)
	}
}

func loopContinues(res result, label string) (stop bool, out result) {
	switch res.c {
	case cBreak:
		if res.label == "" || res.label == label {
			return true, normalResult
		}
		return true, res
	case cContinue:
		if res.label == "" || res.label == label {
			return false, normalResult
		}
		return true, res
	case cReturn:
		return true, res
	}
	return false, normalResult
}

func (r *Runtime) execFor(n *ForStmt, s *Scope, label string) result {
	ls := s
	var letNames []string
	if d, ok := n.Init.(*VarDecl); ok && d.Kind != tVAR {
		ls = newScope(s)
		for _, dc := range d.Decls {
			for _, name := range patternNames(dc.Target) {
				ls.declare(name, Undefined, d.Kind == tCONST, false)
				letNames = append(letNames, name)
			}
		}
		r.execVarDecl(d, ls)
	} else if d, ok := n.Init.(*VarDecl); ok {
		r.execVarDecl(d, s)
	} else if e, ok := n.Init.(Expr); ok && e != nil {
		r.eval(e, s)
	}
	iter := ls
	copyScope := func() *Scope {
		if len(letNames) == 0 {
			return ls
		}
		ns := newScope(s)
		for _, name := range letNames {
			_, i := iter.find(name)
			b := iter.vars[i]
			ns.declare(name, b.v, b.cnst, b.init)
		}
		return ns
	}
	iter = copyScope()
	for {
		if n.Test != nil {
			if !toBoolean(r.eval(n.Test, iter)) {
				break
			}
		}
		res := r.exec(n.Body, iter)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
		iter = copyScope()
		if n.Update != nil {
			r.eval(n.Update, iter)
		}
	}
	return normalResult
}

func (r *Runtime) execWhile(n *WhileStmt, s *Scope, label string) result {
	for toBoolean(r.eval(n.Test, s)) {
		res := r.exec(n.Body, s)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
	}
	return normalResult
}

func (r *Runtime) execDoWhile(n *DoWhileStmt, s *Scope, label string) result {
	for {
		res := r.exec(n.Body, s)
		if stop, out := loopContinues(res, label); stop {
			return out
		}
		if !toBoolean(r.eval(n.Test, s)) {
			break
		}
	}
	return normalResult
}

func (r *Runtime) execForIn(n *ForInStmt, s *Scope, label string) result {
	var decl *VarDecl
	if d, ok := n.Left.(*VarDecl); ok {
		decl = d
	}
	bindOne := func(v Value) *Scope {
		if decl != nil {
			if decl.Kind == tVAR {
				r.bindPattern(decl.Decls[0].Target, v, s, bindVar)
				return s
			}
			ns := newScope(s)
			kind := bindLet
			if decl.Kind == tCONST {
				kind = bindConst
			}
			for _, name := range patternNames(decl.Decls[0].Target) {
				ns.declare(name, Undefined, decl.Kind == tCONST, false)
			}
			r.bindPattern(decl.Decls[0].Target, v, ns, kind)
			return ns
		}
		r.bindPattern(n.Left, v, s, bindAssign)
		return s
	}
	var out result
	if n.Of {
		var rhsScope = s
		if decl != nil && decl.Kind != tVAR {
			rhsScope = newScope(s)
			for _, name := range patternNames(decl.Decls[0].Target) {
				rhsScope.declare(name, Undefined, false, false)
			}
		}
		coll := r.eval(n.Right, rhsScope)
		r.iterate(coll, func(v Value) bool {
			bs := bindOne(v)
			res := r.exec(n.Body, bs)
			stop, o := loopContinues(res, label)
			if stop {
				out = o
				return false
			}
			return true
		})
		return out
	}
	coll := r.eval(n.Right, s)
	if isNullish(coll) {
		return normalResult
	}
	obj := r.toObject(coll)
	visited := map[string]bool{}
	for o := obj; o != nil; o = o.Proto {
		keys := r.ownKeys(o, false)
		for _, k := range keys {
			ks, ok := k.(string)
			if !ok {
				continue
			}
			if visited[ks] {
				continue
			}
			visited[ks] = true
			p := r.getOwnPropertyFull(o, ks)
			if p == nil || !p.Enumerable {
				continue
			}
			bs := bindOne(ks)
			res := r.exec(n.Body, bs)
			if stop, o := loopContinues(res, label); stop {
				return o
			}
		}
	}
	return normalResult
}

func (r *Runtime) execTry(n *TryStmt, s *Scope) (res result) {
	if n.Finalizer != nil {
		defer func() {
			rec := recover()
			fres := r.exec(n.Finalizer, s)
			if fres.c != cNormal {
				res = fres
				return
			}
			if rec != nil {
				panic(rec)
			}
		}()
	}
	if n.Handler == nil {
		return r.exec(n.Block, s)
	}
	thrown, caught, bres := r.tryBlock(n.Block, s)
	if !caught {
		return bres
	}
	cs := newScope(s)
	if n.Param != nil {
		for _, name := range patternNames(n.Param) {
			cs.declare(name, Undefined, false, false)
		}
		r.bindPattern(n.Param, thrown, cs, bindLet)
	}
	return r.exec(n.Handler, cs)
}

func (r *Runtime) tryBlock(b *BlockStmt, s *Scope) (thrown Value, caught bool, res result) {
	depth := r.callDepth
	defer func() {
		if rec := recover(); rec != nil {
			r.callDepth = depth
			if t, ok := rec.(*Throw); ok {
				thrown = t.Value
				caught = true
				return
			}
			panic(rec)
		}
	}()
	res = r.exec(b, s)
	return nil, false, res
}

func (r *Runtime) execSwitch(n *SwitchStmt, s *Scope) result {
	d := r.eval(n.Disc, s)
	bs := newScope(s)
	var all []Stmt
	for _, c := range n.Cases {
		all = append(all, c.Body...)
	}
	r.hoistLexical(all, bs)
	matched := -1
	for i, c := range n.Cases {
		if c.Test == nil {
			continue
		}
		if strictEquals(d, r.eval(c.Test, bs)) {
			matched = i
			break
		}
	}
	if matched < 0 {
		for i, c := range n.Cases {
			if c.Test == nil {
				matched = i
				break
			}
		}
	}
	if matched < 0 {
		return normalResult
	}
	for i := matched; i < len(n.Cases); i++ {
		res := r.execStmts(n.Cases[i].Body, bs)
		if res.c == cBreak && res.label == "" {
			return normalResult
		}
		if res.c != cNormal {
			return res
		}
	}
	return normalResult
}
