func (r *Runtime) enter() {
	r.callDepth++
	if r.callDepth > 20000 {
		r.callDepth = 0
		panic(r.newRangeError("Maximum call stack size exceeded"))
	}
}

func (r *Runtime) callClosure(fnObj *Object, c *Closure, this Value, args []Value, newTarget *Object) Value {
	lit := c.Lit
	if c.classCtor && newTarget == nil {
		panic(r.newTypeError("Class constructor " + r.safeToString(r.GetStr(fnObj, "name")) + " cannot be invoked without 'new'"))
	}
	if lit.IsGenerator {
		return r.makeGenerator(fnObj, c, this, args, lit.IsAsync)
	}
	if lit.IsAsync {
		return r.runAsync(fnObj, c, this, args)
	}
	return r.invoke(fnObj, c, this, args, newTarget)
}

func (r *Runtime) invoke(fnObj *Object, c *Closure, this Value, args []Value, newTarget *Object) Value {
	lit := c.Lit
	r.enter()
	defer func() { r.callDepth-- }()
	var fr *frame
	if lit.IsArrow {
		fr = c.Frame
	} else {
		fr = &frame{this: this, thisInit: true, home: c.Home, fnObj: fnObj, args: args, closure: c}
		if newTarget != nil {
			fr.newTarget = newTarget
		} else {
			fr.newTarget = Undefined
		}
	}
	s := &Scope{parent: c.Scope, fr: fr, isFunc: true}
	if !lit.IsArrow {
		s.fr = fr
	}
	r.bindParams(lit, s, args)
	if lit.ExprBody != nil {
		return r.eval(lit.ExprBody, s)
	}
	r.hoistFunction(lit, s)
	res := r.execStmts(lit.Body, s)
	if res.c == cReturn {
		return res.v
	}
	return Undefined
