package js

import (
	"strconv"
)

type Closure struct {
	Lit       *FuncLit
	Scope     *Scope
	Frame     *frame // captured frame for arrows
	Home      *Object
	classCtor bool
	derived   bool
	class     *classInfo
}

type classInfo struct {
	fields      []*fieldDef
	privateKeys map[string]*privateName
	proto       *Object
	ctor        *Object
	scope       *Scope
}

type fieldDef struct {
	key      Value
	priv     *privateName
	init     Expr
	isMethod bool
	method   *Object
	getter   *Object
	setter   *Object
	scope    *Scope
	home     *Object
}

type privateName struct {
	name string
	id   *int
}

type bindKind int

const (
	bindVar bindKind = iota
	bindLet
	bindConst
	bindAssign
	bindParam
)

func (r *Runtime) makeClosure(lit *FuncLit, s *Scope, home *Object) *Object {
	c := &Closure{Lit: lit, Scope: s, Home: home}
	if lit.IsArrow {
		c.Frame = s.fr
	}
	f := &Object{Class: "Function", Proto: r.FunctionProto, Extensible: true, Closure: c, rt: r}
	if lit.IsAsync {
		f.Proto = r.FunctionProto
	}
	nparams := 0
	for i := range lit.Params {
		if lit.Defaults != nil && i < len(lit.Defaults) && lit.Defaults[i] != nil {
			break
		}
		nparams++
	}
	f.setOwn("length", &Property{Value: float64(nparams), Configurable: true})
	name := ""
	if lit.Name != nil {
		name = lit.Name.Name
	}
	f.setOwn("name", &Property{Value: name, Configurable: true})
	if lit.IsGenerator {
		proto := r.newObjectProto(r.GeneratorProto)
		f.setOwn("prototype", &Property{Value: proto, Writable: true})
	} else if !lit.IsArrow && !lit.IsMethod && !lit.IsAsync {
		proto := r.newObject()
		proto.DefineHidden("constructor", f)
		f.setOwn("prototype", &Property{Value: proto, Writable: true})
	}
	// named function expression binding
	if lit.Name != nil && !lit.IsArrow && !lit.IsMethod {
		ns := newScope(s)
		ns.declare(lit.Name.Name, f, false, true)
		c.Scope = ns
	}
	return f
}

func (r *Runtime) enter() {
	r.callDepth++
	if r.callDepth > 20000 {
		r.callDepth = 0
		panic(r.newRangeError("Maximum call stack size exceeded"))
	}
}

func (r *Runtime) callClosure(fnObj *Object, c *Closure, this Value, args []Value, newTarget *Object) Value {
	lit := c.Lit
	if c.classCtor && newTarget == nil {
		panic(r.newTypeError("Class constructor " + r.safeToString(r.GetStr(fnObj, "name")) + " cannot be invoked without 'new'"))
	}
	if lit.IsGenerator {
		return r.makeGenerator(fnObj, c, this, args, lit.IsAsync)
	}
	if lit.IsAsync {
		return r.runAsync(fnObj, c, this, args)
	}
	return r.invoke(fnObj, c, this, args, newTarget)
}

func (r *Runtime) invoke(fnObj *Object, c *Closure, this Value, args []Value, newTarget *Object) Value {
	lit := c.Lit
	r.enter()
	defer func() { r.callDepth-- }()
	var fr *frame
	if lit.IsArrow {
		fr = c.Frame
	} else {
		fr = &frame{this: this, thisInit: true, home: c.Home, fnObj: fnObj, args: args, closure: c}
		if newTarget != nil {
			fr.newTarget = newTarget
		} else {
			fr.newTarget = Undefined
		}
	}
	s := &Scope{parent: c.Scope, fr: fr, isFunc: true}
	if !lit.IsArrow {
		s.fr = fr
	}
	r.bindParams(lit, s, args)
	if lit.ExprBody != nil {
		return r.eval(lit.ExprBody, s)
	}
	r.hoistFunction(lit, s)
	res := r.execStmts(lit.Body, s)
	if res.c == cReturn {
		return res.v
	}
	return Undefined
}

func (r *Runtime) bindParams(lit *FuncLit, s *Scope, args []Value) {
	simple := true
	for i, p := range lit.Params {
		if _, ok := p.(*Identifier); !ok {
			simple = false
			break
		}
		if lit.Defaults != nil && i < len(lit.Defaults) && lit.Defaults[i] != nil {
			simple = false
			break
		}
	}
	if simple && lit.Rest == nil {
		for i, p := range lit.Params {
			var v Value = Undefined
			if i < len(args) {
				v = args[i]
			}
			s.declare(p.(*Identifier).Name, v, false, true)
		}
		return
	}
	// declare all names first (TDZ for defaults referencing later params)
	for _, p := range lit.Params {
		for _, name := range patternNames(p) {
			s.declare(name, Undefined, false, false)
		}
	}
	if lit.Rest != nil {
		for _, name := range patternNames(lit.Rest) {
			s.declare(name, Undefined, false, false)
		}
	}
	for i, p := range lit.Params {
		var v Value = Undefined
		if i < len(args) {
			v = args[i]
		}
		if lit.Defaults != nil && i < len(lit.Defaults) && lit.Defaults[i] != nil {
			if _, isU := v.(undefinedType); isU {
				v = r.eval(lit.Defaults[i], s)
				if id, ok := p.(*Identifier); ok {
					if f, ok := lit.Defaults[i].(*FuncLit); ok && f.Name == nil {
						r.setFunctionName(v, id.Name, "")
					}
				}
			}
		}
		r.bindPattern(p, v, s, bindParam)
	}
	if lit.Rest != nil {
		var rest []Value
		if len(args) > len(lit.Params) {
			rest = append(rest, args[len(lit.Params):]...)
		}
		r.bindPattern(lit.Rest, r.newArray(rest), s, bindParam)
	}
}

// hoistFunction declares var names and function declarations for a function body.
func (r *Runtime) hoistFunction(lit *FuncLit, s *Scope) {
	if lit.varNames == nil {
		names := []string{}
		seen := map[string]bool{}
		collectVarNames(lit.Body, &names, seen)
		lit.varNames = names
	}
	for _, name := range lit.varNames {
		if s.lookupLocal(name) < 0 {
			s.declare(name, Undefined, false, true)
		}
	}
	r.hoistLexical(lit.Body, s)
}

// HoistProgram hoists for top-level script.
func (r *Runtime) hoistProgram(list []Stmt, s *Scope) {
	names := []string{}
	seen := map[string]bool{}
	collectVarNames(list, &names, seen)
	for _, name := range names {
		if _, i := s.find(name); i < 0 {
			if p := r.Global.getOwnProp(name); p == nil {
				r.Global.putOwn(name, Undefined)
			}
		}
	}
	// function declarations go to global object
	for _, st := range list {
		if fd, ok := st.(*FuncDecl); ok && fd.Func.Name != nil {
			fn := r.makeClosure(fd.Func, s, nil)
			r.Global.putOwn(fd.Func.Name.Name, fn)
		}
	}
	for _, st := range list {
		switch d := st.(type) {
		case *VarDecl:
			if d.Kind != tVAR {
				for _, dc := range d.Decls {
					for _, name := range patternNames(dc.Target) {
						s.declare(name, Undefined, d.Kind == tCONST, false)
					}
				}
			}
		case *ClassDecl:
			if d.Class.Name != nil {
				s.declare(d.Class.Name.Name, Undefined, false, false)
			}
		}
	}
}

func (r *Runtime) hoistLexical(list []Stmt, s *Scope) {
	for _, st := range list {
		switch d := st.(type) {
		case *VarDecl:
			if d.Kind != tVAR {
				for _, dc := range d.Decls {
					for _, name := range patternNames(dc.Target) {
						s.declare(name, Undefined, d.Kind == tCONST, false)
					}
				}
			}
		case *ClassDecl:
			if d.Class.Name != nil {
				s.declare(d.Class.Name.Name, Undefined, false, false)
			}
		}
	}
	for _, st := range list {
		if fd, ok := st.(*FuncDecl); ok && fd.Func.Name != nil {
			fn := r.makeClosure(fd.Func, s, nil)
			s.declare(fd.Func.Name.Name, fn, false, true)
		}
	}
}

func collectVarNames(list []Stmt, names *[]string, seen map[string]bool) {
	for _, st := range list {
		collectVarStmt(st, names, seen)
	}
}

func addName(name string, names *[]string, seen map[string]bool) {
	if !seen[name] {
		seen[name] = true
		*names = append(*names, name)
	}
}

func collectVarStmt(st Stmt, names *[]string, seen map[string]bool) {
	switch n := st.(type) {
	case *VarDecl:
		if n.Kind == tVAR {
			for _, d := range n.Decls {
				for _, name := range patternNames(d.Target) {
					addName(name, names, seen)
				}
			}
		}
	case *IfStmt:
		collectVarStmt(n.Cons, names, seen)
		if n.Alt != nil {
			collectVarStmt(n.Alt, names, seen)
		}
	case *BlockStmt:
		collectVarNames(n.List, names, seen)
	case *ForStmt:
		if d, ok := n.Init.(*VarDecl); ok {
			collectVarStmt(d, names, seen)
		}
		collectVarStmt(n.Body, names, seen)
	case *ForInStmt:
		if d, ok := n.Left.(*VarDecl); ok {
			collectVarStmt(d, names, seen)
		}
		collectVarStmt(n.Body, names, seen)
	case *WhileStmt:
		collectVarStmt(n.Body, names, seen)
	case *DoWhileStmt:
		collectVarStmt(n.Body, names, seen)
	case *TryStmt:
		collectVarStmt(n.Block, names, seen)
		if n.Handler != nil {
			collectVarStmt(n.Handler, names, seen)
		}
		if n.Finalizer != nil {
			collectVarStmt(n.Finalizer, names, seen)
		}
	case *SwitchStmt:
		for _, c := range n.Cases {
			collectVarNames(c.Body, names, seen)
		}
	case *LabeledStmt:
		collectVarStmt(n.Body, names, seen)
	case *WithStmt:
		collectVarStmt(n.Body, names, seen)
	}
}

func patternNames(p Node) []string {
	var out []string
	var walk func(p Node)
	walk = func(p Node) {
		switch t := p.(type) {
		case *Identifier:
			out = append(out, t.Name)
		case *ObjectPattern:
			for _, pp := range t.Props {
				walk(pp.Target)
			}
			if t.Rest != nil {
				walk(t.Rest)
			}
		case *ArrayPattern:
			for _, el := range t.Elems {
				if el.Target != nil {
					walk(el.Target)
				}
			}
			if t.Rest != nil {
				walk(t.Rest)
			}
		case *AssignExpr:
			walk(t.Target)
		}
	}
	walk(p)
	return out
}

// bindPattern binds a value to a pattern.
func (r *Runtime) bindPattern(p Node, v Value, s *Scope, kind bindKind) {
	switch t := p.(type) {
	case *Identifier:
		switch kind {
		case bindAssign:
			r.assignIdent(t.Name, v, s)
		case bindVar:
			sc, i := s.find(t.Name)
			if sc != nil {
				sc.vars[i].v = v
				sc.vars[i].init = true
			} else {
				r.setProp(r.Global, t.Name, v, r.Global)
			}
		default:
			if i := s.lookupLocal(t.Name); i >= 0 {
				s.vars[i].v = v
				s.vars[i].init = true
				if kind == bindConst {
					s.vars[i].cnst = true
				}
			} else {
				s.declare(t.Name, v, kind == bindConst, true)
			}
		}
	case *MemberExpr:
		if kind != bindAssign {
			panic(r.newSyntaxError("Invalid destructuring target"))
		}
		obj := r.eval(t.Object, s)
		if t.Private {
			r.setPrivate(obj, t.Name, v, s)
			return
		}
		key := r.memberKey(t, s)
		r.putV(obj, key, v)
	case *ParenExpr:
		r.bindPattern(t.Expr, v, s, kind)
	case *AssignExpr:
		if _, isU := v.(undefinedType); isU {
			v = r.eval(t.Value, s)
		}
		r.bindPattern(t.Target, v, s, kind)
	case *ObjectPattern:
		if isNullish(v) {
			panic(r.newTypeError("Cannot destructure '" + r.safeToString(v) + "' as it is " + r.safeToString(v) + "."))
		}
		var used map[Value]bool
		if t.Rest != nil {
			used = map[Value]bool{}
		}
		for _, pp := range t.Props {
			var key Value
			if pp.Computed {
				key = r.toPropertyKey(r.eval(pp.Key, s))
			} else {
				key = pp.Name
			}
			if used != nil {
				used[key] = true
			}
			pv := r.getV(v, key)
			if pp.Default != nil {
				if _, isU := pv.(undefinedType); isU {
					pv = r.eval(pp.Default, s)
					if id, ok := pp.Target.(*Identifier); ok {
						if f, ok := pp.Default.(*FuncLit); ok && f.Name == nil {
							r.setFunctionName(pv, id.Name, "")
						}
					}
				}
			}
			r.bindPattern(pp.Target, pv, s, kind)
		}
		if t.Rest != nil {
			rest := r.newObject()
			r.copyDataProperties(rest, v, used)
			r.bindPattern(t.Rest, rest, s, kind)
		}
	case *ArrayPattern:
		var vals []Value
		need := len(t.Elems)
		if o, ok := v.(*Object); ok && o.IsArr && o.Proto == r.ArrayProto && o.Class == "Array" {
			for _, e := range o.Arr {
				if e == nil {
					e = Undefined
				}
				vals = append(vals, e)
			}
		} else {
			count := 0
			r.iterateN(v, func(x Value) bool {
				vals = append(vals, x)
				count++
				return t.Rest != nil || count < need
			}, need == 0 && t.Rest == nil)
		}
		for i, el := range t.Elems {
			var ev Value = Undefined
			if i < len(vals) {
				ev = vals[i]
			}
			if el.Target == nil {
				continue
			}
			if el.Default != nil {
				if _, isU := ev.(undefinedType); isU {
					ev = r.eval(el.Default, s)
					if id, ok := el.Target.(*Identifier); ok {
						if f, ok := el.Default.(*FuncLit); ok && f.Name == nil {
							r.setFunctionName(ev, id.Name, "")
						}
					}
				}
			}
			r.bindPattern(el.Target, ev, s, kind)
		}
		if t.Rest != nil {
			var rest []Value
			if len(vals) > len(t.Elems) {
				rest = append(rest, vals[len(t.Elems):]...)
			}
			r.bindPattern(t.Rest, r.newArray(rest), s, kind)
		}
	default:
		panic(r.newSyntaxError("Invalid destructuring target"))
	}
}

// ---------- constructors ----------

func (r *Runtime) constructClosure(fnObj *Object, args []Value, newTarget *Object) Value {
	c := fnObj.Closure
	if c.derived {
		fr := &frame{thisInit: false, derived: true, home: c.Home, fnObj: fnObj, args: args, closure: c, newTarget: newTarget}
		res := r.invokeWithFrame(fnObj, c, fr, args)
		if o, ok := res.(*Object); ok {
			return o
		}
		if !fr.thisInit {
			panic(r.newReferenceError("Must call super constructor in derived class before accessing 'this' or returning from derived constructor"))
		}
		return fr.this
	}
	proto := r.getPrototypeFromCtor(newTarget, r.ObjectProto)
	obj := r.newObjectProto(proto)
	fr := &frame{this: obj, thisInit: true, home: c.Home, fnObj: fnObj, args: args, closure: c, newTarget: newTarget}
	if c.class != nil {
		r.initFields(obj, c.class)
	}
	res := r.invokeWithFrame(fnObj, c, fr, args)
	if o, ok := res.(*Object); ok {
		return o
	}
	return obj
}

func (r *Runtime) invokeWithFrame(fnObj *Object, c *Closure, fr *frame, args []Value) Value {
	lit := c.Lit
	r.enter()
	defer func() { r.callDepth-- }()
	s := &Scope{parent: c.Scope, fr: fr, isFunc: true}
	if lit == nil {
		return Undefined
	}
	r.bindParams(lit, s, args)
	r.hoistFunction(lit, s)
	res := r.execStmts(lit.Body, s)
	if res.c == cReturn {
		return res.v
	}
	return Undefined
}

func (r *Runtime) superCall(e *CallExpr, s *Scope) Value {
	fr := s.fr
	if fr == nil || fr.closure == nil {
		panic(r.newSyntaxError("'super' keyword unexpected here"))
	}
	fnObj := fr.fnObj
	parent := fnObj.Proto
	args := r.evalArgs(e.Args, s)
	if parent == nil || !parent.IsConstructor() {
		panic(r.newTypeError("Super constructor is not a constructor"))
	}
	if fr.thisInit {
		panic(r.newReferenceError("Super constructor may only be called once"))
	}
	nt, _ := fr.newTarget.(*Object)
	res := r.construct(parent, args, nt)
	fr.this = res
	fr.thisInit = true
	if c := fnObj.Closure; c != nil && c.class != nil {
		if o, ok := res.(*Object); ok {
			r.initFields(o, c.class)
		}
	}
	return Undefined
}

func (r *Runtime) initFields(obj *Object, ci *classInfo) {
	for _, f := range ci.fields {
		if f.priv != nil {
			pstore := privateStore(obj)
			if f.isMethod {
				pstore[f.priv.id] = &Property{Value: f.method}
				continue
			}
			if f.getter != nil || f.setter != nil {
				pstore[f.priv.id] = &Property{Accessor: true, Getter: f.getter, Setter: f.setter}
				continue
			}
			var v Value = Undefined
			if f.init != nil {
				v = r.evalFieldInit(f, obj)
			}
			pstore[f.priv.id] = &Property{Value: v, Writable: true}
			continue
		}
		var v Value = Undefined
		if f.init != nil {
			v = r.evalFieldInit(f, obj)
			if fl, ok := f.init.(*FuncLit); ok && fl.Name == nil {
				r.setFunctionName(v, f.key, "")
			}
		}
		r.defineOwnProperty(obj, f.key, &Property{Value: v, Writable: true, Enumerable: true, Configurable: true},
			map[string]bool{"value": true, "writable": true, "enumerable": true, "configurable": true})
	}
}

func (r *Runtime) evalFieldInit(f *fieldDef, this *Object) Value {
	fr := &frame{this: this, thisInit: true, home: f.home, newTarget: Undefined}
	s := &Scope{parent: f.scope, fr: fr, isFunc: true}
	return r.eval(f.init, s)
}

type privStore map[*int]*Property

func privateStore(o *Object) privStore {
	if o.props == nil {
		o.props = make(map[Value]*Property)
	}
	if p, ok := o.props[privKey]; ok {
		return p.Value.(privStore)
	}
	ps := privStore{}
	o.props[privKey] = &Property{Value: ps}
	return ps
}

type privKeyT struct{}

var privKey = &privKeyT{}

func (r *Runtime) resolvePrivate(name string, s *Scope) *privateName {
	for sc := s; sc != nil; sc = sc.parent {
		if i := sc.lookupLocal("#priv" + name); i >= 0 {
			return sc.vars[i].v.(*privateName)
		}
	}
	panic(r.newSyntaxError("Private field '" + name + "' must be declared in an enclosing class"))
}

func (r *Runtime) getPrivate(obj Value, name string, s *Scope) Value {
	pn := r.resolvePrivate(name, s)
	o, ok := obj.(*Object)
	if !ok {
		panic(r.newTypeError("Cannot read private member " + name + " from an object whose class did not declare it"))
	}
	var p *Property
	if o.props != nil {
		if pp, ok := o.props[privKey]; ok {
			p = pp.Value.(privStore)[pn.id]
		}
	}
	if p == nil {
		panic(r.newTypeError("Cannot read private member " + name + " from an object whose class did not declare it"))
	}
	if p.Accessor {
		if p.Getter == nil {
			panic(r.newTypeError("'" + name + "' was defined without a getter"))
		}
		return r.call(p.Getter, o, nil)
	}
	return p.Value
}

func (r *Runtime) setPrivate(obj Value, name string, v Value, s *Scope) {
	pn := r.resolvePrivate(name, s)
	o, ok := obj.(*Object)
	if !ok {
		panic(r.newTypeError("Cannot write private member " + name + " to an object whose class did not declare it"))
	}
	var p *Property
	if o.props != nil {
		if pp, ok := o.props[privKey]; ok {
			p = pp.Value.(privStore)[pn.id]
		}
	}
	if p == nil {
		panic(r.newTypeError("Cannot write private member " + name + " to an object whose class did not declare it"))
	}
	if p.Accessor {
		if p.Setter == nil {
			panic(r.newTypeError("'" + name + "' was defined without a setter"))
		}
		r.call(p.Setter, o, []Value{v})
		return
	}
	if !p.Writable {
		panic(r.newTypeError("Private method is not writable"))
	}
	p.Value = v
}

func (r *Runtime) evalClass(n *ClassLit, s *Scope) Value {
	var protoParent = r.ObjectProto
	var ctorParent = r.FunctionProto
	derived := false
	if n.Super != nil {
		sv := r.eval(n.Super, s)
		derived = true
		switch sp := sv.(type) {
		case nullType:
			protoParent = nil
		case *Object:
			if !sp.IsConstructor() {
				panic(r.newTypeError("Class extends value " + r.safeToString(sv) + " is not a constructor or null"))
			}
			pp := r.GetStr(sp, "prototype")
			switch ppv := pp.(type) {
			case *Object:
				protoParent = ppv
			case nullType:
				protoParent = nil
			default:
				panic(r.newTypeError("Class extends value does not have valid prototype property"))
			}
			ctorParent = sp
		default:
			panic(r.newTypeError("Class extends value " + r.safeToString(sv) + " is not a constructor or null"))
		}
	}
	cs := newScope(s)
	if n.Name != nil {
		cs.declare(n.Name.Name, Undefined, true, false)
	}
	// private names
	for _, m := range n.Members {
		if m.Private {
			id := new(int)
			cs.declare("#priv"+m.Name, &privateName{name: m.Name, id: id}, true, true)
		}
	}
	proto := r.newObjectProto(protoParent)
	ctorLit := n.Ctor
	if ctorLit == nil {
		ctorLit = &FuncLit{IsCtor: true, IsMethod: true}
		if derived {
			ctorLit.Rest = &Identifier{Name: "args"}
			ctorLit.Body = []Stmt{&ExprStmt{X: &CallExpr{Callee: &SuperExpr{}, Args: []Expr{&SpreadElem{Arg: &Identifier{Name: "args"}}}}}}
		}
	}
	ci := &classInfo{proto: proto, scope: cs}
	c := &Closure{Lit: ctorLit, Scope: cs, Home: proto, classCtor: true, derived: derived, class: ci}
	ctor := &Object{Class: "Function", Proto: ctorParent, Extensible: true, Closure: c, rt: r}
	ci.ctor = ctor
	nparams := 0
	for i := range ctorLit.Params {
		if ctorLit.Defaults != nil && i < len(ctorLit.Defaults) && ctorLit.Defaults[i] != nil {
			break
		}
		nparams++
	}
	ctor.setOwn("length", &Property{Value: float64(nparams), Configurable: true})
	name := ""
	if n.Name != nil {
		name = n.Name.Name
	}
	ctor.setOwn("name", &Property{Value: name, Configurable: true})
	ctor.setOwn("prototype", &Property{Value: proto})
	proto.DefineHidden("constructor", ctor)
	var staticInits []func()
	for _, m := range n.Members {
		target := proto
		if m.Static {
			target = ctor
		}
		if m.IsBlock {
			blk := m.Block
			staticInits = append(staticInits, func() {
				fr := &frame{this: ctor, thisInit: true, home: ctor, newTarget: Undefined}
				bs := &Scope{parent: cs, fr: fr, isFunc: true}
				lit := &FuncLit{Body: blk}
				r.hoistFunction(lit, bs)
				r.execStmts(blk, bs)
			})
			continue
		}
		var key Value
		var pn *privateName
		if m.Private {
			_, i := cs.find("#priv" + m.Name)
			pn = cs.vars[i].v.(*privateName)
		} else if m.Computed {
			key = r.toPropertyKey(r.eval(m.Key, cs))
		} else {
			key = m.Name
		}
		switch m.Kind {
		case propMethod, propGet, propSet:
			fl := m.Value.(*FuncLit)
			fn := r.makeClosure(fl, cs, target)
			prefix := ""
			if m.Kind == propGet {
				prefix = "get"
			} else if m.Kind == propSet {
				prefix = "set"
			}
			if pn != nil {
				fn.setOwn("name", &Property{Value: m.Name, Configurable: true})
				fd := &fieldDef{priv: pn}
				if m.Kind == propMethod {
					fd.isMethod = true
					fd.method = fn
				} else if m.Kind == propGet {
					fd.getter = fn
				} else {
					fd.setter = fn
				}
				if m.Static {
					ps := privateStore(ctor)
					if ex, ok := ps[pn.id]; ok && ex.Accessor {
						if fd.getter != nil {
							ex.Getter = fd.getter
						}
						if fd.setter != nil {
							ex.Setter = fd.setter
						}
					} else if fd.isMethod {
						ps[pn.id] = &Property{Value: fn}
					} else {
						ps[pn.id] = &Property{Accessor: true, Getter: fd.getter, Setter: fd.setter}
					}
				} else {
					merged := false
					for _, ex := range ci.fields {
						if ex.priv == pn && (ex.getter != nil || ex.setter != nil) {
							if fd.getter != nil {
								ex.getter = fd.getter
							}
							if fd.setter != nil {
								ex.setter = fd.setter
							}
							merged = true
						}
					}
					if !merged {
						ci.fields = append([]*fieldDef{fd}, ci.fields...)
					}
				}
				continue
			}
			r.setFunctionName(fn, key, prefix)
			if m.Kind == propMethod {
				target.DefineHidden(key, fn)
			} else {
				ex := target.getOwnProp(key)
				np := &Property{Accessor: true, Configurable: true}
