func (r *Runtime) iterateN(v Value, fn func(Value) bool, closeImmediately bool) {
	switch x := v.(type) {
	case *Object:
		if x.IsArr && x.Class == "Array" && x.Proto == r.ArrayProto && r.arrayIterPristine(x) {
			for i := 0; i < len(x.Arr); i++ {
				e := x.Arr[i]
				if e == nil {
					e = Undefined
				}
				if !fn(e) {
					return
				}
			}
			return
		}
	case string:
		if r.stringIterPristine() {
			u := toUTF16(x)
			for i := 0; i < len(u); i++ {
				c := u[i]
				if c >= 0xD800 && c <= 0xDBFF && i+1 < len(u) && u[i+1] >= 0xDC00 && u[i+1] <= 0xDFFF {
					if !fn(utf16ToString(u[i : i+2])) {
						return
					}
					i++
					continue
				}
				if !fn(utf16ToString(u[i : i+1])) {
					return
				}
			}
			return
		}
	}
	if isNullish(v) {
		panic(r.newTypeError(r.safeToString(v) + " is not iterable"))
	}
	itf := r.getV(v, r.symIterator)
	f, ok := itf.(*Object)
	if !ok || !f.IsCallable() {
		if _, isObj := v.(*Object); isObj {
			panic(r.newTypeError("object is not iterable"))
		}
		panic(r.newTypeError(typeOf(v) + " " + r.safeToString(v) + " is not iterable"))
	}
	it := r.call(f, v, nil)
	ito, ok := it.(*Object)
	if !ok {
		panic(r.newTypeError("Iterator result " + r.safeToString(it) + " is not an object"))
	}
	next := r.GetStr(ito, "next")
	nf, ok := next.(*Object)
	if !ok || !nf.IsCallable() {
		panic(r.newTypeError("iterator.next is not a function"))
	}
	if closeImmediately {
		r.iteratorClose(ito)
		return
	}
	for {
		res := r.call(nf, ito, nil)
		ro, ok := res.(*Object)
		if !ok {
			panic(r.newTypeError("Iterator result " + r.safeToString(res) + " is not an object"))
		}
		if toBoolean(r.GetStr(ro, "done")) {
			return
		}
		val := r.GetStr(ro, "value")
		cont := r.callIterBody(fn, val, ito)
		if !cont {
			r.iteratorClose(ito)
			return
		}
	}
}

func (r *Runtime) callIterBody(fn func(Value) bool, val Value, ito *Object) (cont bool) {
	defer func() {
		if rec := recover(); rec != nil {
			if _, ok := rec.(*Throw); ok {
				func() {
					defer func() { recover() }()
					r.iteratorClose(ito)
				}()
			}
			panic(rec)
		}
	}()
	return fn(val)
}

func (r *Runtime) iteratorClose(ito *Object) {
	ret := r.GetStr(ito, "return")
	if f, ok := ret.(*Object); ok && f.IsCallable() {
		r.call(f, ito, nil)
	}
}

func (r *Runtime) arrayIterPristine(o *Object) bool {
	if o.props != nil {
		if _, ok := o.props[r.symIterator]; ok {
			return false
		}
	}
	p := r.ArrayProto.getOwnProp(r.symIterator)
	return p != nil && p.Value == r.arrayValuesFn
}

func (r *Runtime) stringIterPristine() bool {
	return true
}

// IterToSlice collects iterable values.
func (r *Runtime) iterToSlice(v Value) []Value {
	var out []Value
	r.iterate(v, func(x Value) bool {
		out = append(out, x)
		return true
	})
	return out
}

func itoa(i int) string { return strconv.Itoa(i) }
