func (r *Runtime) freeze(o *Object, frozen bool) {
	o.Extensible = false
	if o.IsArr {
		if frozen {
			o.Internal = frozenMarker
			o.arrLenWritable = false
		}
	}
	for _, k := range o.keys {
		p := o.props[k]
		p.Configurable = false
		if frozen && !p.Accessor {
			p.Writable = false
		}
	}
}

func (r *Runtime) isFrozen(o *Object, frozen bool) bool {
	if o.Extensible {
		return false
	}
	if o.IsArr && len(o.Arr) > 0 && o.Internal != frozenMarker {
		return false
	}
	for _, k := range o.keys {
		p := o.props[k]
		if p.Configurable {
			return false
		}
		if frozen && !p.Accessor && p.Writable {
			return false
		}
	}
	return true
