				return f.Closure.Lit.homeClass.Source
			}
			return "class " + r.safeToString(r.GetStr(f, "name")) + " { }"
		}
		if f.Closure.Lit.Source != "" {
			return f.Closure.Lit.Source
		}
	}
	name := ""
	if p := f.getOwnProp("name"); p != nil {
		if s, ok := p.Value.(string); ok {
			name = s
		}
	}
	return "function " + name + "() { [native code] }"
}

func (r *Runtime) initFunction() {
	fp := r.FunctionProto
	fp.setOwn("length", &Property{Value: 0.0, Configurable: true})
	fp.setOwn("name", &Property{Value: "", Configurable: true})
	ctor := r.newCtor("Function", 1, func(this Value, args []Value) Value {
		return r.createDynamicFunction(args)
	}, func(args []Value, nt *Object) Value {
		return r.createDynamicFunction(args)
	}, fp)
	r.FunctionCtor = ctor
	r.defMethod(fp, "call", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.IsCallable() {
			panic(r.newTypeError("Function.prototype.call called on incompatible receiver"))
		}
		var rest []Value
		if len(args) > 1 {
			rest = args[1:]
		}
		return r.call(f, arg(args, 0), rest)
	})
	r.defMethod(fp, "apply", 2, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.IsCallable() {
			panic(r.newTypeError("Function.prototype.apply called on incompatible receiver"))
		}
		var list []Value
		if a := arg(args, 1); !isNullish(a) {
			list = r.arrayLikeToSlice(a)
		}
		return r.call(f, arg(args, 0), list)
	})
	r.defMethod(fp, "bind", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.IsCallable() {
			panic(r.newTypeError("Bind must be called on a function"))
		}
		boundThis := arg(args, 0)
		var bargs []Value
		if len(args) > 1 {
			bargs = append(bargs, args[1:]...)
		}
		name := "bound "
		if s, ok := r.GetStr(f, "name").(string); ok {
			name += s
		}
		ln := 0.0
		if l, ok := r.GetStr(f, "length").(float64); ok {
			ln = math.Max(0, l-float64(len(bargs)))
		}
		bf := r.newNative(name, int(ln), func(this Value, a []Value) Value {
			all := append(append([]Value{}, bargs...), a...)
			return r.call(f, boundThis, all)
		})
		bf.Internal = &boundFunc{target: f, this: boundThis, args: bargs}
		if f.IsConstructor() {
			bf.Construct = func(a []Value, nt *Object) Value {
				all := append(append([]Value{}, bargs...), a...)
				if nt == bf {
					nt = f
				}
				return r.construct(f, all, nt)
			}
		}
		return bf
	})
	r.defMethod(fp, "toString", 0, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok || !f.IsCallable() {
			panic(r.newTypeError("Function.prototype.toString requires that 'this' be a Function"))
		}
		return r.funcToString(f)
	})
	r.defaultHasInstance = r.defMethodSym(fp, r.symHasInstance, "[Symbol.hasInstance]", 1, func(this Value, args []Value) Value {
		f, ok := this.(*Object)
		if !ok {
			return false
		}
		return r.ordinaryHasInstance(f, arg(args, 0))
	})
}

func (r *Runtime) createDynamicFunction(args []Value) Value {
	var params []string
	body := ""
	for i, a := range args {
		if i == len(args)-1 {
			body = r.toString(a)
		} else {
			params = append(params, r.toString(a))
		}
	}
	src := "(function anonymous(" + strings.Join(params, ",") + "\n) {\n" + body + "\n})"
	prog, err := ParseProgram(src)
	if err != nil {
		panic(r.newSyntaxError(err.Error()))
	}
	if len(prog) == 1 {
		if es, ok := prog[0].(*ExprStmt); ok {
			return r.eval(es.X, r.globalScope)
		}
	}
	panic(r.newSyntaxError("Invalid function"))
}

func (r *Runtime) arrayLikeToSlice(v Value) []Value {
	o, ok := v.(*Object)
	if !ok {
		panic(r.newTypeError("CreateListFromArrayLike called on non-object"))
	}
	if o.IsArr {
		out := make([]Value, len(o.Arr))
		for i, e := range o.Arr {
			if e == nil {
				e = Undefined
			}
			out[i] = e
		}
		return out
	}
	n := r.toLength(r.GetStr(o, "length"))
	out := make([]Value, n)
	for i := 0; i < n; i++ {
		out[i] = r.Get(o, strconv.Itoa(i))
	}
	return out
}

// ---------- Error ----------

func (r *Runtime) initError() {
	r.errorProtos = map[string]*Object{}
	r.errorCtors = map[string]*Object{}
	r.ErrorProto = r.newObject()
	r.ErrorProto.Class = "Object"
	mk := func(name string, proto *Object, parentCtor *Object) *Object {
		r.errorProtos[name] = proto
		var ctor *Object
		construct := func(args []Value, nt *Object) Value {
			o := &Object{Class: "Error", Proto: r.getPrototypeFromCtor(nt, proto), Extensible: true, rt: r}
			if m := arg(args, 0); !isNullish(m) || m == Null {
				if _, isU := m.(undefinedType); !isU {
					o.DefineHidden("message", r.toString(m))
				}
			}
			if opts, ok := arg(args, 1).(*Object); ok && r.hasProperty(opts, "cause") {
				o.DefineHidden("cause", r.GetStr(opts, "cause"))
			}
			o.DefineHidden("stack", r.safeToString(o))
			return o
		}
		ctor = r.newCtor(name, 1, func(this Value, args []Value) Value {
			return construct(args, nil)
		}, construct, proto)
		if parentCtor != nil {
			ctor.Proto = parentCtor
		}
		proto.DefineHidden("name", name)
		proto.DefineHidden("message", "")
		r.errorCtors[name] = ctor
		return ctor
	}
	errCtor := mk("Error", r.ErrorProto, nil)
	r.defMethod(r.ErrorProto, "toString", 0, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			panic(r.newTypeError("Method Error.prototype.toString called on incompatible receiver " + r.safeToString(this)))
		}
		name := "Error"
		if n := r.GetStr(o, "name"); !isNullish(n) || n == Null {
			if _, isU := n.(undefinedType); !isU {
				name = r.toString(n)
			}
		}
		msg := ""
		if m := r.GetStr(o, "message"); m != nil {
			if _, isU := m.(undefinedType); !isU {
				msg = r.toString(m)
			}
		}
		if name == "" {
			return msg
		}
		if msg == "" {
			return name
		}
		return name + ": " + msg
	})
	r.defMethod(errCtor, "captureStackTrace", 1, func(this Value, args []Value) Value { return Undefined })
	for _, n := range []string{"TypeError", "ReferenceError", "SyntaxError", "RangeError", "EvalError", "URIError"} {
		p := r.newObjectProto(r.ErrorProto)
		mk(n, p, errCtor)
	}
	ap := r.newObjectProto(r.ErrorProto)
	agg := mk("AggregateError", ap, errCtor)
	agg.Construct = func(args []Value, nt *Object) Value {
		o := &Object{Class: "Error", Proto: r.getPrototypeFromCtor(nt, ap), Extensible: true, rt: r}
		if m := arg(args, 1); m != Undefined {
			o.DefineHidden("message", r.toString(m))
		}
		o.DefineHidden("errors", r.newArray(r.iterToSlice(arg(args, 0))))
		return o
	}
	agg.Call = func(this Value, args []Value) Value { return agg.Construct(args, nil) }
	gp := r.newObjectProto(r.ErrorProto)
	mk("GoError", gp, errCtor)
}

// ---------- Symbol ----------

func (r *Runtime) initSymbol() {
	r.SymbolProto = r.newObject()
	ctor := r.newCtor("Symbol", 0, func(this Value, args []Value) Value {
		d := arg(args, 0)
		if _, isU := d.(undefinedType); isU {
			return &Symbol{}
		}
		return &Symbol{Description: r.toString(d), HasDesc: true}
	}, nil, r.SymbolProto)
	ctor.Construct = nil
	for name, s := range map[string]*Symbol{"iterator": r.symIterator, "asyncIterator": r.symAsyncIterator,
		"hasInstance": r.symHasInstance, "toPrimitive": r.symToPrimitive, "toStringTag": r.symToStringTag,
		"species": r.symSpecies, "isConcatSpreadable": r.symIsConcatSpreadable, "unscopables": r.symUnscopables,
		"match": r.symMatch, "matchAll": r.symMatchAll, "replace": r.symReplace, "search": r.symSearch, "split": r.symSplit} {
		ctor.setOwn(name, &Property{Value: s})
	}
	r.defMethod(ctor, "for", 1, func(this Value, args []Value) Value {
		k := r.toString(arg(args, 0))
		if s, ok := r.symRegistry[k]; ok {
			return s
		}
		s := &Symbol{Description: k, HasDesc: true, registered: true}
		r.symRegistry[k] = s
		return s
	})
	r.defMethod(ctor, "keyFor", 1, func(this Value, args []Value) Value {
		s, ok := arg(args, 0).(*Symbol)
		if !ok {
			panic(r.newTypeError(r.safeToString(arg(args, 0)) + " is not a symbol"))
		}
		if s.registered {
			return s.Description
		}
		return Undefined
	})
	thisSym := func(this Value) *Symbol {
		switch x := this.(type) {
		case *Symbol:
			return x
		case *Object:
			if s, ok := x.Internal.(*Symbol); ok {
				return s
			}
		}
		panic(r.newTypeError("Value is not a Symbol"))
	}
	r.defMethod(r.SymbolProto, "toString", 0, func(this Value, args []Value) Value {
		return thisSym(this).String()
	})
	r.defMethod(r.SymbolProto, "valueOf", 0, func(this Value, args []Value) Value {
		return thisSym(this)
	})
	r.defGetter(r.SymbolProto, "description", func(this Value, args []Value) Value {
		s := thisSym(this)
		if !s.HasDesc {
			return Undefined
		}
		return s.Description
	})
	r.SymbolProto.setOwn(r.symToStringTag, &Property{Value: "Symbol", Configurable: true})
	r.defMethodSym(r.SymbolProto, r.symToPrimitive, "[Symbol.toPrimitive]", 1, func(this Value, args []Value) Value {
		return thisSym(this)
	})
}

