func (r *Runtime) initBoolean() {
	r.BooleanProto = r.newObject()
	r.BooleanProto.Class = "Boolean"
	r.BooleanProto.Internal = false
	r.newCtor("Boolean", 1, func(this Value, args []Value) Value {
		return toBoolean(arg(args, 0))
	}, func(args []Value, nt *Object) Value {
		o := r.newObjectProto(r.getPrototypeFromCtor(nt, r.BooleanProto))
		o.Class = "Boolean"
		o.Internal = toBoolean(arg(args, 0))
		return o
	}, r.BooleanProto)
	thisBool := func(this Value) bool {
		switch x := this.(type) {
		case bool:
			return x
		case *Object:
			if b, ok := x.Internal.(bool); ok && x.Class == "Boolean" {
				return b
			}
		}
		panic(r.newTypeError("Method Boolean.prototype.valueOf called on incompatible receiver " + r.safeToString(this)))
	}
	r.defMethod(r.BooleanProto, "toString", 0, func(this Value, args []Value) Value {
		if thisBool(this) {
			return "true"
		}
		return "false"
	})
	r.defMethod(r.BooleanProto, "valueOf", 0, func(this Value, args []Value) Value {
		return thisBool(this)
	})
}

// ---------- BigInt ----------

func (r *Runtime) toBigInt(v Value) *big.Int {
	switch x := r.toPrimitive(v, "number").(type) {
	case *big.Int:
		return x
	case bool:
		if x {
			return big.NewInt(1)
		}
		return big.NewInt(0)
	case string:
		b, ok := stringToBigInt(x)
		if !ok {
			panic(r.newSyntaxError("Cannot convert " + x + " to a BigInt"))
		}
		return b
	case float64:
		panic(r.newTypeError("Cannot convert " + numberToString(x) + " to a BigInt"))
	case undefinedType:
		panic(r.newTypeError("Cannot convert undefined to a BigInt"))
	case nullType:
		panic(r.newTypeError("Cannot convert null to a BigInt"))
	case *Symbol:
		panic(r.newTypeError("Cannot convert Symbol to a BigInt"))
	}
	panic(r.newTypeError("Cannot convert to BigInt"))
}

func (r *Runtime) initBigInt() {
	r.BigIntProto = r.newObject()
	ctor := r.newCtor("BigInt", 1, func(this Value, args []Value) Value {
		v := r.toPrimitive(arg(args, 0), "number")
		if f, ok := v.(float64); ok {
			if f != math.Trunc(f) || math.IsInf(f, 0) || f != f {
				panic(r.newRangeError("Cannot convert " + numberToString(f) + " to a BigInt"))
			}
			b, _ := new(big.Float).SetFloat64(f).Int(nil)
			return b
		}
		return r.toBigInt(v)
	}, nil, r.BigIntProto)
	ctor.Construct = nil
	thisBig := func(this Value) *big.Int {
		switch x := this.(type) {
		case *big.Int:
			return x
		case *Object:
			if b, ok := x.Internal.(*big.Int); ok {
				return b
			}
		}
		panic(r.newTypeError("Value is not a BigInt"))
	}
	r.defMethod(r.BigIntProto, "toString", 0, func(this Value, args []Value) Value {
		b := thisBig(this)
		radix := 10
		if rv := arg(args, 0); rv != Undefined {
			radix = int(r.toIntegerOrInfinity(rv))
			if radix < 2 || radix > 36 {
				panic(r.newRangeError("toString() radix argument must be between 2 and 36"))
			}
		}
		return b.Text(radix)
	})
	r.defMethod(r.BigIntProto, "toLocaleString", 0, func(this Value, args []Value) Value {
		return thisBig(this).String()
	})
	r.defMethod(r.BigIntProto, "valueOf", 0, func(this Value, args []Value) Value {
		return thisBig(this)
	})
	r.BigIntProto.setOwn(r.symToStringTag, &Property{Value: "BigInt", Configurable: true})
	r.defMethod(ctor, "asUintN", 2, func(this Value, args []Value) Value {
		bits := uint(r.toIntegerOrInfinity(arg(args, 0)))
		b := r.toBigInt(arg(args, 1))
		mod := new(big.Int).Lsh(big.NewInt(1), bits)
		res := new(big.Int).Mod(b, mod)
		return res
	})
	r.defMethod(ctor, "asIntN", 2, func(this Value, args []Value) Value {
		bits := uint(r.toIntegerOrInfinity(arg(args, 0)))
		b := r.toBigInt(arg(args, 1))
		if bits == 0 {
			return big.NewInt(0)
		}
		mod := new(big.Int).Lsh(big.NewInt(1), bits)
		res := new(big.Int).Mod(b, mod)
		half := new(big.Int).Lsh(big.NewInt(1), bits-1)
		if res.Cmp(half) >= 0 {
			res.Sub(res, mod)
		}
		return res
	})
}

// ---------- globals ----------

func (r *Runtime) initGlobals() {
	g := r.Global
	g.DefineHidden("globalThis", g)
	g.setOwn("NaN", &Property{Value: math.NaN()})
	g.setOwn("undefined", &Property{Value: Undefined})
	g.setOwn("Infinity", &Property{Value: math.Inf(1)})
	r.defMethod(g, "isNaN", 1, func(this Value, args []Value) Value {
		f := r.toNumber(arg(args, 0))
		return f != f
	})
	r.defMethod(g, "isFinite", 1, func(this Value, args []Value) Value {
		f := r.toNumber(arg(args, 0))
		return !(f != f || math.IsInf(f, 0))
	})
	r.defMethod(g, "parseInt", 2, func(this Value, args []Value) Value {
		return parseIntJS(r.toString(arg(args, 0)), arg(args, 1), r)
	})
	r.defMethod(g, "parseFloat", 1, func(this Value, args []Value) Value {
		return parseFloatJS(r.toString(arg(args, 0)))
	})
	r.defMethod(g, "eval", 1, func(this Value, args []Value) Value {
		src, ok := arg(args, 0).(string)
		if !ok {
			return arg(args, 0)
		}
		prog, err := ParseProgram(src)
		if err != nil {
			panic(r.newSyntaxError(err.Error()))
		}
		s := newScope(r.globalScope)
		r.hoistLexical(prog, s)
		var last Value = Undefined
		for _, st := range prog {
			if es, ok := st.(*ExprStmt); ok {
				last = r.eval(es.X, s)
				continue
			}
			res := r.exec(st, s)
			if res.c != cNormal {
				break
			}
		}
		return last
	})
	r.defMethod(g, "encodeURIComponent", 1, func(this Value, args []Value) Value {
		return r.encodeURI(r.toString(arg(args, 0)), "-_.!~*'()")
	})
	r.defMethod(g, "encodeURI", 1, func(this Value, args []Value) Value {
		return r.encodeURI(r.toString(arg(args, 0)), "-_.!~*'();/?:@&=+$,#")
	})
	r.defMethod(g, "decodeURIComponent", 1, func(this Value, args []Value) Value {
		return r.decodeURI(r.toString(arg(args, 0)), "")
	})
	r.defMethod(g, "decodeURI", 1, func(this Value, args []Value) Value {
		return r.decodeURI(r.toString(arg(args, 0)), ";/?:@&=+$,#")
	})
	r.defMethod(g, "escape", 1, func(this Value, args []Value) Value {
		s := toUTF16(r.toString(arg(args, 0)))
		var sb strings.Builder
		for _, c := range s {
			if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || strings.ContainsRune("@*_+-./", rune(c)) {
				sb.WriteByte(byte(c))
			} else if c < 256 {
				sb.WriteString("%" + strings.ToUpper(hex2(int(c))))
			} else {
				h := strings.ToUpper(strconv.FormatInt(int64(c), 16))
				for len(h) < 4 {
					h = "0" + h
				}
				sb.WriteString("%u" + h)
			}
		}
		return sb.String()
	})
	r.defMethod(g, "unescape", 1, func(this Value, args []Value) Value {
		s := toUTF16(r.toString(arg(args, 0)))
		var out []uint16
		for i := 0; i < len(s); i++ {
			c := s[i]
			if c == '%' {
				if i+6 <= len(s) && s[i+1] == 'u' {
					if v, err := strconv.ParseUint(utf16ToString(s[i+2:i+6]), 16, 16); err == nil {
						out = append(out, uint16(v))
						i += 5
						continue
					}
				}
				if i+3 <= len(s) {
					if v, err := strconv.ParseUint(utf16ToString(s[i+1:i+3]), 16, 8); err == nil {
						out = append(out, uint16(v))
						i += 2
						continue
					}
				}
			}
			out = append(out, c)
		}
		return utf16ToString(out)
	})
}

func hex2(v int) string {
	s := strconv.FormatInt(int64(v), 16)
	if len(s) < 2 {
		s = "0" + s
	}
	return s
}

func (r *Runtime) encodeURI(s string, unreserved string) Value {
	u := toUTF16(s)
	var sb strings.Builder
	for i := 0; i < len(u); i++ {
		c := u[i]
		if c < 128 && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || strings.IndexByte(unreserved, byte(c)) >= 0) {
			sb.WriteByte(byte(c))
			continue
		}
		var cp rune
		if c >= 0xDC00 && c <= 0xDFFF {
			panic(&Throw{r.makeError("URIError", "URI malformed")})
		}
		if c >= 0xD800 && c <= 0xDBFF {
			if i+1 >= len(u) || u[i+1] < 0xDC00 || u[i+1] > 0xDFFF {
				panic(&Throw{r.makeError("URIError", "URI malformed")})
			}
			cp = (rune(c)-0xD800)*0x400 + rune(u[i+1]) - 0xDC00 + 0x10000
			i++
		} else {
			cp = rune(c)
		}
		buf := []byte(string(cp))
		for _, b := range buf {
			sb.WriteString("%" + strings.ToUpper(hex2(int(b))))
		}
	}
	return sb.String()
}

func (r *Runtime) decodeURI(s string, reserved string) Value {
	var out []byte
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c != '%' {
			out = append(out, c)
			continue
		}
		if i+2 >= len(s) {
			panic(&Throw{r.makeError("URIError", "URI malformed")})
		}
		v, err := strconv.ParseUint(s[i+1:i+3], 16, 8)
		if err != nil {
			panic(&Throw{r.makeError("URIError", "URI malformed")})
		}
		if v < 128 && strings.IndexByte(reserved, byte(v)) >= 0 {
			out = append(out, s[i:i+3]...)
		} else {
			out = append(out, byte(v))
		}
		i += 2
	}
	res := string(out)
	if _, err := url.PathUnescape("x"); err != nil {
		_ = err
	}
	if !validUTF8(out) {
		panic(&Throw{r.makeError("URIError", "URI malformed")})
	}
	return res
}

func validUTF8(b []byte) bool {
	return strings.ToValidUTF8(string(b), "\uFFFD") == string(b)
}

func parseIntJS(s string, radixV Value, r *Runtime) Value {
	s = strings.TrimLeftFunc(s, isWS)
	sign := 1.0
	if strings.HasPrefix(s, "-") {
		sign = -1
		s = s[1:]
	} else if strings.HasPrefix(s, "+") {
		s = s[1:]
	}
	radix := int(toInt32(r.toNumber(radixV)))
	strip := true
	if radix != 0 {
		if radix < 2 || radix > 36 {
			return math.NaN()
		}
		if radix != 16 {
			strip = false
		}
	} else {
		radix = 10
	}
	if strip && len(s) >= 2 && s[0] == '0' && (s[1] == 'x' || s[1] == 'X') {
		s = s[2:]
		radix = 16
	}
	end := 0
	for end < len(s) {
		c := rune(s[end])
		d := 99
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'z':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'Z':
			d = int(c-'A') + 10
		}
		if d >= radix {
			break
		}
		end++
	}
	if end == 0 {
		return math.NaN()
	}
	digits := s[:end]
	if radix == 10 {
