func (r *Runtime) arrayConstruct(args []Value) *Object {
	if len(args) == 1 {
		if f, ok := args[0].(float64); ok {
			n := toUint32(f)
			if float64(n) != f {
				panic(r.newRangeError("Invalid array length"))
			}
			if n > 50000000 {
				panic(r.newRangeError("Invalid array length"))
			}
			return r.newArray(make([]Value, n))
		}
	}
	return r.newArray(append([]Value{}, args...))
}

func (r *Runtime) arrayJoin(a *arrayLike, sep string) string {
	n := a.length()
	var sb strings.Builder
	for i := 0; i < n; i++ {
		if i > 0 {
			sb.WriteString(sep)
		}
		v := a.get(i)
		if isNullish(v) {
			continue
		}
		if o, ok := v.(*Object); ok && o == a.o {
			continue
		}
		sb.WriteString(r.toString(v))
	}
	return sb.String()
}

type sortCtx struct {
	r    *Runtime
	vals []Value
	cmp  *Object
}

func (s *sortCtx) Len() int      { return len(s.vals) }
func (s *sortCtx) Swap(i, j int) { s.vals[i], s.vals[j] = s.vals[j], s.vals[i] }
func (s *sortCtx) Less(i, j int) bool {
	return s.compare(s.vals[i], s.vals[j]) < 0
}

func (s *sortCtx) compare(x, y Value) int {
	if x == nil && y == nil {
		return 0
	}
	if x == nil {
		return 1
	}
	if y == nil {
		return -1
	}
	_, xu := x.(undefinedType)
	_, yu := y.(undefinedType)
	if xu && yu {
		return 0
	}
	if xu {
		return 1
	}
	if yu {
		return -1
	}
	if s.cmp != nil {
		f := s.r.toNumber(s.r.call(s.cmp, Undefined, []Value{x, y}))
		if f > 0 {
			return 1
		}
		if f < 0 {
			return -1
		}
		if math.Signbit(f) {
			return -1
		}
		return 0
	}
	return compareUTF16(s.r.toString(x), s.r.toString(y))
}

func (r *Runtime) sortValues(vals []Value, cmp *Object) {
	sort.Stable(&sortCtx{r: r, vals: vals, cmp: cmp})
