	r.defMethod(r.ArrayIteratorProto, "next", 0, func(this Value, args []Value) Value {
		o, ok := this.(*Object)
		if !ok {
			panic(r.newTypeError("next method called on incompatible receiver"))
		}
		it, ok := o.Internal.(*arrayIter)
		if !ok {
			panic(r.newTypeError("next method called on incompatible receiver"))
		}
		return it.next(r)
	})
	r.GeneratorProto = r.newObjectProto(r.IteratorProto)
	r.GeneratorProto.setOwn(r.symToStringTag, &Property{Value: "Generator", Configurable: true})
	r.initGeneratorProto()
}

type arrayIter struct {
	o    *Object
	idx  int
	kind int // 0 keys 1 values 2 entries
	done bool
	str  []uint16
	isStr bool
}

func (it *arrayIter) next(r *Runtime) Value {
	if it.done {
		return r.iterResult(Undefined, true)
	}
	if it.isStr {
		if it.idx >= len(it.str) {
			it.done = true
			return r.iterResult(Undefined, true)
		}
		c := it.str[it.idx]
		if c >= 0xD800 && c <= 0xDBFF && it.idx+1 < len(it.str) && it.str[it.idx+1] >= 0xDC00 && it.str[it.idx+1] <= 0xDFFF {
			v := utf16ToString(it.str[it.idx : it.idx+2])
			it.idx += 2
			return r.iterResult(v, false)
		}
		v := utf16ToString(it.str[it.idx : it.idx+1])
		it.idx++
		return r.iterResult(v, false)
	}
	var n int
	if ta, ok := it.o.Internal.(*typedArray); ok {
		n = ta.length
	} else if it.o.IsArr {
		n = len(it.o.Arr)
	} else {
		n = r.toLength(r.GetStr(it.o, "length"))
	}
	if it.idx >= n {
		it.done = true
		return r.iterResult(Undefined, true)
	}
	i := it.idx
	it.idx++
	switch it.kind {
	case 0:
		return r.iterResult(float64(i), false)
	case 1:
		return r.iterResult(r.getV(it.o, strconv.Itoa(i)), false)
	}
	return r.iterResult(r.newArray([]Value{float64(i), r.getV(it.o, strconv.Itoa(i))}), false)
}

func (r *Runtime) newArrayIterator(o *Object, kind int) *Object {
	it := r.newObjectProto(r.ArrayIteratorProto)
	it.Internal = &arrayIter{o: o, kind: kind}
	return it
}

func (r *Runtime) iterResult(v Value, done bool) *Object {
	o := r.newObject()
	o.keys = make([]Value, 0, 2)
	o.props = make(map[Value]*Property, 2)
	o.setOwn("value", &Property{Value: v, Writable: true, Enumerable: true, Configurable: true})
	o.setOwn("done", &Property{Value: done, Writable: true, Enumerable: true, Configurable: true})
	return o
}
