func (s *sortCtx) compare(x, y Value) int {
	if x == nil && y == nil {
		return 0
	}
	if x == nil {
		return 1
	}
	if y == nil {
		return -1
	}
	_, xu := x.(undefinedType)
	_, yu := y.(undefinedType)
	if xu && yu {
		return 0
