			p.pos = save
			return atom
		}
		min = n1
		max = n1
		if p.peek() == ',' {
			p.pos++
			if p.peek() == '}' {
				max = -1
			} else {
				n2, ok2 := p.parseInt()
				if !ok2 {
					if p.u {
						p.fail("Incomplete quantifier")
					}
					p.pos = save
					return atom
				}
				max = n2
			}
		}
		if p.peek() != '}' {
			if p.u {
				p.fail("Incomplete quantifier")
			}
			p.pos = save
			return atom
		}
		p.pos++
		if max != -1 && max < min {
			p.fail("numbers out of order in {} quantifier")
		}
	default:
		return atom
	}
	switch atom.kind {
	case reBOL, reEOL, reWordB, reNotWordB:
		p.fail("Nothing to repeat")
	case reLook:
		if p.u || !atom.ahead {
			p.fail("Nothing to repeat")
		}
	}
	greedy := true
	if p.peek() == '?' {
		p.pos++
		greedy = false
	}
	rep := &reNode{kind: reRepeat, children: []*reNode{atom}, min: min, max: max, greedy: greedy}
	rep.minCapIdx, rep.maxCapIdx = capRange(atom)
	return rep
}

func capRange(n *reNode) (int, int) {
	lo, hi := 1<<30, 0
	var walk func(n *reNode)
	walk = func(n *reNode) {
		if n.kind == reGroup && n.capIdx > 0 {
			if n.capIdx < lo {
				lo = n.capIdx
			}
			if n.capIdx > hi {
				hi = n.capIdx
			}
		}
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(n)
	if hi == 0 {
		return 0, -1
	}
	return lo, hi
}

func (p *reParser) parseInt() (int, bool) {
	start := p.pos
	n := 0
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		n = n*10 + int(p.peek()-'0')
		if n > 1<<30 {
			n = 1 << 30
		}
		p.pos++
	}
	return n, p.pos > start
}

func (p *reParser) parseAtom() *reNode {
	c := p.src[p.pos]
	switch c {
	case '^':
		p.pos++
		return &reNode{kind: reBOL}
	case '$':
		p.pos++
		return &reNode{kind: reEOL}
	case '.':
		p.pos++
		return &reNode{kind: reAny}
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseClass()
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		p.fail("Nothing to repeat")
	case '{':
		if p.u {
			p.fail("Nothing to repeat")
		}
		// check if valid quantifier
		save := p.pos
		p.pos++
		if _, ok := p.parseInt(); ok {
			if p.peek() == ',' {
				p.pos++
				p.parseInt()
			}
			if p.peek() == '}' {
				p.fail("Nothing to repeat")
			}
		}
		p.pos = save + 1
		return &reNode{kind: reChar, ch: '{'}
	case '}', ']':
		if p.u {
			p.fail("Lone quantifier brackets")
		}
	}
	p.pos++
	if p.u && c >= 0xD800 && c <= 0xDBFF {
		// already runes
	}
	return &reNode{kind: reChar, ch: c}
}

func (p *reParser) parseGroup() *reNode {
	p.pos++ // (
	if p.peek() == '?' {
		p.pos++
		switch p.peek() {
		case ':':
			p.pos++
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reGroup, children: []*reNode{n}}
		case '=', '!':
			neg := p.peek() == '!'
			p.pos++
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reLook, ahead: true, neg: neg, children: []*reNode{n}}
		case '<':
			p.pos++
			if p.peek() == '=' || p.peek() == '!' {
				neg := p.peek() == '!'
				p.pos++
				n := p.parseAlt()
				p.expectClose()
				return &reNode{kind: reLook, ahead: false, neg: neg, children: []*reNode{n}}
			}
			name := p.parseGroupName()
			p.ncap++
			idx := p.ncap
			if _, dup := p.names[name]; dup {
				p.fail("Duplicate capture group name")
			}
			p.names[name] = idx
			p.order = append(p.order, name)
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reGroup, capIdx: idx, children: []*reNode{n}}
		}
		p.fail("Invalid group")
	}
	p.ncap++
	idx := p.ncap
	n := p.parseAlt()
	p.expectClose()
	return &reNode{kind: reGroup, capIdx: idx, children: []*reNode{n}}
}

func (p *reParser) parseGroupName() string {
	start := p.pos
	for p.more() && p.peek() != '>' {
		c := p.peek()
		if !(c == '$' || c == '_' || unicode.IsLetter(c) || (p.pos > start && unicode.IsDigit(c))) {
			p.fail("Invalid capture group name")
		}
		p.pos++
	}
	if !p.more() || p.pos == start {
		p.fail("Invalid capture group name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	return name
}

func (p *reParser) expectClose() {
	if p.peek() != ')' {
		p.fail("Unterminated group")
	}
	p.pos++
}

func isWordChar(c rune) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func isDigitRune(c rune) bool { return c >= '0' && c <= '9' }

func isSpaceRune(c rune) bool {
	return isWS(c) || c == '\n' || c == '\r' || c == '\u2028' || c == '\u2029'
}

func (p *reParser) parseEscape() *reNode {
	p.pos++ // backslash
	if !p.more() {
		p.fail("\\ at end of pattern")
	}
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'd':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isDigitRune}}
	case 'D':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isDigitRune}, negate: true}
	case 'w':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isWordChar}}
	case 'W':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isWordChar}, negate: true}
	case 's':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isSpaceRune}}
	case 'S':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isSpaceRune}, negate: true}
	case 'b':
		return &reNode{kind: reWordB}
	case 'B':
		return &reNode{kind: reNotWordB}
	case 'p', 'P':
		if p.u {
			fn := p.parseUnicodeProp()
			return &reNode{kind: reClass, classFns: []func(rune) bool{fn}, negate: c == 'P'}
		}
		return &reNode{kind: reChar, ch: c}
	case 'k':
		if p.hasNamed || p.u {
			if p.peek() != '<' {
				p.fail("Invalid named reference")
			}
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '>' {
				p.pos++
			}
			if !p.more() {
				p.fail("Invalid named reference")
			}
			name := string(p.src[start:p.pos])
			p.pos++
			return &reNode{kind: reBackref, refName: name}
		}
		return &reNode{kind: reChar, ch: 'k'}
	}
	if c >= '1' && c <= '9' {
		n := int(c - '0')
		for p.more() && isDigitRune(p.peek()) {
			n = n*10 + int(p.peek()-'0')
			p.pos++
		}
		return &reNode{kind: reBackref, capIdx: n}
	}
	p.pos--
	ch := p.parseCharEscape(false)
	return &reNode{kind: reChar, ch: ch}
}

func (p *reParser) parseUnicodeProp() func(rune) bool {
	if p.peek() != '{' {
		p.fail("Invalid property name")
	}
	p.pos++
	start := p.pos
	for p.more() && p.peek() != '}' {
		p.pos++
	}
	if !p.more() {
		p.fail("Invalid property name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	if i := strings.Index(name, "="); i >= 0 {
		name = name[i+1:]
	}
	aliases := map[string]string{"Letter": "L", "Lowercase_Letter": "Ll", "Uppercase_Letter": "Lu", "Number": "N",
		"Decimal_Number": "Nd", "Punctuation": "P", "Symbol": "S", "Separator": "Z", "Mark": "M", "Other": "C",
		"digit": "Nd", "Alphabetic": "L", "White_Space": "White_Space"}
	if a, ok := aliases[name]; ok {
		name = a
	}
	switch name {
	case "Any":
		return func(rune) bool { return true }
	case "ASCII":
		return func(c rune) bool { return c < 128 }
	case "White_Space":
		return unicode.IsSpace
	}
	if t, ok := unicode.Categories[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	if t, ok := unicode.Scripts[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	if t, ok := unicode.Properties[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	p.fail("Invalid property name")
	return nil
}

// parseCharEscape parses an escape (after backslash) producing a single char.
func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 'r':
		return '\r'
	case 't':
		return '\t'
	case 'v':
		return '\v'
	case 'f':
		return '\f'
	case '0':
		if p.more() && isDigitRune(p.peek()) && !p.u {
			// legacy octal
			v := 0
			p.pos--
			for i := 0; i < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7'; i++ {
				v = v*8 + int(p.peek()-'0')
				p.pos++
			}
			return rune(v)
		}
		return 0
	case 'c':
		if p.more() {
			l := p.peek()
			if (l >= 'a' && l <= 'z') || (l >= 'A' && l <= 'Z') {
				p.pos++
				return l % 32
			}
		}
		p.pos--
		return '\\'
	case 'x':
		if p.pos+2 <= len(p.src) {
			if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+2]), 16, 8); err == nil {
				p.pos += 2
				return rune(v)
			}
		}
		if p.u {
			p.fail("Invalid escape")
		}
		return 'x'
	case 'u':
		if p.peek() == '{' && p.u {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			v, err := strconv.ParseUint(string(p.src[start:p.pos]), 16, 32)
			if err != nil || !p.more() {
				p.fail("Invalid Unicode escape")
			}
			p.pos++
			return rune(v)
		}
		if p.pos+4 <= len(p.src) {
			if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+4]), 16, 16); err == nil {
				p.pos += 4
				r := rune(v)
				if p.u && r >= 0xD800 && r <= 0xDBFF && p.pos+6 <= len(p.src) && p.src[p.pos] == '\\' && p.src[p.pos+1] == 'u' {
					if v2, err := strconv.ParseUint(string(p.src[p.pos+2:p.pos+6]), 16, 16); err == nil && v2 >= 0xDC00 && v2 <= 0xDFFF {
						p.pos += 6
						return (r-0xD800)*0x400 + rune(v2) - 0xDC00 + 0x10000
					}
				}
				return r
			}
		}
		if p.u {
			p.fail("Invalid Unicode escape")
		}
		return 'u'
	case 'b':
		if inClass {
			return '\b'
		}
	}
	if p.u {
		if strings.ContainsRune("^$\\.*+?()[]{}|/-", c) {
			return c
		}
		p.fail("Invalid escape")
	}
	return c
}

func (p *reParser) parseClass() *reNode {
	p.pos++ // [
	n := &reNode{kind: reClass}
	if p.peek() == '^' {
		n.negate = true
		p.pos++
	}
	for {
		if !p.more() {
			p.fail("Unterminated character class")
		}
		c := p.peek()
		if c == ']' {
			p.pos++
			break
		}
		lo, isSet := p.parseClassAtom(n)
		if isSet {
			continue
		}
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hi, hiSet := p.parseClassAtom(n)
			if hiSet {
				if p.u {
					p.fail("Invalid character class")
				}
				n.ranges = append(n.ranges, reRange{lo, lo}, reRange{'-', '-'})
				continue
			}
			if hi < lo {
				p.fail("Range out of order in character class")
			}
			n.ranges = append(n.ranges, reRange{lo, hi})
			continue
		}
		n.ranges = append(n.ranges, reRange{lo, lo})
	}
	return n
}

// parseClassAtom returns char or adds a set to n (isSet true).
func (p *reParser) parseClassAtom(n *reNode) (rune, bool) {
	c := p.src[p.pos]
	if c != '\\' {
		p.pos++
		return c, false
	}
	p.pos++
	if !p.more() {
		p.fail("\\ at end of pattern")
	}
	e := p.src[p.pos]
	switch e {
	case 'd':
		p.pos++
		n.classFns = append(n.classFns, isDigitRune)
		return 0, true
	case 'D':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isDigitRune(c) })
		return 0, true
	case 'w':
		p.pos++
		n.classFns = append(n.classFns, isWordChar)
		return 0, true
	case 'W':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isWordChar(c) })
		return 0, true
	case 's':
		p.pos++
		n.classFns = append(n.classFns, isSpaceRune)
		return 0, true
	case 'S':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isSpaceRune(c) })
		return 0, true
	case 'p', 'P':
		if p.u {
			p.pos++
			fn := p.parseUnicodeProp()
			if e == 'P' {
				f := fn
				fn = func(c rune) bool { return !f(c) }
			}
			n.classFns = append(n.classFns, fn)
			return 0, true
		}
	case '-':
		p.pos++
		return '-', false
	}
	if e >= '1' && e <= '9' && !p.u {
		// octal-ish or literal
		p.pos++
		v := int(e - '0')
		if e <= '7' {
			for i := 0; i < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7'; i++ {
				v = v*8 + int(p.peek()-'0')
				p.pos++
			}
			return rune(v), false
		}
		return e, false
	}
	return p.parseCharEscape(true), false
}

// ---------- matcher ----------

type reMatcher struct {
	prog  *regexProg
	input []rune // code units (non-unicode) or code points (unicode)
	caps  []int
	steps int
}

func canonicalize(c rune, unicodeMode bool) rune {
	if unicodeMode {
		return unicode.SimpleFold(unicode.ToLower(c))
	}
	u := unicode.ToUpper(c)
	if c >= 128 && u < 128 {
		return c
	}
	return u
}

func (m *reMatcher) classMatch(n *reNode, c rune) bool {
	res := m.classMatchRaw(n, c)
	if !res && m.prog.ignoreCase {
		// try case variants
		for _, alt := range []rune{unicode.ToUpper(c), unicode.ToLower(c), unicode.ToTitle(c)} {
			if alt != c && m.classMatchRaw(n, alt) {
				res = true
				break
			}
		}
		if !res {
			f := unicode.SimpleFold(c)
			for f != c {
				if m.classMatchRaw(n, f) {
					res = true
					break
				}
				f = unicode.SimpleFold(f)
			}
		}
	}
	if n.negate {
		return !res
	}
	return res
}

func (m *reMatcher) classMatchRaw(n *reNode, c rune) bool {
	for _, r := range n.ranges {
		if c >= r.lo && c <= r.hi {
			return true
		}
	}
	for _, f := range n.classFns {
		if f(c) {
			return true
		}
	}
	return false
}

func isLineTerm(c rune) bool {
	return c == '\n' || c == '\r' || c == '\u2028' || c == '\u2029'
}

func (m *reMatcher) isWordAt(i int) bool {
	if i < 0 || i >= len(m.input) {
		return false
	}
	c := m.input[i]
	if isWordChar(c) {
		return true
	}
	if m.prog.ignoreCase && m.prog.unicode {
		return c == 0x017F || c == 0x212A
	}
	return false
}

// match tries node n at position i, calling k on success.
func (m *reMatcher) match(n *reNode, i int, k func(int) bool) bool {
	m.steps++
	switch n.kind {
	case reChar:
		if i < len(m.input) {
			c := m.input[i]
			if c == n.ch || (m.prog.ignoreCase && canonicalize(c, m.prog.unicode) == canonicalize(n.ch, m.prog.unicode)) {
				return k(i + 1)
			}
		}
		return false
	case reAny:
		if i < len(m.input) {
			if m.prog.dotAll || !isLineTerm(m.input[i]) {
				return k(i + 1)
			}
		}
		return false
	case reClass:
		if i < len(m.input) && m.classMatch(n, m.input[i]) {
			return k(i + 1)
		}
		return false
	case reSeq:
		return m.matchSeq(n.children, 0, i, k)
	case reAlt:
		for _, c := range n.children {
			if m.match(c, i, k) {
				return true
			}
		}
		return false
	case reGroup:
		if n.capIdx == 0 {
			return m.match(n.children[0], i, k)
		}
		idx := n.capIdx
		oldS, oldE := m.caps[2*idx], m.caps[2*idx+1]
		if m.match(n.children[0], i, func(j int) bool {
			ps, pe := m.caps[2*idx], m.caps[2*idx+1]
			m.caps[2*idx], m.caps[2*idx+1] = i, j
			if k(j) {
				return true
			}
			m.caps[2*idx], m.caps[2*idx+1] = ps, pe
			return false
		}) {
			return true
		}
		m.caps[2*idx], m.caps[2*idx+1] = oldS, oldE
		return false
	case reRepeat:
		return m.matchRepeat(n, i, 0, -1, k)
	case reBOL:
		if i == 0 || (m.prog.multiline && isLineTerm(m.input[i-1])) {
			return k(i)
		}
		return false
	case reEOL:
		if i == len(m.input) || (m.prog.multiline && isLineTerm(m.input[i])) {
			return k(i)
		}
		return false
	case reWordB, reNotWordB:
		a := m.isWordAt(i - 1)
		b := m.isWordAt(i)
		if (a != b) == (n.kind == reWordB) {
			return k(i)
		}
		return false
	case reBackref:
		idx := n.capIdx
		if n.refName != "" {
			idx = m.prog.names[n.refName]
		}
		if idx*2+1 >= len(m.caps) {
			return k(i)
		}
		s, e := m.caps[2*idx], m.caps[2*idx+1]
		if s < 0 || e < 0 {
			return k(i)
		}
		ln := e - s
		if i+ln > len(m.input) {
			return false
		}
		for j := 0; j < ln; j++ {
			a, b := m.input[s+j], m.input[i+j]
			if a != b && !(m.prog.ignoreCase && canonicalize(a, m.prog.unicode) == canonicalize(b, m.prog.unicode)) {
				return false
			}
		}
		return k(i + ln)
	case reLook:
		saved := append([]int{}, m.caps...)
		var ok bool
		if n.ahead {
			ok = m.match(n.children[0], i, func(int) bool { return true })
		} else {
			ok = m.matchBehind(n.children[0], i)
		}
		if n.neg {
			copy(m.caps, saved)
			if ok {
				return false
			}
			return k(i)
		}
		if !ok {
			copy(m.caps, saved)
			return false
		}
		if k(i) {
			return true
		}
		copy(m.caps, saved)
		return false
	case reEmpty:
		return k(i)
	}
	return false
}

func (m *reMatcher) matchBehind(n *reNode, end int) bool {
	for start := end; start >= 0; start-- {
		if m.match(n, start, func(j int) bool { return j == end }) {
			return true
		}
	}
	return false
}

func (m *reMatcher) matchSeq(list []*reNode, idx int, i int, k func(int) bool) bool {
	if idx == len(list) {
		return k(i)
	}
	return m.match(list[idx], i, func(j int) bool {
		return m.matchSeq(list, idx+1, j, k)
	})
}

func (m *reMatcher) clearCaps(n *reNode) {
	if n.maxCapIdx >= n.minCapIdx && n.maxCapIdx > 0 {
		for c := n.minCapIdx; c <= n.maxCapIdx; c++ {
			m.caps[2*c], m.caps[2*c+1] = -1, -1
		}
	}
}

func (m *reMatcher) matchRepeat(n *reNode, i int, count int, lastPos int, k func(int) bool) bool {
	if n.max != -1 && count >= n.max {
		return k(i)
	}
	tryOne := func() bool {
		saved := make([]int, 0)
		if n.maxCapIdx > 0 {
			saved = append(saved, m.caps[2*n.minCapIdx:2*n.maxCapIdx+2]...)
			m.clearCaps(n)
		}
		ok := m.match(n.children[0], i, func(j int) bool {
			if j == i && count >= n.min {
				return false // empty iteration
			}
			return m.matchRepeat(n, j, count+1, i, k)
		})
		if !ok && n.maxCapIdx > 0 {
			copy(m.caps[2*n.minCapIdx:], saved)
		}
		return ok
	}
	if count < n.min {
		return tryOne()
	}
	if n.greedy {
		if tryOne() {
			return true
		}
		return k(i)
	}
	if k(i) {
		return true
	}
	return tryOne()
}

// exec runs the regex at index start; returns capture positions or nil.
func (prog *regexProg) execAt(input []rune, start int) []int {
	m := &reMatcher{prog: prog, input: input}
	ncap := prog.ncap + 1
	m.caps = make([]int, ncap*2)
	for s := start; s <= len(input); s++ {
		for j := range m.caps {
			m.caps[j] = -1
		}
		end := -1
		if m.match(prog.root, s, func(j int) bool { end = j; return true }) {
			m.caps[0] = s
			m.caps[1] = end
			return m.caps
		}
		if prog.sticky {
			return nil
		}
	}
	return nil
}
