cd /workspace/internal/js && cat > regexp.go <<'EOF'
package js

import (
	"strconv"
	"strings"
	"unicode"
)

// ---------- regex AST ----------

type reNodeKind int

const (
	reChar reNodeKind = iota
	reAny
	reClass
	reSeq
	reAlt
	reGroup
	reRepeat
	reBOL
	reEOL
	reWordB
	reNotWordB
	reBackref
	reLook
	reEmpty
)

type reRange struct{ lo, hi rune }

type reNode struct {
	kind     reNodeKind
	ch       rune
	ranges   []reRange
	negate   bool
	classFns []func(rune) bool
	children []*reNode
	capIdx   int // for group: capture index (0 = non-capturing)
	min, max int // repeat; max -1 = inf
	greedy   bool
	ahead    bool // look: true = lookahead
	neg      bool
	refName  string
	minCapIdx, maxCapIdx int
}

type regexProg struct {
	root      *reNode
	ncap      int
	names     map[string]int
	nameOrder []string
	ignoreCase, multiline, dotAll, unicode, sticky, global bool
	source    string
}

type reParser struct {
	src   []rune
	pos   int
	ncap  int
	names map[string]int
	order []string
	u     bool
	err   string
	hasNamed bool
}

type reSyntaxError struct{ msg string }

func (p *reParser) fail(msg string) {
	panic(&reSyntaxError{msg})
}

func compileRegex(pattern, flags string) (prog *regexProg, errMsg string) {
	prog = &regexProg{source: pattern}
	for _, f := range flags {
		switch f {
		case 'g':
			if prog.global {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.global = true
		case 'i':
			if prog.ignoreCase {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.ignoreCase = true
		case 'm':
			if prog.multiline {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.multiline = true
		case 's':
			if prog.dotAll {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.dotAll = true
		case 'u':
			if prog.unicode {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.unicode = true
		case 'y':
			if prog.sticky {
				return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
			}
			prog.sticky = true
		case 'd':
		default:
			return nil, "Invalid flags supplied to RegExp constructor '" + flags + "'"
		}
	}
	p := &reParser{src: []rune(pattern), names: map[string]int{}, u: prog.unicode}
	// pre-scan for named groups
	if strings.Contains(pattern, "(?<") {
		p.hasNamed = true
	}
	defer func() {
		if rec := recover(); rec != nil {
			if e, ok := rec.(*reSyntaxError); ok {
				prog = nil
				errMsg = e.msg
				return
			}
			panic(rec)
		}
	}()
	root := p.parseAlt()
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			p.fail("Unmatched ')'")
		}
		p.fail("Unexpected character")
	}
	prog.root = root
	prog.ncap = p.ncap
	prog.names = p.names
	prog.nameOrder = p.order
	return prog, ""
}

func (p *reParser) more() bool { return p.pos < len(p.src) }
func (p *reParser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}

func (p *reParser) parseAlt() *reNode {
	first := p.parseSeq()
	if p.peek() != '|' {
		return first
	}
	alt := &reNode{kind: reAlt, children: []*reNode{first}}
	for p.peek() == '|' {
		p.pos++
		alt.children = append(alt.children, p.parseSeq())
	}
	return alt
}

func (p *reParser) parseSeq() *reNode {
	seq := &reNode{kind: reSeq}
	for p.more() {
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuantifier(atom)
		seq.children = append(seq.children, atom)
	}
	return seq
}

func (p *reParser) parseQuantifier(atom *reNode) *reNode {
	if !p.more() {
		return atom
	}
	c := p.peek()
	min, max := -1, -1
	switch c {
	case '*':
		min, max = 0, -1
		p.pos++
	case '+':
		min, max = 1, -1
		p.pos++
	case '?':
		min, max = 0, 1
		p.pos++
	case '{':
		save := p.pos
		p.pos++
		n1, ok1 := p.parseInt()
		if !ok1 {
			if p.u {
				p.fail("Incomplete quantifier")
			}
			p.pos = save
			return atom
		}
		min = n1
		max = n1
		if p.peek() == ',' {
			p.pos++
			if p.peek() == '}' {
				max = -1
			} else {
				n2, ok2 := p.parseInt()
				if !ok2 {
					if p.u {
						p.fail("Incomplete quantifier")
					}
					p.pos = save
					return atom
				}
				max = n2
			}
		}
		if p.peek() != '}' {
			if p.u {
				p.fail("Incomplete quantifier")
			}
			p.pos = save
			return atom
		}
		p.pos++
		if max != -1 && max < min {
			p.fail("numbers out of order in {} quantifier")
		}
	default:
		return atom
	}
	switch atom.kind {
	case reBOL, reEOL, reWordB, reNotWordB:
		p.fail("Nothing to repeat")
	case reLook:
		if p.u || !atom.ahead {
			p.fail("Nothing to repeat")
		}
	}
	greedy := true
	if p.peek() == '?' {
		p.pos++
		greedy = false
	}
	rep := &reNode{kind: reRepeat, children: []*reNode{atom}, min: min, max: max, greedy: greedy}
	rep.minCapIdx, rep.maxCapIdx = capRange(atom)
	return rep
}

func capRange(n *reNode) (int, int) {
	lo, hi := 1<<30, 0
	var walk func(n *reNode)
	walk = func(n *reNode) {
		if n.kind == reGroup && n.capIdx > 0 {
			if n.capIdx < lo {
				lo = n.capIdx
			}
			if n.capIdx > hi {
				hi = n.capIdx
			}
		}
		for _, c := range n.children {
			walk(c)
		}
	}
	walk(n)
	if hi == 0 {
		return 0, -1
	}
	return lo, hi
}

func (p *reParser) parseInt() (int, bool) {
	start := p.pos
	n := 0
	for p.more() && p.peek() >= '0' && p.peek() <= '9' {
		n = n*10 + int(p.peek()-'0')
		if n > 1<<30 {
			n = 1 << 30
		}
		p.pos++
	}
	return n, p.pos > start
}

func (p *reParser) parseAtom() *reNode {
	c := p.src[p.pos]
	switch c {
	case '^':
		p.pos++
		return &reNode{kind: reBOL}
	case '$':
		p.pos++
		return &reNode{kind: reEOL}
	case '.':
		p.pos++
		return &reNode{kind: reAny}
	case '(':
		return p.parseGroup()
	case '[':
		return p.parseClass()
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		p.fail("Nothing to repeat")
	case '{':
		if p.u {
			p.fail("Nothing to repeat")
		}
		// check if valid quantifier
		save := p.pos
		p.pos++
		if _, ok := p.parseInt(); ok {
			if p.peek() == ',' {
				p.pos++
				p.parseInt()
			}
			if p.peek() == '}' {
				p.fail("Nothing to repeat")
			}
		}
		p.pos = save + 1
		return &reNode{kind: reChar, ch: '{'}
	case '}', ']':
		if p.u {
			p.fail("Lone quantifier brackets")
		}
	}
	p.pos++
	if p.u && c >= 0xD800 && c <= 0xDBFF {
		// already runes
	}
	return &reNode{kind: reChar, ch: c}
}

func (p *reParser) parseGroup() *reNode {
	p.pos++ // (
	if p.peek() == '?' {
		p.pos++
		switch p.peek() {
		case ':':
			p.pos++
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reGroup, children: []*reNode{n}}
		case '=', '!':
			neg := p.peek() == '!'
			p.pos++
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reLook, ahead: true, neg: neg, children: []*reNode{n}}
		case '<':
			p.pos++
			if p.peek() == '=' || p.peek() == '!' {
				neg := p.peek() == '!'
				p.pos++
				n := p.parseAlt()
				p.expectClose()
				return &reNode{kind: reLook, ahead: false, neg: neg, children: []*reNode{n}}
			}
			name := p.parseGroupName()
			p.ncap++
			idx := p.ncap
			if _, dup := p.names[name]; dup {
				p.fail("Duplicate capture group name")
			}
			p.names[name] = idx
			p.order = append(p.order, name)
			n := p.parseAlt()
			p.expectClose()
			return &reNode{kind: reGroup, capIdx: idx, children: []*reNode{n}}
		}
		p.fail("Invalid group")
	}
	p.ncap++
	idx := p.ncap
	n := p.parseAlt()
	p.expectClose()
	return &reNode{kind: reGroup, capIdx: idx, children: []*reNode{n}}
}

func (p *reParser) parseGroupName() string {
	start := p.pos
	for p.more() && p.peek() != '>' {
		c := p.peek()
		if !(c == '$' || c == '_' || unicode.IsLetter(c) || (p.pos > start && unicode.IsDigit(c))) {
			p.fail("Invalid capture group name")
		}
		p.pos++
	}
	if !p.more() || p.pos == start {
		p.fail("Invalid capture group name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	return name
}

func (p *reParser) expectClose() {
	if p.peek() != ')' {
		p.fail("Unterminated group")
	}
	p.pos++
}

func isWordChar(c rune) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
}

func isDigitRune(c rune) bool { return c >= '0' && c <= '9' }

func isSpaceRune(c rune) bool {
	return isWS(c) || c == '\n' || c == '\r' || c == '\u2028' || c == '\u2029'
}

func (p *reParser) parseEscape() *reNode {
	p.pos++ // backslash
	if !p.more() {
		p.fail("\\ at end of pattern")
	}
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'd':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isDigitRune}}
	case 'D':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isDigitRune}, negate: true}
	case 'w':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isWordChar}}
	case 'W':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isWordChar}, negate: true}
	case 's':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isSpaceRune}}
	case 'S':
		return &reNode{kind: reClass, classFns: []func(rune) bool{isSpaceRune}, negate: true}
	case 'b':
		return &reNode{kind: reWordB}
	case 'B':
		return &reNode{kind: reNotWordB}
	case 'p', 'P':
		if p.u {
			fn := p.parseUnicodeProp()
			return &reNode{kind: reClass, classFns: []func(rune) bool{fn}, negate: c == 'P'}
		}
		return &reNode{kind: reChar, ch: c}
	case 'k':
		if p.hasNamed || p.u {
			if p.peek() != '<' {
				p.fail("Invalid named reference")
			}
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '>' {
				p.pos++
			}
			if !p.more() {
				p.fail("Invalid named reference")
			}
			name := string(p.src[start:p.pos])
			p.pos++
			return &reNode{kind: reBackref, refName: name}
		}
		return &reNode{kind: reChar, ch: 'k'}
	}
	if c >= '1' && c <= '9' {
		n := int(c - '0')
		for p.more() && isDigitRune(p.peek()) {
			n = n*10 + int(p.peek()-'0')
			p.pos++
		}
		return &reNode{kind: reBackref, capIdx: n}
	}
	p.pos--
	ch := p.parseCharEscape(false)
	return &reNode{kind: reChar, ch: ch}
}

func (p *reParser) parseUnicodeProp() func(rune) bool {
	if p.peek() != '{' {
		p.fail("Invalid property name")
	}
	p.pos++
	start := p.pos
	for p.more() && p.peek() != '}' {
		p.pos++
	}
	if !p.more() {
		p.fail("Invalid property name")
	}
	name := string(p.src[start:p.pos])
	p.pos++
	if i := strings.Index(name, "="); i >= 0 {
		name = name[i+1:]
	}
	aliases := map[string]string{"Letter": "L", "Lowercase_Letter": "Ll", "Uppercase_Letter": "Lu", "Number": "N",
		"Decimal_Number": "Nd", "Punctuation": "P", "Symbol": "S", "Separator": "Z", "Mark": "M", "Other": "C",
		"digit": "Nd", "Alphabetic": "L", "White_Space": "White_Space"}
	if a, ok := aliases[name]; ok {
		name = a
	}
	switch name {
	case "Any":
		return func(rune) bool { return true }
	case "ASCII":
		return func(c rune) bool { return c < 128 }
	case "White_Space":
		return unicode.IsSpace
	}
	if t, ok := unicode.Categories[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	if t, ok := unicode.Scripts[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	if t, ok := unicode.Properties[name]; ok {
		return func(c rune) bool { return unicode.Is(t, c) }
	}
	p.fail("Invalid property name")
	return nil
}

// parseCharEscape parses an escape (after backslash) producing a single char.
func (p *reParser) parseCharEscape(inClass bool) rune {
	c := p.src[p.pos]
	p.pos++
	switch c {
	case 'n':
		return '\n'
	case 'r':
		return '\r'
	case 't':
		return '\t'
	case 'v':
		return '\v'
	case 'f':
		return '\f'
	case '0':
		if p.more() && isDigitRune(p.peek()) && !p.u {
			// legacy octal
			v := 0
			p.pos--
			for i := 0; i < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7'; i++ {
				v = v*8 + int(p.peek()-'0')
				p.pos++
			}
			return rune(v)
		}
		return 0
	case 'c':
		if p.more() {
			l := p.peek()
			if (l >= 'a' && l <= 'z') || (l >= 'A' && l <= 'Z') {
				p.pos++
				return l % 32
			}
		}
		p.pos--
		return '\\'
	case 'x':
		if p.pos+2 <= len(p.src) {
			if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+2]), 16, 8); err == nil {
				p.pos += 2
				return rune(v)
			}
		}
		if p.u {
			p.fail("Invalid escape")
		}
		return 'x'
	case 'u':
		if p.peek() == '{' && p.u {
			p.pos++
			start := p.pos
			for p.more() && p.peek() != '}' {
				p.pos++
			}
			v, err := strconv.ParseUint(string(p.src[start:p.pos]), 16, 32)
			if err != nil || !p.more() {
				p.fail("Invalid Unicode escape")
			}
			p.pos++
			return rune(v)
		}
		if p.pos+4 <= len(p.src) {
			if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+4]), 16, 16); err == nil {
				p.pos += 4
				r := rune(v)
				if p.u && r >= 0xD800 && r <= 0xDBFF && p.pos+6 <= len(p.src) && p.src[p.pos] == '\\' && p.src[p.pos+1] == 'u' {
					if v2, err := strconv.ParseUint(string(p.src[p.pos+2:p.pos+6]), 16, 16); err == nil && v2 >= 0xDC00 && v2 <= 0xDFFF {
						p.pos += 6
						return (r-0xD800)*0x400 + rune(v2) - 0xDC00 + 0x10000
					}
				}
				return r
			}
		}
		if p.u {
			p.fail("Invalid Unicode escape")
		}
		return 'u'
	case 'b':
		if inClass {
			return '\b'
		}
	}
	if p.u {
		if strings.ContainsRune("^$\\.*+?()[]{}|/-", c) {
			return c
		}
		p.fail("Invalid escape")
	}
	return c
}

func (p *reParser) parseClass() *reNode {
	p.pos++ // [
	n := &reNode{kind: reClass}
	if p.peek() == '^' {
		n.negate = true
		p.pos++
	}
	for {
		if !p.more() {
			p.fail("Unterminated character class")
		}
		c := p.peek()
		if c == ']' {
			p.pos++
			break
		}
		lo, isSet := p.parseClassAtom(n)
		if isSet {
			continue
		}
		if p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			p.pos++
			hi, hiSet := p.parseClassAtom(n)
			if hiSet {
				if p.u {
					p.fail("Invalid character class")
				}
				n.ranges = append(n.ranges, reRange{lo, lo}, reRange{'-', '-'})
				continue
			}
			if hi < lo {
				p.fail("Range out of order in character class")
			}
			n.ranges = append(n.ranges, reRange{lo, hi})
			continue
		}
		n.ranges = append(n.ranges, reRange{lo, lo})
	}
	return n
}

// parseClassAtom returns char or adds a set to n (isSet true).
func (p *reParser) parseClassAtom(n *reNode) (rune, bool) {
	c := p.src[p.pos]
	if c != '\\' {
		p.pos++
		return c, false
	}
	p.pos++
	if !p.more() {
		p.fail("\\ at end of pattern")
	}
	e := p.src[p.pos]
	switch e {
	case 'd':
		p.pos++
		n.classFns = append(n.classFns, isDigitRune)
		return 0, true
	case 'D':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isDigitRune(c) })
		return 0, true
	case 'w':
		p.pos++
		n.classFns = append(n.classFns, isWordChar)
		return 0, true
	case 'W':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isWordChar(c) })
		return 0, true
	case 's':
		p.pos++
		n.classFns = append(n.classFns, isSpaceRune)
		return 0, true
	case 'S':
		p.pos++
		n.classFns = append(n.classFns, func(c rune) bool { return !isSpaceRune(c) })
		return 0, true
	case 'p', 'P':
		if p.u {
			p.pos++
			fn := p.parseUnicodeProp()
			if e == 'P' {
				f := fn
				fn = func(c rune) bool { return !f(c) }
			}
			n.classFns = append(n.classFns, fn)
			return 0, true
		}
	case '-':
		p.pos++
		return '-', false
	}
