}

func canonicalize(c rune, unicodeMode bool) rune {
	if unicodeMode {
		return unicode.SimpleFold(unicode.ToLower(c))
	}
	u := unicode.ToUpper(c)
	if c >= 128 && u < 128 {
		return c
	}
	return u
}

func (m *reMatcher) classMatch(n *reNode, c rune) bool {
	res := m.classMatchRaw(n, c)
	if !res && m.prog.ignoreCase {
		// try case variants
		for _, alt := range []rune{unicode.ToUpper(c), unicode.ToLower(c), unicode.ToTitle(c)} {
			if alt != c && m.classMatchRaw(n, alt) {
				res = true
				break
			}
		}
		if !res {
			f := unicode.SimpleFold(c)
			for f != c {
				if m.classMatchRaw(n, f) {
					res = true
					break
				}
				f = unicode.SimpleFold(f)
			}
		}
	}
	if n.negate {
		return !res
	}
	return res
}

func (m *reMatcher) classMatchRaw(n *reNode, c rune) bool {
	for _, r := range n.ranges {
		if c >= r.lo && c <= r.hi {
			return true
		}
	}
	for _, f := range n.classFns {
		if f(c) {
			return true
		}
	}
	return false
}

func isLineTerm(c rune) bool {
	return c == '\n' || c == '\r' || c == '\u2028' || c == '\u2029'
