			return true
		}
		copy(m.caps, saved)
		return false
	case reEmpty:
		return k(i)
	}
	return false
}

func (m *reMatcher) matchBehind(n *reNode, end int) bool {
	for start := end; start >= 0; start-- {
		if m.match(n, start, func(j int) bool { return j == end }) {
