func (m *reMatcher) matchSeq(list []*reNode, idx int, i int, k func(int) bool) bool {
	if idx == len(list) {
		return k(i)
	}
	return m.match(list[idx], i, func(j int) bool {
		return m.matchSeq(list, idx+1, j, k)
	})
}

func (m *reMatcher) clearCaps(n *reNode) {
	if n.maxCapIdx >= n.minCapIdx && n.maxCapIdx > 0 {
		for c := n.minCapIdx; c <= n.maxCapIdx; c++ {
			m.caps[2*c], m.caps[2*c+1] = -1, -1
		}
	}
