func (m *reMatcher) matchRepeat(n *reNode, i int, count int, lastPos int, k func(int) bool) bool {
	if n.max != -1 && count >= n.max {
		return k(i)
	}
	tryOne := func() bool {
		saved := make([]int, 0)
