		}
		return k(i)
	}
	if k(i) {
		return true
	}
	return tryOne()
}

// exec runs the regex at index start; returns capture positions or nil.
func (prog *regexProg) execAt(input []rune, start int) []int {
	m := &reMatcher{prog: prog, input: input}
	ncap := prog.ncap + 1
	m.caps = make([]int, ncap*2)
	for s := start; s <= len(input); s++ {
		for j := range m.caps {
			m.caps[j] = -1
		}
		end := -1
		if m.match(prog.root, s, func(j int) bool { end = j; return true }) {
			m.caps[0] = s
			m.caps[1] = end
			return m.caps
		}
		if prog.sticky {
			return nil
		}
	}
	return nil
}
