			ncaps = 0
		}
		matched := r.toString(r.getV(ro, "0"))
		mlen := strLen(matched)
		pos := int(r.toIntegerOrInfinity(r.GetStr(ro, "index")))
		if pos < 0 {
			pos = 0
		}
		if pos > len(u) {
			pos = len(u)
		}
		caps := make([]Value, ncaps)
		for i := 1; i <= ncaps; i++ {
			c := r.getV(ro, strconv.Itoa(i))
			if c != Undefined {
				c = r.toString(c)
			}
			caps[i-1] = c
		}
		groups := r.GetStr(ro, "groups")
		var repl string
		if fn != nil {
			fargs := []Value{matched}
			fargs = append(fargs, caps...)
			fargs = append(fargs, float64(pos), s)
			if groups != Undefined {
				fargs = append(fargs, groups)
			}
			repl = r.toString(r.call(fn, Undefined, fargs))
		} else {
			if groups != Undefined {
				groups = r.toObject(groups)
			}
			repl = r.getSubstitution(matched, s, pos, caps, groups, replStr)
		}
		if pos >= next {
			out = append(out, u[next:pos]...)
			out = append(out, toUTF16(repl)...)
			next = pos + mlen
		}
	}
	if next < len(u) {
		out = append(out, u[next:]...)
	}
	return utf16ToString(out)
}

func (r *Runtime) getSubstitution(matched, str string, pos int, caps []Value, groups Value, repl string) string {
	if !strings.Contains(repl, "$") {
		return repl
	}
	u := toUTF16(str)
	mlen := strLen(matched)
	var sb strings.Builder
	for i := 0; i < len(repl); i++ {
		c := repl[i]
		if c != '$' || i+1 >= len(repl) {
			sb.WriteByte(c)
			continue
		}
		n := repl[i+1]
		switch {
		case n == '$':
			sb.WriteByte('$')
			i++
		case n == '&':
			sb.WriteString(matched)
			i++
		case n == '`':
			sb.WriteString(utf16ToString(u[:pos]))
			i++
		case n == '\'':
			end := pos + mlen
			if end < len(u) {
				sb.WriteString(utf16ToString(u[end:]))
			}
			i++
		case n >= '0' && n <= '9':
			idx := int(n - '0')
			consumed := 1
			if i+2 < len(repl) && repl[i+2] >= '0' && repl[i+2] <= '9' {
				two := idx*10 + int(repl[i+2]-'0')
				if two >= 1 && two <= len(caps) {
					idx = two
					consumed = 2
				}
			}
			if idx >= 1 && idx <= len(caps) {
				if v := caps[idx-1]; v != Undefined {
					sb.WriteString(v.(string))
				}
				i += consumed
			} else {
				sb.WriteByte('$')
			}
		case n == '<':
			if groups == Undefined {
				sb.WriteByte('$')
				continue
			}
			end := strings.IndexByte(repl[i+2:], '>')
			if end < 0 {
				sb.WriteByte('$')
				continue
			}
			name := repl[i+2 : i+2+end]
			v := r.getV(groups, name)
			if v != Undefined {
				sb.WriteString(r.toString(v))
			}
			i += 2 + end
		default:
			sb.WriteByte('$')
		}
	}
	return sb.String()
}
