	return int(f)
}

func eqU16(a, b []uint16) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func utf16IndexOf(s, search string, from int) int {
	if isASCII(s) && isASCII(search) {
		if from > len(s) {
			if search == "" {
				return len(s)
			}
			return -1
		}
		i := strings.Index(s[from:], search)
		if i < 0 {
			return -1
		}
		return i + from
