	us, ut := toUTF16(s), toUTF16(search)
	for i := from; i+len(ut) <= len(us); i++ {
		if eqU16(us[i:i+len(ut)], ut) {
			return i
		}
	}
	return -1
}

func jsToUpper(s string) string {
	if isASCII(s) {
		return strings.ToUpper(s)
	}
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case 'ß':
			sb.WriteString("SS")
			continue
		case 'ŉ':
			sb.WriteString("ʼN")
			continue
		}
		sb.WriteRune(unicode.ToUpper(c))
	}
	return sb.String()
