func jsToLower(s string) string {
	if isASCII(s) {
		return strings.ToLower(s)
	}
	var sb strings.Builder
	rs := []rune(s)
	for i, c := range rs {
		if c == 'İ' {
			sb.WriteString("i̇")
			continue
		}
		if c == 'Σ' {
			// final sigma rule
			if i > 0 && unicode.IsLetter(rs[i-1]) && (i+1 >= len(rs) || !unicode.IsLetter(rs[i+1])) {
				sb.WriteRune('ς')
				continue
			}
		}
		sb.WriteRune(unicode.ToLower(c))
	}
	return sb.String()
}

func localeCompare(a, b string) int {
	// approximate locale compare: compare case-insensitively first, then lowercase before uppercase
	ka := collationKey(a)
	kb := collationKey(b)
	if c := strings.Compare(ka, kb); c != 0 {
		return c
	}
	// tie-break: lowercase first
	ra, rb := []rune(a), []rune(b)
	for i := 0; i < len(ra) && i < len(rb); i++ {
		if ra[i] != rb[i] {
			la, lb := unicode.IsLower(ra[i]), unicode.IsLower(rb[i])
			if la && !lb {
				return -1
			}
			if !la && lb {
				return 1
			}
			if ra[i] < rb[i] {
				return -1
			}
			return 1
		}
	}
	if len(ra) < len(rb) {
		return -1
	}
	if len(ra) > len(rb) {
		return 1
	}
	return 0
}

func collationKey(s string) string {
	d := norm.NFD.String(s)
	var sb strings.Builder
	for _, c := range d {
		if unicode.Is(unicode.Mn, c) {
			continue
		}
		sb.WriteRune(unicode.ToLower(c))
	}
	return sb.String()
}
