func clampInt(f float64, n int) int {
	if f < 0 {
		return 0
	}
	if f > float64(n) {
		return n
	}
	return int(f)
}

func eqU16(a, b []uint16) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func utf16IndexOf(s, search string, from int) int {
	if isASCII(s) && isASCII(search) {
		if from > len(s) {
			if search == "" {
				return len(s)
			}
			return -1
		}
		i := strings.Index(s[from:], search)
		if i < 0 {
			return -1
		}
		return i + from
	}
	us, ut := toUTF16(s), toUTF16(search)
	for i := from; i+len(ut) <= len(us); i++ {
		if eqU16(us[i:i+len(ut)], ut) {
			return i
		}
	}
	return -1
}

func jsToUpper(s string) string {
	if isASCII(s) {
		return strings.ToUpper(s)
	}
	var sb strings.Builder
	for _, c := range s {
		switch c {
		case 'ß':
			sb.WriteString("SS")
			continue
		case 'ŉ':
			sb.WriteString("ʼN")
			continue
		}
		sb.WriteRune(unicode.ToUpper(c))
	}
	return sb.String()
}

func jsToLower(s string) string {
	if isASCII(s) {
		return strings.ToLower(s)
	}
	var sb strings.Builder
	rs := []rune(s)
	for i, c := range rs {
		if c == 'İ' {
			sb.WriteString("i̇")
			continue
		}
		if c == 'Σ' {
			// final sigma rule
			if i > 0 && unicode.IsLetter(rs[i-1]) && (i+1 >= len(rs) || !unicode.IsLetter(rs[i+1])) {
				sb.WriteRune('ς')
				continue
			}
		}
		sb.WriteRune(unicode.ToLower(c))
	}
	return sb.String()
}

func localeCompare(a, b string) int {
	// approximate locale compare: compare case-insensitively first, then lowercase before uppercase
	ka := collationKey(a)
	kb := collationKey(b)
	if c := strings.Compare(ka, kb); c != 0 {
		return c
	}
	// tie-break: lowercase first
	ra, rb := []rune(a), []rune(b)
	for i := 0; i < len(ra) && i < len(rb); i++ {
		if ra[i] != rb[i] {
			la, lb := unicode.IsLower(ra[i]), unicode.IsLower(rb[i])
			if la && !lb {
				return -1
			}
			if !la && lb {
				return 1
			}
			if ra[i] < rb[i] {
				return -1
			}
			return 1
		}
	}
	if len(ra) < len(rb) {
		return -1
	}
	if len(ra) > len(rb) {
		return 1
	}
	return 0
}

func collationKey(s string) string {
	d := norm.NFD.String(s)
	var sb strings.Builder
	for _, c := range d {
		if unicode.Is(unicode.Mn, c) {
			continue
		}
		sb.WriteRune(unicode.ToLower(c))
	}
	return sb.String()
}
