// exactDecimal returns digits of round(x * 10^f) using round-half-up on exact value.
func roundScaled(x float64, f int) *big.Int {
	rat := new(big.Rat).SetFloat64(x)
	scale := new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(f)), nil))
	if f < 0 {
		scale = new(big.Rat).SetFrac(big.NewInt(1), new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-f)), nil))
	}
	rat.Mul(rat, scale)
	// round half up
	num := new(big.Int).Set(rat.Num())
	den := rat.Denom()
	q, m := new(big.Int).QuoRem(num, den, new(big.Int))
	m2 := new(big.Int).Mul(m, big.NewInt(2))
	if m2.Cmp(den) >= 0 {
		q.Add(q, big.NewInt(1))
	}
	return q
}

func toFixedJS(x float64, f int) string {
	if x != x {
		return "NaN"
	}
	if math.Abs(x) >= 1e21 {
		return numberToString(x)
	}
	neg := false
	if x < 0 {
		neg = true
		x = -x
	}
	n := roundScaled(x, f)
	s := n.String()
	if f > 0 {
		for len(s) <= f {
			s = "0" + s
		}
		s = s[:len(s)-f] + "." + s[len(s)-f:]
	}
	if neg && (n.Sign() != 0 || true) {
		if n.Sign() == 0 && x == 0 {
			return s
		}
		s = "-" + s
	}
	return s
}

// digitsExp returns p significant digits of x (x>0) and exponent e such that x ≈ d.ddd * 10^e
func precisionDigits(x float64, p int) (string, int) {
	e := int(math.Floor(math.Log10(x)))
	for {
		n := roundScaled(x, p-1-e)
		s := n.String()
		if len(s) > p {
			e++
			continue
		}
		if len(s) < p {
			e--
			continue
		}
		return s, e
	}
}

func toPrecisionJS(x float64, p int) string {
	if x != x {
		return "NaN"
	}
	if math.IsInf(x, 0) {
		return numberToString(x)
	}
	neg := ""
	if x < 0 {
		neg = "-"
		x = -x
	}
	var digits string
	var e int
	if x == 0 {
		digits = strings.Repeat("0", p)
		e = 0
	} else {
		digits, e = precisionDigits(x, p)
	}
	if e < -6 || e >= p {
		s := digits[:1]
		if p > 1 {
			s += "." + digits[1:]
		}
		sign := "+"
		if e < 0 {
			sign = "-"
			e = -e
		}
		return neg + s + "e" + sign + strconv.Itoa(e)
	}
	if e == p-1 {
		return neg + digits
	}
	if e >= 0 {
		return neg + digits[:e+1] + "." + digits[e+1:]
	}
	return neg + "0." + strings.Repeat("0", -(e+1)) + digits
}

func toExponentialJS(x float64, f int, auto bool) string {
	if x != x {
		return "NaN"
	}
	if math.IsInf(x, 0) {
		return numberToString(x)
	}
	neg := ""
	if x < 0 {
		neg = "-"
		x = -x
	}
	var digits string
	var e int
	if x == 0 {
		if auto {
			f = 0
		}
		digits = strings.Repeat("0", f+1)
		e = 0
	} else if auto {
		es := strconv.FormatFloat(x, 'e', -1, 64)
		mant, ex, _ := strings.Cut(es, "e")
		digits = strings.Replace(mant, ".", "", 1)
		e, _ = strconv.Atoi(ex)
	} else {
		digits, e = precisionDigits(x, f+1)
	}
	s := digits[:1]
	if len(digits) > 1 {
		s += "." + digits[1:]
	}
	sign := "+"
	if e < 0 {
		sign = "-"
		e = -e
	}
	return neg + s + "e" + sign + strconv.Itoa(e)
}

func nextDouble(x float64) float64 {
	return math.Nextafter(x, math.Inf(1))
}

func doubleExponent(x float64) int {
	b := math.Float64bits(x)
	e := int((b>>52)&0x7FF) - 1075
	return e
}

func toRadixString(value float64, radix int) string {
	const chars = "0123456789abcdefghijklmnopqrstuvwxyz"
	if value != value {
		return "NaN"
	}
	if math.IsInf(value, 1) {
		return "Infinity"
	}
	if math.IsInf(value, -1) {
		return "-Infinity"
	}
	if value == 0 {
		return "0"
	}
	buf := make([]byte, 2200)
	intCursor := 1100
	fracCursor := intCursor
	negative := value < 0
	if negative {
		value = -value
	}
	integer := math.Floor(value)
	fraction := value - integer
	delta := 0.5 * (nextDouble(value) - value)
	if d := nextDouble(0); d > delta {
		delta = d
	}
	if fraction >= delta {
		buf[fracCursor] = '.'
		fracCursor++
		for {
			fraction *= float64(radix)
			delta *= float64(radix)
			digit := int(fraction)
			buf[fracCursor] = chars[digit]
			fracCursor++
			fraction -= float64(digit)
			if fraction > 0.5 || (fraction == 0.5 && (digit&1) != 0) {
				if fraction+delta > 1 {
					for {
						fracCursor--
						if fracCursor == 1100 {
							integer += 1
							break
						}
						c := buf[fracCursor]
						var d int
						if c > '9' {
							d = int(c-'a') + 10
						} else {
							d = int(c - '0')
						}
						if d+1 < radix {
							buf[fracCursor] = chars[d+1]
							fracCursor++
							break
						}
					}
					break
				}
			}
			if !(fraction >= delta) {
				break
			}
		}
	}
	for doubleExponent(integer/float64(radix)) > 0 {
		integer /= float64(radix)
		intCursor--
		buf[intCursor] = '0'
	}
	for {
		rem := math.Mod(integer, float64(radix))
		intCursor--
		buf[intCursor] = chars[int(rem)]
		integer = (integer - rem) / float64(radix)
		if integer <= 0 {
			break
		}
	}
	if negative {
		intCursor--
		buf[intCursor] = '-'
	}
	return string(buf[intCursor:fracCursor])
}

