// exactDecimal returns digits of round(x * 10^f) using round-half-up on exact value.
func roundScaled(x float64, f int) *big.Int {
	rat := new(big.Rat).SetFloat64(x)
	scale := new(big.Rat).SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(f)), nil))
	if f < 0 {
		scale = new(big.Rat).SetFrac(big.NewInt(1), new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-f)), nil))
	}
	rat.Mul(rat, scale)
	// round half up
	num := new(big.Int).Set(rat.Num())
	den := rat.Denom()
	q, m := new(big.Int).QuoRem(num, den, new(big.Int))
	m2 := new(big.Int).Mul(m, big.NewInt(2))
	if m2.Cmp(den) >= 0 {
		q.Add(q, big.NewInt(1))
	}
	return q
}

