func precisionDigits(x float64, p int) (string, int) {
	e := int(math.Floor(math.Log10(x)))
	for {
		n := roundScaled(x, p-1-e)
		s := n.String()
		if len(s) > p {
			e++
			continue
		}
		if len(s) < p {
			e--
			continue
		}
		return s, e
	}
}

