	var sb strings.Builder
	sb.Grow(len(s) + 2)
	sb.WriteByte('"')
	for i := 0; i < len(s); {
		c := s[i]
		if c < 0x80 {
			switch c {
			case '"':
				sb.WriteString("\\\"")
			case '\\':
				sb.WriteString("\\\\")
			case '\b':
				sb.WriteString("\\b")
			case '\f':
				sb.WriteString("\\f")
			case '\n':
				sb.WriteString("\\n")
			case '\r':
				sb.WriteString("\\r")
			case '\t':
				sb.WriteString("\\t")
			default:
				if c < 0x20 {
					sb.WriteString("\\u00")
					sb.WriteByte("0123456789abcdef"[c>>4])
					sb.WriteByte("0123456789abcdef"[c&0xF])
				} else {
					sb.WriteByte(c)
				}
			}
			i++
			continue
		}
		// lone surrogate (WTF-8)
		if c == 0xED && i+2 < len(s) && s[i+1] >= 0xA0 && s[i+1] <= 0xBF {
			cp := (int(c&0x0F) << 12) | (int(s[i+1]&0x3F) << 6) | int(s[i+2]&0x3F)
			sb.WriteString(fmt.Sprintf("\\u%04x", cp))
			i += 3
			continue
		}
		sb.WriteByte(c)
		i++
	}
	sb.WriteByte('"')
	return sb.String()
}
