import (
	"math"
	"math/big"
)

type mapEntry struct {
	key, value Value
	deleted    bool
}

type orderedMap struct {
	entries []*mapEntry
	index   map[interface{}]*mapEntry
	size    int
}

type nanKey struct{}
type bigKey struct{ s string }

func normKey(k Value) interface{} {
	switch x := k.(type) {
	case float64:
		if x != x {
			return nanKey{}
		}
		if x == 0 {
			return 0.0
		}
		return x
	case *big.Int:
		return bigKey{x.String()}
	}
	return k
}

func newOrderedMap() *orderedMap {
	return &orderedMap{index: map[interface{}]*mapEntry{}}
}

func (m *orderedMap) get(k Value) (Value, bool) {
	if e, ok := m.index[normKey(k)]; ok {
		return e.value, true
	}
	return nil, false
}

func (m *orderedMap) set(k, v Value) {
	nk := normKey(k)
	if e, ok := m.index[nk]; ok {
		e.value = v
		return
	}
	if f, ok := k.(float64); ok && f == 0 {
		k = 0.0
	}
	e := &mapEntry{key: k, value: v}
	m.entries = append(m.entries, e)
	m.index[nk] = e
	m.size++
}

func (m *orderedMap) delete(k Value) bool {
	nk := normKey(k)
	if e, ok := m.index[nk]; ok {
		e.deleted = true
		delete(m.index, nk)
		m.size--
		return true
	}
	return false
}

func (m *orderedMap) clear() {
	for _, e := range m.entries {
		e.deleted = true
	}
	m.entries = nil
	m.index = map[interface{}]*mapEntry{}
	m.size = 0
}

