type genReturnSignal struct{ val Value }

func (r *Runtime) makeGenerator(fnObj *Object, c *Closure, this Value, args []Value, async bool) Value {
	protoV := r.GetStr(fnObj, "prototype")
	proto, ok := protoV.(*Object)
