			msg := <-g.resumeCh
			if msg.kind == 1 {
				g.yieldCh <- genMsg{panic: &Throw{msg.val}, done: true}
				return
			}
			if msg.kind == 2 {
				g.yieldCh <- genMsg{val: msg.val, done: true}
				return
			}
