type genHandle struct{ g *generator }

func (r *Runtime) findGen(s *Scope) *generator {
	for sc := s; sc != nil; sc = sc.parent {
		if sc.isFunc {
			if len(sc.vars) > 0 && sc.vars[0].name == "%gen" {
