	g.yieldCh <- genMsg{val: v}
	msg := <-g.resumeCh
	r.callDepth = depth
	switch msg.kind {
	case 1:
		panic(&Throw{msg.val})
	case 2:
		panic(&genReturnSignal{msg.val})
