				r.microtasks = append(r.microtasks, func() {
					called := false
					res := r.newNative("", 1, func(this Value, a []Value) Value {
						if called {
							return Undefined
						}
						called = true
						settled = false
						resolve(arg(a, 0))
						return Undefined
					})
					rej := r.newNative("", 1, func(this Value, a []Value) Value {
						if called {
							return Undefined
						}
						called = true
						settle(2, arg(a, 0))
						return Undefined
					})
					func() {
						defer func() {
							if rec := recover(); rec != nil {
								if th, ok := rec.(*Throw); ok {
									if !called {
										called = true
										settle(2, th.Value)
									}
									return
								}
								panic(rec)
							}
						}()
