	}
	reject = func(v Value) {
		if settled {
			return
		}
		settled = true
		settle(2, v)
	}
	return o, resolve, reject
}

func (r *Runtime) runMicrotasks() {
	for len(r.microtasks) > 0 {
		t := r.microtasks[0]
		r.microtasks = r.microtasks[1:]
		t()
	}
}

