		return ok
	})
	r.defMethod(rf, "has", 2, func(this Value, args []Value) Value {
		return r.hasProperty(needObj(arg(args, 0), "has"), r.toPropertyKey(arg(args, 1)))
	})
	r.defMethod(rf, "ownKeys", 1, func(this Value, args []Value) Value {
		return r.newArray(r.ownKeys(needObj(arg(args, 0), "ownKeys"), true))
	})
	r.defMethod(rf, "getOwnPropertyDescriptor", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "getOwnPropertyDescriptor")
		return r.fromDescriptor(r.getOwnPropertyFull(o, r.toPropertyKey(arg(args, 1))))
	})
	r.defMethod(rf, "getPrototypeOf", 1, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "getPrototypeOf")
		if o.Proto == nil {
			return Null
		}
		return o.Proto
	})
	r.defMethod(rf, "setPrototypeOf", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "setPrototypeOf")
		switch p := arg(args, 1).(type) {
		case *Object:
			o.Proto = p
		case nullType:
			o.Proto = nil
		default:
			panic(r.newTypeError("Object prototype may only be an Object or null: " + r.safeToString(p)))
		}
		return true
	})
	r.defMethod(rf, "isExtensible", 1, func(this Value, args []Value) Value {
		return needObj(arg(args, 0), "isExtensible").Extensible
	})
	r.defMethod(rf, "preventExtensions", 1, func(this Value, args []Value) Value {
		needObj(arg(args, 0), "preventExtensions").Extensible = false
		return true
	})
	r.initProxy()
}

// ---------- Proxy ----------

type proxyData struct {
	target  *Object
	handler *Object
}

func (r *Runtime) proxyTrap(px *proxyData, name string) *Object {
	if px.handler == nil {
		panic(r.newTypeError("Cannot perform '" + name + "' on a proxy that has been revoked"))
	}
	t := r.GetStr(px.handler, name)
	if f, ok := t.(*Object); ok && f.IsCallable() {
		return f
	}
	return nil
}

func keyVal(k Value) Value { return k }

func (r *Runtime) proxyGet(o *Object, px *proxyData, key Value, receiver Value) Value {
	if t := r.proxyTrap(px, "get"); t != nil {
		return r.call(t, px.handler, []Value{px.target, keyVal(key), receiver})
	}
	return r.getProp(px.target, key, receiver)
}

func (r *Runtime) proxySet(o *Object, px *proxyData, key Value, v Value, receiver Value) {
	if t := r.proxyTrap(px, "set"); t != nil {
		res := r.call(t, px.handler, []Value{px.target, keyVal(key), v, receiver})
		if !toBoolean(res) {
			panic(r.newTypeError("'set' on proxy: trap returned falsish for property '" + keyToDisplay(key) + "'"))
		}
		return
	}
	if receiver == Value(o) {
		receiver = px.target
	}
	r.setProp(px.target, key, v, receiver)
}

func (r *Runtime) proxyHas(o *Object, px *proxyData, key Value) bool {
	if t := r.proxyTrap(px, "has"); t != nil {
		return toBoolean(r.call(t, px.handler, []Value{px.target, keyVal(key)}))
	}
	return r.hasProperty(px.target, key)
}

func (r *Runtime) proxyDelete(o *Object, px *proxyData, key Value) bool {
	if t := r.proxyTrap(px, "deleteProperty"); t != nil {
		return toBoolean(r.call(t, px.handler, []Value{px.target, keyVal(key)}))
	}
	return r.deleteProp(px.target, key)
}

func (r *Runtime) proxyOwnKeys(o *Object, px *proxyData) []Value {
	if t := r.proxyTrap(px, "ownKeys"); t != nil {
		res := r.call(t, px.handler, []Value{px.target})
		return r.arrayLikeToSlice(res)
	}
	return r.ownKeys(px.target, true)
}

func (r *Runtime) proxyGetOwnProperty(o *Object, px *proxyData, key Value) *Property {
	if t := r.proxyTrap(px, "getOwnPropertyDescriptor"); t != nil {
		res := r.call(t, px.handler, []Value{px.target, keyVal(key)})
		if res == Undefined {
			return nil
		}
		d, _ := r.toDescriptor(res)
		return d
	}
	if r.proxyTrap(px, "ownKeys") != nil {
		// assume enumerable data property
		return &Property{Value: r.proxyGet(o, px, key, o), Enumerable: true, Configurable: true, Writable: true}
	}
	return r.getOwnPropertyFull(px.target, key)
}

func (r *Runtime) initProxy() {
	ctor := r.newCtor("Proxy", 2, func(this Value, args []Value) Value {
		panic(r.newTypeError("Constructor Proxy requires 'new'"))
	}, func(args []Value, nt *Object) Value {
		t, ok1 := arg(args, 0).(*Object)
		h, ok2 := arg(args, 1).(*Object)
		if !ok1 || !ok2 {
			panic(r.newTypeError("Cannot create proxy with a non-object as target or handler"))
		}
		return r.newProxy(t, h)
	}, nil)
	r.defMethod(ctor, "revocable", 2, func(this Value, args []Value) Value {
		t, ok1 := arg(args, 0).(*Object)
		h, ok2 := arg(args, 1).(*Object)
		if !ok1 || !ok2 {
			panic(r.newTypeError("Cannot create proxy with a non-object as target or handler"))
		}
		p := r.newProxy(t, h)
		res := r.newObject()
		res.Set("proxy", p)
		res.Set("revoke", r.newNative("", 0, func(this Value, a []Value) Value {
			p.Internal.(*proxyData).handler = nil
			return Undefined
		}))
		return res
	})
}

func (r *Runtime) newProxy(t, h *Object) *Object {
	px := &proxyData{target: t, handler: h}
	o := &Object{Class: t.Class, Proto: nil, Extensible: true, rt: r, Internal: px}
	if t.IsCallable() {
		o.Call = func(this Value, args []Value) Value {
			if tr := r.proxyTrap(px, "apply"); tr != nil {
				return r.call(tr, px.handler, []Value{px.target, this, r.newArray(append([]Value{}, args...))})
			}
			return r.call(px.target, this, args)
		}
		if t.IsConstructor() {
			o.Construct = func(args []Value, nt *Object) Value {
				if tr := r.proxyTrap(px, "construct"); tr != nil {
					return r.call(tr, px.handler, []Value{px.target, r.newArray(append([]Value{}, args...)), nt})
				}
				if nt == o {
					nt = px.target
				}
				return r.construct(px.target, args, nt)
			}
		}
	}
	return o
}

// ---------- typed arrays ----------

type typedArray struct {
	kind   string
	data   []float64
	length int
}

func (t *typedArray) get(i int) Value {
	return t.data[i]
}

func (t *typedArray) set(r *Runtime, i int, v Value) {
	f := r.toNumber(v)
	t.data[i] = convTyped(t.kind, f)
}

func convTyped(kind string, f float64) float64 {
	switch kind {
	case "Uint8Array":
		return float64(uint8(toInt32(f)))
	case "Uint8ClampedArray":
		if f != f {
			return 0
		}
		if f < 0 {
			return 0
		}
		if f > 255 {
			return 255
		}
		return math.RoundToEven(f)
	case "Int8Array":
		return float64(int8(toInt32(f)))
	case "Uint16Array":
		return float64(uint16(toInt32(f)))
	case "Int16Array":
		return float64(int16(toInt32(f)))
	case "Uint32Array":
		return float64(toUint32(f))
	case "Int32Array":
		return float64(toInt32(f))
	case "Float32Array":
		return float64(float32(f))
	}
	return f
}

func (r *Runtime) initTypedArrays() {
	r.TypedArrayProto = r.newObject()
	r.typedArrayProtos = map[string]*Object{}
	tp := r.TypedArrayProto
	for _, name := range []string{"forEach", "map", "filter", "join", "indexOf", "lastIndexOf", "includes", "reduce", "reduceRight", "some", "every", "find", "findIndex", "findLast", "findLastIndex", "at", "keys", "values", "entries", "toString", "toLocaleString"} {
		if p := r.ArrayProto.getOwnProp(name); p != nil {
			if name == "map" || name == "filter" {
				orig := p.Value.(*Object)
				nm := name
				r.defMethod(tp, nm, 1, func(this Value, args []Value) Value {
					res := r.call(orig, this, args).(*Object)
					to := this.(*Object)
					ta := to.Internal.(*typedArray)
					return r.newTypedArray(ta.kind, res.Arr)
				})
				continue
			}
			tp.DefineHidden(name, p.Value)
		}
	}
	tp.DefineHidden(r.symIterator, r.GetStr(r.ArrayProto, "values"))
	r.defGetter(tp, "length", func(this Value, args []Value) Value {
		if o, ok := this.(*Object); ok {
			if ta, ok := o.Internal.(*typedArray); ok {
				return float64(ta.length)
			}
		}
		return 0.0
	})
	r.defMethod(tp, "set", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		src := r.arrayLikeToSlice(arg(args, 0))
		off := int(r.toIntegerOrInfinity(arg(args, 1)))
		for i, v := range src {
			if off+i < ta.length {
				ta.set(r, off+i, v)
			}
		}
		return Undefined
	})
	slice := func(name string) {
		r.defMethod(tp, name, 2, func(this Value, args []Value) Value {
			o := this.(*Object)
			ta := o.Internal.(*typedArray)
			start := relIndex(r.toIntegerOrInfinity(arg(args, 0)), ta.length)
			end := ta.length
			if e := arg(args, 1); e != Undefined {
				end = relIndex(r.toIntegerOrInfinity(e), ta.length)
			}
			var vals []Value
			for i := start; i < end; i++ {
				vals = append(vals, ta.data[i])
			}
			return r.newTypedArray(ta.kind, vals)
		})
	}
	slice("slice")
	slice("subarray")
	r.defMethod(tp, "fill", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		for i := 0; i < ta.length; i++ {
			ta.set(r, i, arg(args, 0))
		}
		return o
	})
	r.defMethod(tp, "reverse", 0, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		for i, j := 0, ta.length-1; i < j; i, j = i+1, j-1 {
			ta.data[i], ta.data[j] = ta.data[j], ta.data[i]
		}
		return o
	})
	r.defMethod(tp, "sort", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		vals := make([]Value, ta.length)
		for i := range vals {
			vals[i] = ta.data[i]
		}
		var cf *Object
		if f, ok := arg(args, 0).(*Object); ok {
			cf = f
		}
		if cf == nil {
			sortStable(vals, func(a, b Value) bool { return a.(float64) < b.(float64) })
		} else {
			r.sortValues(vals, cf)
		}
		for i := range vals {
			ta.data[i] = vals[i].(float64)
		}
		return o
	})
	for _, kind := range []string{"Uint8Array", "Uint8ClampedArray", "Int8Array", "Uint16Array", "Int16Array", "Uint32Array", "Int32Array", "Float32Array", "Float64Array", "BigInt64Array", "BigUint64Array"} {
		kind := kind
		proto := r.newObjectProto(tp)
		r.typedArrayProtos[kind] = proto
		proto.setOwn(r.symToStringTag, &Property{Value: kind, Configurable: true})
		ctor := r.newCtor(kind, 3, func(this Value, args []Value) Value {
			panic(r.newTypeError("Constructor " + kind + " requires 'new'"))
		}, func(args []Value, nt *Object) Value {
			a0 := arg(args, 0)
			switch x := a0.(type) {
			case float64:
				n := int(x)
				vals := make([]Value, n)
				for i := range vals {
					vals[i] = 0.0
				}
				return r.newTypedArray(kind, vals)
			case *Object:
				return r.newTypedArray(kind, r.iterToSlice(x))
			}
			return r.newTypedArray(kind, nil)
		}, proto)
		r.defMethod(ctor, "from", 1, func(this Value, args []Value) Value {
			vals := r.iterToSlice(arg(args, 0))
			if f, ok := arg(args, 1).(*Object); ok && f.IsCallable() {
				for i, v := range vals {
					vals[i] = r.call(f, Undefined, []Value{v, float64(i)})
				}
			}
			return r.newTypedArray(kind, vals)
		})
		r.defMethod(ctor, "of", 0, func(this Value, args []Value) Value {
			return r.newTypedArray(kind, append([]Value{}, args...))
		})
		ctor.setOwn("BYTES_PER_ELEMENT", &Property{Value: 1.0})
	}
	r.ArrayBufferProto = r.newObject()
	r.newCtor("ArrayBuffer", 1, func(this Value, args []Value) Value {
		panic(r.newTypeError("Constructor ArrayBuffer requires 'new'"))
	}, func(args []Value, nt *Object) Value {
		o := r.newObjectProto(r.ArrayBufferProto)
		o.Class = "ArrayBuffer"
		o.Set("byteLength", r.toNumber(arg(args, 0)))
		return o
	}, r.ArrayBufferProto)
	r.DataViewProto = r.newObject()
	r.newCtor("DataView", 1, func(this Value, args []Value) Value {
		panic(r.newTypeError("Constructor DataView requires 'new'"))
	}, func(args []Value, nt *Object) Value {
		o := r.newObjectProto(r.DataViewProto)
		o.Class = "DataView"
		return o
	}, r.DataViewProto)
}

func (r *Runtime) newTypedArray(kind string, vals []Value) *Object {
	ta := &typedArray{kind: kind, data: make([]float64, len(vals)), length: len(vals)}
	for i, v := range vals {
		if v == nil {
			v = Undefined
		}
		ta.data[i] = convTyped(kind, r.toNumber(v))
	}
	o := r.newObjectProto(r.typedArrayProtos[kind])
	o.Class = kind
	o.Internal = ta
	return o
}

