package js

import (
	"math"
	"strconv"
)

// ---------- generators ----------

type genMsg struct {
	kind  int // 0 next, 1 throw, 2 return
	val   Value
	done  bool
	panic interface{}
}

type generator struct {
	state    int // 0 suspendedStart, 1 suspendedYield, 2 executing, 3 completed
	resumeCh chan genMsg
	yieldCh  chan genMsg
	start    func()
}

type genReturnSignal struct{ val Value }

func (r *Runtime) makeGenerator(fnObj *Object, c *Closure, this Value, args []Value, async bool) Value {
	protoV := r.GetStr(fnObj, "prototype")
	proto, ok := protoV.(*Object)
	if !ok {
		proto = r.GeneratorProto
	}
	g := &generator{resumeCh: make(chan genMsg), yieldCh: make(chan genMsg)}
	obj := r.newObjectProto(proto)
	obj.Class = "Generator"
	obj.Internal = g
	g.start = func() {
		go func() {
			msg := <-g.resumeCh
			if msg.kind == 1 {
				g.yieldCh <- genMsg{panic: &Throw{msg.val}, done: true}
				return
			}
			if msg.kind == 2 {
				g.yieldCh <- genMsg{val: msg.val, done: true}
				return
			}
			var result Value
			var pv interface{}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						if rs, ok := rec.(*genReturnSignal); ok {
							result = rs.val
							return
						}
						pv = rec
					}
				}()
				lit := c.Lit
				fr := &frame{this: this, thisInit: true, home: c.Home, fnObj: fnObj, args: args, closure: c, newTarget: Undefined}
				s := &Scope{parent: c.Scope, fr: fr, isFunc: true}
				s.vars = append(s.vars, binding{name: "%gen", v: &genHandle{g}, init: true})
				r.bindParams(lit, s, args)
				r.hoistFunction(lit, s)
				res := r.execStmts(lit.Body, s)
				if res.c == cReturn {
					result = res.v
				} else {
					result = Undefined
				}
			}()
			if pv != nil {
				g.yieldCh <- genMsg{panic: pv, done: true}
				return
			}
			g.yieldCh <- genMsg{val: result, done: true}
		}()
	}
	return obj
}

type genHandle struct{ g *generator }

func (r *Runtime) findGen(s *Scope) *generator {
	for sc := s; sc != nil; sc = sc.parent {
		if sc.isFunc {
			if len(sc.vars) > 0 && sc.vars[0].name == "%gen" {
				return sc.vars[0].v.(*genHandle).g
			}
			if sc.fr != nil && sc.fr.closure != nil && !sc.fr.closure.Lit.IsArrow {
				return nil
			}
		}
	}
	return nil
}

func (r *Runtime) genYield(g *generator, v Value) Value {
	depth := r.callDepth
	g.yieldCh <- genMsg{val: v}
	msg := <-g.resumeCh
	r.callDepth = depth
	switch msg.kind {
	case 1:
		panic(&Throw{msg.val})
	case 2:
		panic(&genReturnSignal{msg.val})
	}
	return msg.val
}

func (r *Runtime) evalYield(n *YieldExpr, s *Scope) Value {
	g := r.findGen(s)
	if g == nil {
		panic(r.newSyntaxError("yield outside generator"))
	}
	if n.Delegate {
		inner := r.eval(n.Arg, s)
		var last Value = Undefined
		itf := r.getV(inner, r.symIterator)
		it := r.callValue(itf, inner, nil)
		next := r.getV(it, "next")
		for {
			res := r.callValue(next, it, nil)
			if toBoolean(r.getV(res, "done")) {
				last = r.getV(res, "value")
				break
			}
			r.genYield(g, r.getV(res, "value"))
		}
		return last
	}
	var v Value = Undefined
	if n.Arg != nil {
		v = r.eval(n.Arg, s)
	}
	return r.genYield(g, v)
}

func (r *Runtime) genResume(this Value, kind int, v Value) Value {
	o, ok := this.(*Object)
	var g *generator
	if ok {
		g, _ = o.Internal.(*generator)
	}
	if g == nil {
		panic(r.newTypeError("next method called on incompatible receiver " + r.safeToString(this)))
	}
	switch g.state {
	case 3:
		if kind == 1 {
			panic(&Throw{v})
		}
		if kind == 2 {
			return r.iterResult(v, true)
		}
		return r.iterResult(Undefined, true)
	case 2:
		panic(r.newTypeError("Generator is already running"))
	case 0:
		if kind != 0 {
			g.state = 3
			if kind == 1 {
				panic(&Throw{v})
			}
			return r.iterResult(v, true)
		}
		g.start()
	}
	g.state = 2
	depth := r.callDepth
	g.resumeCh <- genMsg{kind: kind, val: v}
	msg := <-g.yieldCh
	r.callDepth = depth
	if msg.done {
		g.state = 3
		if msg.panic != nil {
			panic(msg.panic)
		}
		return r.iterResult(msg.val, true)
	}
	g.state = 1
	return r.iterResult(msg.val, false)
}

func (r *Runtime) initGeneratorProto() {
	gp := r.GeneratorProto
	r.defMethod(gp, "next", 1, func(this Value, args []Value) Value {
		return r.genResume(this, 0, arg(args, 0))
	})
	r.defMethod(gp, "throw", 1, func(this Value, args []Value) Value {
		return r.genResume(this, 1, arg(args, 0))
	})
	r.defMethod(gp, "return", 1, func(this Value, args []Value) Value {
		return r.genResume(this, 2, arg(args, 0))
	})
}

// ---------- async ----------

func (r *Runtime) runAsync(fnObj *Object, c *Closure, this Value, args []Value) Value {
	p, resolve, reject := r.newPromiseCapability()
	func() {
		defer func() {
			if rec := recover(); rec != nil {
				if t, ok := rec.(*Throw); ok {
					reject(t.Value)
					return
				}
				panic(rec)
			}
		}()
		v := r.invoke(fnObj, c, this, args, nil)
		resolve(v)
	}()
	return p
}

func (r *Runtime) evalAwait(n *AwaitExpr, s *Scope) Value {
	v := r.eval(n.Arg, s)
	if o, ok := v.(*Object); ok {
		if pd, ok := o.Internal.(*promiseData); ok {
			r.runMicrotasks()
			switch pd.state {
			case 1:
				return pd.value
			case 2:
				pd.handled = true
				panic(&Throw{pd.value})
			}
			return Undefined
		}
	}
	return v
}

// ---------- Promise ----------

type promiseData struct {
	state     int // 0 pending 1 fulfilled 2 rejected
	value     Value
	reactions []func()
	handled   bool
}

func (r *Runtime) newPromiseCapability() (*Object, func(Value), func(Value)) {
	o := r.newObjectProto(r.PromiseProto)
	o.Class = "Promise"
	pd := &promiseData{}
	o.Internal = pd
	var resolve, reject func(Value)
	settled := false
	settle := func(state int, v Value) {
		if pd.state != 0 {
			return
		}
		pd.state = state
		pd.value = v
		rs := pd.reactions
		pd.reactions = nil
		for _, f := range rs {
			r.microtasks = append(r.microtasks, f)
		}
	}
	resolve = func(v Value) {
		if settled {
			return
		}
		settled = true
		if vo, ok := v.(*Object); ok {
			if vo == o {
				settle(2, r.makeError("TypeError", "Chaining cycle detected for promise"))
				return
			}
			then := func() (t Value) {
				defer func() {
					if rec := recover(); rec != nil {
						if th, ok := rec.(*Throw); ok {
							settle(2, th.Value)
							t = nil
							return
						}
						panic(rec)
					}
				}()
				return r.GetStr(vo, "then")
			}()
			if then == nil {
				return
			}
			if tf, ok := then.(*Object); ok && tf.IsCallable() {
				r.microtasks = append(r.microtasks, func() {
					called := false
					res := r.newNative("", 1, func(this Value, a []Value) Value {
						if called {
							return Undefined
						}
						called = true
						settled = false
						resolve(arg(a, 0))
						return Undefined
					})
					rej := r.newNative("", 1, func(this Value, a []Value) Value {
						if called {
							return Undefined
						}
						called = true
						settle(2, arg(a, 0))
						return Undefined
					})
					func() {
						defer func() {
							if rec := recover(); rec != nil {
								if th, ok := rec.(*Throw); ok {
									if !called {
										called = true
										settle(2, th.Value)
									}
									return
								}
								panic(rec)
							}
						}()
						r.call(tf, vo, []Value{res, rej})
					}()
				})
				return
			}
		}
		settle(1, v)
	}
	reject = func(v Value) {
		if settled {
			return
		}
		settled = true
		settle(2, v)
	}
	return o, resolve, reject
}

func (r *Runtime) runMicrotasks() {
	for len(r.microtasks) > 0 {
		t := r.microtasks[0]
		r.microtasks = r.microtasks[1:]
		t()
	}
}

func (r *Runtime) RunMicrotasks() { r.runMicrotasks() }

func (r *Runtime) promiseThen(p *Object, onF, onR Value) *Object {
	pd := p.Internal.(*promiseData)
	np, resolve, reject := r.newPromiseCapability()
	reaction := func() {
		var handler Value
		if pd.state == 1 {
			handler = onF
		} else {
			handler = onR
		}
		hf, ok := handler.(*Object)
		if !ok || !hf.IsCallable() {
			if pd.state == 1 {
				resolve(pd.value)
			} else {
				reject(pd.value)
			}
			return
		}
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					if th, ok := rec.(*Throw); ok {
						reject(th.Value)
						return
					}
					panic(rec)
				}
			}()
			resolve(r.call(hf, Undefined, []Value{pd.value}))
		}()
	}
	pd.handled = true
	if pd.state == 0 {
		pd.reactions = append(pd.reactions, reaction)
	} else {
		r.microtasks = append(r.microtasks, reaction)
	}
	return np
}

func (r *Runtime) promiseResolve(v Value) *Object {
	if o, ok := v.(*Object); ok {
		if _, ok := o.Internal.(*promiseData); ok {
			return o
		}
	}
	p, resolve, _ := r.newPromiseCapability()
	resolve(v)
	return p
}

func (r *Runtime) initPromise() {
	pp := r.newObject()
	r.PromiseProto = pp
	ctor := r.newCtor("Promise", 1, func(this Value, args []Value) Value {
		panic(r.newTypeError("Promise constructor cannot be invoked without 'new'"))
	}, func(args []Value, nt *Object) Value {
		ex, ok := arg(args, 0).(*Object)
		if !ok || !ex.IsCallable() {
			panic(r.newTypeError("Promise resolver " + r.safeToString(arg(args, 0)) + " is not a function"))
		}
		p, resolve, reject := r.newPromiseCapability()
		p.Proto = r.getPrototypeFromCtor(nt, pp)
		resF := r.newNative("", 1, func(this Value, a []Value) Value { resolve(arg(a, 0)); return Undefined })
		rejF := r.newNative("", 1, func(this Value, a []Value) Value { reject(arg(a, 0)); return Undefined })
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					if th, ok := rec.(*Throw); ok {
						reject(th.Value)
						return
					}
					panic(rec)
				}
			}()
			r.call(ex, Undefined, []Value{resF, rejF})
		}()
		return p
	}, pp)
	r.PromiseCtor = ctor
	pp.setOwn(r.symToStringTag, &Property{Value: "Promise", Configurable: true})
	thisPromise := func(this Value) *Object {
		if o, ok := this.(*Object); ok {
			if _, ok := o.Internal.(*promiseData); ok {
				return o
			}
		}
		panic(r.newTypeError("Method Promise.prototype.then called on incompatible receiver " + r.safeToString(this)))
	}
	r.defMethod(pp, "then", 2, func(this Value, args []Value) Value {
		return r.promiseThen(thisPromise(this), arg(args, 0), arg(args, 1))
	})
	r.defMethod(pp, "catch", 1, func(this Value, args []Value) Value {
		return r.callValue(r.getV(this, "then"), this, []Value{Undefined, arg(args, 0)})
	})
	r.defMethod(pp, "finally", 1, func(this Value, args []Value) Value {
		f := arg(args, 0)
		fo, ok := f.(*Object)
		if !ok || !fo.IsCallable() {
			return r.callValue(r.getV(this, "then"), this, []Value{f, f})
		}
		onF := r.newNative("", 1, func(_ Value, a []Value) Value {
			r.call(fo, Undefined, nil)
			return arg(a, 0)
		})
		onR := r.newNative("", 1, func(_ Value, a []Value) Value {
			r.call(fo, Undefined, nil)
			panic(&Throw{arg(a, 0)})
		})
		return r.callValue(r.getV(this, "then"), this, []Value{onF, onR})
	})
	r.defMethod(ctor, "resolve", 1, func(this Value, args []Value) Value {
		return r.promiseResolve(arg(args, 0))
	})
	r.defMethod(ctor, "reject", 1, func(this Value, args []Value) Value {
		p, _, reject := r.newPromiseCapability()
		reject(arg(args, 0))
		return p
	})
	combinator := func(name string, mode int) {
		r.defMethod(ctor, name, 1, func(this Value, args []Value) Value {
			p, resolve, reject := r.newPromiseCapability()
			items := r.iterToSlice(arg(args, 0))
			results := make([]Value, len(items))
			remaining := len(items)
			if remaining == 0 {
				switch mode {
				case 0, 1:
					resolve(r.newArray(results))
				case 3:
					reject(r.makeError("AggregateError", "All promises were rejected"))
				}
				return p
			}
			for i, it := range items {
				i := i
				ip := r.promiseResolve(it)
				onF := r.newNative("", 1, func(_ Value, a []Value) Value {
					switch mode {
					case 0:
						results[i] = arg(a, 0)
						remaining--
						if remaining == 0 {
							resolve(r.newArray(results))
						}
					case 1:
						o := r.newObject()
						o.Set("status", "fulfilled")
						o.Set("value", arg(a, 0))
						results[i] = o
						remaining--
						if remaining == 0 {
							resolve(r.newArray(results))
						}
					case 2, 3:
						resolve(arg(a, 0))
					}
					return Undefined
				})
				onR := r.newNative("", 1, func(_ Value, a []Value) Value {
					switch mode {
					case 0, 2:
						reject(arg(a, 0))
					case 1:
						o := r.newObject()
						o.Set("status", "rejected")
						o.Set("reason", arg(a, 0))
						results[i] = o
						remaining--
						if remaining == 0 {
							resolve(r.newArray(results))
						}
					case 3:
						results[i] = arg(a, 0)
						remaining--
						if remaining == 0 {
							e := r.makeError("AggregateError", "All promises were rejected")
							e.DefineHidden("errors", r.newArray(results))
							reject(e)
						}
					}
					return Undefined
				})
				r.promiseThen(ip, onF, onR)
			}
			return p
		})
	}
	combinator("all", 0)
	combinator("allSettled", 1)
	combinator("race", 2)
	combinator("any", 3)
}

// ---------- Reflect ----------

func (r *Runtime) initReflect() {
	rf := r.newObject()
	r.Global.DefineHidden("Reflect", rf)
	rf.setOwn(r.symToStringTag, &Property{Value: "Reflect", Configurable: true})
	needObj := func(v Value, fn string) *Object {
		o, ok := v.(*Object)
		if !ok {
			panic(r.newTypeError("Reflect." + fn + " called on non-object"))
		}
		return o
	}
	r.defMethod(rf, "apply", 3, func(this Value, args []Value) Value {
		f := r.callbackFn(arg(args, 0), "apply")
		return r.call(f, arg(args, 1), r.arrayLikeToSlice(arg(args, 2)))
	})
	r.defMethod(rf, "construct", 2, func(this Value, args []Value) Value {
		f, ok := arg(args, 0).(*Object)
		if !ok || !f.IsConstructor() {
			panic(r.newTypeError("Value is not a constructor"))
		}
		nt := f
		if len(args) > 2 {
			if o, ok := args[2].(*Object); ok {
				nt = o
			}
		}
		return r.construct(f, r.arrayLikeToSlice(arg(args, 1)), nt)
	})
	r.defMethod(rf, "defineProperty", 3, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "defineProperty")
		desc, has := r.toDescriptor(arg(args, 2))
		ok := true
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					if _, isT := rec.(*Throw); isT {
						ok = false
						return
					}
					panic(rec)
				}
			}()
			r.defineOwnProperty(o, r.toPropertyKey(arg(args, 1)), desc, has)
		}()
		return ok
	})
	r.defMethod(rf, "deleteProperty", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "deleteProperty")
		return o.deleteOwn(r.toPropertyKey(arg(args, 1)))
	})
	r.defMethod(rf, "get", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "get")
		recv := Value(o)
		if len(args) > 2 {
			recv = args[2]
		}
		return r.getProp(o, r.toPropertyKey(arg(args, 1)), recv)
	})
	r.defMethod(rf, "set", 3, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "set")
		recv := Value(o)
		if len(args) > 3 {
			recv = args[3]
		}
		ok := true
		func() {
			defer func() {
				if rec := recover(); rec != nil {
					if _, isT := rec.(*Throw); isT {
						ok = false
						return
					}
					panic(rec)
				}
			}()
			r.setProp(o, r.toPropertyKey(arg(args, 1)), arg(args, 2), recv)
		}()
		return ok
	})
	r.defMethod(rf, "has", 2, func(this Value, args []Value) Value {
		return r.hasProperty(needObj(arg(args, 0), "has"), r.toPropertyKey(arg(args, 1)))
	})
	r.defMethod(rf, "ownKeys", 1, func(this Value, args []Value) Value {
		return r.newArray(r.ownKeys(needObj(arg(args, 0), "ownKeys"), true))
	})
	r.defMethod(rf, "getOwnPropertyDescriptor", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "getOwnPropertyDescriptor")
		return r.fromDescriptor(r.getOwnPropertyFull(o, r.toPropertyKey(arg(args, 1))))
	})
	r.defMethod(rf, "getPrototypeOf", 1, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "getPrototypeOf")
		if o.Proto == nil {
			return Null
		}
		return o.Proto
	})
	r.defMethod(rf, "setPrototypeOf", 2, func(this Value, args []Value) Value {
		o := needObj(arg(args, 0), "setPrototypeOf")
		switch p := arg(args, 1).(type) {
		case *Object:
			o.Proto = p
		case nullType:
			o.Proto = nil
		default:
			panic(r.newTypeError("Object prototype may only be an Object or null: " + r.safeToString(p)))
		}
		return true
	})
	r.defMethod(rf, "isExtensible", 1, func(this Value, args []Value) Value {
		return needObj(arg(args, 0), "isExtensible").Extensible
	})
	r.defMethod(rf, "preventExtensions", 1, func(this Value, args []Value) Value {
		needObj(arg(args, 0), "preventExtensions").Extensible = false
		return true
	})
	r.initProxy()
}

// ---------- Proxy ----------

type proxyData struct {
	target  *Object
	handler *Object
}

func (r *Runtime) proxyTrap(px *proxyData, name string) *Object {
	if px.handler == nil {
		panic(r.newTypeError("Cannot perform '" + name + "' on a proxy that has been revoked"))
	}
	t := r.GetStr(px.handler, name)
	if f, ok := t.(*Object); ok && f.IsCallable() {
		return f
	}
	return nil
}

func keyVal(k Value) Value { return k }

func (r *Runtime) proxyGet(o *Object, px *proxyData, key Value, receiver Value) Value {
	if t := r.proxyTrap(px, "get"); t != nil {
		return r.call(t, px.handler, []Value{px.target, keyVal(key), receiver})
	}
	return r.getProp(px.target, key, receiver)
}

func (r *Runtime) proxySet(o *Object, px *proxyData, key Value, v Value, receiver Value) {
	if t := r.proxyTrap(px, "set"); t != nil {
		res := r.call(t, px.handler, []Value{px.target, keyVal(key), v, receiver})
		if !toBoolean(res) {
			panic(r.newTypeError("'set' on proxy: trap returned falsish for property '" + keyToDisplay(key) + "'"))
		}
		return
	}
	if receiver == Value(o) {
		receiver = px.target
	}
	r.setProp(px.target, key, v, receiver)
}

func (r *Runtime) proxyHas(o *Object, px *proxyData, key Value) bool {
	if t := r.proxyTrap(px, "has"); t != nil {
		return toBoolean(r.call(t, px.handler, []Value{px.target, keyVal(key)}))
	}
	return r.hasProperty(px.target, key)
}

func (r *Runtime) proxyDelete(o *Object, px *proxyData, key Value) bool {
	if t := r.proxyTrap(px, "deleteProperty"); t != nil {
		return toBoolean(r.call(t, px.handler, []Value{px.target, keyVal(key)}))
	}
	return r.deleteProp(px.target, key)
}

func (r *Runtime) proxyOwnKeys(o *Object, px *proxyData) []Value {
	if t := r.proxyTrap(px, "ownKeys"); t != nil {
		res := r.call(t, px.handler, []Value{px.target})
		return r.arrayLikeToSlice(res)
	}
	return r.ownKeys(px.target, true)
}

func (r *Runtime) proxyGetOwnProperty(o *Object, px *proxyData, key Value) *Property {
	if t := r.proxyTrap(px, "getOwnPropertyDescriptor"); t != nil {
		res := r.call(t, px.handler, []Value{px.target, keyVal(key)})
		if res == Undefined {
			return nil
		}
		d, _ := r.toDescriptor(res)
		return d
	}
	if r.proxyTrap(px, "ownKeys") != nil {
		// assume enumerable data property
		return &Property{Value: r.proxyGet(o, px, key, o), Enumerable: true, Configurable: true, Writable: true}
	}
	return r.getOwnPropertyFull(px.target, key)
}

func (r *Runtime) initProxy() {
	ctor := r.newCtor("Proxy", 2, func(this Value, args []Value) Value {
		panic(r.newTypeError("Constructor Proxy requires 'new'"))
	}, func(args []Value, nt *Object) Value {
		t, ok1 := arg(args, 0).(*Object)
		h, ok2 := arg(args, 1).(*Object)
		if !ok1 || !ok2 {
			panic(r.newTypeError("Cannot create proxy with a non-object as target or handler"))
		}
		return r.newProxy(t, h)
	}, nil)
	r.defMethod(ctor, "revocable", 2, func(this Value, args []Value) Value {
		t, ok1 := arg(args, 0).(*Object)
		h, ok2 := arg(args, 1).(*Object)
		if !ok1 || !ok2 {
			panic(r.newTypeError("Cannot create proxy with a non-object as target or handler"))
		}
		p := r.newProxy(t, h)
		res := r.newObject()
		res.Set("proxy", p)
		res.Set("revoke", r.newNative("", 0, func(this Value, a []Value) Value {
			p.Internal.(*proxyData).handler = nil
			return Undefined
		}))
		return res
	})
}

func (r *Runtime) newProxy(t, h *Object) *Object {
	px := &proxyData{target: t, handler: h}
	o := &Object{Class: t.Class, Proto: nil, Extensible: true, rt: r, Internal: px}
	if t.IsCallable() {
		o.Call = func(this Value, args []Value) Value {
			if tr := r.proxyTrap(px, "apply"); tr != nil {
				return r.call(tr, px.handler, []Value{px.target, this, r.newArray(append([]Value{}, args...))})
			}
			return r.call(px.target, this, args)
		}
		if t.IsConstructor() {
			o.Construct = func(args []Value, nt *Object) Value {
				if tr := r.proxyTrap(px, "construct"); tr != nil {
					return r.call(tr, px.handler, []Value{px.target, r.newArray(append([]Value{}, args...)), nt})
				}
				if nt == o {
					nt = px.target
				}
				return r.construct(px.target, args, nt)
			}
		}
	}
	return o
}

// ---------- typed arrays ----------

type typedArray struct {
	kind   string
	data   []float64
	length int
}

func (t *typedArray) get(i int) Value {
	return t.data[i]
}

func (t *typedArray) set(r *Runtime, i int, v Value) {
	f := r.toNumber(v)
	t.data[i] = convTyped(t.kind, f)
}

func convTyped(kind string, f float64) float64 {
	switch kind {
	case "Uint8Array":
		return float64(uint8(toInt32(f)))
	case "Uint8ClampedArray":
		if f != f {
			return 0
		}
		if f < 0 {
			return 0
		}
		if f > 255 {
			return 255
		}
		return math.RoundToEven(f)
	case "Int8Array":
		return float64(int8(toInt32(f)))
	case "Uint16Array":
		return float64(uint16(toInt32(f)))
	case "Int16Array":
		return float64(int16(toInt32(f)))
	case "Uint32Array":
		return float64(toUint32(f))
	case "Int32Array":
		return float64(toInt32(f))
	case "Float32Array":
		return float64(float32(f))
	}
	return f
}

func (r *Runtime) initTypedArrays() {
	r.TypedArrayProto = r.newObject()
	r.typedArrayProtos = map[string]*Object{}
	tp := r.TypedArrayProto
	for _, name := range []string{"forEach", "map", "filter", "join", "indexOf", "lastIndexOf", "includes", "reduce", "reduceRight", "some", "every", "find", "findIndex", "findLast", "findLastIndex", "at", "keys", "values", "entries", "toString", "toLocaleString"} {
		if p := r.ArrayProto.getOwnProp(name); p != nil {
			if name == "map" || name == "filter" {
				orig := p.Value.(*Object)
				nm := name
				r.defMethod(tp, nm, 1, func(this Value, args []Value) Value {
					res := r.call(orig, this, args).(*Object)
					to := this.(*Object)
					ta := to.Internal.(*typedArray)
					return r.newTypedArray(ta.kind, res.Arr)
				})
				continue
			}
			tp.DefineHidden(name, p.Value)
		}
	}
	tp.DefineHidden(r.symIterator, r.GetStr(r.ArrayProto, "values"))
	r.defGetter(tp, "length", func(this Value, args []Value) Value {
		if o, ok := this.(*Object); ok {
			if ta, ok := o.Internal.(*typedArray); ok {
				return float64(ta.length)
			}
		}
		return 0.0
	})
	r.defMethod(tp, "set", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		src := r.arrayLikeToSlice(arg(args, 0))
		off := int(r.toIntegerOrInfinity(arg(args, 1)))
		for i, v := range src {
			if off+i < ta.length {
				ta.set(r, off+i, v)
			}
		}
		return Undefined
	})
	slice := func(name string) {
		r.defMethod(tp, name, 2, func(this Value, args []Value) Value {
			o := this.(*Object)
			ta := o.Internal.(*typedArray)
			start := relIndex(r.toIntegerOrInfinity(arg(args, 0)), ta.length)
			end := ta.length
			if e := arg(args, 1); e != Undefined {
				end = relIndex(r.toIntegerOrInfinity(e), ta.length)
			}
			var vals []Value
			for i := start; i < end; i++ {
				vals = append(vals, ta.data[i])
			}
			return r.newTypedArray(ta.kind, vals)
		})
	}
	slice("slice")
	slice("subarray")
	r.defMethod(tp, "fill", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		for i := 0; i < ta.length; i++ {
			ta.set(r, i, arg(args, 0))
		}
		return o
	})
	r.defMethod(tp, "reverse", 0, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		for i, j := 0, ta.length-1; i < j; i, j = i+1, j-1 {
			ta.data[i], ta.data[j] = ta.data[j], ta.data[i]
		}
		return o
	})
	r.defMethod(tp, "sort", 1, func(this Value, args []Value) Value {
		o := this.(*Object)
		ta := o.Internal.(*typedArray)
		vals := make([]Value, ta.length)
		for i := range vals {
			vals[i] = ta.data[i]
		}
		var cf *Object
		if f, ok := arg(args, 0).(*Object); ok {
			cf = f
		}
		if cf == nil {
			sortStable(vals, func(a, b Value) bool { return a.(float64) < b.(float64) })
		} else {
			r.sortValues(vals, cf)
		}
		for i := range vals {
			ta.data[i] = vals[i].(float64)
		}
		return o
	})
	for _, kind := range []string{"Uint8Array", "Uint8ClampedArray", "Int8Array", "Uint16Array", "Int16Array", "Uint32Array", "Int32Array", "Float32Array", "Float64Array", "BigInt64Array", "BigUint64Array"} {
		kind := kind
		proto := r.newObjectProto(tp)
		r.typedArrayProtos[kind] = proto
		proto.setOwn(r.symToStringTag, &Property{Value: kind, Configurable: true})
		ctor := r.newCtor(kind, 3, func(this Value, args []Value) Value {
			panic(r.newTypeError("Constructor " + kind + " requires 'new'"))
		}, func(args []Value, nt *Object) Value {
			a0 := arg(args, 0)
			switch x := a0.(type) {
			case float64:
				n := int(x)
				vals := make([]Value, n)
				for i := range vals {
					vals[i] = 0.0
				}
				return r.newTypedArray(kind, vals)
			case *Object:
				return r.newTypedArray(kind, r.iterToSlice(x))
			}
			return r.newTypedArray(kind, nil)
		}, proto)
		r.defMethod(ctor, "from", 1, func(this Value, args []Value) Value {
			vals := r.iterToSlice(arg(args, 0))
			if f, ok := arg(args, 1).(*Object); ok && f.IsCallable() {
				for i, v := range vals {
					vals[i] = r.call(f, Undefined, []Value{v, float64(i)})
				}
			}
			return r.newTypedArray(kind, vals)
		})
		r.defMethod(ctor, "of", 0, func(this Value, args []Value) Value {
			return r.newTypedArray(kind, append([]Value{}, args...))
		})
