package js

// Compile-time validation emulating goja's compiler checks.

type validator struct {
	strict   bool
	err      *SyntaxErr
	src      []rune
	inMethod int
	privates []map[string]bool
	inFunc   int
}

func (v *validator) fail(idx int, msg string) {
	if v.err != nil {
		return
	}
	line, col := lineCol(v.src, idx)
	v.err = &SyntaxErr{Msg: msg, Idx: idx, Line: line, Col: col}
}

func (v *validator) checkIdentName(name string, idx int) {
	if v.strict && strictReserved[name] {
		v.fail(idx, "Unexpected strict mode reserved word")
	}
}

func (v *validator) checkBindingName(name string, idx int) {
	v.checkIdentName(name, idx)
	if v.strict && (name == "eval" || name == "arguments") {
		v.fail(idx, "Assignment to eval or arguments is not allowed in strict mode")
	}
}

// Validate checks a parsed program. strict selects strict-mode checks.
func Validate(src string, prog []Stmt, strict bool) *SyntaxErr {
	v := &validator{strict: strict, src: []rune(src)}
	v.stmts(prog)
	return v.err
}

func (v *validator) stmts(list []Stmt) {
	for _, s := range list {
		if v.err != nil {
			return
		}
		v.stmt(s)
	}
}

func (v *validator) pattern(p Node, binding bool) {
	if v.err != nil || p == nil {
		return
	}
	switch t := p.(type) {
	case *Identifier:
		if binding {
			v.checkBindingName(t.Name, t.idx)
		} else {
			v.checkIdentName(t.Name, t.idx)
			if v.strict && (t.Name == "eval" || t.Name == "arguments") {
				v.fail(t.idx, "Assignment to eval or arguments is not allowed in strict mode")
			}
		}
	case *ObjectPattern:
		for _, pp := range t.Props {
			if pp.Computed {
				v.expr(pp.Key)
			}
			v.pattern(pp.Target, binding)
			if pp.Default != nil {
				v.expr(pp.Default)
			}
		}
		v.pattern(t.Rest, binding)
	case *ArrayPattern:
		for _, el := range t.Elems {
			if el.Target != nil {
				v.pattern(el.Target, binding)
			}
			if el.Default != nil {
				v.expr(el.Default)
			}
		}
		v.pattern(t.Rest, binding)
	case *AssignExpr:
		v.pattern(t.Target, binding)
		v.expr(t.Value)
	case Expr:
		v.expr(t)
	}
}

func (v *validator) stmt(s Stmt) {
	if v.err != nil || s == nil {
		return
	}
	switch n := s.(type) {
	case *ExprStmt:
		v.expr(n.X)
	case *VarDecl:
		for _, d := range n.Decls {
			v.pattern(d.Target, true)
			if d.Init != nil {
				v.expr(d.Init)
			}
		}
	case *FuncDecl:
		v.function(n.Func)
	case *ClassDecl:
		v.class(n.Class)
	case *BlockStmt:
		v.stmts(n.List)
	case *IfStmt:
		v.expr(n.Test)
		v.stmt(n.Cons)
		v.stmt(n.Alt)
	case *ForStmt:
		switch i := n.Init.(type) {
		case *VarDecl:
			v.stmt(i)
		case Expr:
			v.expr(i)
		}
		if n.Test != nil {
			v.expr(n.Test)
		}
		if n.Update != nil {
			v.expr(n.Update)
		}
		v.stmt(n.Body)
	case *ForInStmt:
		switch l := n.Left.(type) {
		case *VarDecl:
			v.stmt(l)
		default:
			v.pattern(l, false)
		}
		v.expr(n.Right)
		v.stmt(n.Body)
	case *WhileStmt:
		v.expr(n.Test)
		v.stmt(n.Body)
	case *DoWhileStmt:
		v.stmt(n.Body)
		v.expr(n.Test)
	case *ReturnStmt:
		if n.Arg != nil {
			v.expr(n.Arg)
		}
	case *ThrowStmt:
		v.expr(n.Arg)
	case *TryStmt:
		v.stmt(n.Block)
		if n.Param != nil {
			v.pattern(n.Param, true)
		}
		if n.Handler != nil {
			v.stmt(n.Handler)
		}
		if n.Finalizer != nil {
			v.stmt(n.Finalizer)
		}
	case *SwitchStmt:
		v.expr(n.Disc)
		for _, c := range n.Cases {
			if c.Test != nil {
				v.expr(c.Test)
			}
			v.stmts(c.Body)
		}
	case *LabeledStmt:
		v.stmt(n.Body)
	case *WithStmt:
		if v.strict {
			v.fail(n.idx, "Strict mode code may not include a with statement")
			return
		}
		v.expr(n.Obj)
		v.stmt(n.Body)
	}
}

func (v *validator) function(f *FuncLit) {
	if v.err != nil {
		return
	}
	if f.Name != nil {
		v.checkBindingName(f.Name.Name, f.Name.idx)
	}
	simple := f.Rest == nil
	for i, p := range f.Params {
		if _, ok := p.(*Identifier); !ok {
			simple = false
		}
		if f.Defaults != nil && i < len(f.Defaults) && f.Defaults[i] != nil {
			simple = false
		}
	}
	if v.strict || f.IsArrow || !simple || f.IsMethod {
		seen := map[string]bool{}
		all := append([]Pattern{}, f.Params...)
		if f.Rest != nil {
			all = append(all, f.Rest)
		}
		for _, p := range all {
			for _, id := range patternIdents(p) {
				if seen[id.Name] {
					v.fail(id.idx, "Duplicate parameter name not allowed in this context")
					return
				}
				seen[id.Name] = true
			}
		}
	}
	for i, p := range f.Params {
		v.pattern(p, true)
		if f.Defaults != nil && i < len(f.Defaults) && f.Defaults[i] != nil {
			v.expr(f.Defaults[i])
		}
	}
	if f.Rest != nil {
		v.pattern(f.Rest, true)
	}
	if f.IsMethod || f.IsCtor {
		v.inMethod++
	} else if !f.IsArrow {
		v.inMethod -= 1000
	}
	if f.ExprBody != nil {
		v.expr(f.ExprBody)
	} else {
		v.stmts(f.Body)
	}
	if f.IsMethod || f.IsCtor {
		v.inMethod--
	} else if !f.IsArrow {
		v.inMethod += 1000
	}
}

func patternIdents(p Node) []*Identifier {
	var out []*Identifier
	var walk func(p Node)
	walk = func(p Node) {
		switch t := p.(type) {
		case *Identifier:
			out = append(out, t)
		case *ObjectPattern:
			for _, pp := range t.Props {
				walk(pp.Target)
			}
			if t.Rest != nil {
				walk(t.Rest)
			}
		case *ArrayPattern:
			for _, el := range t.Elems {
				if el.Target != nil {
					walk(el.Target)
				}
			}
			if t.Rest != nil {
				walk(t.Rest)
			}
		case *AssignExpr:
			walk(t.Target)
		}
	}
	walk(p)
	return out
}

func (v *validator) class(c *ClassLit) {
	if v.err != nil {
		return
	}
	if c.Name != nil {
		v.checkBindingName(c.Name.Name, c.Name.idx)
	}
	if c.Super != nil {
		v.expr(c.Super)
	}
	privs := map[string]bool{}
	for _, m := range c.Members {
		if m.Private {
			privs[m.Name] = true
		}
	}
	v.privates = append(v.privates, privs)
	saved := v.strict
	v.strict = true
	if c.Ctor != nil {
		v.function(c.Ctor)
	}
	for _, m := range c.Members {
		if m.Computed {
			v.expr(m.Key)
		}
		if m.IsBlock {
			v.inMethod++
			v.stmts(m.Block)
			v.inMethod--
			continue
		}
		if f, ok := m.Value.(*FuncLit); ok && m.Kind != propInit {
			v.function(f)
		} else if m.Value != nil {
			v.inMethod++
			v.expr(m.Value)
			v.inMethod--
		}
	}
	v.strict = saved
	v.privates = v.privates[:len(v.privates)-1]
}

func (v *validator) privateDeclared(name string) bool {
	for _, m := range v.privates {
		if m[name] {
			return true
		}
	}
	return false
}

func (v *validator) expr(e Expr) {
	if v.err != nil || e == nil {
		return
	}
	switch n := e.(type) {
	case *Identifier:
		if len(n.Name) > 0 && n.Name[0] == '#' {
			v.fail(n.idx, "Compiler bug: Unknown expression type: *ast.PrivateIdentifier")
			return
		}
		v.checkIdentName(n.Name, n.idx)
	case *NumberLit:
		if v.strict && n.Octal {
			v.fail(n.idx, "Octal literals are not allowed in strict mode")
		}
	case *RegExpLit:
		_, msg := compileRegex(n.Pattern, n.Flags)
		if msg != "" {
			v.fail(n.idx, msg)
		}
	case *TemplateLit:
		if n.Tag != nil {
			v.expr(n.Tag)
		}
		for _, x := range n.Exprs {
			v.expr(x)
		}
	case *ArrayLit:
		for _, x := range n.Elems {
			if x != nil {
				v.expr(x)
			}
		}
	case *SpreadElem:
		v.expr(n.Arg)
	case *ObjectLit:
		for _, p := range n.Props {
			if p.Computed {
				v.expr(p.Key)
			}
			if f, ok := p.Value.(*FuncLit); ok && (p.Kind == propMethod || p.Kind == propGet || p.Kind == propSet) {
				v.function(f)
				continue
			}
			if p.Shorthand {
				if id, ok := p.Value.(*Identifier); ok {
					v.checkIdentName(id.Name, id.idx)
					continue
				}
			}
			v.expr(p.Value)
		}
	case *FuncLit:
		v.function(n)
	case *ClassLit:
		v.class(n)
	case *UnaryExpr:
		if n.Op == tDELETE && v.strict {
			if id, ok := n.Operand.(*Identifier); ok {
				v.fail(id.idx, "Delete of an unqualified identifier in strict mode.")
				return
			}
		}
		v.expr(n.Operand)
	case *UpdateExpr:
		if id, ok := n.Target.(*Identifier); ok && v.strict && (id.Name == "eval" || id.Name == "arguments") {
			v.fail(id.idx, "Assignment to eval or arguments is not allowed in strict mode")
			return
		}
		v.expr(n.Target)
	case *BinaryExpr:
		v.expr(n.Left)
		v.expr(n.Right)
	case *LogicalExpr:
		v.expr(n.Left)
		v.expr(n.Right)
	case *AssignExpr:
		if id, ok := n.Target.(*Identifier); ok {
			v.checkIdentName(id.Name, id.idx)
			if v.strict && (id.Name == "eval" || id.Name == "arguments") {
				v.fail(id.idx, "Assignment to eval or arguments is not allowed in strict mode")
				return
			}
		} else {
			v.pattern(n.Target, false)
		}
		v.expr(n.Value)
	case *CondExpr:
		v.expr(n.Test)
		v.expr(n.Cons)
		v.expr(n.Alt)
	case *CallExpr:
		if _, ok := n.Callee.(*SuperExpr); ok {
			if v.inMethod <= 0 {
				v.fail(n.Callee.Pos(), "'super' keyword unexpected here")
				return
			}
		} else {
			v.expr(n.Callee)
		}
		for _, a := range n.Args {
			v.expr(a)
		}
	case *NewExpr:
		v.expr(n.Callee)
		for _, a := range n.Args {
			v.expr(a)
		}
	case *MemberExpr:
		if _, ok := n.Object.(*SuperExpr); ok {
			if v.inMethod <= 0 {
				v.fail(n.Object.Pos(), "'super' keyword unexpected here")
				return
			}
		} else {
			v.expr(n.Object)
		}
		if n.Private && !v.privateDeclared(n.Name[1:]) && !v.privateDeclared(n.Name) {
			v.fail(n.PropIdx, "Private field '"+n.Name+"' must be declared in an enclosing class")
			return
		}
		if n.Computed {
			v.expr(n.Prop)
		}
	case *SuperExpr:
		if v.inMethod <= 0 {
			v.fail(n.idx, "'super' keyword unexpected here")
		}
	case *OptionalChain:
		v.expr(n.Expr)
	case *SeqExpr:
		for _, x := range n.List {
			v.expr(x)
		}
	case *YieldExpr:
		if n.Arg != nil {
			v.expr(n.Arg)
		}
	case *AwaitExpr:
		v.expr(n.Arg)
	case *ParenExpr:
		v.expr(n.Expr)
	case *ObjectPattern, *ArrayPattern:
		v.pattern(n, false)
	}
}

// ParseAndValidate parses a script and runs validation.
func ParseAndValidate(src string, strict bool) ([]Stmt, *SyntaxErr, bool) {
	prog, serr, _ := parseWith(src, false)
	if serr != nil {
		return nil, serr, false
	}
	if verr := Validate(src, prog, strict); verr != nil {
		return nil, verr, true
	}
	return prog, nil, false
}
