	case *YieldExpr:
		if n.Arg != nil {
			v.expr(n.Arg)
		}
	case *AwaitExpr:
		v.expr(n.Arg)
	case *ParenExpr:
		v.expr(n.Expr)
	case *ObjectPattern, *ArrayPattern:
		v.pattern(n, false)
