// ParseAndValidate parses a script and runs validation.
func ParseAndValidate(src string, strict bool) ([]Stmt, *SyntaxErr, bool) {
	prog, serr, _ := parseWith(src, false)
	if serr != nil {
		return nil, serr, false
	}
	if verr := Validate(src, prog, strict); verr != nil {
		return nil, verr, true
	}
	return prog, nil, false
}
