package engine

import (
	"bufio"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math"
	"math/big"
	"os"
	"strconv"
	"strings"

	"fx/internal/js"
	"fx/internal/jsonx"
	"fx/internal/yamlconv"

	"github.com/mattn/go-runewidth"
)

type VM struct {
	R        *js.Runtime
	Out      *bufio.Writer
	FilePath string
	main     js.Value
	skip     js.Value
	ExitCode int
}

// ExitError requests program exit with code.
type ExitError struct{ Code int }

// PanicError mimics a Go panic with a message.
type PanicError struct{ Msg string }

func blockFor(code string, args []string, i int) string {
	return "  try {\n    json = apply((function () {\n      const x = this\n      return " + Transpile(code) + "\n    }).call(json), json)\n  } catch (e) {\n    throw " + strconv.Quote(errorHeader(args, i)) + " + e.toString()\n  }\n\n  if (json === skip) return skip\n\n"
}

func errorHeader(args []string, i int) string {
	pre := 0
	for j := 0; j < i; j++ {
		pre += runewidth.StringWidth(args[j]) + 1
	}
	s := "\n  " + strings.Join(args, " ") + "\n  " + strings.Repeat(" ", pre) + strings.Repeat("^", runewidth.StringWidth(args[i])) + "\n\n"
	if t := Transpile(args[i]); t != args[i] {
		s += t + "\n\n"
	}
	return s
}

func mainSource(args []string, only int) string {
	var sb strings.Builder
	sb.WriteString("function __main__(json) {\n\n")
	for i, a := range args {
		if only >= 0 && i != only {
			continue
		}
		sb.WriteString(blockFor(a, args, i))
	}
	sb.WriteString("  return json\n}")
	return sb.String()
}

// CheckArgs validates each code argument. Returns error output (to stderr) or "".
func CheckArgs(args []string) string {
	for i := range args {
		src := "\n" + mainSource(args, i) + "\n"
		_, serr, compile := js.ParseAndValidate(src, false)
		if serr != nil {
			if compile {
				return fmt.Sprintf("SyntaxError: SyntaxError: %s at %d:%d\n", serr.Msg, serr.Line, serr.Col)
			}
			msg := serr.Msg
			if serr.Multiple {
				msg += " "
			}
			pre := 0
			for j := 0; j < i; j++ {
				pre += runewidth.StringWidth(args[j]) + 1
			}
			out := "\n  " + strings.Join(args, " ") + "\n  " + strings.Repeat(" ", pre) + strings.Repeat("^", runewidth.StringWidth(args[i])) + "\n\n"
			if t := Transpile(args[i]); t != args[i] {
				out += t + "\n\n"
			}
			return out + msg + "\n"
		}
	}
	// full strict compile
	src := mainSource(args, -1)
	_, serr, _ := js.ParseAndValidate(src, true)
	if serr != nil {
		return fmt.Sprintf("SyntaxError: SyntaxError: %s at %d:%d\n", serr.Msg, serr.Line+205, serr.Col)
	}
	return ""
}

func NewVM(args []string, out *bufio.Writer, filePath string) *VM {
	r := js.NewRuntime()
	vm := &VM{R: r, Out: out, FilePath: filePath}
	r.DefineFunc("println", 0, func(this js.Value, a []js.Value) js.Value {
		s := ""
		if len(a) > 0 {
			s = vm.exportToGoString(a[0])
		}
		out.WriteString(s)
		out.WriteString("\n")
		return js.Null
	})
	r.DefineFunc("__save__", 0, func(this js.Value, a []js.Value) js.Value {
		if vm.FilePath == "" {
			panic(r.NewGoError("specify a file as the first argument to be able to save: fx file.json "))
		}
		s := ""
		if len(a) > 0 {
			s = vm.exportToGoString(a[0])
		}
		if err := os.WriteFile(vm.FilePath, []byte(s), 0644); err != nil {
			panic(r.NewGoError(err.Error()))
		}
		return js.Null
	})
	r.DefineFunc("__stringify__", 0, func(this js.Value, a []js.Value) js.Value {
		var v js.Value = js.Undefined
		if len(a) > 0 {
			v = a[0]
		}
		return vm.Stringify(v, 0) + "\n"
	})
	r.DefineFunc("__toBase64__", 0, func(this js.Value, a []js.Value) js.Value {
		s := ""
		if len(a) > 0 {
			s = vm.exportToGoString(a[0])
		}
		return base64.StdEncoding.EncodeToString([]byte(s))
	})
	r.DefineFunc("__fromBase64__", 0, func(this js.Value, a []js.Value) js.Value {
		s := ""
		if len(a) > 0 {
			s = vm.exportToGoString(a[0])
		}
		b, err := base64.StdEncoding.DecodeString(s)
		if err != nil {
			panic(r.NewGoError(err.Error()))
		}
		return strings.ToValidUTF8(string(b), "\uFFFD")
	})
	r.DefineFunc("__yaml_parse__", 0, func(this js.Value, a []js.Value) js.Value {
		s := ""
		if len(a) > 0 {
			s = vm.exportToGoString(a[0])
		}
		res, err := yamlconv.ToJSON([]byte(s))
		if err != nil {
			panic(r.NewGoError(err.Error()))
		}
		return string(res)
	})
	r.DefineFunc("__yaml_stringify__", 0, func(this js.Value, a []js.Value) js.Value {
		var v js.Value = js.Undefined
		if len(a) > 0 {
			v = a[0]
		}
		res, err := yamlconv.FromValue(vm.toYAMLNode(v))
		if err != nil {
			panic(r.NewGoError(err.Error()))
		}
		return res
	})
	r.DefineFunc("__exit__", 0, func(this js.Value, a []js.Value) js.Value {
		code := 0
		if len(a) > 0 {
			if f, ok := a[0].(float64); ok {
				code = int(f)
			}
		}
		panic(&ExitError{Code: code})
	})
	if err := r.RunScript(prelude); err != nil {
		panic("prelude: " + err.Msg)
	}
	src := mainSource(args, -1)
	if err := r.RunScript(src); err != nil {
		panic("main: " + err.Msg)
	}
	vm.main = r.LookupGlobal("__main__")
	vm.skip = r.LookupGlobal("skip")
	reorderGlobals(r)
	return vm
}

var globalOrder = []string{"Object", "Function", "Array", "String", "Number", "BigInt", "RegExp", "Date", "Boolean", "Proxy", "Reflect", "Error", "AggregateError", "TypeError", "ReferenceError", "SyntaxError", "RangeError", "EvalError", "URIError", "GoError", "eval", "Math", "JSON", "ArrayBuffer", "DataView", "Uint8Array", "Uint8ClampedArray", "Int8Array", "Uint16Array", "Int16Array", "Uint32Array", "Int32Array", "Float32Array", "Float64Array", "BigInt64Array", "BigUint64Array", "Symbol", "WeakSet", "WeakMap", "Map", "Set", "Promise", "globalThis", "NaN", "undefined", "Infinity", "isNaN", "parseInt", "parseFloat", "isFinite", "decodeURI", "decodeURIComponent", "encodeURI", "encodeURIComponent", "escape", "unescape"}

func reorderGlobals(r *js.Runtime) {
	r.ReorderKeys(r.GlobalObject(), globalOrder)
}

func (vm *VM) exportToGoString(v js.Value) string {
	switch x := v.(type) {
	case nil:
		return ""
	case string:
		return strings.ToValidUTF8(x, "\uFFFD")
	}
	if js.IsUndefined(v) || js.IsNull(v) {
		return ""
	}
	if vm.R.Classify(v) == js.ExString {
		return vm.R.ExportString(v)
	}
	return vm.R.ToString(v)
}

// ToValue converts a JSON node into a JS value.
func (vm *VM) ToValue(n *jsonx.Node) js.Value {
	r := vm.R
	switch n.Kind {
	case jsonx.Null:
		return js.Null
	case jsonx.Bool:
		return n.Raw == "true"
	case jsonx.String:
		var s string
		if err := json.Unmarshal([]byte(n.Raw), &s); err != nil {
			panic(&PanicError{Msg: err.Error()})
		}
		return s
	case jsonx.Number:
