package yamlconv

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"math"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

var floatRe = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+\.[0-9]*)([eE][-+]?[0-9]+)?$`)
var decRe = regexp.MustCompile(`^[-+]?[0-9][0-9_]*$`)

type scalarKind int

const (
	kString scalarKind = iota
	kNull
	kBool
	kInt
	kFloat
)

// resolvePlain resolves a plain scalar like goccy/go-yaml.
func resolvePlain(s string) (scalarKind, string) {
	switch s {
	case "", "~", "null", "Null", "NULL":
		return kNull, "null"
	case "true", "True", "TRUE":
		return kBool, "true"
	case "false", "False", "FALSE":
		return kBool, "false"
	case ".inf", ".Inf", ".INF":
		return kFloat, ".inf"
	case "-.inf", "-.Inf", "-.INF":
		return kFloat, "-.inf"
	case ".nan", ".NaN", ".NAN":
		return kFloat, ".nan"
	}
	if v, ok := parseYAMLInt(s); ok {
		return kInt, v
	}
	if floatRe.MatchString(s) {
		f, err := strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
		if err == nil {
			return kFloat, formatFloat(f)
		}
	}
	return kString, s
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if f != f {
		return ".nan"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

func parseYAMLInt(s string) (string, bool) {
	neg := false
	body := s
	if strings.HasPrefix(body, "-") {
		neg = true
		body = body[1:]
	} else if strings.HasPrefix(body, "+") {
		body = body[1:]
	}
	base := 10
	digits := body
	switch {
	case strings.HasPrefix(body, "0x"):
		base, digits = 16, body[2:]
	case strings.HasPrefix(body, "0o"):
		base, digits = 8, body[2:]
	case strings.HasPrefix(body, "0b"):
		base, digits = 2, body[2:]
	case len(body) > 1 && body[0] == '0':
		base, digits = 8, body[1:]
	}
	if digits == "" {
		return "", false
	}
	if base == 10 && !decRe.MatchString(body) {
		return "", false
	}
	digits = strings.ReplaceAll(digits, "_", "")
	if digits == "" {
		return "", false
	}
	for _, c := range digits {
		d := -1
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		}
		if d < 0 || d >= base {
			return "", false
		}
	}
	if neg {
		v, err := strconv.ParseInt("-"+digits, base, 64)
		if err != nil {
			return "", false
		}
		return strconv.FormatInt(v, 10), true
	}
	v, err := strconv.ParseUint(digits, base, 64)
	if err != nil {
		return "", false
	}
	return strconv.FormatUint(v, 10), true
}

func quoteJSON(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func scalarJSON(n *yaml.Node) string {
	tag := n.Tag
	if n.Style&(yaml.DoubleQuotedStyle|yaml.SingleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0 && (tag == "" || tag == "!!str" || tag == "!") {
		return quoteJSON(n.Value)
	}
	switch tag {
	case "!!str":
		if n.Style == 0 && n.Tag == "!!str" && !strings.HasPrefix(n.ShortTag(), "!!") {
			return quoteJSON(n.Value)
		}
	}
	explicit := strings.Contains(n.LineComment, "") && false
	_ = explicit
	switch n.Tag {
	case "!!int":
		if v, ok := parseYAMLInt(n.Value); ok {
			return v
		}
		if f, err := strconv.ParseFloat(n.Value, 64); err == nil {
			return strconv.FormatInt(int64(f), 10)
		}
		return "0"
	case "!!float":
		if v, ok := parseYAMLInt(n.Value); ok {
			f, _ := strconv.ParseFloat(v, 64)
			return formatFloat(f)
		}
		k, v := resolvePlain(n.Value)
		if k == kFloat {
			return v
		}
		return "0.0"
	case "!!bool":
		k, v := resolvePlain(n.Value)
		if k == kBool {
			return v
		}
		return "false"
	case "!!null":
		return "null"
	}
	if n.Style&(yaml.DoubleQuotedStyle|yaml.SingleQuotedStyle|yaml.LiteralStyle|yaml.FoldedStyle) != 0 {
		return quoteJSON(n.Value)
	}
	if hasExplicitStrTag(n) {
		return quoteJSON(n.Value)
	}
	k, v := resolvePlain(n.Value)
	if k == kString {
		return quoteJSON(v)
	}
	return v
}

func hasExplicitStrTag(n *yaml.Node) bool {
	return n.Tag == "!!str" && n.Style == yaml.TaggedStyle
}

func keyJSON(n *yaml.Node) string {
	for n.Kind == yaml.AliasNode && n.Alias != nil {
		n = n.Alias
	}
	if n.Kind != yaml.ScalarNode {
		return quoteJSON(n.Value)
	}
	s := scalarJSON(n)
	if strings.HasPrefix(s, "\"") {
		return s
	}
	return quoteJSON(s)
}

func convert(sb *strings.Builder, n *yaml.Node) {
	switch n.Kind {
	case yaml.DocumentNode:
		if len(n.Content) == 0 {
			sb.WriteString("null")
			return
		}
		convert(sb, n.Content[0])
	case yaml.AliasNode:
		if n.Alias != nil {
			convert(sb, n.Alias)
		} else {
			sb.WriteString("null")
		}
	case yaml.ScalarNode:
		sb.WriteString(scalarJSON(n))
	case yaml.SequenceNode:
		sb.WriteString("[")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			convert(sb, c)
		}
		sb.WriteString("]")
	case yaml.MappingNode:
		sb.WriteString("{")
		first := true
		var writePairs func(m *yaml.Node)
		writePairs = func(m *yaml.Node) {
			for m.Kind == yaml.AliasNode && m.Alias != nil {
				m = m.Alias
			}
			if m.Kind != yaml.MappingNode {
				return
			}
			for i := 0; i+1 < len(m.Content); i += 2 {
				k, v := m.Content[i], m.Content[i+1]
				if k.Kind == yaml.ScalarNode && k.Value == "<<" && k.Style == 0 && (k.Tag == "!!merge" || k.Tag == "") {
					vv := v
					for vv.Kind == yaml.AliasNode && vv.Alias != nil {
						vv = vv.Alias
					}
					if vv.Kind == yaml.SequenceNode {
						for _, item := range vv.Content {
							writePairs(item)
						}
					} else {
						writePairs(vv)
					}
					continue
				}
				if !first {
					sb.WriteString(", ")
				}
				first = false
				sb.WriteString(keyJSON(k))
				sb.WriteString(": ")
				convert(sb, v)
			}
		}
		writePairs(n)
		sb.WriteString("}")
	}
}

// ToJSON converts YAML (possibly multi-document) into JSON text.
func ToJSON(data []byte) ([]byte, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var out strings.Builder
	for {
		var n yaml.Node
		err := dec.Decode(&n)
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, formatErr(err)
		}
		if len(n.Content) == 0 {
			break
		}
		if n.Content[0].Kind == yaml.ScalarNode && n.Content[0].Tag == "!!null" && n.Content[0].Value == "" {
			break
		}
		convert(&out, &n)
		out.WriteString("\n")
	}
	return []byte(out.String()), nil
}

func formatErr(err error) error {
	msg := err.Error()
	msg = strings.TrimPrefix(msg, "yaml: ")
	return errors.New(msg)
}
