package yamlconv

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"math"
	"regexp"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

var floatRe = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+\.[0-9]*)([eE][-+]?[0-9]+)?$`)
var decRe = regexp.MustCompile(`^[-+]?[0-9][0-9_]*$`)

type scalarKind int

const (
	kString scalarKind = iota
	kNull
	kBool
	kInt
	kFloat
)

// resolvePlain resolves a plain scalar like goccy/go-yaml.
func resolvePlain(s string) (scalarKind, string) {
	switch s {
	case "", "~", "null", "Null", "NULL":
		return kNull, "null"
	case "true", "True", "TRUE":
		return kBool, "true"
	case "false", "False", "FALSE":
		return kBool, "false"
	case ".inf", ".Inf", ".INF":
		return kFloat, ".inf"
	case "-.inf", "-.Inf", "-.INF":
		return kFloat, "-.inf"
	case ".nan", ".NaN", ".NAN":
		return kFloat, ".nan"
	}
	if v, ok := parseYAMLInt(s); ok {
		return kInt, v
	}
	if floatRe.MatchString(s) {
		f, err := strconv.ParseFloat(strings.ReplaceAll(s, "_", ""), 64)
		if err == nil {
			return kFloat, formatFloat(f)
		}
	}
	return kString, s
}

func formatFloat(f float64) string {
	if math.IsInf(f, 1) {
		return ".inf"
	}
	if math.IsInf(f, -1) {
		return "-.inf"
	}
	if f != f {
		return ".nan"
	}
	s := strconv.FormatFloat(f, 'g', -1, 64)
	if !strings.ContainsAny(s, ".eE") {
		s += ".0"
	}
	return s
}

func parseYAMLInt(s string) (string, bool) {
	neg := false
	body := s
	if strings.HasPrefix(body, "-") {
		neg = true
		body = body[1:]
	} else if strings.HasPrefix(body, "+") {
		body = body[1:]
	}
	base := 10
	digits := body
	switch {
	case strings.HasPrefix(body, "0x"):
		base, digits = 16, body[2:]
	case strings.HasPrefix(body, "0o"):
		base, digits = 8, body[2:]
	case strings.HasPrefix(body, "0b"):
		base, digits = 2, body[2:]
	case len(body) > 1 && body[0] == '0':
		base, digits = 8, body[1:]
	}
	if digits == "" {
		return "", false
	}
	if base == 10 && !decRe.MatchString(body) {
		return "", false
	}
	digits = strings.ReplaceAll(digits, "_", "")
	if digits == "" {
		return "", false
	}
	for _, c := range digits {
		d := -1
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c >= 'a' && c <= 'f':
			d = int(c-'a') + 10
		case c >= 'A' && c <= 'F':
			d = int(c-'A') + 10
		}
		if d < 0 || d >= base {
			return "", false
		}
	}
	if neg {
		v, err := strconv.ParseInt("-"+digits, base, 64)
		if err != nil {
			return "", false
		}
		return strconv.FormatInt(v, 10), true
	}
	v, err := strconv.ParseUint(digits, base, 64)
	if err != nil {
		return "", false
	}
	return strconv.FormatUint(v, 10), true
}

func quoteJSON(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if r < 0x20 {
				sb.WriteString(fmt.Sprintf("\\u%04x", r))
			} else {
				sb.WriteRune(r)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

