	case yaml.ScalarNode:
		sb.WriteString(scalarJSON(n))
	case yaml.SequenceNode:
		sb.WriteString("[")
		for i, c := range n.Content {
			if i > 0 {
				sb.WriteString(", ")
			}
			convert(sb, c)
		}
		sb.WriteString("]")
	case yaml.MappingNode:
		sb.WriteString("{")
		first := true
		var writePairs func(m *yaml.Node)
		writePairs = func(m *yaml.Node) {
