				}
				first = false
				sb.WriteString(keyJSON(k))
				sb.WriteString(": ")
				convert(sb, v)
			}
		}
		writePairs(n)
		sb.WriteString("}")
	}
}

// ToJSON converts YAML (possibly multi-document) into JSON text.
func ToJSON(data []byte) ([]byte, error) {
	dec := yaml.NewDecoder(bytes.NewReader(data))
	var out strings.Builder
	for {
		var n yaml.Node
		err := dec.Decode(&n)
		if errors.Is(err, io.EOF) {
