	case '@', '`', '!', '&', '*', '%', '{', '[', ']', '}', '>', '|', '"', '\'', '#', ' ':
		return true
	}
	if strings.HasPrefix(s, "- ") {
		return true
	}
	if strings.HasSuffix(s, " ") || strings.HasSuffix(s, ":") {
		return true
	}
	if strings.Contains(s, ": ") || strings.Contains(s, "#") || strings.Contains(s, "\\") {
		return true
	}
	return false
}

func dquote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		default:
			sb.WriteRune(r)
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func scalarText(n *YNode, indent string) string {
	if n.Kind == YRaw {
		return n.Value
	}
	s := n.Value
	if strings.Contains(s, "\n") && !strings.HasPrefix(s, " ") {
		header := "|-"
		trimmed := strings.TrimRight(s, "\n")
		trail := len(s) - len(trimmed)
		if trail == 1 {
			header = "|"
		} else if trail > 1 {
			header = "|+"
		}
		lines := strings.Split(trimmed, "\n")
		var sb strings.Builder
		sb.WriteString(header)
		for _, l := range lines {
			sb.WriteString("\n")
			if l != "" {
				sb.WriteString(indent + "  ")
				sb.WriteString(l)
			}
		}
		for i := 1; i < trail; i++ {
			sb.WriteString("\n")
		}
		return sb.String()
	}
	if needsQuote(s) || strings.Contains(s, "\n") {
		return dquote(s)
	}
	return s
}

func keyText(k string) string {
	if needsQuote(k) || strings.Contains(k, "\n") {
		return dquote(k)
	}
	return k
}

func isEmptyColl(n *YNode) bool {
	return (n.Kind == YSeq || n.Kind == YMap) && len(n.Children) == 0
}

func emptyText(n *YNode) string {
	if n.Kind == YSeq {
		return "[]"
	}
	return "{}"
}

func emit(sb *strings.Builder, n *YNode, indent string) {
	switch n.Kind {
	case YMap:
		if len(n.Children) == 0 {
			sb.WriteString(indent + "{}\n")
			return
		}
		for i, c := range n.Children {
			emitMapEntry(sb, n.Keys[i], c, indent, indent)
		}
	case YSeq:
		if len(n.Children) == 0 {
			sb.WriteString(indent + "[]\n")
			return
		}
		for _, c := range n.Children {
			emitSeqItem(sb, c, indent)
		}
	default:
		sb.WriteString(indent + scalarText(n, indent) + "\n")
	}
}

func emitMapEntry(sb *strings.Builder, key string, v *YNode, firstPrefix, indent string) {
	sb.WriteString(firstPrefix + keyText(key) + ":")
	switch {
	case isEmptyColl(v):
		sb.WriteString(" " + emptyText(v) + "\n")
	case v.Kind == YMap:
		sb.WriteString("\n")
		for i, c := range v.Children {
			emitMapEntry(sb, v.Keys[i], c, indent+"  ", indent+"  ")
		}
	case v.Kind == YSeq:
		sb.WriteString("\n")
		for _, c := range v.Children {
			emitSeqItem(sb, c, indent)
		}
	default:
		sb.WriteString(" " + scalarText(v, indent) + "\n")
	}
}

func emitSeqItem(sb *strings.Builder, v *YNode, indent string) {
	switch {
	case isEmptyColl(v):
		sb.WriteString(indent + "- " + emptyText(v) + "\n")
	case v.Kind == YMap:
		for i, c := range v.Children {
			prefix := indent + "  "
			if i == 0 {
				prefix = indent + "- "
			}
			emitMapEntry(sb, v.Keys[i], c, prefix, indent+"  ")
		}
	case v.Kind == YSeq:
		for i, c := range v.Children {
			if i == 0 {
				var inner strings.Builder
				emitSeqItem(&inner, c, indent+"  ")
				s := inner.String()
				sb.WriteString(indent + "- " + strings.TrimPrefix(s, indent+"  "))
			} else {
				emitSeqItem(sb, c, indent+"  ")
			}
		}
	default:
		sb.WriteString(indent + "- " + scalarText(v, indent) + "\n")
	}
}

// FromValue renders a YNode tree as YAML.
func FromValue(n *YNode) (string, error) {
	var sb strings.Builder
	if n.Kind != YMap && n.Kind != YSeq {
		sb.WriteString(scalarText(n, "") + "\n")
		return sb.String(), nil
	}
	emit(&sb, n, "")
	return sb.String(), nil
}

// NumberScalar converts a JSON number token into YAML scalar text.
func NumberScalar(tok string) string {
	if v, ok := parseYAMLInt(tok); ok {
		return v
	}
	if floatRe.MatchString(tok) {
		if f, err := strconv.ParseFloat(tok, 64); err == nil {
			return strconv.FormatFloat(f, 'g', -1, 64)
		}
	}
	return tok
}
