// ReorderKeys reorders own keys of o so that names in order come first.
func (r *Runtime) ReorderKeys(o *Object, order []string) {
	pos := map[string]int{}
	for i, n := range order {
		pos[n] = i
	}
	var first []Value
	var rest []Value
	firstSet := make([]Value, len(order))
	for _, k := range o.keys {
		if s, ok := k.(string); ok {
			if i, ok := pos[s]; ok {
				firstSet[i] = k
				continue
			}
		}
		rest = append(rest, k)
	}
	for _, k := range firstSet {
		if k != nil {
			first = append(first, k)
		}
	}
	o.keys = append(first, rest...)
}
