			c := &jsonx.Node{Kind: jsonx.String, Raw: strconv.Quote(line), Parent: arr}
			arr.Children = append(arr.Children, c)
		}
		return arr, ""
	}
	p := jsonx.NewParser(input, opts.strict)
	for !p.AtEOF() {
		n, err := p.Parse()
		if err != nil {
			return nil, err.Error()
		}
		if n == nil {
			break
		}
		jsonx.ComputeInline(n)
		n.Parent = arr
		arr.Children = append(arr.Children, n)
	}
	return arr, ""
}

