func rawLines(input []byte) []string {
	var lines []string
	sc := bufio.NewScanner(strings.NewReader(string(input)))
	sc.Buffer(make([]byte, 1024*1024), 1<<30)
	for sc.Scan() {
		lines = append(lines, sc.Text())
