package main

import (
	"os"
	"strings"
	"syscall"
	"time"
	"unsafe"

	"fx/internal/jsonx"
)

type termios syscall.Termios

func isTerminal(fd uintptr) bool {
	var t syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	return err == 0
}

func getTermios(fd uintptr) (*syscall.Termios, error) {
	var t syscall.Termios
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCGETS), uintptr(unsafe.Pointer(&t)))
	if err != 0 {
		return nil, err
	}
	return &t, nil
}

func setTermios(fd uintptr, t *syscall.Termios) error {
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(t)))
	if err != 0 {
		return err
	}
	return nil
}

func makeRaw(fd uintptr) (*syscall.Termios, error) {
	old, err := getTermios(fd)
	if err != nil {
		return nil, err
	}
	raw := *old
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	if err := setTermios(fd, &raw); err != nil {
		return nil, err
	}
	return old, nil
}

type winsize struct {
	Row, Col, X, Y uint16
}

func termSize(fd uintptr) (int, int) {
	var ws winsize
	_, _, err := syscall.Syscall(syscall.SYS_IOCTL, fd, uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(&ws)))
	if err != 0 || ws.Col == 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

// colorProfile returns "none", "ansi", "ansi256" or "truecolor".
func colorProfile() string {
	if !isTerminal(os.Stdout.Fd()) {
		return "none"
	}
	if os.Getenv("NO_COLOR") != "" {
		return "none"
	}
	if os.Getenv("CLICOLOR") == "0" {
		return "none"
	}
	ct := strings.ToLower(os.Getenv("COLORTERM"))
	if ct == "truecolor" || ct == "24bit" {
		return "truecolor"
	}
	term := os.Getenv("TERM")
	switch {
	case strings.HasPrefix(term, "alacritty"), strings.HasPrefix(term, "wezterm"), strings.HasPrefix(term, "xterm-kitty"),
		strings.HasPrefix(term, "xterm-ghostty"), strings.HasPrefix(term, "contour"), strings.HasPrefix(term, "rio"):
		return "truecolor"
	case strings.Contains(term, "256color"):
		return "ansi256"
	case term == "xterm", strings.Contains(term, "color"), term == "linux", term == "ansi", strings.HasPrefix(term, "rxvt"), term == "konsole":
		return "ansi"
	}
	return "none"
}

var queriedTerminal = false

// queryTerminal emulates the background color query performed on TTYs.
func queryTerminal() {
	if queriedTerminal {
		return
	}
	queriedTerminal = true
	if !isTerminal(os.Stdout.Fd()) {
		return
	}
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return
	}
	defer tty.Close()
	old, err := makeRaw(tty.Fd())
	if err != nil {
		return
	}
	defer setTermios(tty.Fd(), old)
	os.Stdout.WriteString("\x1b]11;?\x1b\\\x1b[6n")
	done := make(chan struct{})
	go func() {
		buf := make([]byte, 1)
		for {
			n, err := tty.Read(buf)
			if err != nil || n == 0 {
				break
			}
			if buf[0] == 'R' {
				break
			}
		}
		close(done)
	}()
	select {
	case <-done:
	case <-time.After(2 * time.Second):
	}
}

func currentTheme() *jsonx.Theme {
	prof := colorProfile()
	if prof == "none" {
		return nil
	}
	queryTerminal()
	name := os.Getenv("FX_THEME")
	codes, ok := themeCodes[prof][name]
	if !ok {
		codes = themeCodes[prof]["1"]
	}
	return themeFromCodes(codes)
}

func sgr(c string) string {
	if c == "" {
		return ""
	}
	return "\x1b[" + c + "m"
}

func themeFromCodes(c [7]string) *jsonx.Theme {
	return &jsonx.Theme{Key: sgr(c[0]), String: sgr(c[1]), Number: sgr(c[2]), Bool: sgr(c[3]), Null: sgr(c[4]), Syntax: sgr(c[5]), Preview: sgr(c[6])}
}

func printThemes() {
	prof := colorProfile()
	if prof != "none" {
		queryTerminal()
	}
	for _, name := range themeOrder {
		var t *jsonx.Theme
		if prof != "none" {
			t = themeFromCodes(themeCodes[prof][name])
		} else {
			t = &jsonx.Theme{}
		}
		c := func(code, s string) string {
			if code == "" {
				return s
			}
			return code + s + "\x1b[0m"
		}
		stdout.WriteString("export FX_THEME=\"" + name + "\"\n")
		stdout.WriteString(c(t.Syntax, "{") + "\n")
		line := func(k, v, vcode string, last bool) {
			stdout.WriteString("  " + c(t.Key, "\""+k+"\"") + c(t.Syntax, ":") + " " + c(vcode, v))
			if !last {
				stdout.WriteString(c(t.Syntax, ","))
			}
			stdout.WriteString("\n")
		}
		line("string", "\"Fox jumps over the lazy dog\"", t.String, false)
		line("number", "1234567890", t.Number, false)
		line("boolean", "true", t.Bool, false)
		line("null", "null", t.Null, false)
		stdout.WriteString("  " + c(t.Key, "\"collapsed\"") + c(t.Syntax, ":") + " " + c(t.Syntax, "{") + c(t.Preview, "\"preview\":…") + c(t.Syntax, "}") + "\n")
		stdout.WriteString(c(t.Syntax, "}") + "\n")
		stdout.Flush()
		os.Stderr.WriteString("\n")
	}
}
