}

func (p *parser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}

func (p *parser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return -1
}

func (p *parser) next() rune {
	c := p.peek()
	if c >= 0 {
		p.pos++
		if c == '\n' {
			p.line++
		}
	}
	return c
}

func (p *parser) skipWS() {
	for {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.pos++
			continue
		}
		return
	}
}

func (p *parser) skipComment() {
	if p.peek() == '#' {
		for p.peek() != '\n' && p.peek() != -1 {
			p.pos++
		}
	}
}

func (p *parser) skipWSNL() {
	for {
		p.skipWS()
		p.skipComment()
		c := p.peek()
		if c == '\n' {
			p.next()
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.pos++
			p.next()
			continue
		}
		return
	}
