mkdir -p /workspace/internal/tomlconv && cd /workspace/internal/tomlconv && cat > toml.go <<'EOF'
package tomlconv

import (
	"encoding/json"
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode/utf8"
)

// PanicErr signals a parse failure (the original panics).
type PanicErr struct{ Msg string }

func (e *PanicErr) Error() string { return e.Msg }

type kind int

const (
	kTable kind = iota
	kArray
	kString
	kInt
	kFloat
	kBool
	kDatetime
)

type value struct {
	k        kind
	s        string // raw output token for scalars / string content
	f        float64
	keys     []string
	m        map[string]*value
	arr      []*value
	inline   bool // inline table / static array (immutable)
	defined  bool // table explicitly defined via header
	implicit bool
	aot      bool // array of tables
}

func newTable() *value { return &value{k: kTable, m: map[string]*value{}} }

func (t *value) set(key string, v *value) {
	if _, ok := t.m[key]; !ok {
		t.keys = append(t.keys, key)
	}
	t.m[key] = v
}

type parser struct {
	src  []rune
	pos  int
	line int
	root *value
	cur  *value
}

type perr struct{ msg string }

func (p *parser) fail(format string, a ...interface{}) {
	panic(perr{fmt.Sprintf("toml: line %d: ", p.line) + fmt.Sprintf(format, a...)})
}

func (p *parser) peek() rune {
	if p.pos < len(p.src) {
		return p.src[p.pos]
	}
	return -1
}

func (p *parser) peekAt(i int) rune {
	if p.pos+i < len(p.src) {
		return p.src[p.pos+i]
	}
	return -1
}

func (p *parser) next() rune {
	c := p.peek()
	if c >= 0 {
		p.pos++
		if c == '\n' {
			p.line++
		}
	}
	return c
}

func (p *parser) skipWS() {
	for {
		c := p.peek()
		if c == ' ' || c == '\t' {
			p.pos++
			continue
		}
		return
	}
}

func (p *parser) skipComment() {
	if p.peek() == '#' {
		for p.peek() != '\n' && p.peek() != -1 {
			p.pos++
		}
	}
}

func (p *parser) skipWSNL() {
	for {
		p.skipWS()
		p.skipComment()
		c := p.peek()
		if c == '\n' {
			p.next()
			continue
		}
		if c == '\r' && p.peekAt(1) == '\n' {
			p.pos++
			p.next()
			continue
		}
		return
	}
}

func (p *parser) expectEOL() {
	p.skipWS()
	p.skipComment()
	c := p.peek()
	if c == -1 {
		return
	}
	if c == '\r' && p.peekAt(1) == '\n' {
		p.pos++
		p.next()
		return
	}
	if c != '\n' {
		p.fail("expected newline, got %q", c)
	}
	p.next()
}

func isBare(c rune) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '-'
}

func (p *parser) parseKeyPart() string {
	c := p.peek()
	switch c {
	case '"':
		return p.parseBasicString()
	case '\'':
		return p.parseLiteralString()
	}
	start := p.pos
	for isBare(p.peek()) {
		p.pos++
	}
	if p.pos == start {
		p.fail("invalid key")
	}
	return string(p.src[start:p.pos])
}

func (p *parser) parseKey() []string {
	var parts []string
	for {
		p.skipWS()
		parts = append(parts, p.parseKeyPart())
		p.skipWS()
		if p.peek() == '.' {
			p.pos++
			continue
		}
		return parts
	}
}

func (p *parser) parseBasicString() string {
	p.pos++ // "
	if p.peek() == '"' && p.peekAt(1) == '"' {
		p.pos += 2
		return p.parseMultiBasic()
	}
	var sb strings.Builder
	for {
		c := p.next()
		switch c {
		case -1, '\n':
			p.fail("unterminated string")
		case '"':
			return sb.String()
		case '\\':
			p.parseEscape(&sb)
		default:
			sb.WriteRune(c)
		}
	}
}

func (p *parser) parseEscape(sb *strings.Builder) {
	c := p.next()
	switch c {
	case 'b':
		sb.WriteByte('\b')
	case 't':
		sb.WriteByte('\t')
	case 'n':
		sb.WriteByte('\n')
	case 'f':
		sb.WriteByte('\f')
	case 'r':
		sb.WriteByte('\r')
	case 'e':
		sb.WriteByte(0x1b)
	case '"':
		sb.WriteByte('"')
	case '\\':
		sb.WriteByte('\\')
	case 'x':
		h := string(p.src[p.pos:min(p.pos+2, len(p.src))])
		v, err := strconv.ParseUint(h, 16, 32)
		if err != nil || len(h) != 2 {
			p.fail("invalid escape")
		}
		p.pos += 2
		sb.WriteRune(rune(v))
	case 'u', 'U':
		n := 4
		if c == 'U' {
			n = 8
		}
		if p.pos+n > len(p.src) {
			p.fail("invalid escape")
		}
		v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+n]), 16, 32)
		if err != nil || !utf8.ValidRune(rune(v)) {
			p.fail("invalid escape")
		}
		p.pos += n
		sb.WriteRune(rune(v))
	default:
		p.fail("invalid escape")
	}
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func (p *parser) parseMultiBasic() string {
	if p.peek() == '\n' {
		p.next()
	} else if p.peek() == '\r' && p.peekAt(1) == '\n' {
		p.pos++
		p.next()
	}
	var sb strings.Builder
	for {
		c := p.peek()
		if c == -1 {
			p.fail("unterminated string")
		}
		if c == '"' && p.peekAt(1) == '"' && p.peekAt(2) == '"' {
			p.pos += 3
			// up to two extra quotes allowed
			for i := 0; i < 2 && p.peek() == '"'; i++ {
				sb.WriteByte('"')
				p.pos++
			}
			return sb.String()
		}
		p.next()
		if c == '\\' {
			// line ending backslash
			save := p.pos
			for p.peek() == ' ' || p.peek() == '\t' {
				p.pos++
			}
			if p.peek() == '\n' || (p.peek() == '\r' && p.peekAt(1) == '\n') {
				for {
					c2 := p.peek()
					if c2 == ' ' || c2 == '\t' || c2 == '\n' || c2 == '\r' {
						p.next()
						continue
					}
					break
				}
				continue
			}
			p.pos = save
			p.parseEscape(&sb)
			continue
		}
		if c == '\r' && p.peek() == '\n' {
			continue
		}
		sb.WriteRune(c)
	}
}

func (p *parser) parseLiteralString() string {
	p.pos++ // '
	if p.peek() == '\'' && p.peekAt(1) == '\'' {
		p.pos += 2
		if p.peek() == '\n' {
			p.next()
		} else if p.peek() == '\r' && p.peekAt(1) == '\n' {
			p.pos++
			p.next()
		}
		var sb strings.Builder
		for {
			c := p.peek()
			if c == -1 {
				p.fail("unterminated string")
			}
			if c == '\'' && p.peekAt(1) == '\'' && p.peekAt(2) == '\'' {
				p.pos += 3
				for i := 0; i < 2 && p.peek() == '\''; i++ {
					sb.WriteByte('\'')
					p.pos++
				}
				return sb.String()
			}
			p.next()
			if c == '\r' && p.peek() == '\n' {
				continue
			}
			sb.WriteRune(c)
		}
	}
	start := p.pos
	for {
		c := p.next()
		if c == -1 || c == '\n' {
			p.fail("unterminated string")
		}
		if c == '\'' {
			return string(p.src[start : p.pos-1])
		}
	}
}

func (p *parser) parseValue() *value {
	c := p.peek()
	switch {
	case c == '"':
		return &value{k: kString, s: p.parseBasicString()}
	case c == '\'':
		return &value{k: kString, s: p.parseLiteralString()}
	case c == '[':
		return p.parseArray()
	case c == '{':
		return p.parseInlineTable()
	case c == 't' && p.hasPrefix("true"):
		p.pos += 4
		return &value{k: kBool, s: "true"}
	case c == 'f' && p.hasPrefix("false"):
		p.pos += 5
		return &value{k: kBool, s: "false"}
	}
	// number or datetime
	start := p.pos
	for {
		c := p.peek()
		if c == -1 || c == ',' || c == ']' || c == '}' || c == '\n' || c == '#' || c == '\r' {
			break
		}
		if c == ' ' {
			// datetime with space separator: date followed by time
			tok := string(p.src[start:p.pos])
			if len(tok) == 10 && tok[4] == '-' && p.peekAt(1) >= '0' && p.peekAt(1) <= '9' {
				p.pos++
				continue
			}
			break
		}
		if c == '\t' {
			break
		}
		p.pos++
	}
	tok := string(p.src[start:p.pos])
	if tok == "" {
		p.fail("expected value")
	}
	return p.parseScalarToken(tok)
}

func (p *parser) hasPrefix(s string) bool {
	rs := []rune(s)
	if p.pos+len(rs) > len(p.src) {
		return false
	}
	for i, r := range rs {
		if p.src[p.pos+i] != r {
			return false
		}
	}
	return true
}

func validUnderscores(s string) bool {
	if strings.HasPrefix(s, "_") || strings.HasSuffix(s, "_") || strings.Contains(s, "__") {
		return false
	}
	return true
}

func (p *parser) parseScalarToken(tok string) *value {
	switch tok {
	case "inf", "+inf":
		return &value{k: kFloat, f: math.Inf(1)}
	case "-inf":
		return &value{k: kFloat, f: math.Inf(-1)}
	case "nan", "+nan", "-nan":
		return &value{k: kFloat, f: math.NaN()}
	}
	if dt, ok := parseDatetime(tok); ok {
		return &value{k: kDatetime, s: dt}
	}
	body := tok
	sign := ""
	if strings.HasPrefix(body, "+") || strings.HasPrefix(body, "-") {
		sign = body[:1]
		body = body[1:]
	}
	if len(body) > 2 && body[0] == '0' && (body[1] == 'x' || body[1] == 'o' || body[1] == 'b') {
		if sign != "" {
			p.fail("invalid number")
		}
		base := map[byte]int{'x': 16, 'o': 8, 'b': 2}[body[1]]
		digits := body[2:]
		if !validUnderscores(digits) {
			p.fail("invalid number")
		}
		v, err := strconv.ParseInt(strings.ReplaceAll(digits, "_", ""), base, 64)
		if err != nil {
			p.fail("invalid number")
		}
		return &value{k: kInt, s: strconv.FormatInt(v, 10)}
	}
	if !validUnderscores(body) {
		p.fail("invalid number")
	}
	clean := strings.ReplaceAll(body, "_", "")
	isFloat := strings.ContainsAny(clean, ".eE")
	if !isFloat {
		if len(clean) > 1 && clean[0] == '0' {
			p.fail("invalid number")
		}
		for _, c := range clean {
			if c < '0' || c > '9' {
				p.fail("invalid value %q", tok)
			}
		}
		v, err := strconv.ParseInt(sign+clean, 10, 64)
		if err != nil {
			p.fail("invalid number")
		}
		return &value{k: kInt, s: strconv.FormatInt(v, 10)}
	}
	// float validation
	ip := clean
	if i := strings.IndexAny(ip, ".eE"); i >= 0 {
		ip = ip[:i]
	}
	if ip == "" || (len(ip) > 1 && ip[0] == '0') {
		p.fail("invalid float")
	}
	if strings.Contains(clean, ".") {
		parts := strings.SplitN(clean, ".", 2)
		frac := parts[1]
		if frac == "" || frac[0] < '0' || frac[0] > '9' {
			p.fail("invalid float")
		}
	}
	f, err := strconv.ParseFloat(sign+clean, 64)
	if err != nil {
		p.fail("invalid float")
	}
	return &value{k: kFloat, f: f}
}

func isDigits(s string) bool {
	if s == "" {
		return false
	}
	for _, c := range s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func parseTimePart(s string) (string, bool) {
	// HH:MM:SS(.frac)?
	if len(s) < 8 || s[2] != ':' || s[5] != ':' || !isDigits(s[0:2]) || !isDigits(s[3:5]) || !isDigits(s[6:8]) {
		return "", false
	}
	rest := s[8:]
	out := s[:8]
	if strings.HasPrefix(rest, ".") {
		i := 1
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		if i == 1 {
			return "", false
		}
		out += rest[:i]
		rest = rest[i:]
	}
	return out + "|" + rest, true
}

func parseDatetime(tok string) (string, bool) {
	if len(tok) >= 10 && tok[4] == '-' && tok[7] == '-' && isDigits(tok[0:4]) && isDigits(tok[5:7]) && isDigits(tok[8:10]) {
		date := tok[:10]
		if len(tok) == 10 {
			return date, true
		}
		sep := tok[10]
		if sep != 'T' && sep != 't' && sep != ' ' {
			return "", false
		}
		tp, ok := parseTimePart(tok[11:])
		if !ok {
			return "", false
		}
		parts := strings.SplitN(tp, "|", 2)
		tm, zone := parts[0], parts[1]
		if zone == "" {
			return date + "T" + tm, true
		}
		if zone == "Z" || zone == "z" {
			return date + "T" + trimFrac(tm) + "Z", true
		}
		if len(zone) == 6 && (zone[0] == '+' || zone[0] == '-') && zone[3] == ':' {
			if zone == "+00:00" || zone == "-00:00" {
				return date + "T" + trimFrac(tm) + "Z", true
			}
			return date + "T" + trimFrac(tm) + zone, true
		}
		return "", false
	}
	if tp, ok := parseTimePart(tok); ok {
		parts := strings.SplitN(tp, "|", 2)
		if parts[1] == "" {
			return parts[0], true
		}
	}
	return "", false
}

func trimFrac(tm string) string {
	if i := strings.IndexByte(tm, '.'); i >= 0 {
		frac := strings.TrimRight(tm[i+1:], "0")
		if frac == "" {
			return tm[:i]
		}
		return tm[:i] + "." + frac
	}
	return tm
}

func (p *parser) parseArray() *value {
	p.pos++ // [
	arr := &value{k: kArray, inline: true}
	for {
		p.skipWSNL()
		if p.peek() == ']' {
			p.pos++
			return arr
		}
		v := p.parseValue()
		arr.arr = append(arr.arr, v)
		p.skipWSNL()
		c := p.peek()
		if c == ',' {
			p.pos++
			continue
		}
		if c == ']' {
			p.pos++
			return arr
		}
		p.fail("expected comma or ]")
	}
}

func (p *parser) parseInlineTable() *value {
	p.pos++ // {
	t := newTable()
	t.inline = true
	p.skipWS()
	if p.peek() == '}' {
		p.pos++
		return t
	}
	for {
		p.skipWS()
		key := p.parseKey()
		p.skipWS()
		if p.peek() != '=' {
			p.fail("expected =")
		}
		p.pos++
		p.skipWS()
		v := p.parseValue()
		p.setDotted(t, key, v, true)
		p.skipWS()
		c := p.peek()
		if c == ',' {
			p.pos++
			continue
		}
		if c == '}' {
			p.pos++
			return t
		}
		p.fail("expected , or }")
	}
}

func (p *parser) setDotted(t *value, key []string, v *value, inInline bool) {
	for _, k := range key[:len(key)-1] {
		ex, ok := t.m[k]
		if !ok {
			nt := newTable()
			nt.implicit = true
			t.set(k, nt)
			t = nt
			continue
		}
		if ex.k != kTable || (ex.inline && !inInline) {
			p.fail("key %q already defined", k)
		}
		t = ex
	}
	last := key[len(key)-1]
	if _, ok := t.m[last]; ok {
		p.fail("key %q already defined", last)
	}
	t.set(last, v)
}

func (p *parser) parse() {
	p.root = newTable()
	p.cur = p.root
	for {
		p.skipWSNL()
		c := p.peek()
		if c == -1 {
			return
		}
		if c == '[' {
			if p.peekAt(1) == '[' {
				p.pos += 2
				key := p.parseKey()
				p.skipWS()
				if !(p.peek() == ']' && p.peekAt(1) == ']') {
					p.fail("expected ]]")
				}
				p.pos += 2
				p.expectEOL()
				p.openArrayTable(key)
				continue
			}
			p.pos++
			key := p.parseKey()
			p.skipWS()
			if p.peek() != ']' {
				p.fail("expected ]")
			}
			p.pos++
			p.expectEOL()
			p.openTable(key)
			continue
		}
		key := p.parseKey()
		p.skipWS()
		if p.peek() != '=' {
			p.fail("expected =")
		}
		p.pos++
		p.skipWS()
		v := p.parseValue()
		p.setDotted(p.cur, key, v, false)
		p.expectEOL()
	}
}

func (p *parser) walkTo(key []string) *value {
	t := p.root
	for _, k := range key {
		ex, ok := t.m[k]
		if !ok {
			nt := newTable()
			nt.implicit = true
			t.set(k, nt)
			t = nt
			continue
		}
		if ex.k == kArray && ex.aot {
			t = ex.arr[len(ex.arr)-1]
			continue
		}
		if ex.k != kTable || ex.inline {
			p.fail("key %q already defined", k)
		}
		t = ex
	}
	return t
}

func (p *parser) openTable(key []string) {
	parent := p.walkTo(key[:len(key)-1])
	last := key[len(key)-1]
	ex, ok := parent.m[last]
	if ok {
		if ex.k != kTable || ex.inline || ex.defined {
			p.fail("table %q already defined", strings.Join(key, "."))
		}
		ex.defined = true
		p.cur = ex
		return
	}
	nt := newTable()
	nt.defined = true
	parent.set(last, nt)
	p.cur = nt
}

func (p *parser) openArrayTable(key []string) {
	parent := p.walkTo(key[:len(key)-1])
	last := key[len(key)-1]
	ex, ok := parent.m[last]
	nt := newTable()
	if ok {
		if ex.k != kArray || !ex.aot {
			p.fail("key %q already defined", last)
		}
		ex.arr = append(ex.arr, nt)
	} else {
		parent.set(last, &value{k: kArray, aot: true, arr: []*value{nt}})
	}
	p.cur = nt
}

type jsonErr struct{ msg string }

func quote(s string) string {
	var sb strings.Builder
	sb.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case '"':
			sb.WriteString("\\\"")
		case '\\':
			sb.WriteString("\\\\")
		case '\n':
			sb.WriteString("\\n")
		case '\r':
			sb.WriteString("\\r")
		case '\t':
			sb.WriteString("\\t")
		case '\b':
			sb.WriteString("\\b")
		case '\f':
			sb.WriteString("\\f")
		default:
			if c < 0x20 || c == 0x7f {
				sb.WriteString(fmt.Sprintf("\\u%04x", c))
			} else {
				sb.WriteByte(c)
			}
		}
	}
	sb.WriteByte('"')
	return sb.String()
}

func emit(sb *strings.Builder, v *value, indent string) {
	switch v.k {
	case kTable:
		if len(v.keys) == 0 {
			sb.WriteString("{}")
			return
		}
		sb.WriteString("{\n")
		for i, k := range v.keys {
			sb.WriteString(indent + "  " + quote(k) + ": ")
			emit(sb, v.m[k], indent+"  ")
			if i < len(v.keys)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(indent + "}")
	case kArray:
		if len(v.arr) == 0 {
			sb.WriteString("[]")
			return
		}
		sb.WriteString("[\n")
		for i, e := range v.arr {
			sb.WriteString(indent + "  ")
			emit(sb, e, indent+"  ")
			if i < len(v.arr)-1 {
				sb.WriteString(",")
			}
			sb.WriteString("\n")
		}
		sb.WriteString(indent + "]")
	case kString, kDatetime:
		sb.WriteString(quote(v.s))
	case kInt, kBool:
		sb.WriteString(v.s)
	case kFloat:
		b, err := json.Marshal(v.f)
		if err != nil {
			panic(jsonErr{err.Error()})
		}
		sb.WriteString(string(b))
	}
}

// ToJSON converts TOML text into JSON text.
func ToJSON(data []byte) (out []byte, err error) {
	p := &parser{src: []rune(strings.TrimPrefix(string(data), "\ufeff")), line: 1}
	defer func() {
		if rec := recover(); rec != nil {
			switch e := rec.(type) {
			case perr:
				out = nil
				err = &PanicErr{Msg: e.msg}
			case jsonErr:
				out = nil
				err = fmt.Errorf("json: %s", strings.TrimPrefix(e.msg, "json: "))
			default:
				panic(rec)
			}
		}
	}()
	p.parse()
	var sb strings.Builder
	emit(&sb, p.root, "")
	sb.WriteString("\n")
	return []byte(sb.String()), nil
}
