const fishScript = "complete --command fx --arguments '(COMP_FISH=(commandline -cp) fx)'\n"

func printCompletionScript(shell string) {
	switch shell {
	case "bash":
		stdout.WriteString(bashScript)
	case "zsh":
		stdout.WriteString(zshScript)
	case "fish":
		stdout.WriteString(fishScript)
	default:
		stdout.WriteString("unknown shell type\n")
	}
}

type compItem struct {
	display, value, typ string
}

func handleCompletion(argv []string) bool {
	var line string
	mode := ""
	if v, ok := os.LookupEnv("COMP_ZSH"); ok {
		line, mode = v, "zsh"
	} else if v, ok := os.LookupEnv("COMP_FISH"); ok {
		line, mode = v, "fish"
	} else if v, ok := os.LookupEnv("COMP_LINE"); ok && len(argv) > 0 {
		line, mode = v, "bash"
		if p, err := strconv.Atoi(os.Getenv("COMP_POINT")); err == nil && p >= 0 && p <= len(line) {
			line = line[:p]
		}
	} else {
		return false
	}
	items := complete(line)
	var out []string
	for _, it := range items {
		if mode == "zsh" {
			out = append(out, it.display+"\t"+it.value+"\t"+it.typ)
		} else {
			out = append(out, it.value)
		}
	}
	stdout.WriteString(strings.Join(out, "\n"))
	return true
}

func splitWords(line string) ([]string, bool) {
	var words []string
	var cur strings.Builder
	inWord := false
	var quote rune
	for _, c := range line {
		if quote != 0 {
			if c == quote {
				quote = 0
				continue
			}
			cur.WriteRune(c)
			continue
		}
		switch c {
		case '\'', '"':
			quote = c
			inWord = true
		case ' ', '\t', '\n':
			if inWord {
				words = append(words, cur.String())
				cur.Reset()
				inWord = false
			}
		case '\\':
			inWord = true
		default:
			cur.WriteRune(c)
			inWord = true
		}
	}
	endsWithSpace := !inWord
	if inWord {
		words = append(words, cur.String())
	}
	return words, endsWithSpace
}

var flagList = []string{"--help", "--raw", "--slurp", "--themes", "--version", "--yaml", "--toml", "--strict", "--no-inline"}

var globalList = []string{"apply", "len", "uniq", "sort", "isFalsely", "filter", "map", "walk", "sortBy", "sortKeys", "groupBy", "chunk", "zip", "flatten", "reverse", "keys", "values", "list", "del", "exit", "save", "toBase64", "fromBase64", "console.log", "Array.isArray", "Array.from", "JSON.stringify", "JSON.parse", "Object.keys", "Object.values", "Object.entries", "Object.fromEntries", "YAML.stringify", "YAML.parse"}

func complete(line string) []compItem {
	words, endsWithSpace := splitWords(line)
	if len(words) > 0 {
		words = words[1:]
	}
	cur := ""
	if !endsWithSpace && len(words) > 0 {
		cur = words[len(words)-1]
		words = words[:len(words)-1]
	}
	var positional []string
	isYAML, isTOML := false, false
	for _, w := range words {
		if strings.HasPrefix(w, "-") && len(w) > 1 {
			if w == "--yaml" {
				isYAML = true
			}
			if w == "--toml" {
				isTOML = true
			}
			continue
		}
		positional = append(positional, w)
	}
	if strings.HasPrefix(cur, "-") {
		var items []compItem
		for _, f := range flagList {
			if strings.HasPrefix(f, cur) {
				items = append(items, compItem{f, f, "flag"})
			}
		}
		return items
	}
	if len(positional) == 0 {
		return fileCompletion(cur)
	}
	data, err := os.ReadFile(positional[0])
	if err != nil {
		return nil
	}
	if isYAML {
		if out, err := yamlconv.ToJSON(data); err == nil {
			data = out
		} else {
			return nil
		}
	} else if isTOML {
		if out, err := tomlconv.ToJSON(data); err == nil {
			data = out
		} else {
			return nil
		}
	}
	p := jsonx.NewParser(data, false)
	node, perr := p.Parse()
	if perr != nil || node == nil {
		return nil
	}
	codeArgs := positional[1:]
	return codeCompletion(node, codeArgs, cur)
}

func fileCompletion(cur string) []compItem {
	dir, prefix := filepath.Split(cur)
	readDir := dir
	if readDir == "" {
		readDir = "."
	}
	entries, err := os.ReadDir(readDir)
	if err != nil {
		return nil
	}
	var items []compItem
	for _, e := range entries {
		name := e.Name()
		if !strings.HasPrefix(name, prefix) {
			continue
		}
		if strings.HasPrefix(name, ".") && !strings.HasPrefix(prefix, ".") {
			continue
		}
		display := name
		isDir := e.IsDir()
		if !isDir && e.Type()&os.ModeSymlink != 0 {
			if st, err := os.Stat(filepath.Join(readDir, name)); err == nil && st.IsDir() {
				isDir = true
			}
		}
		if isDir {
			display += "/"
		}
		items = append(items, compItem{display, dir + name, "file"})
	}
	return items
}

var identRe = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$]*$`)
var pathRe = regexp.MustCompile(`(?:^|[^A-Za-z0-9_$.\]\[])((?:x|this|@|\?)?(?:\.[A-Za-z_$][A-Za-z0-9_$]*|\[\d+\]|\[\])*)(\.[A-Za-z0-9_$]*)?$`)
var globalWordRe = regexp.MustCompile(`^[A-Za-z_$][A-Za-z0-9_$.]*$`)

type pathSeg struct {
	kind int // 0 key, 1 index, 2 flatten
	key  string
	idx  int
}

var segRe = regexp.MustCompile(`\.[A-Za-z_$][A-Za-z0-9_$]*|\[\d+\]|\[\]`)

func codeCompletion(node *jsonx.Node, codeArgs []string, cur string) []compItem {
	vm := engine.NewVM([]string{"."}, stdout, "")
	val := vm.ToValue(node)
	ok := true
	for _, code := range codeArgs {
		v, good := evalCode(code, val)
		if !good {
			ok = false
			break
		}
		val = v
	}
	if !ok {
		return nil
	}
	rt := vm.R
	// list all keys for base words
	switch cur {
	case "", ".", "x", "this", "@", "?":
		target := val
		mapped := false
		if cur == "@" {
			target, mapped = mapValues(rt, val)
		}
		keys := objectKeys(rt, target, mapped)
		var items []compItem
		for _, k := range keys {
			var disp, suffix string
			if identRe.MatchString(k) {
				disp = "." + k
				suffix = "." + k
			} else {
				q, _ := json.Marshal(k)
				qs := strings.ReplaceAll(string(q), "\\u003c", "<")
				qs = strings.ReplaceAll(qs, "\\u003e", ">")
				qs = strings.ReplaceAll(qs, "\\u0026", "&")
				disp = ".[" + qs + "]"
				suffix = "[" + qs + "]"
			}
			base := cur
			if cur == "." {
				base = ""
				if !identRe.MatchString(k) {
					suffix = "." + suffix
				}
			}
			items = append(items, compItem{disp, base + suffix, "key"})
		}
		return items
	}
	if m := pathRe.FindStringSubmatchIndex(cur); m != nil && m[4] >= 0 {
		pathPart := cur[m[2]:m[3]]
		last := cur[m[4]:m[5]]
		partial := last[1:]
		target := val
		mapped := false
		rest := pathPart
		switch {
		case strings.HasPrefix(rest, "this"):
			rest = rest[4:]
		case strings.HasPrefix(rest, "x"):
			rest = rest[1:]
		case strings.HasPrefix(rest, "@"):
			rest = rest[1:]
			target, mapped = mapValues(rt, val)
		case strings.HasPrefix(rest, "?"):
			rest = rest[1:]
		}
		for _, s := range segRe.FindAllString(rest, -1) {
			target, mapped = applySeg(rt, target, mapped, s)
			if target == nil {
				return nil
			}
		}
		keys := objectKeys(rt, target, mapped)
		prefix := cur[:m[4]]
		var items []compItem
		for _, k := range keys {
			if !identRe.MatchString(k) || !strings.HasPrefix(k, partial) {
				continue
			}
			items = append(items, compItem{"." + k, prefix + "." + k, "key"})
		}
		return items
	}
	if globalWordRe.MatchString(cur) {
		var items []compItem
		for _, g := range globalList {
			if strings.HasPrefix(g, cur) {
				items = append(items, compItem{g, g, "global"})
			}
		}
		return items
	}
	return nil
}

func evalCode(code string, val js.Value) (res js.Value, ok bool) {
	defer func() {
		if r := recover(); r != nil {
			ok = false
		}
	}()
	if code == "." || code == "x" || code == "this" {
		return val, true
	}
	if engine.CheckArgs([]string{code}) != "" {
		return nil, false
	}
	vm := engine.NewVM([]string{code}, stdout, "")
	out, errOut := vm.EvalRaw(val)
	if errOut {
		return nil, false
	}
	return out, true
}

func mapValues(rt *js.Runtime, v js.Value) (js.Value, bool) {
	if o, ok := v.(*js.Object); ok && o.IsArr {
		return v, true
	}
	return v, false
}

func applySeg(rt *js.Runtime, v js.Value, mapped bool, seg string) (js.Value, bool) {
	apply1 := func(x js.Value) js.Value {
		o, ok := x.(*js.Object)
		if !ok {
			return nil
		}
		if strings.HasPrefix(seg, ".") {
			if o.IsArr {
				return nil
			}
			if !rt.HasOwn(o, seg[1:]) {
				return nil
			}
			return rt.GetKey(o, seg[1:])
		}
		if seg == "[]" {
			if !o.IsArr {
				return nil
			}
			return x
		}
		if !o.IsArr {
			return nil
		}
		n, _ := strconv.Atoi(seg[1 : len(seg)-1])
		if n >= len(o.Arr) || o.Arr[n] == nil {
			return nil
		}
		return o.Arr[n]
	}
	if mapped {
		o := v.(*js.Object)
		var out []js.Value
		for _, e := range o.Arr {
			if e == nil {
				continue
			}
			r := apply1(e)
			if r == nil {
				continue
			}
