cd /workspace && cat > tui.go <<'EOF'
package main

import (
	"bufio"
	"encoding/json"
	"fmt"
	"os"
	"os/signal"
	"regexp"
	"strconv"
	"strings"
	"syscall"
	"time"

	"fx/internal/jsonx"

	"github.com/mattn/go-runewidth"
)

type rowKind int

const (
	rowValue rowKind = iota
	rowClose
	rowError
)

type row struct {
	node *jsonx.Node
	kind rowKind
	seg  int // wrapped segment index
	nseg int
}

type tuiModel struct {
	roots     []*jsonx.Node
	hasErr    bool
	collapsed map[*jsonx.Node]bool
	order     map[*jsonx.Node]int
	total     int
	rows      []row
	cursor    int
	offset    int
	width     int
	height    int
	theme     *jsonx.Theme
	fileName  string
	showHelp  bool
	helpOff   int
	out       *bufio.Writer
	tty       *os.File
	wrap      bool
}

func startTUI(input []byte, nodes []*jsonx.Node, opts options, filePath string) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		goPanic(fmt.Sprintf("could not open a new TTY: %s", err.Error()), mainTrace)
	}
	m := &tuiModel{collapsed: map[*jsonx.Node]bool{}, order: map[*jsonx.Node]int{}, tty: tty, wrap: true}
	if filePath != "" {
		m.fileName = filePathBase(filePath)
	}
	if opts.raw {
		lines := rawLines(input)
		if len(lines) > 0 {
			m.roots = []*jsonx.Node{{Kind: jsonx.String, Raw: strconv.Quote(lines[len(lines)-1])}}
		}
	} else {
		p := jsonx.NewParser(input, opts.strict)
		for !p.AtEOF() {
			n, perr := p.Parse()
			if perr != nil {
				if len(m.roots) == 0 {
					tty.Close()
					stdout.Flush()
					fmt.Fprint(os.Stderr, perr.Error())
					os.Exit(1)
				}
				m.hasErr = true
				break
			}
			if n == nil {
				break
			}
			m.roots = append(m.roots, n)
		}
	}
	idx := 0
	var number func(n *jsonx.Node)
	number = func(n *jsonx.Node) {
		m.order[n] = idx
		idx++
		for _, c := range n.Children {
			number(c)
		}
		if n.Kind == jsonx.Object || n.Kind == jsonx.Array {
			if len(n.Children) > 0 {
				idx++
			}
		}
	}
	for _, r := range m.roots {
		number(r)
	}
	m.total = idx
	m.theme = tuiTheme()
	m.run()
}

func filePathBase(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[i+1:]
	}
	return p
}

func tuiTheme() *jsonx.Theme {
	term := os.Getenv("TERM")
	prof := "ansi256"
	ct := strings.ToLower(os.Getenv("COLORTERM"))
	switch {
	case os.Getenv("NO_COLOR") != "":
		prof = "none"
	case ct == "truecolor" || ct == "24bit":
		prof = "truecolor"
	case strings.Contains(term, "256color"):
		prof = "ansi256"
	case term == "xterm" || strings.Contains(term, "color") || term == "linux":
		prof = "ansi"
	case term == "" || term == "dumb":
		prof = "none"
	default:
		prof = "ansi256"
	}
	if prof == "none" {
		return &jsonx.Theme{}
	}
	name := os.Getenv("FX_THEME")
	codes, ok := themeCodes[prof][name]
	if !ok {
		codes = themeCodes[prof]["1"]
	}
	return themeFromCodes(codes)
}

func (m *tuiModel) isContainer(n *jsonx.Node) bool {
	return n.Kind == jsonx.Object || n.Kind == jsonx.Array
}

func (m *tuiModel) expanded(n *jsonx.Node) bool {
	return m.isContainer(n) && len(n.Children) > 0 && !m.collapsed[n]
}

func depthOf(n *jsonx.Node) int {
	d := 0
	for p := n.Parent; p != nil; p = p.Parent {
		d++
	}
	return d
}

// prefixWidth returns the display width before the value on the first line.
func (m *tuiModel) prefixWidth(n *jsonx.Node) int {
	w := depthOf(n) * 2
	if n.HasKey {
		w += runewidth.StringWidth(n.Key) + 2
	}
	return w
}

func (m *tuiModel) stringSegments(n *jsonx.Node) []string {
	tok := n.Raw
	if !m.wrap || m.width <= 0 {
		return []string{tok}
	}
	first := m.width - m.prefixWidth(n)
	rest := m.width - depthOf(n)*2
	if first < 1 || rest < 1 {
		return []string{tok}
	}
	var segs []string
	var cur strings.Builder
	cw := 0
	limit := first
	for _, r := range tok {
		rw := runewidth.RuneWidth(r)
		if cw+rw > limit && cw > 0 {
			segs = append(segs, cur.String())
			cur.Reset()
			cw = 0
			limit = rest
		}
		cur.WriteRune(r)
		cw += rw
	}
	segs = append(segs, cur.String())
	return segs
}

func (m *tuiModel) buildRows() {
	m.rows = m.rows[:0]
	var add func(n *jsonx.Node)
	add = func(n *jsonx.Node) {
		if n.Kind == jsonx.String {
			segs := m.stringSegments(n)
			for i := range segs {
				m.rows = append(m.rows, row{node: n, kind: rowValue, seg: i, nseg: len(segs)})
			}
			return
		}
		m.rows = append(m.rows, row{node: n, kind: rowValue, nseg: 1})
		if m.expanded(n) {
			for _, c := range n.Children {
				add(c)
			}
			m.rows = append(m.rows, row{node: n, kind: rowClose, nseg: 1})
		}
	}
	for _, r := range m.roots {
		add(r)
	}
	if m.hasErr {
		m.rows = append(m.rows, row{kind: rowError, nseg: 1})
	}
}

func isLast(n *jsonx.Node) bool {
	p := n.Parent
	if p == nil {
		return true
	}
	return p.Children[len(p.Children)-1] == n
}

func (m *tuiModel) color(code, s string) string {
	if code == "" {
		return s
	}
	return code + s + "\x1b[0m"
}

func (m *tuiModel) valueColor(n *jsonx.Node) string {
	switch n.Kind {
	case jsonx.String:
		return m.theme.String
	case jsonx.Number:
		return m.theme.Number
	case jsonx.Bool:
		return m.theme.Bool
	case jsonx.Null:
		return m.theme.Null
	}
	return ""
}

const reverse = "\x1b[7m"

func (m *tuiModel) preview(n *jsonx.Node) string {
	if n.Kind == jsonx.Array {
		return "…"
	}
	c := n.Children[0]
	s := c.Key + ":"
	if c.IsPrimitive() {
		v := c.Raw
		avail := m.width - m.prefixWidth(n) - 2
		if runewidth.StringWidth(s+v)+3 <= avail {
			s += v
			if len(n.Children) > 1 {
				s += ",…"
			}
			return s
		}
	}
	return s + "…"
}

func (m *tuiModel) renderRow(r row, selected bool) string {
	var sb strings.Builder
	if r.kind == rowError {
		if selected {
			return reverse + " " + "\x1b[0m"
		}
		return ""
	}
	n := r.node
	indent := strings.Repeat("  ", depthOf(n))
	sb.WriteString(indent)
	comma := ""
	if !isLast(n) {
		comma = m.color(m.theme.Syntax, ",")
	}
	if r.kind == rowClose {
		br := "}"
		if n.Kind == jsonx.Array {
			br = "]"
		}
		if selected {
			sb.WriteString(reverse + br + "\x1b[0m")
		} else {
			sb.WriteString(m.color(m.theme.Syntax, br))
		}
		sb.WriteString(comma)
		return sb.String()
	}
	if n.Kind == jsonx.String && r.seg > 0 {
		segs := m.stringSegments(n)
		s := segs[r.seg]
		if selected {
			sb.WriteString(reverse + s + "\x1b[0m")
		} else {
			sb.WriteString(m.color(m.theme.String, s))
		}
		if r.seg == r.nseg-1 {
			sb.WriteString(comma)
		}
		return sb.String()
	}
	keySelected := false
	if n.HasKey {
		if selected {
			sb.WriteString(reverse + n.Key + "\x1b[0m")
			keySelected = true
		} else {
			sb.WriteString(m.color(m.theme.Key, n.Key))
		}
		sb.WriteString(m.color(m.theme.Syntax, ":"))
		sb.WriteString(" ")
	}
	sel := selected && !keySelected
	switch {
	case m.isContainer(n):
		open, close := "{", "}"
		if n.Kind == jsonx.Array {
			open, close = "[", "]"
		}
		if len(n.Children) == 0 {
			if sel {
				sb.WriteString(reverse + open + close + "\x1b[0m")
			} else {
				sb.WriteString(m.color(m.theme.Syntax, open+close))
			}
		} else if m.collapsed[n] {
			if sel {
				sb.WriteString(reverse + open + "\x1b[0m")
			} else {
				sb.WriteString(m.color(m.theme.Syntax, open))
			}
			sb.WriteString(m.color(m.theme.Preview, m.preview(n)))
			sb.WriteString(m.color(m.theme.Syntax, close))
		} else {
			if sel {
				sb.WriteString(reverse + open + "\x1b[0m")
			} else {
				sb.WriteString(m.color(m.theme.Syntax, open))
			}
			return sb.String()
		}
	case n.Kind == jsonx.String:
		segs := m.stringSegments(n)
		s := segs[0]
		if sel {
			sb.WriteString(reverse + s + "\x1b[0m")
		} else {
			sb.WriteString(m.color(m.theme.String, s))
		}
		if r.nseg > 1 {
			return sb.String()
		}
	default:
		if sel {
			sb.WriteString(reverse + n.Raw + "\x1b[0m")
		} else {
			sb.WriteString(m.color(m.valueColor(n), n.Raw))
		}
	}
	sb.WriteString(comma)
	return sb.String()
}

var ansiRe = regexp.MustCompile("\x1b\\[[0-9;]*m")

// truncate cuts a rendered line to the given display width.
func truncateANSI(s string, width int) string {
	var sb strings.Builder
	w := 0
	i := 0
	for i < len(s) {
		if s[i] == 0x1b {
			loc := ansiRe.FindStringIndex(s[i:])
			if loc != nil && loc[0] == 0 {
				sb.WriteString(s[i : i+loc[1]])
				i += loc[1]
				continue
			}
		}
		r, size := utf8DecodeRune(s[i:])
		rw := runewidth.RuneWidth(r)
		if w+rw > width {
			sb.WriteString("\x1b[0m")
			break
		}
		w += rw
		sb.WriteString(s[i : i+size])
		i += size
	}
	return sb.String()
}

func (m *tuiModel) contentHeight() int {
	h := m.height - 1
	if h < 1 {
		h = 1
	}
	return h
}

func (m *tuiModel) fixOffset() {
	h := m.contentHeight()
	if m.cursor < 0 {
		m.cursor = 0
	}
	if m.cursor >= len(m.rows) {
		m.cursor = len(m.rows) - 1
	}
	if m.cursor < m.offset {
		m.offset = m.cursor
	}
	if m.cursor >= m.offset+h {
		m.offset = m.cursor - h + 1
	}
	if m.offset < 0 {
		m.offset = 0
	}
}

func keyPathPart(n *jsonx.Node) string {
	if n.Parent == nil {
		return ""
	}
	if n.Parent.Kind == jsonx.Array {
		for i, c := range n.Parent.Children {
			if c == n {
				return "[" + strconv.Itoa(i) + "]"
			}
		}
	}
	var k string
	if err := json.Unmarshal([]byte(n.Key), &k); err != nil {
		k = n.Key
	}
	if identRe.MatchString(k) {
		return "." + k
	}
	return "[" + n.Key + "]"
}

func nodePath(n *jsonx.Node) string {
	var parts []string
	for c := n; c != nil && c.Parent != nil; c = c.Parent {
		parts = append([]string{keyPathPart(c)}, parts...)
	}
	return strings.Join(parts, "")
}

func (m *tuiModel) statusBar() string {
	left := ""
	percent := 0
	if m.cursor < len(m.rows) {
		r := m.rows[m.cursor]
		if r.node != nil {
			left = nodePath(r.node)
			idx := m.order[r.node]
			if r.kind == rowClose {
				idx = m.closeIndex(r.node)
			}
			if m.total > 0 {
				percent = (idx + 1) * 100 / m.total
			}
			if idx == 0 {
				percent = 1
			}
		} else {
			percent = 100
		}
	}
	right := strconv.Itoa(percent) + "%"
	if m.fileName != "" {
		right += " " + m.fileName
	}
	pad := m.width - len(left) - len(right)
	if pad < 1 {
		pad = 1
	}
	line := left + strings.Repeat(" ", pad) + right
	return "\x1b[30;47m" + line + "\x1b[0m"
}

func (m *tuiModel) closeIndex(n *jsonx.Node) int {
	// index of closing row: after all descendants
	last := n
	for m.isContainer(last) && len(last.Children) > 0 {
		last = last.Children[len(last.Children)-1]
	}
	idx := m.order[last]
	if m.isContainer(last) && len(last.Children) > 0 {
		idx++
	}
	// count closing rows of containers between last and n
	for c := last; c != n; {
		c = c.Parent
		if c == nil {
			break
		}
		idx++
		if c == n {
			break
		}
	}
	if last == n {
		return idx
	}
	return idx
}

func (m *tuiModel) render() {
	var sb strings.Builder
	sb.WriteString("\x1b[H")
	h := m.contentHeight()
	if m.showHelp {
		lines := helpLines()
		for i := 0; i < m.height; i++ {
			j := i + m.helpOff
			if j < len(lines) {
				sb.WriteString(truncateANSI(lines[j], m.width))
			}
			sb.WriteString("\x1b[K")
			if i < m.height-1 {
				sb.WriteString("\r\n")
			}
		}
		m.tty.WriteString(sb.String())
		return
	}
	for i := 0; i < h; i++ {
		j := m.offset + i
		if j < len(m.rows) {
			sb.WriteString(truncateANSI(m.renderRow(m.rows[j], j == m.cursor), m.width))
		} else {
			sb.WriteString(m.color("\x1b[90m", "~"))
		}
		sb.WriteString("\x1b[K\r\n")
	}
	sb.WriteString(m.statusBar())
	sb.WriteString("\x1b[K")
	m.tty.WriteString(sb.String())
}

func helpLines() []string {
	g := func(s string) string { return "\x1b[90m" + s + "\x1b[0m" }
	sections := []struct {
		title string
		items [][2]string
	}{
		{"Navigation", [][2]string{{"up, k", "up"}, {"down, j", "down"}, {"pgup, b", "page up"}, {"pgdown, space, f", "page down"}, {"ctrl+u", "half page up"}, {"ctrl+d", "half page down"}, {"g, home", "goto top"}, {"G, end", "goto bottom"}, {"J, shift+down", "next sibling"}, {"K, shift+up", "previous sibling"}, {"[", "go back"}, {"]", "go forward"}}},
		{"Expand / Collapse", [][2]string{{"right, l, enter", "expand"}, {"left, h, backspace", "collapse"}, {"L, shift+right", "expand recursively"}, {"H, shift+left", "collapse recursively"}, {"e", "expand all"}, {"E", "collapse all"}, {"1-9", "collapse to nth level"}}},
		{"Search", [][2]string{{"/", "search regexp"}, {"n", "next search result"}, {"N", "prev search result"}, {"@", "goto symbol"}, {"ctrl+g", "goto ref"}}},
		{"Actions", [][2]string{{"y", "yank/copy"}, {"d", "delete node"}, {"p", "preview node"}, {"P", "print to stdout"}, {"v", "open in editor"}}},
		{"View", [][2]string{{"z", "toggle strings wrap"}, {"s", "show sizes/line numbers"}}},
		{"Other", [][2]string{{"?", "show help"}, {":", "open command line"}, {"q, ctrl+c, esc", "exit program"}}},
	}
	lines := []string{"", "\x1b[1m  Key Bindings\x1b[0m", g("  " + strings.Repeat("─", 41)), ""}
	for i, s := range sections {
		lines = append(lines, g("  "+s.title))
		for _, it := range s.items {
			lines = append(lines, "    "+it[0]+strings.Repeat(" ", 22-len(it[0]))+g(it[1]))
		}
		if i < len(sections)-1 {
			lines = append(lines, "")
		}
	}
	lines = append(lines, "")
	return lines
}

func (m *tuiModel) curNode() *jsonx.Node {
	if m.cursor < len(m.rows) {
		return m.rows[m.cursor].node
	}
	return nil
}

func (m *tuiModel) rowOf(n *jsonx.Node, closing bool) int {
	for i, r := range m.rows {
		if r.node == n && (r.kind == rowClose) == closing {
			return i
		}
	}
	return -1
}

func (m *tuiModel) setCursorNode(n *jsonx.Node) {
	m.buildRows()
	if i := m.rowOf(n, false); i >= 0 {
		m.cursor = i
	}
	m.fixOffset()
}

func (m *tuiModel) collapseRecursive(n *jsonx.Node, v bool) {
	if m.isContainer(n) && len(n.Children) > 0 {
		m.collapsed[n] = v
		for _, c := range n.Children {
			m.collapseRecursive(c, v)
		}
	}
}

func (m *tuiModel) handleKey(k string) bool {
	if m.showHelp {
		switch k {
		case "q", "esc", "?":
			m.showHelp = false
		case "ctrl+c":
			return false
		case "j", "down":
			if m.helpOff+m.height < len(helpLines()) {
				m.helpOff++
			}
		case "k", "up":
			if m.helpOff > 0 {
				m.helpOff--
			}
		}
		return true
	}
	h := m.contentHeight()
	cur := m.curNode()
	switch k {
	case "q", "ctrl+c", "esc":
		return false
	case "?":
		m.showHelp = true
		m.helpOff = 0
	case "j", "down":
		m.cursor++
	case "k", "up":
		m.cursor--
	case "g", "home":
		m.cursor = 0
	case "G", "end":
		m.cursor = len(m.rows) - 1
	case "pgdown", " ", "f":
		m.cursor += h
		m.offset += h
		if m.offset > len(m.rows)-h {
			m.offset = len(m.rows) - h
		}
	case "pgup", "b":
		m.cursor -= h
		m.offset -= h
	case "ctrl+d":
		m.cursor += h / 2
		m.offset += h / 2
		if m.offset > len(m.rows)-h {
			m.offset = len(m.rows) - h
		}
	case "ctrl+u":
		m.cursor -= h / 2
		m.offset -= h / 2
	case "l", "right", "enter":
		if cur != nil && m.isContainer(cur) && m.collapsed[cur] {
			m.collapsed[cur] = false
			m.setCursorNode(cur)
			return true
		}
	case "h", "left", "backspace":
		if cur == nil {
			break
		}
		r := m.rows[m.cursor]
		if m.expanded(cur) {
			m.collapsed[cur] = true
			m.setCursorNode(cur)
			return true
		}
		_ = r
		if cur.Parent != nil {
			m.setCursorNode(cur.Parent)
			return true
		}
	case "L", "shift+right":
		if cur != nil {
			m.collapseRecursive(cur, false)
			m.setCursorNode(cur)
			return true
		}
	case "H", "shift+left":
		if cur != nil {
			m.collapseRecursive(cur, true)
			m.setCursorNode(cur)
			return true
		}
	case "e":
		for _, r := range m.roots {
			m.collapseRecursive(r, false)
		}
		m.setCursorNode(cur)
		return true
	case "E":
		for _, r := range m.roots {
			for _, c := range r.Children {
				m.collapseRecursive(c, true)
			}
		}
		top := cur
		for top != nil && top.Parent != nil && top.Parent.Parent != nil {
			top = top.Parent
		}
		m.setCursorNode(top)
		return true
	case "J", "shift+down":
		if cur != nil && cur.Parent != nil {
			sib := cur.Parent.Children
			for i, c := range sib {
				if c == cur && i+1 < len(sib) {
					m.setCursorNode(sib[i+1])
					return true
				}
			}
		}
	case "K", "shift+up":
		if cur != nil && cur.Parent != nil {
			sib := cur.Parent.Children
			for i, c := range sib {
				if c == cur && i > 0 {
					m.setCursorNode(sib[i-1])
					return true
				}
			}
		}
	case "1", "2", "3", "4", "5", "6", "7", "8", "9":
		level := int(k[0] - '0')
		var walk func(n *jsonx.Node, d int)
		walk = func(n *jsonx.Node, d int) {
			if m.isContainer(n) && len(n.Children) > 0 {
				m.collapsed[n] = d >= level
				for _, c := range n.Children {
					walk(c, d+1)
				}
			}
		}
		for _, r := range m.roots {
			walk(r, 0)
		}
		top := cur
		for top != nil && depthOf(top) >= level {
			top = top.Parent
		}
		m.setCursorNode(top)
		return true
	case "z":
		m.wrap = !m.wrap
		m.setCursorNode(cur)
		return true
	}
	m.fixOffset()
	return true
}

func (m *tuiModel) updateSize() {
	m.width, m.height = termSize(m.tty.Fd())
}

func (m *tuiModel) run() {
	old, err := makeRaw(m.tty.Fd())
	if err != nil {
		goPanic(err.Error(), mainTrace)
	}
	m.tty.WriteString("\x1b[?1049h\x1b[?25l\x1b[2J")
	restore := func() {
		m.tty.WriteString("\x1b[2J\x1b[H\x1b[?25h\x1b[?1049l")
		setTermios(m.tty.Fd(), old)
	}
	defer restore()
	m.updateSize()
	m.buildRows()
	m.fixOffset()
	m.render()
	winch := make(chan os.Signal, 1)
	signal.Notify(winch, syscall.SIGWINCH)
	keys := make(chan string, 64)
	go readKeys(m.tty, keys)
	for {
		select {
		case <-winch:
			m.updateSize()
			cur := m.curNode()
			m.buildRows()
			if cur != nil {
				if i := m.rowOf(cur, false); i >= 0 && m.rows[m.cursor].node != cur {
					m.cursor = i
				}
			}
			m.fixOffset()
			m.tty.WriteString("\x1b[2J")
			m.render()
		case k, ok := <-keys:
			if !ok {
				return
			}
			if !m.handleKey(k) {
				return
			}
			m.render()
		}
	}
}

func readKeys(tty *os.File, out chan<- string) {
	buf := make([]byte, 256)
	pending := []byte{}
	for {
		n, err := tty.Read(buf)
		if err != nil {
			close(out)
			return
		}
		pending = append(pending, buf[:n]...)
		for len(pending) > 0 {
			k, size := parseKey(pending)
			if size == 0 {
				// incomplete escape: wait briefly
				time.Sleep(10 * time.Millisecond)
				if k == "" {
					k = "esc"
					size = 1
				}
			}
			pending = pending[size:]
			if k != "" {
				out <- k
			}
		}
	}
}

func parseKey(b []byte) (string, int) {
	c := b[0]
	if c == 0x1b {
		if len(b) == 1 {
			return "esc", 1
		}
		if b[1] == '[' || b[1] == 'O' {
			// find final byte
			for i := 2; i < len(b); i++ {
				if b[i] >= 0x40 && b[i] <= 0x7e {
					seq := string(b[2:i])
					fin := b[i]
					name := ""
					switch fin {
					case 'A':
						name = "up"
					case 'B':
						name = "down"
					case 'C':
						name = "right"
					case 'D':
						name = "left"
					case 'H':
						name = "home"
					case 'F':
						name = "end"
					case '~':
						switch seq {
						case "5":
							name = "pgup"
						case "6":
							name = "pgdown"
						case "1", "7":
							name = "home"
						case "4", "8":
							name = "end"
						case "3":
							name = "delete"
						}
						return name, i + 1
					}
					if strings.HasSuffix(seq, ";2") && name != "" {
						name = "shift+" + name
					}
					return name, i + 1
				}
			}
			return "", 0
		}
		return "esc", 1
	}
	switch c {
	case 0x03:
		return "ctrl+c", 1
	case 0x04:
		return "ctrl+d", 1
	case 0x15:
		return "ctrl+u", 1
	case 0x07:
		return "ctrl+g", 1
	case 0x0d, 0x0a:
		return "enter", 1
	case 0x7f, 0x08:
		return "backspace", 1
	}
	r, size := utf8DecodeRune(string(b))
	return string(r), size
}
