func (m *tuiModel) runSearch() {
	m.searching = false
	m.searchShown = true
	m.searchLine = "/" + m.input + "/i"
	m.matches = nil
	m.matchIdx = 0
	re, err := regexp.Compile("(?i)" + m.input)
	if err != nil {
		m.searchRight = err.Error()
		return
	}
	var walk func(n *jsonx.Node)
	walk = func(n *jsonx.Node) {
		if n.HasKey {
			for _, loc := range re.FindAllStringIndex(n.Key, -1) {
				if loc[1] > loc[0] {
					m.matches = append(m.matches, match{node: n, inKey: true, start: loc[0], end: loc[1]})
				}
			}
		}
		if n.IsPrimitive() {
			for _, loc := range re.FindAllStringIndex(n.Raw, -1) {
				if loc[1] > loc[0] {
					m.matches = append(m.matches, match{node: n, start: loc[0], end: loc[1]})
				}
			}
		}
		for _, c := range n.Children {
			walk(c)
		}
	}
	for _, r := range m.roots {
		walk(r)
	}
	if len(m.matches) == 0 {
		m.searchRight = "not found"
		return
	}
	m.jumpToMatch()
}

func (m *tuiModel) jumpToMatch() {
	mt := m.matches[m.matchIdx]
	m.searchRight = fmt.Sprintf("found: [%d/%d]", m.matchIdx+1, len(m.matches))
	for p := mt.node.Parent; p != nil; p = p.Parent {
		m.collapsed[p] = false
	}
	m.buildRows()
	row := m.rowOf(mt.node, false)
	if !mt.inKey && mt.node.Kind == jsonx.String {
		// find segment containing match start
		segs := m.stringSegments(mt.node)
		off := 0
		for i, sg := range segs {
			if mt.start < off+len(sg) {
				row += i
				break
			}
			off += len(sg)
		}
	}
	if row >= 0 {
		m.cursor = row
		h := m.contentHeight()
		m.offset = m.cursor - h/2
		if m.offset > len(m.rows)-h {
			m.offset = len(m.rows) - h
		}
		if m.offset < 0 {
			m.offset = 0
		}
	}
}

// highlightMatch wraps the matched part of text (which starts at byte base of raw token).
func (m *tuiModel) matchFor(n *jsonx.Node, inKey bool) *match {
	if !m.searchShown || len(m.matches) == 0 {
		return nil
	}
	mt := &m.matches[m.matchIdx]
	if mt.node == n && mt.inKey == inKey {
		return mt
	}
	return nil
}

func (m *tuiModel) hlText(text string, base int, color string, mt *match) (string, bool) {
	if mt == nil {
		return m.color(color, text), false
	}
	s := mt.start - base
	e := mt.end - base
	if e <= 0 || s >= len(text) {
		return m.color(color, text), false
	}
	if s < 0 {
		s = 0
	}
	if e > len(text) {
		e = len(text)
	}
	var sb strings.Builder
	if s > 0 {
		sb.WriteString(m.color(color, text[:s]))
	}
	sb.WriteString(reverse + text[s:e] + "\\x1b[0m")
	if e < len(text) {
		sb.WriteString(m.color(color, text[e:]))
	}
	return sb.String(), true
}''')
