func (m *tuiModel) jumpToMatch() {
	mt := m.matches[m.matchIdx]
	m.searchRight = fmt.Sprintf("found: [%d/%d]", m.matchIdx+1, len(m.matches))
	for p := mt.node.Parent; p != nil; p = p.Parent {
		m.collapsed[p] = false
	}
	m.buildRows()
	first := m.rowOf(mt.node, false)
	if first < 0 {
		return
	}
	row := first
	if !mt.inKey && mt.node.Kind == jsonx.String {
		segs := m.stringSegments(mt.node)
		off := 0
		for i, sg := range segs {
			if mt.start < off+len(sg) {
				row = first + i
				break
			}
			off += len(sg)
		}
	}
	m.cursor = row
	h := m.contentHeight()
	center := first + m.rows[first].nseg/2
	m.offset = center - h/2 + 1
	if m.offset > len(m.rows)-h {
		m.offset = len(m.rows) - h
	}
	if m.offset < 0 {
		m.offset = 0
	}
}

func (m *tuiModel) matchesFor(n *jsonx.Node, inKey bool) []hlRange {
