			out = append(out, hlRange{mt.start, mt.end, i == m.matchIdx})
		}
	}
	return out
}

func hasCurrent(rs []hlRange, base, length int) bool {
	for _, r := range rs {
		if r.current && r.end > base && r.start < base+length {
			return true
		}
	}
	return false
}

func (m *tuiModel) hlText(text string, base int, color string, rs []hlRange) (string, bool) {
	if len(rs) == 0 {
		return m.color(color, text), false
	}
	var sb strings.Builder
	pos := 0
	hitCur := false
	for _, r := range rs {
		st := r.start - base
		e := r.end - base
		if e <= 0 || st >= len(text) {
			continue
		}
		if st < pos {
			st = pos
		}
		if e > len(text) {
			e = len(text)
		}
		if st > pos {
			sb.WriteString(m.color(color, text[pos:st]))
		}
