			sb.WriteString(reverse + text[st:e] + "\\x1b[0m")
			hitCur = true
		} else {
			sb.WriteString(otherMatch + text[st:e] + "\\x1b[0m")
		}
		pos = e
	}
	if pos < len(text) {
		sb.WriteString(m.color(color, text[pos:]))
	}
	return sb.String(), hitCur
}

