// legacyDateParse approximates V8's legacy date parser (local time = UTC).
func legacyDateParse(s string) float64 {
	type tok struct {
		kind  byte // 'n' number, 'w' word, 's' symbol
		num   int
		ndig  int
		word  string
		sym   byte
	}
	var toks []tok
	i := 0
	for i < len(s) {
		c := s[i]
		switch {
		case c >= '0' && c <= '9':
			j := i
			v := 0
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				if v < 1e9 {
					v = v*10 + int(s[j]-'0')
				}
				j++
			}
			toks = append(toks, tok{kind: 'n', num: v, ndig: j - i})
			i = j
		case (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'):
			j := i
			for j < len(s) && ((s[j] >= 'a' && s[j] <= 'z') || (s[j] >= 'A' && s[j] <= 'Z')) {
				j++
			}
			toks = append(toks, tok{kind: 'w', word: strings.ToLower(s[i:j])})
			i = j
		case c == ' ' || c == '\t' || c == ',' || c == '\n':
			i++
		case c == '(':
			// skip parenthesized comments
			depth := 0
			for i < len(s) {
				if s[i] == '(' {
					depth++
				} else if s[i] == ')' {
					depth--
					if depth == 0 {
						i++
						break
					}
				}
				i++
			}
		default:
			toks = append(toks, tok{kind: 's', sym: c})
			i++
		}
	}
	months := map[string]int{"jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6, "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12}
	zones := map[string]int{"ut": 0, "utc": 0, "gmt": 0, "z": 0, "est": -5, "edt": -4, "cst": -6, "cdt": -5, "mst": -7, "mdt": -6, "pst": -8, "pdt": -7}
