// gameOfLife renders Conway's game of life using half-block characters.
func gameOfLife() {
	w, h := termSize(os.Stdout.Fd())
	rows := h * 2
	grid := make([][]bool, rows)
	for y := range grid {
		grid[y] = make([]bool, w)
		for x := range grid[y] {
			grid[y][x] = rand.Intn(4) == 0
		}
	}
	os.Stdout.WriteString("\x1b[2J\x1b[?25l")
	for {
		var sb strings.Builder
		sb.WriteString("\x1b[H")
		for y := 0; y < h; y++ {
			if y > 0 {
				sb.WriteString("\n")
			}
			for x := 0; x < w; x++ {
				top, bot := grid[2*y][x], grid[2*y+1][x]
				switch {
				case top && bot:
					sb.WriteString("█")
				case top:
					sb.WriteString("▀")
				case bot:
					sb.WriteString("▄")
				default:
					sb.WriteString(" ")
				}
			}
		}
		os.Stdout.WriteString(sb.String())
		next := make([][]bool, rows)
		for y := 0; y < rows; y++ {
			next[y] = make([]bool, w)
			for x := 0; x < w; x++ {
				n := 0
				for dy := -1; dy <= 1; dy++ {
					for dx := -1; dx <= 1; dx++ {
						if dx == 0 && dy == 0 {
							continue
						}
						yy, xx := (y+dy+rows)%rows, (x+dx+w)%w
						if grid[yy][xx] {
							n++
						}
					}
				}
				next[y][x] = n == 3 || (n == 2 && grid[y][x])
			}
		}
		grid = next
