cat > main.go <<'EOF'
package main

import (
	"encoding/json"
	"fmt"
	"math"
	"math/big"
	"math/bits"
	"os"
	"strconv"
)

type diyfp struct {
	f uint64
	e int
}

func normalize(a diyfp) diyfp {
	for a.f&(1<<63) == 0 {
		a.f <<= 1
		a.e--
	}
	return a
}

func times(a, b diyfp) diyfp {
	hi, lo := bits.Mul64(a.f, b.f)
	// round
	if lo&(1<<63) != 0 {
		hi++
	}
	return diyfp{hi, a.e + b.e + 64}
}

type cachedPower struct {
	f    uint64
	e    int
	dexp int
}

var powers []cachedPower

func init() {
	for k := -348; k <= 340; k += 8 {
		r := new(big.Rat)
		if k >= 0 {
			r.SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(k)), nil))
		} else {
			r.SetFrac(big.NewInt(1), new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-k)), nil))
		}
		// find e with 2^63 <= r/2^e < 2^64
		e := 0
		approx, _ := r.Float64()
		e = int(math.Floor(math.Log2(approx))) - 63
		for {
			q := new(big.Rat).Set(r)
			if e >= 0 {
				q.Quo(q, new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), uint(e))))
			} else {
				q.Mul(q, new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), uint(-e))))
			}
			// q in [2^63, 2^64)?
			lo := new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), 63))
			hi := new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), 64))
			if q.Cmp(lo) < 0 {
				e--
				continue
			}
			if q.Cmp(hi) >= 0 {
				e++
				continue
			}
			// round to nearest
			n := new(big.Int).Quo(q.Num(), q.Denom())
			rem := new(big.Rat).Sub(q, new(big.Rat).SetInt(n))
			if rem.Cmp(big.NewRat(1, 2)) >= 0 {
				n.Add(n, big.NewInt(1))
			}
			powers = append(powers, cachedPower{n.Uint64(), e, k})
			break
		}
	}
}

func cachedPowerFor(minExp int) (diyfp, int) {
	k := math.Ceil(float64(minExp+63) * 0.30102999566398114)
	index := (348+int(k)-1)/8 + 1
	p := powers[index]
	return diyfp{p.f, p.e}, p.dexp
}

func biggestPowerTen(number uint32, numberBits int) (uint32, int) {
	pow := []uint32{0, 1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000}
	guess := ((numberBits + 1) * 1233) >> 12
	guess++
	if guess >= len(pow) {
		guess = len(pow) - 1
	}
	if number < pow[guess] {
		guess--
	}
	return pow[guess], guess
}

func roundWeed(buf []byte, length int, distTooHighW, unsafeInterval, rest, tenKappa, unit uint64) bool {
	small := distTooHighW - unit
	big := distTooHighW + unit
	for rest < small && unsafeInterval-rest >= tenKappa && (rest+tenKappa < small || small-rest >= rest+tenKappa-small) {
		buf[length-1]--
		rest += tenKappa
	}
	if rest < big && unsafeInterval-rest >= tenKappa && (rest+tenKappa < big || big-rest > rest+tenKappa-big) {
		return false
	}
	return 2*unit <= rest && rest <= unsafeInterval-4*unit
}

func digitGen(low, w, high diyfp, buf []byte) (int, int, bool) {
	unit := uint64(1)
	tooLow := diyfp{low.f - unit, low.e}
	tooHigh := diyfp{high.f + unit, high.e}
	unsafeInterval := diyfp{tooHigh.f - tooLow.f, tooHigh.e}
	one := diyfp{uint64(1) << uint(-w.e), w.e}
	integrals := uint32(tooHigh.f >> uint(-one.e))
	fractionals := tooHigh.f & (one.f - 1)
	divisor, kappa := biggestPowerTen(integrals, 64-(-one.e))
	length := 0
	for kappa > 0 {
		digit := integrals / divisor
		buf[length] = byte('0' + digit)
		length++
		integrals %= divisor
		kappa--
		rest := (uint64(integrals) << uint(-one.e)) + fractionals
		if rest < unsafeInterval.f {
			ok := roundWeed(buf, length, tooHigh.f-w.f, unsafeInterval.f, rest, uint64(divisor)<<uint(-one.e), unit)
			return length, kappa, ok
		}
		divisor /= 10
	}
	for {
		fractionals *= 10
		unit *= 10
		unsafeInterval.f *= 10
		digit := int(fractionals >> uint(-one.e))
		buf[length] = byte('0' + digit)
		length++
		fractionals &= one.f - 1
		kappa--
		if fractionals < unsafeInterval.f {
			ok := roundWeed(buf, length, (tooHigh.f-w.f)*unit, unsafeInterval.f, fractionals, one.f, unit)
			return length, kappa, ok
		}
	}
}

func grisu3(v float64) (string, int, bool) {
	b := math.Float64bits(v)
	frac := b & ((1 << 52) - 1)
	bexp := int((b >> 52) & 0x7FF)
	var f uint64
	var e int
	if bexp == 0 {
		f = frac
		e = -1074
	} else {
		f = frac | (1 << 52)
		e = bexp - 1075
	}
	w := normalize(diyfp{f, e})
	mPlus := normalize(diyfp{(f << 1) + 1, e - 1})
	var mMinus diyfp
	if frac == 0 && bexp > 1 {
		mMinus = diyfp{(f << 2) - 1, e - 2}
	} else {
		mMinus = diyfp{(f << 1) - 1, e - 1}
	}
	mMinus.f <<= uint(mMinus.e - mPlus.e)
	mMinus.e = mPlus.e
	tenMk, mk := cachedPowerFor(-60 - (w.e + 64))
	sw := times(w, tenMk)
	sMinus := times(mMinus, tenMk)
	sPlus := times(mPlus, tenMk)
	buf := make([]byte, 20)
	length, kappa, ok := digitGen(sMinus, sw, sPlus, buf)
	return string(buf[:length]), -mk + kappa, ok
}

func main() {
	var vals []float64
	data, _ := os.ReadFile(os.Args[1])
	json.Unmarshal(data, &vals)
	fails := 0
	wrong := 0
	var failVals []string
	for _, v := range vals {
		d, _, ok := grisu3(v)
		if !ok {
			fails++
			failVals = append(failVals, strconv.FormatFloat(v, 'g', -1, 64))
			continue
		}
		es := strconv.FormatFloat(v, 'e', -1, 64)
		digits := ""
		for _, c := range es {
			if c == 'e' {
				break
			}
			if c >= '0' && c <= '9' {
				digits += string(c)
			}
		}
		if digits != d {
			wrong++
			if wrong < 5 {
