type diyfp struct {
	f uint64
	e int
}

func normalize(a diyfp) diyfp {
	for a.f&(1<<63) == 0 {
		a.f <<= 1
		a.e--
	}
	return a
}

func times(a, b diyfp) diyfp {
	hi, lo := bits.Mul64(a.f, b.f)
	// round
	if lo&(1<<63) != 0 {
		hi++
	}
	return diyfp{hi, a.e + b.e + 64}
}

type cachedPower struct {
	f    uint64
	e    int
	dexp int
}

var powers []cachedPower

func init() {
	for k := -348; k <= 340; k += 8 {
		r := new(big.Rat)
		if k >= 0 {
			r.SetInt(new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(k)), nil))
		} else {
			r.SetFrac(big.NewInt(1), new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(-k)), nil))
		}
		// find e with 2^63 <= r/2^e < 2^64
		e := 0
		approx, _ := r.Float64()
		e = int(math.Floor(math.Log2(approx))) - 63
		for {
			q := new(big.Rat).Set(r)
			if e >= 0 {
				q.Quo(q, new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), uint(e))))
			} else {
				q.Mul(q, new(big.Rat).SetInt(new(big.Int).Lsh(big.NewInt(1), uint(-e))))
			}
