			break
		}
	}
}

func cachedPowerFor(minExp int) (diyfp, int) {
	k := math.Ceil(float64(minExp+63) * 0.30102999566398114)
	index := (348+int(k)-1)/8 + 1
	p := powers[index]
	return diyfp{p.f, p.e}, p.dexp
}

func biggestPowerTen(number uint32, numberBits int) (uint32, int) {
	pow := []uint32{0, 1, 10, 100, 1000, 10000, 100000, 1000000, 10000000, 100000000, 1000000000}
	guess := ((numberBits + 1) * 1233) >> 12
	guess++
	if guess >= len(pow) {
