	}
	if number < pow[guess] {
		guess--
	}
	return pow[guess], guess
}

func roundWeed(buf []byte, length int, distTooHighW, unsafeInterval, rest, tenKappa, unit uint64) bool {
	small := distTooHighW - unit
	big := distTooHighW + unit
