		if rest < unsafeInterval {
			return roundWeed(buf, length, tooHigh.f-w.f, unsafeInterval, rest, uint64(divisor)<<uint(-one.e), unit)
		}
		divisor /= 10
	}
	for length < len(buf) {
		fractionals *= 10
		unit *= 10
		unsafeInterval *= 10
		digit := int(fractionals >> uint(-one.e))
