// grisu3Fails reports whether Grisu3 shortest mode bails out for v (> 0).
func grisu3Fails(v float64) bool {
	if cachedPowers == nil {
		initCachedPowers()
	}
	b := math.Float64bits(v)
	frac := b & ((1 << 52) - 1)
	bexp := int((b >> 52) & 0x7FF)
	var f uint64
	var e int
	if bexp == 0 {
		f = frac
		e = -1074
	} else {
		f = frac | (1 << 52)
		e = bexp - 1075
	}
	if f == 0 {
		return false
	}
	w := diyNormalize(diyfp{f, e})
	mPlus := diyNormalize(diyfp{(f << 1) + 1, e - 1})
	var mMinus diyfp
	if frac == 0 && bexp > 1 {
		mMinus = diyfp{(f << 2) - 1, e - 2}
	} else {
		mMinus = diyfp{(f << 1) - 1, e - 1}
	}
	mMinus.f <<= uint(mMinus.e - mPlus.e)
	mMinus.e = mPlus.e
	minExp := -60 - (w.e + 64)
	k := math.Ceil(float64(minExp+63) * 0.30102999566398114)
	index := (348+int(k)-1)/8 + 1
	if index < 0 || index >= len(cachedPowers) {
		return false
	}
	p := cachedPowers[index]
	tenMk := diyfp{p.f, p.e}
	sw := diyTimes(w, tenMk)
	sMinus := diyTimes(mMinus, tenMk)
	sPlus := diyTimes(mPlus, tenMk)
	buf := make([]byte, 24)
	return !digitGen(sMinus, sw, sPlus, buf)
}

// gojaDigits adjusts shortest digits to reproduce goja's output.
// digits/exp as from FormatFloat 'e' (d.ddd e exp); v > 0.
func gojaDigits(v float64, digits string, exp int) (string, int) {
	n := len(digits)
	if n < 2 || digits[n-1] != '9' {
		return digits, exp
	}
	if !grisu3Fails(v) {
		return digits, exp
	}
	// exact comparison: digits value must be above v
	sval, _, err := big.ParseFloat(digits[:1]+"."+digits[1:]+"e"+strconv.Itoa(exp), 10, 2000, big.ToNearestEven)
	if err != nil {
		return digits, exp
	}
	if sval.Cmp(new(big.Float).SetPrec(2000).SetFloat64(v)) <= 0 {
		return digits, exp
	}
	// round up to n-1 digits
	short := []byte(digits[:n-1])
	i := len(short) - 1
	for i >= 0 {
		if short[i] == '9' {
			short[i] = '0'
			i--
			continue
		}
		short[i]++
		break
	}
	nexp := exp
	if i < 0 {
		short = append([]byte{'1'}, short...)
		nexp++
	}
	// trim trailing zeros
	for len(short) > 1 && short[len(short)-1] == '0' {
		short = short[:len(short)-1]
	}
	cs := string(short[:1])
	if len(short) > 1 {
		cs += "." + string(short[1:])
	}
	cf, err := strconv.ParseFloat(cs+"e"+strconv.Itoa(nexp), 64)
	if err != nil || cf != math.Nextafter(v, math.Inf(1)) {
		return digits, exp
	}
	return string(short), nexp
}
